CREATE OR REPLACE FUNCTION public.complete_survey_atomic(
  p_appointment_id uuid,
  p_completed_by uuid,
  p_survey_payload jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_appointment record;
  v_survey record;
  v_member record;
  v_now timestamptz := clock_timestamp();
  v_company_id uuid;
  v_customer_id uuid;
  v_measurements jsonb;
  v_photos jsonb;
  v_site_condition text;
  v_notes text;
  v_completed_at timestamptz;
BEGIN
  -- 2.1. Khóa dòng appointment bằng SELECT FOR UPDATE
  SELECT id, company_id, customer_id, status, type, assignee_id
  INTO v_appointment
  FROM public.appointments
  WHERE id = p_appointment_id
  FOR UPDATE;

  -- 2.2. Kiểm tra tồn tại
  IF NOT FOUND THEN
    RAISE EXCEPTION 'APPOINTMENT_NOT_FOUND';
  END IF;

  -- 2.3. Kiểm tra type
  IF v_appointment.type <> 'SURVEY' THEN
    RAISE EXCEPTION 'APPOINTMENT_TYPE_NOT_SURVEY';
  END IF;

  -- 2.4. Kiểm tra trạng thái terminal & tiền đề (P0: Predecessor State Check)
  IF v_appointment.status IN ('COMPLETED', 'CANCELLED') THEN
    RAISE EXCEPTION 'APPOINTMENT_ALREADY_TERMINAL';
  END IF;

  IF v_appointment.status NOT IN ('IN_PROGRESS', 'ACCEPTED') THEN
    RAISE EXCEPTION 'INVALID_PREDECESSOR_STATE: APPOINTMENT_STATE_INVALID';
  END IF;

  -- 2.5. Trích xuất an toàn & chống giả mạo danh tính (P0: Identity Spoofing Prevention)
  -- BẮT BUỘC gán company_id và customer_id từ chính bản ghi appointment đã khóa, tuyệt đối không tin payload
  v_company_id := v_appointment.company_id;
  v_customer_id := v_appointment.customer_id;

  -- 2.5.1. P1 Hardening: Xác thực p_completed_by (truyền riêng biệt, không parse từ JSON payload)
  IF p_completed_by IS NULL THEN
    RAISE EXCEPTION 'INVALID_COMPLETED_BY';
  END IF;

  -- Xác minh p_completed_by bắt buộc là thành viên ACTIVE thuộc cùng company_id
  SELECT role, status
  INTO v_member
  FROM public.company_members
  WHERE user_id = p_completed_by
    AND company_id = v_company_id
    AND status = 'ACTIVE';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'INVALID_COMPLETED_BY';
  END IF;

  -- Kiểm tra phân quyền: TECHNICIAN phải là assignee_id của lịch hẹn; BOSS_ADMIN được phép
  IF v_member.role = 'TECHNICIAN' THEN
    IF v_appointment.assignee_id IS NULL OR v_appointment.assignee_id <> p_completed_by THEN
      RAISE EXCEPTION 'INVALID_COMPLETED_BY: TECHNICIAN_NOT_ASSIGNEE';
    END IF;
  ELSIF v_member.role = 'BOSS_ADMIN' THEN
    -- BOSS_ADMIN được phép hoàn tất khảo sát
    NULL;
  ELSE
    RAISE EXCEPTION 'INVALID_COMPLETED_BY';
  END IF;

  v_measurements := COALESCE(p_survey_payload->'measurements', '{}'::jsonb);
  v_photos := COALESCE(p_survey_payload->'photos', '[]'::jsonb);
  v_site_condition := COALESCE(p_survey_payload->>'site_condition', p_survey_payload->>'siteCondition', '');
  v_notes := p_survey_payload->>'notes';
  v_completed_at := COALESCE((p_survey_payload->>'completed_at')::timestamptz, v_now);

  -- 2.6. Atomic Step A: Cập nhật appointment sang COMPLETED (có ràng buộc trạng thái tiền đề)
  UPDATE public.appointments
  SET status = 'COMPLETED',
      updated_at = v_now
  WHERE id = p_appointment_id
    AND status IN ('IN_PROGRESS', 'ACCEPTED');

  -- 2.7. Atomic Step B: Insert survey
  INSERT INTO public.surveys (
    company_id,
    customer_id,
    appointment_id,
    completed_by,
    measurements,
    photos,
    site_condition,
    notes,
    completed_at,
    created_at,
    updated_at
  ) VALUES (
    v_company_id,
    v_customer_id,
    p_appointment_id,
    p_completed_by,
    v_measurements,
    v_photos,
    v_site_condition,
    v_notes,
    v_completed_at,
    v_now,
    v_now
  )
  RETURNING * INTO v_survey;

  -- 2.8. Trả về bản ghi survey vừa tạo dạng JSON
  RETURN to_jsonb(v_survey);
END;
$$;

CREATE OR REPLACE FUNCTION public.record_quality_check_atomic(
  p_company_id uuid,
  p_production_order_id uuid,
  p_qc_status text,
  p_inspector_id uuid,
  p_notes text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_prod record;
  v_order record;
  v_next_status text;
  v_db_qc_status text;
  v_timestamp timestamptz;
BEGIN
  v_timestamp := now();

  -- 1. Khóa và truy vấn lệnh sản xuất
  SELECT id, company_id, order_id, status, qc_status
  INTO v_prod
  FROM public.production_orders
  WHERE company_id = p_company_id AND id = p_production_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'RESOURCE_NOT_FOUND: Không tìm thấy lệnh sản xuất để kiểm tra QC.';
  END IF;

  -- 2. Kiểm tra điều kiện trạng thái xưởng: bắt buộc QC_IN_PROGRESS
  IF v_prod.status <> 'QC_IN_PROGRESS' THEN
    RAISE EXCEPTION 'INVALID_STATE_TRANSITION: Lệnh xưởng phải ở trạng thái QC_IN_PROGRESS để kiểm tra QC. Trạng thái hiện tại: %', v_prod.status;
  END IF;

  -- 3. Phân định trạng thái tiếp theo dựa trên kết quả QC
  IF p_qc_status = 'PASSED' THEN
    v_next_status := 'READY_FOR_DISPATCH';
    v_db_qc_status := 'PASSED';
  ELSIF p_qc_status = 'REWORK_REQUIRED' OR p_qc_status = 'REJECTED' THEN
    v_next_status := 'QC_FAILED';
    v_db_qc_status := p_qc_status;
  ELSE
    RAISE EXCEPTION 'INVALID_INPUT: Trạng thái QC không hợp lệ: %', p_qc_status;
  END IF;

  -- 4. Cập nhật production_orders
  UPDATE public.production_orders
  SET status = v_next_status,
      qc_status = v_db_qc_status,
      updated_at = v_timestamp
  WHERE company_id = p_company_id AND id = p_production_order_id;

  -- 5. Nếu PASSED, kích hoạt orders -> READY_FOR_INSTALL
  IF v_db_qc_status = 'PASSED' THEN
    SELECT id, company_id, order_status
    INTO v_order
    FROM public.orders
    WHERE company_id = p_company_id AND id = v_prod.order_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'RESOURCE_NOT_FOUND: Không tìm thấy đơn hàng tương ứng với lệnh sản xuất.';
    END IF;

    UPDATE public.orders
    SET order_status = 'READY_FOR_INSTALL',
        updated_at = v_timestamp
    WHERE company_id = p_company_id AND id = v_prod.order_id;
  END IF;

  -- 6. Ghi audit_logs (Bắt buộc fail-closed trong transaction)
  INSERT INTO public.audit_logs (
    company_id,
    user_id,
    action,
    resource_type,
    resource_id,
    result,
    metadata
  ) VALUES (
    p_company_id,
    p_inspector_id,
    'RECORD_QUALITY_CHECK',
    'production_orders',
    p_production_order_id,
    'SUCCESS',
    jsonb_build_object(
      'from_status', v_prod.status,
      'to_status', v_next_status,
      'qc_status', v_db_qc_status,
      'actor_id', p_inspector_id,
      'notes', p_notes
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'production_order_id', p_production_order_id,
    'status', v_next_status,
    'qc_status', v_db_qc_status
  );
END;
$$;

