CREATE OR REPLACE FUNCTION public.get_sales_style_learning_input(
  p_company_id uuid,
  p_sale_user_id uuid,
  p_limit integer DEFAULT 100
)
RETURNS TABLE (
  interaction_id uuid,
  channel text,
  sanitized_content text,
  created_at timestamptz
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_user_status text;
  v_member_role text;
  v_member_status text;
  v_limit integer;
BEGIN
  -- 1. Validate target user existence and status in user_profiles
  SELECT up.status
  INTO v_user_status
  FROM public.user_profiles up
  WHERE up.id = p_sale_user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'USER_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  IF v_user_status <> 'ACTIVE' THEN
    RAISE EXCEPTION 'USER_INACTIVE' USING ERRCODE = '42501';
  END IF;

  -- 2. Validate company membership in target company
  SELECT cm.role, cm.status
  INTO v_member_role, v_member_status
  FROM public.company_members cm
  WHERE cm.company_id = p_company_id
    AND cm.user_id = p_sale_user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'MEMBERSHIP_NOT_FOUND' USING ERRCODE = '42501';
  END IF;

  IF v_member_role <> 'SALE' THEN
    RAISE EXCEPTION 'ROLE_NOT_SALE' USING ERRCODE = '42501';
  END IF;

  IF v_member_status <> 'ACTIVE' THEN
    RAISE EXCEPTION 'MEMBERSHIP_INACTIVE' USING ERRCODE = '42501';
  END IF;

  -- 3. Validate limit parameter (1 to 200)
  IF p_limit IS NOT NULL AND (p_limit < 1 OR p_limit > 200) THEN
    RAISE EXCEPTION 'INVALID_LIMIT' USING ERRCODE = '22000';
  END IF;
  v_limit := COALESCE(p_limit, 100);

  -- 4. Query latest-N sanitized outbound SALE messages, then reorder chronologically ASC
  RETURN QUERY
  WITH latest_interactions AS (
    SELECT
      i.id AS interaction_id,
      i.channel,
      i.sanitized_content,
      i.created_at
    FROM public.interactions i
    WHERE i.company_id = p_company_id
      AND i.actor_type = 'SALE'
      AND i.actor_user_id = p_sale_user_id
      AND i.direction = 'OUTBOUND'
      AND i.type = 'MESSAGE'
      AND i.sanitization_status = 'SUCCEEDED'
      AND i.sanitized_content IS NOT NULL
    ORDER BY i.created_at DESC, i.id DESC
    LIMIT v_limit
  )
  SELECT
    li.interaction_id,
    li.channel,
    li.sanitized_content,
    li.created_at
  FROM latest_interactions li
  ORDER BY li.created_at ASC, li.interaction_id ASC;
END;
$$;

CREATE OR REPLACE FUNCTION public.record_sales_style_profile(
  p_company_id uuid,
  p_sale_user_id uuid,
  p_source_refs jsonb,
  p_salutation_rules jsonb,
  p_sentence_style jsonb,
  p_question_style jsonb,
  p_objection_style jsonb,
  p_closing_style jsonb,
  p_model_version text
)
RETURNS TABLE (
  id uuid,
  company_id uuid,
  sale_user_id uuid,
  version text,
  salutation_rules jsonb,
  sentence_style jsonb,
  question_style jsonb,
  objection_style jsonb,
  closing_style jsonb,
  examples jsonb,
  source_refs jsonb,
  model_version text,
  generation_status text,
  created_at timestamptz,
  updated_at timestamptz
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_user_status text;
  v_member_role text;
  v_member_status text;
  v_elem jsonb;
  v_ref_id uuid;
  v_ref_type text;
  v_int_company_id uuid;
  v_int_actor_type text;
  v_int_actor_user_id uuid;
  v_int_direction text;
  v_int_type text;
  v_int_sanitization_status text;
  v_int_sanitized_content text;
  v_version text;
  v_derived_examples jsonb;
  v_unique_source_count integer;
  v_total_source_count integer;
  v_combined_style_text text;
  v_new_row public.sales_style_profiles%ROWTYPE;
BEGIN
  -- 1. Validate target Sale user existence and active status
  SELECT up.status
  INTO v_user_status
  FROM public.user_profiles up
  WHERE up.id = p_sale_user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'USER_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  IF v_user_status <> 'ACTIVE' THEN
    RAISE EXCEPTION 'USER_INACTIVE' USING ERRCODE = '42501';
  END IF;

  -- 2. Validate target Sale company membership in target company
  SELECT cm.role, cm.status
  INTO v_member_role, v_member_status
  FROM public.company_members cm
  WHERE cm.company_id = p_company_id
    AND cm.user_id = p_sale_user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'MEMBERSHIP_NOT_FOUND' USING ERRCODE = '42501';
  END IF;

  IF v_member_role <> 'SALE' THEN
    RAISE EXCEPTION 'ROLE_NOT_SALE' USING ERRCODE = '42501';
  END IF;

  IF v_member_status <> 'ACTIVE' THEN
    RAISE EXCEPTION 'MEMBERSHIP_INACTIVE' USING ERRCODE = '42501';
  END IF;

  -- 3. Validate model_version (trusted provenance: non-null, non-empty, length <= 100)
  IF p_model_version IS NULL OR pg_catalog.btrim(p_model_version) = '' THEN
    RAISE EXCEPTION 'EMPTY_MODEL_VERSION' USING ERRCODE = '22000';
  END IF;
  IF pg_catalog.length(p_model_version) > 100 THEN
    RAISE EXCEPTION 'MODEL_VERSION_TOO_LONG' USING ERRCODE = '22000';
  END IF;

  -- 4. Validate style JSON structures at DB level (must be non-null JSON objects)
  IF p_salutation_rules IS NULL OR jsonb_typeof(p_salutation_rules) <> 'object' THEN
    RAISE EXCEPTION 'INVALID_SALUTATION_RULES' USING ERRCODE = '22000';
  END IF;
  IF p_sentence_style IS NULL OR jsonb_typeof(p_sentence_style) <> 'object' THEN
    RAISE EXCEPTION 'INVALID_SENTENCE_STYLE' USING ERRCODE = '22000';
  END IF;
  IF p_question_style IS NULL OR jsonb_typeof(p_question_style) <> 'object' THEN
    RAISE EXCEPTION 'INVALID_QUESTION_STYLE' USING ERRCODE = '22000';
  END IF;
  IF p_objection_style IS NULL OR jsonb_typeof(p_objection_style) <> 'object' THEN
    RAISE EXCEPTION 'INVALID_OBJECTION_STYLE' USING ERRCODE = '22000';
  END IF;
  IF p_closing_style IS NULL OR jsonb_typeof(p_closing_style) <> 'object' THEN
    RAISE EXCEPTION 'INVALID_CLOSING_STYLE' USING ERRCODE = '22000';
  END IF;

  -- 4b. Business-policy content firewall at DB level (Defense in depth)
  v_combined_style_text := p_salutation_rules::text || ' ' ||
                           p_sentence_style::text || ' ' ||
                           p_question_style::text || ' ' ||
                           p_objection_style::text || ' ' ||
                           p_closing_style::text;

  IF v_combined_style_text ~* '(giảm\s*giá|chiết\s*khấu|\ydiscount\y|khuyến\s*m[aã]i|%|\ypercent\y|\yphần\s*trăm\y|giá\s*bán|mức\s*giá|báo\s*giá|bảng\s*giá|đơn\s*giá|\yvnđ\y|\yvnd\y|₫|đặt\s*cọc|tiền\s*cọc|\ycọc\y|payment\s*terms|\ythanh\s*toán\y|\ypayment\y|chuyển\s*khoản|trả\s*góp|hợp\s*đồng|\ycontract\y|bảo\s*hành|\ywarranty\y|\yphí\y|lãi\s*suất|cam\s*kết\s*(giao\s*hàng|bảo\s*hành|tiến\s*độ|giá|doanh\s*nghiệp|chất\s*lượng|hoàn\s*tiền))'
     OR v_combined_style_text ~* '\m\d+([\.,]\d{3})*\s*(triệu|nghìn|ngàn|tr|k|đồng|đ)\M' THEN
    RAISE EXCEPTION 'FORBIDDEN_BUSINESS_POLICY_IN_STYLE' USING ERRCODE = '22000';
  END IF;

  -- 5. Validate source_refs array (1 to 200 items, audit-safe)
  IF p_source_refs IS NULL OR jsonb_typeof(p_source_refs) <> 'array' THEN
    RAISE EXCEPTION 'INVALID_SOURCE_REFS_STRUCTURE' USING ERRCODE = '22000';
  END IF;
  IF jsonb_array_length(p_source_refs) = 0 THEN
    RAISE EXCEPTION 'EMPTY_SOURCE_REFS' USING ERRCODE = '22000';
  END IF;
  IF jsonb_array_length(p_source_refs) > 200 THEN
    RAISE EXCEPTION 'SOURCE_REFS_LIMIT_EXCEEDED' USING ERRCODE = '22000';
  END IF;

  -- Validate uniqueness of source_refs interaction IDs (Reject duplicate source refs)
  SELECT count(DISTINCT (elem->>'id')::uuid), count(*)
  INTO v_unique_source_count, v_total_source_count
  FROM jsonb_array_elements(p_source_refs) elem;

  IF v_unique_source_count <> v_total_source_count THEN
    RAISE EXCEPTION 'DUPLICATE_SOURCE_REF' USING ERRCODE = '22000';
  END IF;

  FOR v_elem IN SELECT * FROM jsonb_array_elements(p_source_refs) LOOP
    IF jsonb_typeof(v_elem) <> 'object' THEN
      RAISE EXCEPTION 'INVALID_SOURCE_REF_ITEM' USING ERRCODE = '22000';
    END IF;

    -- Security: Only type 'INTERACTION' is allowed
    v_ref_type := v_elem->>'type';
    IF v_ref_type IS NULL OR v_ref_type <> 'INTERACTION' THEN
      RAISE EXCEPTION 'FORBIDDEN_SOURCE_REF_TYPE' USING ERRCODE = '22000';
    END IF;

    -- Security: Forbid storing sensitive keys in source_refs
    IF v_elem ? 'content' OR v_elem ? 'phone' OR v_elem ? 'transcript'
       OR v_elem ? 'recording' OR v_elem ? 'raw_payload' OR v_elem ? 'token' THEN
      RAISE EXCEPTION 'SENSITIVE_DATA_IN_SOURCE_REF' USING ERRCODE = '22000';
    END IF;

    BEGIN
      v_ref_id := (v_elem->>'id')::uuid;
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'INVALID_SOURCE_REF_UUID' USING ERRCODE = '22000';
    END;

    IF v_ref_id IS NULL THEN
      RAISE EXCEPTION 'INVALID_SOURCE_REF_UUID' USING ERRCODE = '22000';
    END IF;

    -- Verify target interaction against strict company, sale actor, outbound, message, and sanitization boundaries
    SELECT i.company_id, i.actor_type, i.actor_user_id, i.direction, i.type, i.sanitization_status, i.sanitized_content
    INTO v_int_company_id, v_int_actor_type, v_int_actor_user_id, v_int_direction, v_int_type, v_int_sanitization_status, v_int_sanitized_content
    FROM public.interactions i
    WHERE i.id = v_ref_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'SOURCE_INTERACTION_NOT_FOUND' USING ERRCODE = 'P0002';
    END IF;

    IF v_int_company_id <> p_company_id THEN
      RAISE EXCEPTION 'SOURCE_INTERACTION_TENANT_MISMATCH' USING ERRCODE = '42501';
    END IF;

    IF v_int_actor_type <> 'SALE' OR v_int_actor_user_id <> p_sale_user_id THEN
      RAISE EXCEPTION 'SOURCE_INTERACTION_ACTOR_MISMATCH' USING ERRCODE = '22000';
    END IF;

    IF v_int_direction <> 'OUTBOUND' THEN
      RAISE EXCEPTION 'SOURCE_INTERACTION_NOT_OUTBOUND' USING ERRCODE = '22000';
    END IF;

    IF v_int_type <> 'MESSAGE' THEN
      RAISE EXCEPTION 'SOURCE_INTERACTION_NOT_MESSAGE' USING ERRCODE = '22000';
    END IF;

    IF v_int_sanitization_status <> 'SUCCEEDED' THEN
      RAISE EXCEPTION 'SOURCE_INTERACTION_NOT_SANITIZED' USING ERRCODE = '22000';
    END IF;

    IF v_int_sanitized_content IS NULL OR pg_catalog.btrim(v_int_sanitized_content) = '' THEN
      RAISE EXCEPTION 'SOURCE_INTERACTION_NO_CONTENT' USING ERRCODE = '22000';
    END IF;
  END LOOP;

  -- 6. Derive trusted provenance examples (metadata only: interaction_id, channel, created_at, capped at 5)
  -- CRITICAL SECURITY INVARIANT: Message content/text is NEVER stored in examples.
  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'interaction_id', sub.id,
        'channel', sub.channel,
        'created_at', sub.created_at
      )
    ),
    '[]'::jsonb
  )
  INTO v_derived_examples
  FROM (
    SELECT i.id, i.channel, i.created_at
    FROM public.interactions i
    WHERE i.id IN (
      SELECT (elem->>'id')::uuid
      FROM jsonb_array_elements(p_source_refs) elem
    )
    ORDER BY i.created_at DESC, i.id DESC
    LIMIT 5
  ) sub;

  -- 7. Generate trusted unique version (server/DB generated, satisfies uq_ssp_company_version)
  v_version := 'ssp_' || replace(gen_random_uuid()::text, '-', '');

  -- 8. Append-only INSERT into public.sales_style_profiles
  -- INVARIANT: generation_status is strictly 'DRAFT' in M9.4A.
  -- INVARIANT: existing profiles are NEVER updated.
  -- INVARIANT: no customer, order, contract, pricing, or payment tables are mutated.
  INSERT INTO public.sales_style_profiles (
    company_id,
    sale_user_id,
    version,
    salutation_rules,
    sentence_style,
    question_style,
    objection_style,
    closing_style,
    examples,
    source_refs,
    model_version,
    generation_status
  ) VALUES (
    p_company_id,
    p_sale_user_id,
    v_version,
    p_salutation_rules,
    p_sentence_style,
    p_question_style,
    p_objection_style,
    p_closing_style,
    v_derived_examples,
    p_source_refs,
    p_model_version,
    'DRAFT'
  )
  RETURNING * INTO v_new_row;

  -- 9. Mandatory Audit Log entry
  -- In case audit insert fails, the entire transaction rolls back fail-closed.
  INSERT INTO public.audit_logs (
    company_id,
    user_id,
    action,
    resource_type,
    resource_id,
    customer_id,
    result,
    metadata
  ) VALUES (
    p_company_id,
    p_sale_user_id,
    'SALES_STYLE_PROFILE_GENERATED',
    'SALES_STYLE_PROFILE',
    v_new_row.id,
    NULL,
    'SUCCESS',
    jsonb_build_object(
      'sale_user_id', p_sale_user_id,
      'version', v_version,
      'model_version', p_model_version,
      'source_count', v_unique_source_count
    )
  );

  RETURN QUERY SELECT
    v_new_row.id,
    v_new_row.company_id,
    v_new_row.sale_user_id,
    v_new_row.version,
    v_new_row.salutation_rules,
    v_new_row.sentence_style,
    v_new_row.question_style,
    v_new_row.objection_style,
    v_new_row.closing_style,
    v_new_row.examples,
    v_new_row.source_refs,
    v_new_row.model_version,
    v_new_row.generation_status,
    v_new_row.created_at,
    v_new_row.updated_at;
  RETURN;
END;
$$;

ALTER TABLE public.sales_style_profiles
  ADD CONSTRAINT uq_sales_style_profiles_company_sale_id
  UNIQUE (company_id, sale_user_id, id);

ALTER TABLE public.sales_style_profiles
  ADD CONSTRAINT chk_sales_style_profiles_no_self_supersede
  CHECK (superseded_by_profile_id IS NULL OR superseded_by_profile_id <> id);

CREATE UNIQUE INDEX uq_sales_style_profiles_active_sale
  ON public.sales_style_profiles (company_id, sale_user_id)
  WHERE generation_status = 'ACTIVE';

CREATE INDEX idx_sales_style_profiles_superseded_by
  ON public.sales_style_profiles (superseded_by_profile_id)
  WHERE superseded_by_profile_id IS NOT NULL;

CREATE OR REPLACE FUNCTION public.activate_sales_style_profile(
  p_profile_id uuid
)
RETURNS TABLE (
  id uuid,
  company_id uuid,
  sale_user_id uuid,
  version text,
  salutation_rules jsonb,
  sentence_style jsonb,
  question_style jsonb,
  objection_style jsonb,
  closing_style jsonb,
  examples jsonb,
  source_refs jsonb,
  model_version text,
  generation_status text,
  activated_at timestamptz,
  activated_by_user_id uuid,
  superseded_at timestamptz,
  superseded_by_profile_id uuid,
  created_at timestamptz,
  updated_at timestamptz
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
#variable_conflict use_column
DECLARE
  v_actor_user_id uuid;
  v_actor_user_status text;
  v_actor_role text;
  v_actor_member_status text;
  v_target_company_id uuid;
  v_target_sale_user_id uuid;
  v_target_status text;
  v_sale_member_role text;
  v_sale_member_status text;
  v_target_sale_user_status text;
  v_target_row public.sales_style_profiles%ROWTYPE;
  v_old_active_row public.sales_style_profiles%ROWTYPE;
  v_now timestamptz;
  v_elem jsonb;
  v_ex jsonb;
  v_ref_id uuid;
  v_unique_source_count integer;
  v_total_source_count integer;
  v_int_company_id uuid;
  v_int_actor_type text;
  v_int_actor_user_id uuid;
  v_int_direction text;
  v_int_type text;
  v_int_sanitization_status text;
  v_int_sanitized_content text;
  v_combined_style_text text;
BEGIN
  -- 1. Derive target resource and verify existence
  SELECT
    ssp.company_id,
    ssp.sale_user_id,
    ssp.generation_status
  INTO
    v_target_company_id,
    v_target_sale_user_id,
    v_target_status
  FROM public.sales_style_profiles ssp
  WHERE ssp.id = p_profile_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PROFILE_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  -- 2. Validate human actor via auth.uid()
  v_actor_user_id := auth.uid();
  IF v_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'UNAUTHENTICATED' USING ERRCODE = '42501';
  END IF;

  -- Verify actor profile in user_profiles
  SELECT up.status
  INTO v_actor_user_status
  FROM public.user_profiles up
  WHERE up.id = v_actor_user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ACTOR_NOT_FOUND' USING ERRCODE = '42501';
  END IF;

  IF v_actor_user_status <> 'ACTIVE' THEN
    RAISE EXCEPTION 'ACTOR_INACTIVE' USING ERRCODE = '42501';
  END IF;

  -- Verify actor company membership: must be same company, role BOSS_ADMIN, status ACTIVE
  SELECT cm.role, cm.status
  INTO v_actor_role, v_actor_member_status
  FROM public.company_members cm
  WHERE cm.company_id = v_target_company_id
    AND cm.user_id = v_actor_user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ACTOR_MEMBERSHIP_NOT_FOUND' USING ERRCODE = '42501';
  END IF;

  IF v_actor_role <> 'BOSS_ADMIN' THEN
    RAISE EXCEPTION 'ACTOR_ROLE_NOT_BOSS_ADMIN' USING ERRCODE = '42501';
  END IF;

  IF v_actor_member_status <> 'ACTIVE' THEN
    RAISE EXCEPTION 'ACTOR_MEMBERSHIP_INACTIVE' USING ERRCODE = '42501';
  END IF;

  -- 3. Concurrency serialization mutex: Lock target Sale company_members row FOR UPDATE
  SELECT cm.role, cm.status
  INTO v_sale_member_role, v_sale_member_status
  FROM public.company_members cm
  WHERE cm.company_id = v_target_company_id
    AND cm.user_id = v_target_sale_user_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'TARGET_SALE_MEMBERSHIP_NOT_FOUND' USING ERRCODE = '42501';
  END IF;

  -- 4. Revalidate target Sale at activation time
  IF v_sale_member_role <> 'SALE' THEN
    RAISE EXCEPTION 'TARGET_NOT_SALE' USING ERRCODE = '42501';
  END IF;

  IF v_sale_member_status <> 'ACTIVE' THEN
    RAISE EXCEPTION 'TARGET_SALE_INACTIVE' USING ERRCODE = '42501';
  END IF;

  SELECT up.status
  INTO v_target_sale_user_status
  FROM public.user_profiles up
  WHERE up.id = v_target_sale_user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'TARGET_SALE_USER_NOT_FOUND' USING ERRCODE = '42501';
  END IF;

  IF v_target_sale_user_status <> 'ACTIVE' THEN
    RAISE EXCEPTION 'TARGET_SALE_USER_INACTIVE' USING ERRCODE = '42501';
  END IF;

  -- 5. Lock target profile FOR UPDATE
  SELECT *
  INTO v_target_row
  FROM public.sales_style_profiles ssp
  WHERE ssp.id = p_profile_id
  FOR UPDATE;

  -- Allowed state transitions:
  -- SUPERSEDED cannot be activated
  IF v_target_row.generation_status = 'SUPERSEDED' THEN
    RAISE EXCEPTION 'PROFILE_ALREADY_SUPERSEDED' USING ERRCODE = '22000';
  END IF;

  -- Idempotency: ACTIVE -> ACTIVE no-op
  IF v_target_row.generation_status = 'ACTIVE' THEN
    -- Verify invariant sanity
    IF v_target_row.activated_at IS NULL OR v_target_row.activated_by_user_id IS NULL
       OR v_target_row.superseded_at IS NOT NULL OR v_target_row.superseded_by_profile_id IS NOT NULL THEN
      RAISE EXCEPTION 'CORRUPT_ACTIVE_PROFILE_STATE' USING ERRCODE = '22000';
    END IF;

    -- Return existing active profile without updating or creating duplicate audit
    RETURN QUERY SELECT
      v_target_row.id,
      v_target_row.company_id,
      v_target_row.sale_user_id,
      v_target_row.version,
      v_target_row.salutation_rules,
      v_target_row.sentence_style,
      v_target_row.question_style,
      v_target_row.objection_style,
      v_target_row.closing_style,
      v_target_row.examples,
      v_target_row.source_refs,
      v_target_row.model_version,
      v_target_row.generation_status,
      v_target_row.activated_at,
      v_target_row.activated_by_user_id,
      v_target_row.superseded_at,
      v_target_row.superseded_by_profile_id,
      v_target_row.created_at,
      v_target_row.updated_at;
    RETURN;
  END IF;

  IF v_target_row.generation_status <> 'DRAFT' THEN
    RAISE EXCEPTION 'INVALID_PROFILE_STATUS' USING ERRCODE = '22000';
  END IF;

  -- ============================================================================
  -- 5b. PROVENANCE REVALIDATION OF DRAFT PROFILE (Defense-in-depth against untrusted DRAFTs)
  -- ============================================================================
  -- 1. Validate model_version: non-null, non-empty trimmed, length <= 100
  IF v_target_row.model_version IS NULL
     OR pg_catalog.btrim(v_target_row.model_version) = ''
     OR pg_catalog.length(v_target_row.model_version) > 100 THEN
    RAISE EXCEPTION 'PROFILE_PROVENANCE_INVALID' USING ERRCODE = '22000';
  END IF;

  -- 2. Validate source_refs: jsonb array, 1..200 items, no duplicates, valid shape INTERACTION
  IF v_target_row.source_refs IS NULL
     OR jsonb_typeof(v_target_row.source_refs) <> 'array'
     OR jsonb_array_length(v_target_row.source_refs) = 0
     OR jsonb_array_length(v_target_row.source_refs) > 200 THEN
    RAISE EXCEPTION 'PROFILE_PROVENANCE_INVALID' USING ERRCODE = '22000';
  END IF;

  -- Validate each item in source_refs for shape and sensitive data
  FOR v_elem IN SELECT * FROM jsonb_array_elements(v_target_row.source_refs) LOOP
    IF jsonb_typeof(v_elem) <> 'object' THEN
      RAISE EXCEPTION 'PROFILE_PROVENANCE_INVALID' USING ERRCODE = '22000';
    END IF;

    IF (v_elem->>'type') IS NULL OR (v_elem->>'type') <> 'INTERACTION' THEN
      RAISE EXCEPTION 'PROFILE_PROVENANCE_INVALID' USING ERRCODE = '22000';
    END IF;

    IF v_elem ? 'content' OR v_elem ? 'sanitized_content' OR v_elem ? 'message_text'
       OR v_elem ? 'phone' OR v_elem ? 'transcript' OR v_elem ? 'recording'
       OR v_elem ? 'raw_payload' OR v_elem ? 'token' THEN
      RAISE EXCEPTION 'PROFILE_PROVENANCE_INVALID' USING ERRCODE = '22000';
    END IF;

    BEGIN
      v_ref_id := (v_elem->>'id')::uuid;
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'PROFILE_PROVENANCE_INVALID' USING ERRCODE = '22000';
    END;

    IF v_ref_id IS NULL THEN
      RAISE EXCEPTION 'PROFILE_PROVENANCE_INVALID' USING ERRCODE = '22000';
    END IF;
  END LOOP;

  -- Check for duplicate IDs in source_refs
  SELECT count(DISTINCT (elem->>'id')::uuid), count(*)
  INTO v_unique_source_count, v_total_source_count
  FROM jsonb_array_elements(v_target_row.source_refs) elem;

  IF v_unique_source_count <> v_total_source_count THEN
    RAISE EXCEPTION 'PROFILE_PROVENANCE_INVALID' USING ERRCODE = '22000';
  END IF;

  -- 3. Revalidate each source interaction against public.interactions:
  -- same company, actor_type = SALE, actor_user_id = target sale, direction = OUTBOUND,
  -- type = MESSAGE, sanitization_status = SUCCEEDED, sanitized_content IS NOT NULL & non-empty
  FOR v_elem IN SELECT * FROM jsonb_array_elements(v_target_row.source_refs) LOOP
    v_ref_id := (v_elem->>'id')::uuid;

    SELECT
      i.company_id,
      i.actor_type,
      i.actor_user_id,
      i.direction,
      i.type,
      i.sanitization_status,
      i.sanitized_content
    INTO
      v_int_company_id,
      v_int_actor_type,
      v_int_actor_user_id,
      v_int_direction,
      v_int_type,
      v_int_sanitization_status,
      v_int_sanitized_content
    FROM public.interactions i
    WHERE i.id = v_ref_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'PROFILE_SOURCE_INVALID' USING ERRCODE = 'P0002';
    END IF;

    IF v_int_company_id <> v_target_company_id THEN
      RAISE EXCEPTION 'PROFILE_SOURCE_INVALID' USING ERRCODE = '42501';
    END IF;

    IF v_int_actor_type <> 'SALE' OR v_int_actor_user_id <> v_target_sale_user_id THEN
      RAISE EXCEPTION 'PROFILE_SOURCE_INVALID' USING ERRCODE = '22000';
    END IF;

    IF v_int_direction <> 'OUTBOUND' THEN
      RAISE EXCEPTION 'PROFILE_SOURCE_INVALID' USING ERRCODE = '22000';
    END IF;

    IF v_int_type <> 'MESSAGE' THEN
      RAISE EXCEPTION 'PROFILE_SOURCE_INVALID' USING ERRCODE = '22000';
    END IF;

    IF v_int_sanitization_status <> 'SUCCEEDED' THEN
      RAISE EXCEPTION 'PROFILE_SOURCE_INVALID' USING ERRCODE = '22000';
    END IF;

    IF v_int_sanitized_content IS NULL OR pg_catalog.btrim(v_int_sanitized_content) = '' THEN
      RAISE EXCEPTION 'PROFILE_SOURCE_INVALID' USING ERRCODE = '22000';
    END IF;
  END LOOP;

  -- 4. Style safety at activation: DB-level business policy firewall
  IF v_target_row.salutation_rules IS NULL OR jsonb_typeof(v_target_row.salutation_rules) <> 'object'
     OR v_target_row.sentence_style IS NULL OR jsonb_typeof(v_target_row.sentence_style) <> 'object'
     OR v_target_row.question_style IS NULL OR jsonb_typeof(v_target_row.question_style) <> 'object'
     OR v_target_row.objection_style IS NULL OR jsonb_typeof(v_target_row.objection_style) <> 'object'
     OR v_target_row.closing_style IS NULL OR jsonb_typeof(v_target_row.closing_style) <> 'object' THEN
    RAISE EXCEPTION 'PROFILE_STYLE_POLICY_UNSAFE' USING ERRCODE = '22000';
  END IF;

  v_combined_style_text := v_target_row.salutation_rules::text || ' ' ||
                           v_target_row.sentence_style::text || ' ' ||
                           v_target_row.question_style::text || ' ' ||
                           v_target_row.objection_style::text || ' ' ||
                           v_target_row.closing_style::text;

  IF v_combined_style_text ~* '(giảm\s*giá|chiết\s*khấu|\ydiscount\y|khuyến\s*m[aã]i|%|\ypercent\y|\yphần\s*trăm\y|giá\s*bán|mức\s*giá|báo\s*giá|bảng\s*giá|đơn\s*giá|\yvnđ\y|\yvnd\y|₫|đặt\s*cọc|tiền\s*cọc|\ycọc\y|payment\s*terms|\ythanh\s*toán\y|\ypayment\y|chuyển\s*khoản|trả\s*góp|hợp\s*đồng|\ycontract\y|bảo\s*hành|\ywarranty\y|\yphí\y|lãi\s*suất|cam\s*kết\s*(giao\s*hàng|bảo\s*hành|tiến\s*độ|giá|doanh\s*nghiệp|chất\s*lượng|hoàn\s*tiền))'
     OR v_combined_style_text ~* '\m\d+([\.,]\d{3})*\s*(triệu|nghìn|ngàn|tr|k|đồng|đ)\M' THEN
    RAISE EXCEPTION 'PROFILE_STYLE_POLICY_UNSAFE' USING ERRCODE = '22000';
  END IF;

  -- 5. Legacy examples validation: array 0..5 items, metadata only, strictly no content/sanitized_content/phone/etc.
  IF v_target_row.examples IS NULL OR jsonb_typeof(v_target_row.examples) <> 'array' THEN
    RAISE EXCEPTION 'PROFILE_EXAMPLES_UNSAFE' USING ERRCODE = '22000';
  END IF;

  IF jsonb_array_length(v_target_row.examples) > 5 THEN
    RAISE EXCEPTION 'PROFILE_EXAMPLES_UNSAFE' USING ERRCODE = '22000';
  END IF;

  FOR v_ex IN SELECT * FROM jsonb_array_elements(v_target_row.examples) LOOP
    IF jsonb_typeof(v_ex) <> 'object' THEN
      RAISE EXCEPTION 'PROFILE_EXAMPLES_UNSAFE' USING ERRCODE = '22000';
    END IF;

    -- Forbid sensitive / leaky keys in examples
    IF v_ex ? 'content' OR v_ex ? 'sanitized_content' OR v_ex ? 'message_text'
       OR v_ex ? 'phone' OR v_ex ? 'transcript' OR v_ex ? 'recording'
       OR v_ex ? 'raw_payload' OR v_ex ? 'token' THEN
      RAISE EXCEPTION 'PROFILE_EXAMPLES_UNSAFE' USING ERRCODE = '22000';
    END IF;

    -- Metadata shape check: must contain interaction_id, channel, created_at
    IF NOT (v_ex ? 'interaction_id' AND v_ex ? 'channel' AND v_ex ? 'created_at') THEN
      RAISE EXCEPTION 'PROFILE_EXAMPLES_UNSAFE' USING ERRCODE = '22000';
    END IF;

    -- Strict whitelist: no other keys allowed
    IF (SELECT count(*) FROM jsonb_object_keys(v_ex) k WHERE k NOT IN ('interaction_id', 'channel', 'created_at')) > 0 THEN
      RAISE EXCEPTION 'PROFILE_EXAMPLES_UNSAFE' USING ERRCODE = '22000';
    END IF;

    BEGIN
      PERFORM (v_ex->>'interaction_id')::uuid;
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'PROFILE_EXAMPLES_UNSAFE' USING ERRCODE = '22000';
    END;
  END LOOP;

  -- Transaction timestamp for atomic transition
  v_now := clock_timestamp();

  -- 6. Lock current ACTIVE profile for this sale (if any exists)
  SELECT *
  INTO v_old_active_row
  FROM public.sales_style_profiles ssp
  WHERE ssp.company_id = v_target_company_id
    AND ssp.sale_user_id = v_target_sale_user_id
    AND ssp.generation_status = 'ACTIVE'
  FOR UPDATE;

  -- 7. Supersede old active profile if found
  IF FOUND AND v_old_active_row.id IS NOT NULL THEN
    UPDATE public.sales_style_profiles ssp
    SET generation_status = 'SUPERSEDED',
        superseded_at = v_now,
        superseded_by_profile_id = p_profile_id,
        updated_at = v_now
    WHERE ssp.id = v_old_active_row.id;

    -- Mandatory audit log for superseded profile
    INSERT INTO public.audit_logs (
      company_id,
      user_id,
      action,
      resource_type,
      resource_id,
      customer_id,
      result,
      metadata
    ) VALUES (
      v_target_company_id,
      v_actor_user_id,
      'SALES_STYLE_PROFILE_SUPERSEDED',
      'SALES_STYLE_PROFILE',
      v_old_active_row.id,
      NULL,
      'SUCCESS',
      jsonb_build_object(
        'sale_user_id', v_target_sale_user_id,
        'superseded_by_profile_id', p_profile_id
      )
    );
  END IF;

  -- 8. Activate target profile
  UPDATE public.sales_style_profiles ssp
  SET generation_status = 'ACTIVE',
      activated_at = v_now,
      activated_by_user_id = v_actor_user_id,
      updated_at = v_now
  WHERE ssp.id = p_profile_id
  RETURNING * INTO v_target_row;

  -- Mandatory audit log for activated profile
  INSERT INTO public.audit_logs (
    company_id,
    user_id,
    action,
    resource_type,
    resource_id,
    customer_id,
    result,
    metadata
  ) VALUES (
    v_target_company_id,
    v_actor_user_id,
    'SALES_STYLE_PROFILE_ACTIVATED',
    'SALES_STYLE_PROFILE',
    p_profile_id,
    NULL,
    'SUCCESS',
    jsonb_build_object(
      'sale_user_id', v_target_sale_user_id,
      'version', v_target_row.version,
      'previous_active_profile_id', v_old_active_row.id
    )
  );

  RETURN QUERY SELECT
    v_target_row.id,
    v_target_row.company_id,
    v_target_row.sale_user_id,
    v_target_row.version,
    v_target_row.salutation_rules,
    v_target_row.sentence_style,
    v_target_row.question_style,
    v_target_row.objection_style,
    v_target_row.closing_style,
    v_target_row.examples,
    v_target_row.source_refs,
    v_target_row.model_version,
    v_target_row.generation_status,
    v_target_row.activated_at,
    v_target_row.activated_by_user_id,
    v_target_row.superseded_at,
    v_target_row.superseded_by_profile_id,
    v_target_row.created_at,
    v_target_row.updated_at;
  RETURN;
END;
$$;

CREATE INDEX IF NOT EXISTS idx_appointments_company_survey_created
  ON public.appointments (company_id, created_at)
  WHERE (type = 'SURVEY');

CREATE INDEX IF NOT EXISTS idx_care_deliveries_company_sent_at
  ON public.care_deliveries (company_id, sent_at)
  WHERE (sent_at IS NOT NULL);

CREATE INDEX IF NOT EXISTS idx_care_deliveries_company_converted_at
  ON public.care_deliveries (company_id, converted_to_sale_at)
  WHERE (converted_to_sale_at IS NOT NULL);

CREATE OR REPLACE FUNCTION public.begin_survey_photo_operation(
  p_appointment_id uuid,
  p_actor_id uuid
)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  a public.appointments;
  v_op public.survey_photo_operations;
  v_token uuid;
BEGIN
  SELECT * INTO a FROM public.appointments WHERE id = p_appointment_id FOR UPDATE;
  IF NOT FOUND OR a.type <> 'SURVEY' OR a.status NOT IN ('ASSIGNED','ACCEPTED','IN_PROGRESS') THEN
    RAISE EXCEPTION 'INVALID_SURVEY_PHOTO_RESOURCE';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.user_profiles p JOIN public.company_members m ON m.user_id = p.id
    WHERE p.id = p_actor_id AND p.status = 'ACTIVE' AND m.status = 'ACTIVE'
      AND m.company_id = a.company_id
      AND (m.role = 'BOSS_ADMIN' OR (m.role = 'TECHNICIAN' AND a.assignee_id = p_actor_id))
  ) THEN RAISE EXCEPTION 'SURVEY_PHOTO_FORBIDDEN'; END IF;

  SELECT * INTO v_op FROM public.survey_photo_operations
  WHERE appointment_id = a.id FOR UPDATE;

  IF FOUND THEN
    IF v_op.expires_at > pg_catalog.now() THEN
      RAISE EXCEPTION 'SURVEY_PHOTO_OPERATION_IN_PROGRESS';
    END IF;
    -- Expired lock: atomically reclaim it with new token and fixed 15-minute lease
    v_token := pg_catalog.gen_random_uuid();
    UPDATE public.survey_photo_operations
    SET token = v_token,
        actor_id = p_actor_id,
        started_at = pg_catalog.now(),
        expires_at = pg_catalog.now() + interval '15 minutes'
    WHERE appointment_id = a.id;
    RETURN v_token;
  END IF;

  v_token := pg_catalog.gen_random_uuid();
  INSERT INTO public.survey_photo_operations(appointment_id, token, actor_id, started_at, expires_at)
  VALUES (a.id, v_token, p_actor_id, pg_catalog.now(), pg_catalog.now() + interval '15 minutes');
  RETURN v_token;
END $$;

CREATE OR REPLACE FUNCTION public.end_survey_photo_operation(p_appointment_id uuid, p_token uuid)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  v_deleted_id uuid;
BEGIN
  PERFORM 1 FROM public.appointments WHERE id = p_appointment_id FOR UPDATE;
  DELETE FROM public.survey_photo_operations
  WHERE appointment_id = p_appointment_id AND token = p_token
  RETURNING appointment_id INTO v_deleted_id;

  IF v_deleted_id IS NULL THEN
    RAISE EXCEPTION 'SURVEY_PHOTO_GUARD_MISMATCH';
  END IF;
END $$;

CREATE OR REPLACE FUNCTION public.guard_survey_appointment_write()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND OLD.type = 'SURVEY' THEN
    IF OLD.status IN ('COMPLETED','CANCELLED','REJECTED') THEN
      IF NEW.status IS DISTINCT FROM OLD.status OR
         NEW.address IS DISTINCT FROM OLD.address OR
         NEW.assignee_id IS DISTINCT FROM OLD.assignee_id OR
         NEW.type IS DISTINCT FROM OLD.type THEN
        RAISE EXCEPTION 'SURVEY_APPOINTMENT_TERMINAL';
      END IF;
    END IF;
    -- A live (unexpired) photo operation blocks modifications
    IF EXISTS (
      SELECT 1 FROM public.survey_photo_operations
      WHERE appointment_id = OLD.id AND expires_at > pg_catalog.now()
    ) THEN
      RAISE EXCEPTION 'SURVEY_PHOTO_OPERATION_IN_PROGRESS';
    END IF;
    IF OLD.status <> 'COMPLETED' AND NEW.status = 'COMPLETED' THEN
      IF pg_catalog.current_setting('app.survey_completion', true) IS DISTINCT FROM NEW.id::text
         OR NOT EXISTS (SELECT 1 FROM public.surveys s WHERE s.appointment_id = NEW.id
           AND s.company_id = NEW.company_id AND s.customer_id = NEW.customer_id
           AND s.completed_by = NEW.assignee_id) THEN
        RAISE EXCEPTION 'SURVEY_COMPLETION_REQUIRES_ATOMIC_RPC';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION public.complete_survey_atomic(
  p_appointment_id uuid, p_completed_by uuid, p_survey_payload jsonb
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  a public.appointments;
  s public.surveys;
  v_now timestamptz := pg_catalog.now();
  m jsonb;
  c jsonb;
  v_photos jsonb := '[]'::jsonb;
  v_slot text;
  v_path text;
  v_key text;
  v_min numeric;
  v_max numeric;
BEGIN
  SELECT * INTO a FROM public.appointments WHERE id = p_appointment_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'APPOINTMENT_NOT_FOUND'; END IF;
  IF a.type <> 'SURVEY' THEN RAISE EXCEPTION 'APPOINTMENT_TYPE_NOT_SURVEY'; END IF;
  IF p_completed_by IS NULL OR a.assignee_id IS DISTINCT FROM p_completed_by THEN
    RAISE EXCEPTION 'INVALID_COMPLETED_BY';
  END IF;
  -- Lock actor records too: deactivation must serialize with this completion transaction.
  PERFORM 1 FROM public.user_profiles p JOIN public.company_members cm ON cm.user_id = p.id
    WHERE p.id = p_completed_by AND p.status = 'ACTIVE'
      AND cm.company_id = a.company_id AND cm.status = 'ACTIVE' AND cm.role = 'TECHNICIAN'
    FOR SHARE OF p, cm;
  IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_COMPLETED_BY'; END IF;

  SELECT * INTO s FROM public.surveys WHERE appointment_id = a.id;
  IF a.status = 'COMPLETED' THEN
    IF s.id IS NULL OR s.company_id <> a.company_id OR s.customer_id <> a.customer_id
       OR s.completed_by IS DISTINCT FROM p_completed_by THEN
      RAISE EXCEPTION 'SURVEY_COMPLETION_INCONSISTENT';
    END IF;
    RETURN pg_catalog.jsonb_build_object('id', s.id, 'isExisting', true);
  END IF;
  IF a.status NOT IN ('ACCEPTED','IN_PROGRESS') THEN RAISE EXCEPTION 'INVALID_PREDECESSOR_STATE'; END IF;
  IF s.id IS NOT NULL THEN RAISE EXCEPTION 'SURVEY_ALREADY_EXISTS'; END IF;
  -- A live (unexpired) photo operation blocks completion
  IF EXISTS (
    SELECT 1 FROM public.survey_photo_operations
    WHERE appointment_id = a.id AND expires_at > pg_catalog.now()
  ) THEN
    RAISE EXCEPTION 'SURVEY_PHOTO_OPERATION_IN_PROGRESS';
  END IF;

  m := p_survey_payload->'measurements';
  c := (p_survey_payload->>'site_condition')::jsonb;
  IF pg_catalog.jsonb_typeof(m) IS DISTINCT FROM 'object' OR pg_catalog.jsonb_typeof(c) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'INVALID_SURVEY_TECHNICAL_INPUT';
  END IF;
  FOR v_key, v_min, v_max IN VALUES ('clear_width_mm',500,15000),
      ('barrier_height_mm',100,3000),('anticipated_flood_height_mm',100,3000) LOOP
    IF pg_catalog.jsonb_typeof(m->v_key) IS DISTINCT FROM 'number' THEN RAISE EXCEPTION 'INVALID_SURVEY_MEASUREMENT'; END IF;
    IF (m->>v_key)::numeric NOT BETWEEN v_min AND v_max
       OR pg_catalog.trunc((m->>v_key)::numeric) <> (m->>v_key)::numeric THEN
      RAISE EXCEPTION 'INVALID_SURVEY_MEASUREMENT';
    END IF;
  END LOOP;
  IF m ? 'step_height_mm' AND (pg_catalog.jsonb_typeof(m->'step_height_mm') <> 'number'
      OR (m->>'step_height_mm')::numeric NOT BETWEEN 0 AND 1000) THEN
    RAISE EXCEPTION 'INVALID_SURVEY_MEASUREMENT';
  END IF;
  IF NOT coalesce(m->>'gate_type' IN ('REMOVABLE_PANEL','AUTOMATIC_HYDRAULIC','ROLL_UP_CANVAS','SWING_GATE'),false)
    OR NOT coalesce(m->>'mounting_method' IN ('INSIDE_JAMB','OUTSIDE_FACE','INSIDE_FACE'),false)
    OR NOT coalesce(c->>'wall_material' IN ('SOLID_BRICK','HOLLOW_BRICK','CONCRETE','STEEL_FRAME','ALUMINUM_GLASS','STONE_TILES'),false)
    OR NOT coalesce(c->>'floor_material' IN ('CONCRETE_SMOOTH','TILES','NATURAL_STONE','ROUGH_CEMENT','PAVING_BRICK'),false)
    OR NOT coalesce(c->>'floor_evenness' IN ('FLAT','SLIGHTLY_UNEVEN','HIGHLY_UNEVEN'),false)
    OR NOT coalesce(c->>'slope_grade' IN ('SLOPING_OUT','LEVEL','SLOPING_IN'),false) THEN
    RAISE EXCEPTION 'INVALID_SURVEY_TECHNICAL_INPUT';
  END IF;
  IF pg_catalog.length(coalesce(p_survey_payload->>'notes','')) > 1000
    OR pg_catalog.length(coalesce(c->>'notes','')) > 1000 OR pg_catalog.length(coalesce(c->>'specialRequirements','')) > 1000 THEN
    RAISE EXCEPTION 'INVALID_SURVEY_NOTES';
  END IF;

  -- Server-owned paths only. Ignore payload.photos, Company, Customer, completed_by and completed_at.
  FOREACH v_slot IN ARRAY ARRAY['OVERVIEW','BOTTOM_LEFT','BOTTOM_RIGHT','OBSTACLE','SLOPE_DETAIL','ADDITIONAL'] LOOP
    v_path := a.company_id::text || '/' || a.customer_id::text || '/' || a.id::text || '/' || v_slot || '.jpg';
    IF EXISTS (SELECT 1 FROM storage.objects WHERE bucket_id = 'survey-photos' AND name = v_path) THEN
      v_photos := v_photos || pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object('slot',v_slot,'objectPath',v_path,
        'uploadedAt',v_now,'slotLabel',v_slot,'isMandatory',v_slot IN ('OVERVIEW','BOTTOM_LEFT','BOTTOM_RIGHT')));
    ELSIF v_slot IN ('OVERVIEW','BOTTOM_LEFT','BOTTOM_RIGHT') THEN
      RAISE EXCEPTION 'MISSING_MANDATORY_SURVEY_PHOTO';
    END IF;
  END LOOP;

  INSERT INTO public.surveys(company_id,customer_id,appointment_id,completed_by,measurements,photos,
    site_condition,notes,completed_at,created_at,updated_at)
  VALUES (a.company_id,a.customer_id,a.id,p_completed_by,m,v_photos,c::text,p_survey_payload->>'notes',v_now,v_now,v_now)
  RETURNING * INTO s;
  PERFORM pg_catalog.set_config('app.survey_completion', a.id::text, true);
  UPDATE public.appointments SET status = 'COMPLETED', updated_at = v_now
    WHERE id = a.id AND status IN ('ACCEPTED','IN_PROGRESS');
  IF NOT FOUND THEN RAISE EXCEPTION 'SURVEY_APPOINTMENT_UPDATE_FAILED'; END IF;
  PERFORM pg_catalog.set_config('app.survey_completion', '', true);
  RETURN pg_catalog.jsonb_build_object('id',s.id,'isExisting',false);
END $$;

CREATE TRIGGER trg_updated_at_voice_dispatch_commands
  BEFORE UPDATE ON public.voice_dispatch_commands
  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();

CREATE OR REPLACE FUNCTION public.prepare_voice_dispatch_atomic(
  p_company_id uuid,
  p_attempt_id uuid,
  p_idempotency_key text,
  p_provider text
)
RETURNS TABLE (
  call_id uuid,
  customer_id uuid,
  raw_phone text,
  provider_call_id text,
  dispatch_status text,
  is_reconciliation boolean
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_cmd public.voice_dispatch_commands%ROWTYPE;
  v_attempt public.call_attempts%ROWTYPE;
  v_call_id uuid;
  v_phone text;
  v_customer_id uuid;
BEGIN
  -- Advisory lock per attempt to serialize concurrent dispatch requests
  PERFORM pg_advisory_xact_lock(hashtextextended(p_company_id::text || ':attempt_dispatch:' || p_attempt_id::text, 0));

  -- 1. Check existing dispatch command
  SELECT * INTO v_cmd
  FROM public.voice_dispatch_commands
  WHERE company_id = p_company_id AND attempt_id = p_attempt_id
  FOR UPDATE;

  IF FOUND THEN
    -- If provider already accepted or in reconciliation, do NOT call provider again!
    IF v_cmd.status IN ('PROVIDER_ACCEPTED', 'RECONCILIATION_REQUIRED', 'ACTIVE', 'COMPLETED') THEN
      SELECT c.customer_id INTO v_customer_id FROM public.calls c WHERE c.id = v_cmd.call_id;
      RETURN QUERY SELECT
        v_cmd.call_id,
        v_customer_id,
        NULL::text,
        v_cmd.provider_call_id,
        v_cmd.status,
        true;
      RETURN;
    END IF;

    -- If currently dispatching and not stale (< 2 min), reject concurrent duplicate
    IF v_cmd.status = 'DISPATCHING' AND v_cmd.created_at > (now() - interval '2 minutes') THEN
      RAISE EXCEPTION 'VOICE_DISPATCH_IN_PROGRESS';
    END IF;
  END IF;

  -- 2. Verify attempt is PENDING and claimable
  SELECT * INTO v_attempt
  FROM public.call_attempts ca
  WHERE ca.company_id = p_company_id AND ca.id = p_attempt_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'VOICE_ATTEMPT_NOT_FOUND';
  END IF;

  IF v_attempt.result <> 'PENDING' THEN
    RAISE EXCEPTION 'VOICE_ATTEMPT_NOT_CLAIMABLE';
  END IF;

  -- 3. Read raw phone strictly in trusted server context
  SELECT cpc.raw_phone INTO v_phone
  FROM private.customer_private_contacts cpc
  WHERE cpc.company_id = p_company_id AND cpc.customer_id = v_attempt.customer_id;

  IF v_phone IS NULL THEN
    RAISE EXCEPTION 'VOICE_PHONE_NOT_FOUND';
  END IF;

  -- 4. Create durable INITIATED call record
  INSERT INTO public.calls (
    company_id, customer_id, direction, agent_type, provider,
    started_at, status, transcript_status
  ) VALUES (
    p_company_id, v_attempt.customer_id, 'OUTBOUND', 'AI', p_provider,
    now(), 'INITIATED', 'PENDING'
  ) RETURNING id INTO v_call_id;

  -- 5. Bind call to attempt
  UPDATE public.call_attempts
  SET call_id = v_call_id,
      called_at = now()
  WHERE id = p_attempt_id;

  -- 6. Insert mandatory audit log
  INSERT INTO public.audit_logs (
    company_id, user_id, action, resource_type, resource_id, customer_id, result, metadata
  ) VALUES (
    p_company_id, NULL, 'INITIATE_AI_OUTBOUND_CALL', 'CALL', v_call_id, v_attempt.customer_id, 'SUCCESS',
    jsonb_build_object(
      'call_id', v_call_id,
      'attempt_id', p_attempt_id,
      'attempt_no', v_attempt.attempt_no,
      'contact_cycle_id', v_attempt.contact_cycle_id
    )
  );

  -- 7. Persist durable dispatch command
  INSERT INTO public.voice_dispatch_commands (
    company_id, attempt_id, call_id, status, idempotency_key, provider
  ) VALUES (
    p_company_id, p_attempt_id, v_call_id, 'DISPATCHING', p_idempotency_key, p_provider
  )
  ON CONFLICT (company_id, attempt_id) DO UPDATE SET
    call_id = EXCLUDED.call_id,
    status = 'DISPATCHING',
    idempotency_key = EXCLUDED.idempotency_key,
    provider = EXCLUDED.provider,
    updated_at = now();

  RETURN QUERY SELECT
    v_call_id,
    v_attempt.customer_id,
    v_phone,
    NULL::text,
    'DISPATCHING'::text,
    false;
END;
$$;

CREATE OR REPLACE FUNCTION public.finalize_voice_dispatch_atomic(
  p_company_id uuid,
  p_attempt_id uuid,
  p_call_id uuid,
  p_provider_call_id text
)
RETURNS TABLE (
  call_id uuid,
  status text
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
#variable_conflict use_column
DECLARE
  v_cmd public.voice_dispatch_commands%ROWTYPE;
  v_customer_id uuid;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(p_company_id::text || ':call:' || p_call_id::text, 0));

  SELECT * INTO v_cmd
  FROM public.voice_dispatch_commands vdc
  WHERE vdc.company_id = p_company_id AND vdc.attempt_id = p_attempt_id AND vdc.call_id = p_call_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'VOICE_DISPATCH_COMMAND_NOT_FOUND';
  END IF;

  SELECT c.customer_id INTO v_customer_id
  FROM public.calls c
  WHERE c.id = p_call_id AND c.company_id = p_company_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'VOICE_CALL_NOT_FOUND';
  END IF;

  -- Atomically bind provider_call_id and transition call to RINGING
  UPDATE public.calls c
  SET provider_call_id = p_provider_call_id,
      status = 'RINGING'
  WHERE c.id = p_call_id AND c.company_id = p_company_id;

  -- Ensure attempt is bound
  UPDATE public.call_attempts ca
  SET call_id = p_call_id,
      called_at = COALESCE(ca.called_at, now())
  WHERE ca.id = p_attempt_id AND ca.company_id = p_company_id;

  -- Mark command ACTIVE
  UPDATE public.voice_dispatch_commands vdc
  SET status = 'ACTIVE',
      provider_call_id = p_provider_call_id,
      updated_at = now()
  WHERE vdc.id = v_cmd.id;

  -- Atomically record call interaction event
  INSERT INTO public.interactions (
    company_id, customer_id, conversation_id, channel, type, direction,
    sanitized_content, sanitization_status, actor_type, actor_user_id, external_ref
  ) VALUES (
    p_company_id, v_customer_id, NULL, 'AI_VOICE', 'CALL_EVENT', 'OUTBOUND',
    NULL, 'NOT_REQUIRED', 'AI', NULL, p_provider_call_id
  )
  ON CONFLICT DO NOTHING;

  RETURN QUERY SELECT p_call_id, 'CALLING'::text;
END;
$$;

CREATE OR REPLACE FUNCTION public.apply_voice_call_status_atomic(
  p_company_id uuid,
  p_provider text,
  p_provider_call_id text,
  p_new_status text,
  p_event_idempotency_key text,
  p_ended_at timestamptz DEFAULT NULL,
  p_next_retry_at timestamptz DEFAULT NULL
)
RETURNS TABLE (
  call_id uuid,
  customer_id uuid,
  previous_status text,
  current_status text,
  is_duplicate boolean,
  attempt_result text
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
#variable_conflict use_column
DECLARE
  v_call public.calls%ROWTYPE;
  v_attempt public.call_attempts%ROWTYPE;
  v_attempt_res text := NULL;
  v_terminal boolean;
  v_current_terminal boolean;
  v_from_stage text;
  v_to_stage text;
  v_next_attempt_id uuid;
  v_next_no integer;
BEGIN
  -- 1. Advisory lock per tenant + provider + call
  PERFORM pg_advisory_xact_lock(hashtextextended(p_company_id::text || ':' || p_provider || ':' || p_provider_call_id, 0));

  -- 2. Check event idempotency
  INSERT INTO public.voice_webhook_events (
    company_id, provider, idempotency_key, provider_call_id, event_type, status
  ) VALUES (
    p_company_id, p_provider, p_event_idempotency_key, p_provider_call_id, 'STATUS_UPDATE', p_new_status
  )
  ON CONFLICT (company_id, provider, idempotency_key) DO NOTHING;

  IF NOT FOUND THEN
    -- Event was already recorded
    SELECT c.id, c.customer_id, c.status INTO v_call.id, v_call.customer_id, v_call.status
    FROM public.calls c
    WHERE c.company_id = p_company_id AND c.provider = p_provider AND c.provider_call_id = p_provider_call_id;
    RETURN QUERY SELECT v_call.id, v_call.customer_id, v_call.status, v_call.status, true, NULL::text;
    RETURN;
  END IF;

  -- 3. Lock and retrieve call
  SELECT * INTO v_call
  FROM public.calls c
  WHERE c.company_id = p_company_id AND c.provider = p_provider AND c.provider_call_id = p_provider_call_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  v_current_terminal := v_call.status IN ('COMPLETED', 'FAILED', 'NO_ANSWER', 'BUSY');
  v_terminal := p_new_status IN ('COMPLETED', 'FAILED', 'NO_ANSWER', 'BUSY');

  -- Illegal state transition: terminal call cannot revert to non-terminal
  IF v_current_terminal AND NOT v_terminal THEN
    RETURN QUERY SELECT v_call.id, v_call.customer_id, v_call.status, v_call.status, false, NULL::text;
    RETURN;
  END IF;

  -- Update call status
  UPDATE public.calls c
  SET status = p_new_status,
      ended_at = COALESCE(p_ended_at, CASE WHEN v_terminal THEN now() ELSE c.ended_at END)
  WHERE c.id = v_call.id;

  -- Update dispatch command if present
  UPDATE public.voice_dispatch_commands vdc
  SET status = CASE WHEN v_terminal THEN 'COMPLETED' ELSE 'ACTIVE' END,
      updated_at = now()
  WHERE vdc.company_id = p_company_id AND vdc.call_id = v_call.id;

  -- 4. Atomically handle attempt and contact cycle if terminal
  IF v_terminal THEN
    v_attempt_res := CASE p_new_status
      WHEN 'COMPLETED' THEN 'ANSWERED'
      WHEN 'NO_ANSWER' THEN 'NO_ANSWER'
      WHEN 'BUSY' THEN 'BUSY'
      ELSE 'FAILED'
    END;

    SELECT * INTO v_attempt
    FROM public.call_attempts ca
    WHERE ca.company_id = p_company_id AND ca.call_id = v_call.id AND ca.result = 'PENDING'
    FOR UPDATE;

    IF FOUND THEN
      UPDATE public.call_attempts
      SET result = v_attempt_res,
          called_at = COALESCE(called_at, now())
      WHERE id = v_attempt.id;

      IF v_attempt_res NOT IN ('ANSWERED', 'CANCELLED') THEN
        SELECT c.stage INTO v_from_stage
        FROM public.customers c
        WHERE c.company_id = p_company_id AND c.id = v_attempt.customer_id
        FOR UPDATE;

        IF v_attempt.attempt_no < 3 THEN
          v_next_no := v_attempt.attempt_no + 1;
          v_to_stage := CASE v_next_no WHEN 2 THEN 'CONTACT_CYCLE_2' ELSE 'CONTACT_CYCLE_3' END;

          IF p_next_retry_at IS NOT NULL THEN
            INSERT INTO public.call_attempts (
              company_id, customer_id, contact_cycle_id, attempt_no, scheduled_at, result
            ) VALUES (
              p_company_id, v_attempt.customer_id, v_attempt.contact_cycle_id,
              v_next_no, p_next_retry_at, 'PENDING'
            ) RETURNING id INTO v_next_attempt_id;
          END IF;
        ELSE
          v_to_stage := 'UNREACHABLE';
        END IF;

        IF v_to_stage IS NOT NULL THEN
          UPDATE public.customers SET stage = v_to_stage, updated_at = now()
          WHERE company_id = p_company_id AND id = v_attempt.customer_id;

          INSERT INTO public.customer_stage_histories (
            company_id, customer_id, from_stage, to_stage, actor_type, reason, source_ref
          ) VALUES (
            p_company_id, v_attempt.customer_id, v_from_stage, v_to_stage, 'AI',
            CASE WHEN v_attempt.attempt_no = 3 THEN 'NO_ANSWER_3_ATTEMPTS' ELSE 'VOICE_RETRY_SCHEDULED' END,
            v_attempt.contact_cycle_id::text
          );
        END IF;
      END IF;
    END IF;

    -- Insert interaction event for terminal event (idempotent by external_ref)
    INSERT INTO public.interactions (
      company_id, customer_id, conversation_id, channel, type, direction,
      sanitized_content, sanitization_status, actor_type, actor_user_id, external_ref
    ) VALUES (
      p_company_id, v_call.customer_id, NULL, 'AI_VOICE', 'CALL_EVENT', v_call.direction,
      NULL, 'NOT_REQUIRED', 'AI', NULL, p_event_idempotency_key
    )
    ON CONFLICT DO NOTHING;
  END IF;

  RETURN QUERY SELECT v_call.id, v_call.customer_id, v_call.status, p_new_status, false, v_attempt_res;
END;
$$;

CREATE OR REPLACE FUNCTION public.ingest_inbound_voice_call_atomic(
  p_company_id uuid,
  p_provider text,
  p_provider_call_id text,
  p_normalized_phone text,
  p_raw_phone text,
  p_phone_identity_hash text
)
RETURNS TABLE (
  call_id uuid,
  customer_id uuid,
  created boolean
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
#variable_conflict use_column
DECLARE
  v_call_id uuid;
  v_customer_id uuid;
  v_existing_call public.calls%ROWTYPE;
BEGIN
  IF p_provider NOT IN ('STRINGEE', 'VIETTEL', 'TWILIO', 'VINFON') OR p_provider_call_id IS NULL THEN
    RAISE EXCEPTION 'VOICE_PROVIDER_CALL_INVALID';
  END IF;
  IF p_normalized_phone !~ '^\+[1-9][0-9]{7,14}$' OR p_phone_identity_hash !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'VOICE_PHONE_IDENTITY_INVALID';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.companies c WHERE c.id = p_company_id) THEN
    RAISE EXCEPTION 'VOICE_COMPANY_NOT_FOUND';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(p_company_id::text || ':' || p_normalized_phone, 0));
  PERFORM pg_advisory_xact_lock(hashtextextended(p_company_id::text || ':' || p_provider || ':' || p_provider_call_id, 0));

  -- 1. Check if call already exists
  SELECT * INTO v_existing_call
  FROM public.calls c
  WHERE c.company_id = p_company_id AND c.provider = p_provider AND c.provider_call_id = p_provider_call_id;

  IF v_existing_call.id IS NOT NULL THEN
    RETURN QUERY SELECT v_existing_call.id, v_existing_call.customer_id, false;
    RETURN;
  END IF;

  -- 2. Resolve customer by normalized phone or identity hash
  SELECT cpc.customer_id INTO v_customer_id
  FROM private.customer_private_contacts cpc
  WHERE cpc.company_id = p_company_id AND cpc.normalized_phone = p_normalized_phone
  FOR UPDATE;

  IF v_customer_id IS NULL THEN
    SELECT i.customer_id INTO v_customer_id
    FROM public.identities i
    WHERE i.company_id = p_company_id AND i.channel = 'PHONE' AND i.external_id = p_phone_identity_hash;
  END IF;

  IF v_customer_id IS NULL THEN
    -- Invariant: ZERO-PHONE in public.customers
    INSERT INTO public.customers (company_id, name, source, stage)
    VALUES (p_company_id, 'Khách gọi Hotline', 'HOTLINE', 'LEAD_NEW')
    RETURNING id INTO v_customer_id;

    -- Raw phone stored strictly in private schema
    INSERT INTO private.customer_private_contacts (
      company_id, customer_id, normalized_phone, raw_phone, is_verified
    ) VALUES (p_company_id, v_customer_id, p_normalized_phone, p_raw_phone, false);
  ELSE
    INSERT INTO private.customer_private_contacts (
      company_id, customer_id, normalized_phone, raw_phone, is_verified
    ) VALUES (p_company_id, v_customer_id, p_normalized_phone, p_raw_phone, false)
    ON CONFLICT (customer_id) DO UPDATE SET
      normalized_phone = EXCLUDED.normalized_phone,
      raw_phone = EXCLUDED.raw_phone,
      updated_at = now()
    WHERE private.customer_private_contacts.company_id = p_company_id;
  END IF;

  -- Bind identity
  INSERT INTO public.identities (company_id, customer_id, channel, external_id, verified, metadata)
  VALUES (p_company_id, v_customer_id, 'PHONE', p_phone_identity_hash, false, '{}'::jsonb)
  ON CONFLICT (company_id, channel, external_id) DO NOTHING;

  -- 3. Create call record
  INSERT INTO public.calls (
    company_id, customer_id, direction, agent_type, provider, provider_call_id,
    started_at, status, transcript_status
  ) VALUES (
    p_company_id, v_customer_id, 'INBOUND', 'AI', p_provider, p_provider_call_id,
    now(), 'CONNECTED', 'PENDING'
  ) RETURNING id INTO v_call_id;

  -- 4. Create interaction record
  INSERT INTO public.interactions (
    company_id, customer_id, conversation_id, channel, type, direction,
    sanitized_content, sanitization_status, actor_type, actor_user_id, external_ref
  ) VALUES (
    p_company_id, v_customer_id, NULL, 'HOTLINE', 'CALL_EVENT', 'INBOUND',
    NULL, 'NOT_REQUIRED', 'SYSTEM', NULL, p_provider_call_id
  );

  RETURN QUERY SELECT v_call_id, v_customer_id, true;
END;
$$;

CREATE OR REPLACE FUNCTION public.attach_call_recording_ref_atomic(
  p_company_id uuid,
  p_call_id uuid,
  p_recording_ref text,
  p_lock_token uuid DEFAULT NULL
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_expected_prefix text;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.calls c
    WHERE c.company_id = p_company_id AND c.id = p_call_id
  ) THEN
    RAISE EXCEPTION 'VOICE_CALL_SCOPE_MISMATCH';
  END IF;

  -- Verify deterministic storage path pattern: tenant/resource bound
  v_expected_prefix := p_company_id::text || '/' || p_call_id::text || '/';
  IF NOT (
    p_recording_ref LIKE v_expected_prefix || '%' OR
    p_recording_ref LIKE 'call-recordings/' || v_expected_prefix || '%' OR
    p_recording_ref LIKE 'voice/' || v_expected_prefix || '%'
  ) THEN
    RAISE EXCEPTION 'VOICE_RECORDING_PATH_ILLEGAL';
  END IF;

  -- Verify audio file extension
  IF NOT (p_recording_ref ~* '\.(mp3|mp4|ogg|wav|webm)$') THEN
    RAISE EXCEPTION 'VOICE_RECORDING_EXTENSION_ILLEGAL';
  END IF;

  IF p_lock_token IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.voice_media_jobs vmj
      WHERE vmj.company_id = p_company_id AND vmj.call_id = p_call_id
        AND vmj.status = 'PROCESSING' AND vmj.lock_token = p_lock_token
    ) THEN
      RAISE EXCEPTION 'VOICE_MEDIA_JOB_LOCK_INVALID';
    END IF;
  END IF;

  UPDATE public.calls
  SET recording_ref = p_recording_ref,
      transcript_status = 'PENDING'
  WHERE id = p_call_id AND company_id = p_company_id;
END;
$$;

CREATE OR REPLACE FUNCTION public.start_voice_contact_cycle(
  p_company_id uuid,
  p_customer_id uuid,
  p_contact_cycle_id uuid,
  p_scheduled_at timestamptz
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_from_stage text;
  v_attempt_id uuid;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(p_company_id::text || ':contact_cycle:' || p_customer_id::text, 0));

  SELECT c.stage INTO v_from_stage
  FROM public.customers c
  WHERE c.company_id = p_company_id AND c.id = p_customer_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'VOICE_CUSTOMER_NOT_FOUND'; END IF;

  -- Predecessor validation: ONLY 'LEAD_NEW' can enter a fresh contact cycle
  IF v_from_stage <> 'LEAD_NEW' THEN
    RAISE EXCEPTION 'VOICE_CONTACT_CYCLE_ILLEGAL_PREDECESSOR';
  END IF;

  -- Check no active pending attempts across any cycles
  IF EXISTS (
    SELECT 1 FROM public.call_attempts ca
    WHERE ca.company_id = p_company_id AND ca.customer_id = p_customer_id AND ca.result = 'PENDING'
  ) THEN
    RAISE EXCEPTION 'VOICE_PENDING_ATTEMPT_EXISTS';
  END IF;

  -- Check unique cycle invariant: cannot restart same contact cycle
  IF EXISTS (
    SELECT 1 FROM public.call_attempts ca
    WHERE ca.company_id = p_company_id AND ca.customer_id = p_customer_id
      AND ca.contact_cycle_id = p_contact_cycle_id
  ) THEN
    RAISE EXCEPTION 'VOICE_CYCLE_ALREADY_EXISTS';
  END IF;

  INSERT INTO public.call_attempts (
    company_id, customer_id, contact_cycle_id, attempt_no, scheduled_at, result
  ) VALUES (p_company_id, p_customer_id, p_contact_cycle_id, 1, p_scheduled_at, 'PENDING')
  RETURNING id INTO v_attempt_id;

  UPDATE public.customers SET stage = 'CONTACT_CYCLE_1', updated_at = now()
  WHERE company_id = p_company_id AND id = p_customer_id;

  INSERT INTO public.customer_stage_histories (
    company_id, customer_id, from_stage, to_stage, actor_type, reason, source_ref
  ) VALUES (
    p_company_id, p_customer_id, v_from_stage, 'CONTACT_CYCLE_1', 'AI',
    'CONTACT_CYCLE_STARTED', p_contact_cycle_id::text
  );

  RETURN v_attempt_id;
END;
$$;

