CREATE FUNCTION public.operations_actor(p_company uuid,p_actor uuid,p_roles text[])
RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE r text;
BEGIN
 SELECT m.role INTO r FROM public.company_members m JOIN public.user_profiles u ON u.id=m.user_id
 WHERE m.company_id=p_company AND m.user_id=p_actor AND m.status='ACTIVE' AND u.status='ACTIVE'
 FOR SHARE OF m,u;
 IF r IS NULL OR NOT(r=ANY(p_roles)) THEN RAISE EXCEPTION 'PERMISSION_DENIED'; END IF;
 RETURN r;
END $$;

CREATE FUNCTION public.operations_audit(p_company uuid,p_actor uuid,p_action text,p_table text,p_id uuid,p_metadata jsonb)
RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$
 INSERT INTO public.audit_logs(company_id,user_id,action,resource_type,resource_id,result,metadata)
 VALUES(p_company,p_actor,p_action,p_table,p_id,'SUCCESS',p_metadata);
$$;

CREATE FUNCTION public.operations_evidence_ref(p_company uuid,p_installation uuid,p_ref text,p_type text)
RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path='' AS $$
 SELECT COALESCE(p_ref ~ ('^' || p_company::text || '/installations/' || p_installation::text || '/' ||
 CASE p_type WHEN 'photo' THEN 'photo/[0-9a-f-]{36}\.(jpg|png|webp)' WHEN 'handover' THEN 'handover/[0-9a-f-]{36}\.pdf' ELSE '$a' END || '$'),false);
$$;

CREATE FUNCTION public.create_production_order_atomic(p_company_id uuid,p_order_id uuid,p_actor_id uuid,p_specs jsonb,p_materials jsonb,p_deadline timestamptz)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE o public.orders; c public.contracts; p public.production_orders;
BEGIN
 PERFORM public.operations_actor(p_company_id,p_actor_id,ARRAY['BOSS_ADMIN']);
 SELECT * INTO o FROM public.orders WHERE company_id=p_company_id AND id=p_order_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'RESOURCE_NOT_FOUND'; END IF;
 IF o.order_status NOT IN ('CONTRACT_SIGNED','DEPOSIT_CONFIRMED') THEN RAISE EXCEPTION 'INVALID_STATE_TRANSITION'; END IF;
 SELECT * INTO c FROM public.contracts WHERE company_id=p_company_id AND order_id=o.id AND is_current FOR UPDATE;
 IF NOT FOUND OR c.status <> 'SIGNED' OR NULLIF(btrim(c.signed_file_ref),'') IS NULL THEN RAISE EXCEPTION 'CONTRACT_NOT_SIGNED'; END IF;
 IF EXISTS(SELECT 1 FROM public.production_orders WHERE order_id=o.id) THEN RAISE EXCEPTION 'PRODUCTION_ALREADY_EXISTS'; END IF;
 INSERT INTO public.production_orders(company_id,order_id,specs,materials,status,deadline,qc_status)
 VALUES(p_company_id,o.id,p_specs,p_materials,'RELEASED_TO_FACTORY',p_deadline,'PENDING') RETURNING * INTO p;
 UPDATE public.orders SET order_status='IN_PRODUCTION',updated_at=now() WHERE id=o.id;
 PERFORM public.operations_audit(p_company_id,p_actor_id,'CREATE_PRODUCTION_ORDER','production_orders',p.id,jsonb_build_object('order_id',o.id));
 RETURN to_jsonb(p);
END $$;

CREATE FUNCTION public.update_production_progress_atomic(p_company_id uuid,p_production_order_id uuid,p_actor_id uuid,p_status text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE p public.production_orders;
BEGIN
 PERFORM public.operations_actor(p_company_id,p_actor_id,ARRAY['BOSS_ADMIN']);
 SELECT * INTO p FROM public.production_orders WHERE company_id=p_company_id AND id=p_production_order_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'RESOURCE_NOT_FOUND'; END IF;
 IF p_status IS NULL OR p_status NOT IN ('RELEASED_TO_FACTORY','IN_PRODUCTION','QC_IN_PROGRESS') OR NOT (
 (p.status='PENDING_SPECS' AND p_status='RELEASED_TO_FACTORY') OR
 (p.status IN ('RELEASED_TO_FACTORY','QC_IN_PROGRESS','QC_FAILED','READY_FOR_DISPATCH') AND p_status='IN_PRODUCTION') OR
 (p.status='IN_PRODUCTION' AND p_status='QC_IN_PROGRESS')) THEN RAISE EXCEPTION 'INVALID_STATE_TRANSITION'; END IF;
 UPDATE public.production_orders SET status=p_status,qc_status=CASE WHEN p_status='IN_PRODUCTION' THEN 'PENDING' ELSE qc_status END,updated_at=now() WHERE id=p.id;
 PERFORM public.operations_audit(p_company_id,p_actor_id,'UPDATE_PRODUCTION_PROGRESS','production_orders',p.id,jsonb_build_object('from_status',p.status,'to_status',p_status));
END $$;

CREATE OR REPLACE FUNCTION public.record_quality_check_atomic(p_company_id uuid,p_production_order_id uuid,p_qc_status text,p_inspector_id uuid,p_notes text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE p public.production_orders; o public.orders; next_status text;
BEGIN
 PERFORM public.operations_actor(p_company_id,p_inspector_id,ARRAY['BOSS_ADMIN']);
 SELECT * INTO p FROM public.production_orders WHERE company_id=p_company_id AND id=p_production_order_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'RESOURCE_NOT_FOUND'; END IF;
 SELECT * INTO o FROM public.orders WHERE company_id=p_company_id AND id=p.order_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'RESOURCE_NOT_FOUND'; END IF;
 IF p.status <> 'QC_IN_PROGRESS' OR o.order_status <> 'IN_PRODUCTION' THEN RAISE EXCEPTION 'INVALID_STATE_TRANSITION'; END IF;
 IF p_qc_status IS NULL OR p_qc_status NOT IN ('PASSED','REWORK_REQUIRED','REJECTED') THEN RAISE EXCEPTION 'INVALID_INPUT'; END IF;
 next_status := CASE WHEN p_qc_status='PASSED' THEN 'READY_FOR_DISPATCH' ELSE 'QC_FAILED' END;
 UPDATE public.production_orders SET status=next_status,qc_status=p_qc_status,updated_at=now() WHERE id=p.id;
 IF p_qc_status='PASSED' THEN UPDATE public.orders SET order_status='READY_FOR_INSTALL',updated_at=now() WHERE id=o.id; END IF;
 PERFORM public.operations_audit(p_company_id,p_inspector_id,'RECORD_QUALITY_CHECK','production_orders',p.id,jsonb_build_object('from_status',p.status,'to_status',next_status,'qc_status',p_qc_status));
 RETURN jsonb_build_object('success',true);
END $$;

CREATE FUNCTION public.schedule_installation_atomic(p_company_id uuid,p_order_id uuid,p_customer_id uuid,p_appointment_id uuid,p_crew jsonb,p_actor_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE o public.orders; p public.production_orders; a public.appointments; i public.installations;
BEGIN
 PERFORM public.operations_actor(p_company_id,p_actor_id,ARRAY['BOSS_ADMIN']);
 -- Match QC's production -> order lock order to avoid deadlocks.
 SELECT * INTO p FROM public.production_orders WHERE company_id=p_company_id AND order_id=p_order_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'RESOURCE_NOT_FOUND'; END IF;
 SELECT * INTO o FROM public.orders WHERE company_id=p_company_id AND id=p_order_id FOR UPDATE;
 IF NOT FOUND OR o.customer_id<>p_customer_id THEN RAISE EXCEPTION 'RESOURCE_NOT_FOUND'; END IF;
 SELECT * INTO a FROM public.appointments WHERE company_id=p_company_id AND id=p_appointment_id FOR UPDATE;
 IF NOT FOUND OR a.customer_id<>p_customer_id THEN RAISE EXCEPTION 'RESOURCE_NOT_FOUND'; END IF;
 IF o.order_status<>'READY_FOR_INSTALL' OR p.status<>'READY_FOR_DISPATCH' OR p.qc_status<>'PASSED' OR a.type<>'INSTALLATION' OR a.status NOT IN ('ASSIGNED','ACCEPTED') THEN RAISE EXCEPTION 'INVALID_STATE_TRANSITION'; END IF;
 INSERT INTO public.installations(company_id,customer_id,order_id,appointment_id,crew,status)
 VALUES(p_company_id,p_customer_id,p_order_id,p_appointment_id,p_crew,'SCHEDULED') RETURNING * INTO i;
 PERFORM public.operations_audit(p_company_id,p_actor_id,'SCHEDULE_INSTALLATION','installations',i.id,'{}');
 RETURN to_jsonb(i);
END $$;

CREATE FUNCTION public.mutate_installation_atomic(p_company_id uuid,p_installation_id uuid,p_actor_id uuid,p_status text DEFAULT NULL,p_ref text DEFAULT NULL,p_type text DEFAULT NULL)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE i public.installations; a public.appointments; r text; allowed jsonb := '{"SCHEDULED":["IN_TRANSIT","INSTALLING","FAILED"],"IN_TRANSIT":["INSTALLING","FAILED"],"INSTALLING":["TESTING","HANDOVER_PENDING","FAILED"],"TESTING":["HANDOVER_PENDING","INSTALLING","FAILED"],"HANDOVER_PENDING":["TESTING","INSTALLING","FAILED"],"FAILED":["SCHEDULED","IN_TRANSIT","INSTALLING"]}';
BEGIN
 r := public.operations_actor(p_company_id,p_actor_id,ARRAY['BOSS_ADMIN','TECHNICIAN']);
 SELECT * INTO i FROM public.installations WHERE company_id=p_company_id AND id=p_installation_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'RESOURCE_NOT_FOUND'; END IF;
 SELECT * INTO a FROM public.appointments WHERE company_id=p_company_id AND id=i.appointment_id FOR UPDATE;
 IF NOT FOUND OR a.customer_id<>i.customer_id OR a.type<>'INSTALLATION' THEN RAISE EXCEPTION 'RESOURCE_NOT_FOUND'; END IF;
 IF r='TECHNICIAN' AND a.assignee_id<>p_actor_id THEN RAISE EXCEPTION 'PERMISSION_DENIED'; END IF;
 IF i.status='COMPLETED' OR a.status NOT IN ('ASSIGNED','ACCEPTED','IN_PROGRESS') THEN RAISE EXCEPTION 'INVALID_STATE_TRANSITION'; END IF;
 IF p_ref IS NOT NULL THEN
  IF NOT public.operations_evidence_ref(p_company_id,i.id,p_ref,p_type) THEN RAISE EXCEPTION 'INVALID_STORAGE_REF'; END IF;
  UPDATE public.installations SET photos=CASE WHEN p_type='photo' AND NOT(photos ? p_ref) THEN photos || jsonb_build_array(p_ref) ELSE photos END,
   handover_ref=CASE WHEN p_type='handover' THEN p_ref ELSE handover_ref END,updated_at=now() WHERE id=i.id;
 ELSE
  IF NOT COALESCE((allowed->i.status) ? p_status,false) THEN RAISE EXCEPTION 'INVALID_STATE_TRANSITION'; END IF;
  UPDATE public.installations SET status=p_status,updated_at=now() WHERE id=i.id;
 END IF;
 PERFORM public.operations_audit(p_company_id,p_actor_id,'UPDATE_INSTALLATION','installations',i.id,jsonb_build_object('to_status',p_status,'evidence_type',p_type));
END $$;

CREATE FUNCTION public.complete_installation_atomic(p_company_id uuid,p_installation_id uuid,p_actor_id uuid,p_verified_photos jsonb,p_verified_handover text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE i public.installations; o public.orders; a public.appointments; r text; ref text;
BEGIN
 r := public.operations_actor(p_company_id,p_actor_id,ARRAY['BOSS_ADMIN','TECHNICIAN']);
 SELECT * INTO i FROM public.installations WHERE company_id=p_company_id AND id=p_installation_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'RESOURCE_NOT_FOUND'; END IF;
 SELECT * INTO o FROM public.orders WHERE company_id=p_company_id AND id=i.order_id FOR UPDATE;
 IF NOT FOUND OR o.customer_id<>i.customer_id THEN RAISE EXCEPTION 'RESOURCE_NOT_FOUND'; END IF;
 SELECT * INTO a FROM public.appointments WHERE company_id=p_company_id AND id=i.appointment_id FOR UPDATE;
 IF NOT FOUND OR a.customer_id<>i.customer_id OR a.type<>'INSTALLATION' THEN RAISE EXCEPTION 'RESOURCE_NOT_FOUND'; END IF;
 IF r='TECHNICIAN' AND a.assignee_id<>p_actor_id THEN RAISE EXCEPTION 'PERMISSION_DENIED'; END IF;
 IF i.status='COMPLETED' AND o.order_status='COMPLETED' THEN RETURN jsonb_build_object('success',true,'idempotent',true); END IF;
 IF i.status<>'HANDOVER_PENDING' OR o.order_status NOT IN ('READY_FOR_INSTALL','INSTALLING') OR a.status NOT IN ('ACCEPTED','IN_PROGRESS') THEN RAISE EXCEPTION 'INVALID_STATE_TRANSITION'; END IF;
 IF jsonb_typeof(i.photos)<>'array' OR jsonb_array_length(i.photos)=0 OR NULLIF(btrim(i.handover_ref),'') IS NULL THEN RAISE EXCEPTION 'MISSING_EVIDENCE'; END IF;
 IF i.photos IS DISTINCT FROM p_verified_photos OR i.handover_ref IS DISTINCT FROM p_verified_handover THEN RAISE EXCEPTION 'EVIDENCE_CHANGED'; END IF;
 FOR ref IN SELECT jsonb_array_elements_text(i.photos) LOOP
  IF NOT public.operations_evidence_ref(p_company_id,i.id,ref,'photo') THEN RAISE EXCEPTION 'INVALID_STORAGE_REF'; END IF;
 END LOOP;
 IF NOT public.operations_evidence_ref(p_company_id,i.id,i.handover_ref,'handover') THEN RAISE EXCEPTION 'INVALID_STORAGE_REF'; END IF;
 UPDATE public.installations SET status='COMPLETED',completed_at=now(),updated_at=now() WHERE id=i.id;
 UPDATE public.orders SET order_status='COMPLETED',updated_at=now() WHERE id=o.id;
 PERFORM public.operations_audit(p_company_id,p_actor_id,'COMPLETE_INSTALLATION_AND_HANDOVER','installations',i.id,jsonb_build_object('order_id',o.id));
 INSERT INTO public.operations_outbox(company_id,order_id,event_type,payload) VALUES(p_company_id,o.id,'ORDER_COMPLETED',jsonb_build_object('installation_id',i.id,'completed_at',now())) ON CONFLICT(company_id,order_id,event_type) DO NOTHING;
 RETURN jsonb_build_object('success',true,'idempotent',false);
END $$;

CREATE FUNCTION public.update_warranty_status_atomic(p_company_id uuid,p_ticket_id uuid,p_actor_id uuid,p_actor_role text,p_operation text,p_status text DEFAULT NULL,p_technician_id uuid DEFAULT NULL,p_notes text DEFAULT NULL)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE t public.warranty_tickets; r text; next_status text; allowed jsonb := '{"OPEN":["CANCELLED"],"ASSIGNED":["IN_PROGRESS","OPEN","CANCELLED"],"IN_PROGRESS":["RESOLVED","FAILED"],"RESOLVED":["CLOSED"],"REOPENED":["IN_PROGRESS"]}';
BEGIN
 r := public.operations_actor(p_company_id,p_actor_id,ARRAY['BOSS_ADMIN','TECHNICIAN','SALE']);
 IF r IS DISTINCT FROM p_actor_role THEN RAISE EXCEPTION 'PERMISSION_DENIED'; END IF;
 SELECT * INTO t FROM public.warranty_tickets WHERE company_id=p_company_id AND id=p_ticket_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'RESOURCE_NOT_FOUND'; END IF;
 IF r='TECHNICIAN' AND t.assigned_to IS DISTINCT FROM p_actor_id THEN RAISE EXCEPTION 'PERMISSION_DENIED'; END IF;
 IF p_operation='assign' THEN
  IF r<>'BOSS_ADMIN' THEN RAISE EXCEPTION 'PERMISSION_DENIED'; END IF;
  IF t.status NOT IN ('OPEN','REOPENED','ASSIGNED') THEN RAISE EXCEPTION 'INVALID_STATE_TRANSITION'; END IF;
  PERFORM public.operations_actor(p_company_id,p_technician_id,ARRAY['TECHNICIAN']);
  next_status := 'ASSIGNED';
 ELSIF p_operation='reopen' THEN
  IF r NOT IN ('BOSS_ADMIN','SALE') THEN RAISE EXCEPTION 'PERMISSION_DENIED'; END IF;
  IF t.status NOT IN ('RESOLVED','CLOSED') OR NULLIF(btrim(p_notes),'') IS NULL THEN RAISE EXCEPTION 'INVALID_STATE_TRANSITION'; END IF;
  next_status := 'REOPENED';
 ELSIF p_operation='update' THEN
  IF r NOT IN ('BOSS_ADMIN','TECHNICIAN') THEN RAISE EXCEPTION 'PERMISSION_DENIED'; END IF;
  IF NOT COALESCE((allowed->t.status) ? p_status,false) THEN RAISE EXCEPTION 'INVALID_STATE_TRANSITION'; END IF;
  next_status := p_status;
 ELSE RAISE EXCEPTION 'INVALID_INPUT'; END IF;
 UPDATE public.warranty_tickets SET status=next_status,
 assigned_to=CASE WHEN p_operation='assign' THEN p_technician_id WHEN next_status='OPEN' THEN NULL ELSE assigned_to END,
 resolved_at=CASE WHEN next_status='RESOLVED' THEN now() WHEN next_status='REOPENED' THEN NULL ELSE resolved_at END,
 notes=CASE WHEN p_operation='reopen' THEN concat_ws(E'\n',notes,'REOPEN: '||p_notes) ELSE COALESCE(p_notes,notes) END,updated_at=now() WHERE id=t.id;
 PERFORM public.operations_audit(p_company_id,p_actor_id,'WARRANTY_'||upper(p_operation),'warranty_tickets',t.id,jsonb_build_object('from_status',t.status,'to_status',next_status));
END $$;

DO $$ DECLARE f regprocedure; BEGIN
 FOR f IN SELECT oid::regprocedure FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN
 ('operations_actor','operations_audit','operations_evidence_ref','create_production_order_atomic','update_production_progress_atomic','record_quality_check_atomic','schedule_installation_atomic','mutate_installation_atomic','complete_installation_atomic','update_warranty_status_atomic') LOOP
 EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon,authenticated',f);
 EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO service_role',f);
 END LOOP;
END $$;

CREATE OR REPLACE FUNCTION public.resolve_response_sla_on_sale_reply(
  p_company_id uuid,
  p_conversation_id uuid,
  p_sale_interaction_id uuid,
  p_resolved_at timestamptz DEFAULT NULL
)
RETURNS TABLE (
  id uuid,
  company_id uuid,
  conversation_id uuid,
  customer_id uuid,
  trigger_interaction_id uuid,
  started_at timestamptz,
  deadline_at timestamptz,
  state text,
  resolved_at timestamptz,
  sale_response_interaction_id uuid,
  ai_response_interaction_id uuid,
  ai_claimed_at timestamptz,
  ai_claim_id uuid,
  ai_claim_expires_at timestamptz,
  created_at timestamptz,
  updated_at timestamptz
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_customer_id uuid;
  v_interaction_company_id uuid;
  v_interaction_customer_id uuid;
  v_interaction_convo_id uuid;
  v_interaction_type text;
  v_interaction_direction text;
  v_interaction_actor text;
  v_interaction_created_at timestamptz;
  v_resolved_at timestamptz;
  v_window public.response_sla_windows%ROWTYPE;
  v_resolved_window public.response_sla_windows%ROWTYPE;
  v_outbox private.han_outbox%ROWTYPE;
BEGIN
  -- 1. Validate Conversation existence & tenant binding
  SELECT c.customer_id
  INTO v_customer_id
  FROM public.conversations c
  WHERE c.id = p_conversation_id
    AND c.company_id = p_company_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'CONVERSATION_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  -- 2. Validate Sale Interaction (enforce company, customer, conversation alignment)
  SELECT
    i.company_id,
    i.customer_id,
    i.conversation_id,
    i.type,
    i.direction,
    i.actor_type,
    i.created_at
  INTO
    v_interaction_company_id,
    v_interaction_customer_id,
    v_interaction_convo_id,
    v_interaction_type,
    v_interaction_direction,
    v_interaction_actor,
    v_interaction_created_at
  FROM public.interactions i
  WHERE i.id = p_sale_interaction_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'SALE_INTERACTION_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  IF v_interaction_company_id <> p_company_id THEN
    RAISE EXCEPTION 'INTERACTION_COMPANY_MISMATCH' USING ERRCODE = '42501';
  END IF;

  IF v_interaction_convo_id IS NULL OR v_interaction_convo_id <> p_conversation_id THEN
    RAISE EXCEPTION 'INTERACTION_CONVERSATION_MISMATCH' USING ERRCODE = '22000';
  END IF;

  IF v_interaction_customer_id <> v_customer_id THEN
    RAISE EXCEPTION 'INTERACTION_CUSTOMER_MISMATCH' USING ERRCODE = '22000';
  END IF;

  IF v_interaction_type <> 'MESSAGE' THEN
    RAISE EXCEPTION 'INVALID_INTERACTION_TYPE' USING ERRCODE = '22000';
  END IF;

  IF v_interaction_direction <> 'OUTBOUND' THEN
    RAISE EXCEPTION 'INVALID_INTERACTION_DIRECTION' USING ERRCODE = '22000';
  END IF;

  IF v_interaction_actor <> 'SALE' THEN
    RAISE EXCEPTION 'INVALID_INTERACTION_ACTOR' USING ERRCODE = '22000';
  END IF;

  -- Canonical resolved timestamp rules:
  -- Priority 1: If matching Hán outbox row exists, outbox.sent_at is canonical and authoritative.
  -- Require outbox status = 'SENT' AND sent_at IS NOT NULL. Caller-supplied p_resolved_at is strictly ignored.
  -- If outbox is SENDING, FAILED, UNKNOWN, or sent_at is NULL, fail closed.
  SELECT *
  INTO v_outbox
  FROM private.han_outbox o
  WHERE o.company_id = p_company_id
    AND o.interaction_id = p_sale_interaction_id;

  IF FOUND THEN
    IF v_outbox.status <> 'SENT' OR v_outbox.sent_at IS NULL THEN
      RAISE EXCEPTION 'OUTBOX_NOT_CONFIRMED' USING ERRCODE = '22000';
    END IF;

    IF v_outbox.sent_at < v_interaction_created_at THEN
      RAISE EXCEPTION 'CORRUPT_OUTBOX_SENT_AT' USING ERRCODE = '22000';
    END IF;

    v_resolved_at := v_outbox.sent_at;
  ELSE
    -- Priority 2: Non-Hán / generic channel compatibility:
    IF p_resolved_at IS NOT NULL THEN
      IF p_resolved_at < v_interaction_created_at THEN
        RAISE EXCEPTION 'RESOLVED_AT_CANNOT_PRECEDE_INTERACTION' USING ERRCODE = '22000';
      END IF;
      v_resolved_at := p_resolved_at;
    ELSE
      v_resolved_at := v_interaction_created_at;
    END IF;
  END IF;

  -- 3. Lock OPEN SLA window for this conversation
  SELECT *
  INTO v_window
  FROM public.response_sla_windows w
  WHERE w.company_id = p_company_id
    AND w.conversation_id = p_conversation_id
    AND w.state = 'OPEN'
  FOR UPDATE;

  -- 4. If no OPEN window, return empty set (idempotent no-op)
  IF NOT FOUND THEN
    RETURN;
  END IF;

  -- 5. Resolve window to SALE_RESPONDED
  UPDATE public.response_sla_windows
  SET state = 'SALE_RESPONDED',
      sale_response_interaction_id = p_sale_interaction_id,
      resolved_at = v_resolved_at,
      updated_at = clock_timestamp()
  WHERE public.response_sla_windows.id = v_window.id
  RETURNING * INTO v_resolved_window;

  -- 6. If conversation was in AI_HANDLING, reset to OPEN because Sale has stepped in
  UPDATE public.conversations
  SET status = 'OPEN',
      updated_at = clock_timestamp()
  WHERE public.conversations.id = p_conversation_id
    AND public.conversations.status = 'AI_HANDLING';

  RETURN QUERY
  SELECT
    v_resolved_window.id,
    v_resolved_window.company_id,
    v_resolved_window.conversation_id,
    v_resolved_window.customer_id,
    v_resolved_window.trigger_interaction_id,
    v_resolved_window.started_at,
    v_resolved_window.deadline_at,
    v_resolved_window.state,
    v_resolved_window.resolved_at,
    v_resolved_window.sale_response_interaction_id,
    v_resolved_window.ai_response_interaction_id,
    v_resolved_window.ai_claimed_at,
    v_resolved_window.ai_claim_id,
    v_resolved_window.ai_claim_expires_at,
    v_resolved_window.created_at,
    v_resolved_window.updated_at;
  RETURN;
END;
$$;

CREATE OR REPLACE FUNCTION public.activate_sales_style_profile(
  p_profile_id uuid
)
RETURNS TABLE (
  id uuid,
  company_id uuid,
  sale_user_id uuid,
  version text,
  salutation_rules jsonb,
  sentence_style jsonb,
  question_style jsonb,
  objection_style jsonb,
  closing_style jsonb,
  examples jsonb,
  source_refs jsonb,
  model_version text,
  generation_status text,
  activated_at timestamptz,
  activated_by_user_id uuid,
  superseded_at timestamptz,
  superseded_by_profile_id uuid,
  created_at timestamptz,
  updated_at timestamptz
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
#variable_conflict use_column
DECLARE
  v_target_company_id uuid;
  v_target_sale_user_id uuid;
  v_target_status text;
  v_actor_user_id uuid;
  v_actor_user_status text;
  v_actor_role text;
  v_actor_member_status text;
  v_sale_member_role text;
  v_sale_member_status text;
  v_target_sale_user_status text;
  v_target_row public.sales_style_profiles%ROWTYPE;
  v_old_active_row public.sales_style_profiles%ROWTYPE;
  v_activated_row public.sales_style_profiles%ROWTYPE;
  v_now timestamptz;
  v_elem jsonb;
  v_ex jsonb;
  v_ref_id uuid;
  v_unique_source_count integer;
  v_total_source_count integer;
  v_int_company_id uuid;
  v_int_actor_type text;
  v_int_actor_user_id uuid;
  v_int_direction text;
  v_int_type text;
  v_int_sanitization_status text;
  v_int_sanitized_content text;
  v_combined_style_text text;
BEGIN
  -- 1. Derive target resource and verify existence
  SELECT
    ssp.company_id,
    ssp.sale_user_id,
    ssp.generation_status
  INTO
    v_target_company_id,
    v_target_sale_user_id,
    v_target_status
  FROM public.sales_style_profiles ssp
  WHERE ssp.id = p_profile_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PROFILE_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  -- 2. Validate human actor via auth.uid()
  v_actor_user_id := auth.uid();
  IF v_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'UNAUTHENTICATED' USING ERRCODE = '42501';
  END IF;

  -- Enforce AAL2: Boss activation of AI Sales Style is a privileged sensitive admin action
  IF coalesce((auth.jwt() ->> 'aal'), '') <> 'aal2' THEN
    RAISE EXCEPTION 'MFA_REQUIRED' USING ERRCODE = '42501';
  END IF;

  -- Verify actor profile in user_profiles
  SELECT up.status
  INTO v_actor_user_status
  FROM public.user_profiles up
  WHERE up.id = v_actor_user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ACTOR_NOT_FOUND' USING ERRCODE = '42501';
  END IF;

  IF v_actor_user_status <> 'ACTIVE' THEN
    RAISE EXCEPTION 'ACTOR_INACTIVE' USING ERRCODE = '42501';
  END IF;

  -- Verify actor company membership: must be same company, role BOSS_ADMIN, status ACTIVE
  SELECT cm.role, cm.status
  INTO v_actor_role, v_actor_member_status
  FROM public.company_members cm
  WHERE cm.company_id = v_target_company_id
    AND cm.user_id = v_actor_user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ACTOR_MEMBERSHIP_NOT_FOUND' USING ERRCODE = '42501';
  END IF;

  IF v_actor_role <> 'BOSS_ADMIN' THEN
    RAISE EXCEPTION 'ACTOR_ROLE_NOT_BOSS_ADMIN' USING ERRCODE = '42501';
  END IF;

  IF v_actor_member_status <> 'ACTIVE' THEN
    RAISE EXCEPTION 'ACTOR_MEMBERSHIP_INACTIVE' USING ERRCODE = '42501';
  END IF;

  -- 3. Concurrency serialization mutex: Lock target Sale company_members row FOR UPDATE
  SELECT cm.role, cm.status
  INTO v_sale_member_role, v_sale_member_status
  FROM public.company_members cm
  WHERE cm.company_id = v_target_company_id
    AND cm.user_id = v_target_sale_user_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'TARGET_SALE_MEMBERSHIP_NOT_FOUND' USING ERRCODE = '42501';
  END IF;

  -- 4. Revalidate target Sale at activation time
  IF v_sale_member_role <> 'SALE' THEN
    RAISE EXCEPTION 'TARGET_NOT_SALE' USING ERRCODE = '42501';
  END IF;

  IF v_sale_member_status <> 'ACTIVE' THEN
    RAISE EXCEPTION 'TARGET_SALE_INACTIVE' USING ERRCODE = '42501';
  END IF;

  SELECT up.status
  INTO v_target_sale_user_status
  FROM public.user_profiles up
  WHERE up.id = v_target_sale_user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'TARGET_SALE_USER_NOT_FOUND' USING ERRCODE = '42501';
  END IF;

  IF v_target_sale_user_status <> 'ACTIVE' THEN
    RAISE EXCEPTION 'TARGET_SALE_USER_INACTIVE' USING ERRCODE = '42501';
  END IF;

  -- 5. Lock target profile FOR UPDATE
  SELECT *
  INTO v_target_row
  FROM public.sales_style_profiles ssp
  WHERE ssp.id = p_profile_id
  FOR UPDATE;

  -- Allowed state transitions:
  -- SUPERSEDED cannot be activated
  IF v_target_row.generation_status = 'SUPERSEDED' THEN
    RAISE EXCEPTION 'PROFILE_ALREADY_SUPERSEDED' USING ERRCODE = '22000';
  END IF;

  -- Idempotency: ACTIVE -> ACTIVE no-op
  IF v_target_row.generation_status = 'ACTIVE' THEN
    -- Verify invariant sanity
    IF v_target_row.activated_at IS NULL OR v_target_row.activated_by_user_id IS NULL
       OR v_target_row.superseded_at IS NOT NULL OR v_target_row.superseded_by_profile_id IS NOT NULL THEN
      RAISE EXCEPTION 'CORRUPT_ACTIVE_PROFILE_STATE' USING ERRCODE = '22000';
    END IF;

    -- Return existing active profile without updating or creating duplicate audit
    RETURN QUERY SELECT
      v_target_row.id,
      v_target_row.company_id,
      v_target_row.sale_user_id,
      v_target_row.version,
      v_target_row.salutation_rules,
      v_target_row.sentence_style,
      v_target_row.question_style,
      v_target_row.objection_style,
      v_target_row.closing_style,
      v_target_row.examples,
      v_target_row.source_refs,
      v_target_row.model_version,
      v_target_row.generation_status,
      v_target_row.activated_at,
      v_target_row.activated_by_user_id,
      v_target_row.superseded_at,
      v_target_row.superseded_by_profile_id,
      v_target_row.created_at,
      v_target_row.updated_at;
    RETURN;
  END IF;

  IF v_target_row.generation_status <> 'DRAFT' THEN
    RAISE EXCEPTION 'INVALID_PROFILE_STATUS' USING ERRCODE = '22000';
  END IF;

  -- ============================================================================
  -- 5b. PROVENANCE REVALIDATION OF DRAFT PROFILE (Defense-in-depth against untrusted DRAFTs)
  -- ============================================================================
  -- 1. Validate model_version: non-null, non-empty trimmed, length <= 100
  IF v_target_row.model_version IS NULL
     OR pg_catalog.btrim(v_target_row.model_version) = ''
     OR pg_catalog.length(v_target_row.model_version) > 100 THEN
    RAISE EXCEPTION 'PROFILE_PROVENANCE_INVALID' USING ERRCODE = '22000';
  END IF;

  -- 2. Validate source_refs: jsonb array, 1..200 items, no duplicates, valid shape INTERACTION
  IF v_target_row.source_refs IS NULL
     OR jsonb_typeof(v_target_row.source_refs) <> 'array'
     OR jsonb_array_length(v_target_row.source_refs) = 0
     OR jsonb_array_length(v_target_row.source_refs) > 200 THEN
    RAISE EXCEPTION 'PROFILE_PROVENANCE_INVALID' USING ERRCODE = '22000';
  END IF;

  -- Validate each item in source_refs for shape and sensitive data
  FOR v_elem IN SELECT * FROM jsonb_array_elements(v_target_row.source_refs) LOOP
    IF jsonb_typeof(v_elem) <> 'object' THEN
      RAISE EXCEPTION 'PROFILE_PROVENANCE_INVALID' USING ERRCODE = '22000';
    END IF;

    IF (v_elem->>'type') IS NULL OR (v_elem->>'type') <> 'INTERACTION' THEN
      RAISE EXCEPTION 'PROFILE_PROVENANCE_INVALID' USING ERRCODE = '22000';
    END IF;

    IF v_elem ? 'content' OR v_elem ? 'sanitized_content' OR v_elem ? 'message_text'
       OR v_elem ? 'phone' OR v_elem ? 'transcript' OR v_elem ? 'recording'
       OR v_elem ? 'raw_payload' OR v_elem ? 'token' THEN
      RAISE EXCEPTION 'PROFILE_PROVENANCE_INVALID' USING ERRCODE = '22000';
    END IF;

    IF (SELECT count(*) FROM jsonb_object_keys(v_elem) k WHERE k NOT IN ('type', 'id')) > 0 THEN
      RAISE EXCEPTION 'PROFILE_PROVENANCE_INVALID' USING ERRCODE = '22000';
    END IF;

    BEGIN
      v_ref_id := (v_elem->>'id')::uuid;
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'PROFILE_PROVENANCE_INVALID' USING ERRCODE = '22000';
    END;
  END LOOP;

  -- Check duplicates in source_refs
  SELECT count(DISTINCT (elem->>'id')::uuid), count(*)
  INTO v_unique_source_count, v_total_source_count
  FROM jsonb_array_elements(v_target_row.source_refs) AS elem;

  IF v_unique_source_count <> v_total_source_count THEN
    RAISE EXCEPTION 'PROFILE_PROVENANCE_INVALID' USING ERRCODE = '22000';
  END IF;

  -- 3. Verify each source interaction in DB: same Company, same Sale user, OUTBOUND, MESSAGE, SUCCEEDED
  FOR v_elem IN SELECT * FROM jsonb_array_elements(v_target_row.source_refs) LOOP
    v_ref_id := (v_elem->>'id')::uuid;

    SELECT
      i.company_id,
      i.actor_type,
      i.actor_user_id,
      i.direction,
      i.type,
      i.sanitization_status,
      i.sanitized_content
    INTO
      v_int_company_id,
      v_int_actor_type,
      v_int_actor_user_id,
      v_int_direction,
      v_int_type,
      v_int_sanitization_status,
      v_int_sanitized_content
    FROM public.interactions i
    WHERE i.id = v_ref_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'PROFILE_SOURCE_INVALID' USING ERRCODE = 'P0002';
    END IF;

    IF v_int_company_id <> v_target_company_id THEN
      RAISE EXCEPTION 'PROFILE_SOURCE_INVALID' USING ERRCODE = '42501';
    END IF;

    IF v_int_actor_type <> 'SALE' OR v_int_actor_user_id <> v_target_sale_user_id THEN
      RAISE EXCEPTION 'PROFILE_SOURCE_INVALID' USING ERRCODE = '22000';
    END IF;

    IF v_int_direction <> 'OUTBOUND' THEN
      RAISE EXCEPTION 'PROFILE_SOURCE_INVALID' USING ERRCODE = '22000';
    END IF;

    IF v_int_type <> 'MESSAGE' THEN
      RAISE EXCEPTION 'PROFILE_SOURCE_INVALID' USING ERRCODE = '22000';
    END IF;

    IF v_int_sanitization_status <> 'SUCCEEDED' THEN
      RAISE EXCEPTION 'PROFILE_SOURCE_INVALID' USING ERRCODE = '22000';
    END IF;

    IF v_int_sanitized_content IS NULL OR pg_catalog.btrim(v_int_sanitized_content) = '' THEN
      RAISE EXCEPTION 'PROFILE_SOURCE_INVALID' USING ERRCODE = '22000';
    END IF;
  END LOOP;

  -- 4. Style safety at activation: DB-level business policy firewall
  IF v_target_row.salutation_rules IS NULL OR jsonb_typeof(v_target_row.salutation_rules) <> 'object'
     OR v_target_row.sentence_style IS NULL OR jsonb_typeof(v_target_row.sentence_style) <> 'object'
     OR v_target_row.question_style IS NULL OR jsonb_typeof(v_target_row.question_style) <> 'object'
     OR v_target_row.objection_style IS NULL OR jsonb_typeof(v_target_row.objection_style) <> 'object'
     OR v_target_row.closing_style IS NULL OR jsonb_typeof(v_target_row.closing_style) <> 'object' THEN
    RAISE EXCEPTION 'PROFILE_STYLE_POLICY_UNSAFE' USING ERRCODE = '22000';
  END IF;

  v_combined_style_text := v_target_row.salutation_rules::text || ' ' ||
                           v_target_row.sentence_style::text || ' ' ||
                           v_target_row.question_style::text || ' ' ||
                           v_target_row.objection_style::text || ' ' ||
                           v_target_row.closing_style::text;

  IF v_combined_style_text ~* '(giảm\s*giá|chiết\s*khấu|\ydiscount\y|khuyến\s*m[aã]i|%|\ypercent\y|\yphần\s*trăm\y|giá\s*bán|mức\s*giá|báo\s*giá|bảng\s*giá|đơn\s*giá|\yvnđ\y|\yvnd\y|₫|đặt\s*cọc|tiền\s*cọc|\ycọc\y|payment\s*terms|\ythanh\s*toán\y|\ypayment\y|chuyển\s*khoản|trả\s*góp|hợp\s*đồng|\ycontract\y|bảo\s*hành|\ywarranty\y|\yphí\y|lãi\s*suất|cam\s*kết\s*(giao\s*hàng|bảo\s*hành|tiến\s*độ|giá|doanh\s*nghiệp|chất\s*lượng|hoàn\s*tiền))'
     OR v_combined_style_text ~* '\m\d+([\.,]\d{3})*\s*(triệu|nghìn|ngàn|tr|k|đồng|đ)\M' THEN
    RAISE EXCEPTION 'PROFILE_STYLE_POLICY_UNSAFE' USING ERRCODE = '22000';
  END IF;

  -- 5. Legacy examples validation: array 0..5 items, metadata only, strictly no content/sanitized_content/phone/etc.
  IF v_target_row.examples IS NULL OR jsonb_typeof(v_target_row.examples) <> 'array' THEN
    RAISE EXCEPTION 'PROFILE_EXAMPLES_UNSAFE' USING ERRCODE = '22000';
  END IF;

  IF jsonb_array_length(v_target_row.examples) > 5 THEN
    RAISE EXCEPTION 'PROFILE_EXAMPLES_UNSAFE' USING ERRCODE = '22000';
  END IF;

  FOR v_ex IN SELECT * FROM jsonb_array_elements(v_target_row.examples) LOOP
    IF jsonb_typeof(v_ex) <> 'object' THEN
      RAISE EXCEPTION 'PROFILE_EXAMPLES_UNSAFE' USING ERRCODE = '22000';
    END IF;

    -- Forbid sensitive / leaky keys in examples
    IF v_ex ? 'content' OR v_ex ? 'sanitized_content' OR v_ex ? 'message_text'
       OR v_ex ? 'phone' OR v_ex ? 'transcript' OR v_ex ? 'recording'
       OR v_ex ? 'raw_payload' OR v_ex ? 'token' THEN
      RAISE EXCEPTION 'PROFILE_EXAMPLES_UNSAFE' USING ERRCODE = '22000';
    END IF;

    -- Metadata shape check: must contain interaction_id, channel, created_at
    IF NOT (v_ex ? 'interaction_id' AND v_ex ? 'channel' AND v_ex ? 'created_at') THEN
      RAISE EXCEPTION 'PROFILE_EXAMPLES_UNSAFE' USING ERRCODE = '22000';
    END IF;

    -- Strict whitelist: no other keys allowed
    IF (SELECT count(*) FROM jsonb_object_keys(v_ex) k WHERE k NOT IN ('interaction_id', 'channel', 'created_at')) > 0 THEN
      RAISE EXCEPTION 'PROFILE_EXAMPLES_UNSAFE' USING ERRCODE = '22000';
    END IF;

    BEGIN
      PERFORM (v_ex->>'interaction_id')::uuid;
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'PROFILE_EXAMPLES_UNSAFE' USING ERRCODE = '22000';
    END;
  END LOOP;

  -- Transaction timestamp for atomic transition
  v_now := clock_timestamp();

  -- 6. Lock current ACTIVE profile for this sale (if any exists)
  SELECT *
  INTO v_old_active_row
  FROM public.sales_style_profiles ssp
  WHERE ssp.company_id = v_target_company_id
    AND ssp.sale_user_id = v_target_sale_user_id
    AND ssp.generation_status = 'ACTIVE'
  FOR UPDATE;

  -- 7. Supersede old active profile if found
  IF FOUND THEN
    UPDATE public.sales_style_profiles ssp
    SET generation_status = 'SUPERSEDED',
        superseded_at = v_now,
        superseded_by_profile_id = p_profile_id,
        updated_at = v_now
    WHERE ssp.id = v_old_active_row.id;

    -- Mandatory audit log for superseded profile
    INSERT INTO public.audit_logs (
      company_id,
      user_id,
      action,
      resource_type,
      resource_id,
      customer_id,
      result,
      metadata
    ) VALUES (
      v_target_company_id,
      v_actor_user_id,
      'SALES_STYLE_PROFILE_SUPERSEDED',
      'SALES_STYLE_PROFILE',
      v_old_active_row.id,
      NULL,
      'SUCCESS',
      jsonb_build_object(
        'sale_user_id', v_target_sale_user_id,
        'superseded_by_profile_id', p_profile_id
      )
    );
  END IF;

  -- 8. Activate target profile
  UPDATE public.sales_style_profiles ssp
  SET generation_status = 'ACTIVE',
      activated_at = v_now,
      activated_by_user_id = v_actor_user_id,
      updated_at = v_now
  WHERE ssp.id = p_profile_id
  RETURNING * INTO v_target_row;

  -- Mandatory audit log for activated profile
  INSERT INTO public.audit_logs (
    company_id,
    user_id,
    action,
    resource_type,
    resource_id,
    customer_id,
    result,
    metadata
  ) VALUES (
    v_target_company_id,
    v_actor_user_id,
    'SALES_STYLE_PROFILE_ACTIVATED',
    'SALES_STYLE_PROFILE',
    p_profile_id,
    NULL,
    'SUCCESS',
    jsonb_build_object(
      'sale_user_id', v_target_sale_user_id,
      'version', v_target_row.version,
      'previous_active_profile_id', v_old_active_row.id
    )
  );

  RETURN QUERY SELECT
    v_target_row.id,
    v_target_row.company_id,
    v_target_row.sale_user_id,
    v_target_row.version,
    v_target_row.salutation_rules,
    v_target_row.sentence_style,
    v_target_row.question_style,
    v_target_row.objection_style,
    v_target_row.closing_style,
    v_target_row.examples,
    v_target_row.source_refs,
    v_target_row.model_version,
    v_target_row.generation_status,
    v_target_row.activated_at,
    v_target_row.activated_by_user_id,
    v_target_row.superseded_at,
    v_target_row.superseded_by_profile_id,
    v_target_row.created_at,
    v_target_row.updated_at;
END;
$$;

