CREATE OR REPLACE FUNCTION public.create_production_order_atomic(
  p_company_id uuid,
  p_order_id uuid,
  p_actor_id uuid,
  p_specs jsonb,
  p_materials jsonb,
  p_deadline timestamptz
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  o public.orders;
  c public.contracts;
  p public.production_orders;
  pc public.price_calculations;
  pp public.pricing_policies;
  s public.surveys;
  v_canonical_specs jsonb;
  v_canonical_materials jsonb;
  v_final_specs jsonb;
  v_final_materials jsonb;
  v_canonical_dim text;
  v_cw_mm numeric;
  v_bh_mm numeric;
  v_w numeric;
  v_h numeric;
  v_key text;
BEGIN
  -- 1. Validate actor: BOSS_ADMIN only
  PERFORM public.operations_actor(p_company_id, p_actor_id, ARRAY['BOSS_ADMIN']);

  -- 2. Reject empty or null client specs / materials
  IF p_specs IS NULL OR jsonb_typeof(p_specs) = 'null' OR p_specs = '{}'::jsonb
     OR p_materials IS NULL OR jsonb_typeof(p_materials) = 'null' OR p_materials = '{}'::jsonb THEN
    RAISE EXCEPTION 'INVALID_TECHNICAL_INPUT';
  END IF;

  -- 3. Reject arbitrary client-only specs keys (must be domain-recognized technical fields or notes)
  FOR v_key IN SELECT jsonb_object_keys(p_specs) LOOP
    IF v_key NOT IN (
      'dimensions', 'clear_width_mm', 'barrier_height_mm', 'width', 'height',
      'gate_type', 'mounting_method', 'thickness_mm', 'tolerance_mm', 'notes'
    ) THEN
      RAISE EXCEPTION 'INVALID_TECHNICAL_INPUT';
    END IF;
  END LOOP;

  -- 4. Reject arbitrary client-only materials keys (must be domain-recognized material specifications)
  FOR v_key IN SELECT jsonb_object_keys(p_materials) LOOP
    IF v_key NOT IN (
      'aluminum', 'inox', 'steel', 'gasket', 'seal', 'profile', 'panel', 'frame', 'hardware', 'fasteners'
    ) THEN
      RAISE EXCEPTION 'INVALID_TECHNICAL_INPUT';
    END IF;
    -- Material value must not be empty or blank string
    IF NULLIF(btrim(p_materials->>v_key), '') IS NULL THEN
      RAISE EXCEPTION 'INVALID_TECHNICAL_INPUT';
    END IF;
  END LOOP;

  -- 5. Fetch order with row lock
  SELECT * INTO o FROM public.orders WHERE company_id = p_company_id AND id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'RESOURCE_NOT_FOUND';
  END IF;

  IF o.order_status NOT IN ('CONTRACT_SIGNED', 'DEPOSIT_CONFIRMED') THEN
    RAISE EXCEPTION 'INVALID_STATE_TRANSITION';
  END IF;

  -- 6. Contract gate: valid signed contract required
  SELECT * INTO c FROM public.contracts
  WHERE company_id = p_company_id AND order_id = o.id AND is_current FOR UPDATE;
  IF NOT FOUND OR c.status <> 'SIGNED' OR NULLIF(btrim(c.signed_file_ref), '') IS NULL THEN
    RAISE EXCEPTION 'CONTRACT_NOT_SIGNED';
  END IF;

  -- 7. Prevent duplicate production order
  IF EXISTS(SELECT 1 FROM public.production_orders WHERE order_id = o.id) THEN
    RAISE EXCEPTION 'PRODUCTION_ALREADY_EXISTS';
  END IF;

  -- 8. Fetch authoritative price calculation record
  SELECT * INTO pc FROM public.price_calculations
  WHERE id = o.price_calculation_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'RESOURCE_NOT_FOUND';
  END IF;

  -- Multi-tenant and customer boundary validation
  IF pc.company_id <> p_company_id THEN
    RAISE EXCEPTION 'PERMISSION_DENIED';
  END IF;
  IF pc.customer_id <> o.customer_id THEN
    RAISE EXCEPTION 'MISMATCHED_CUSTOMER_REFERENCE';
  END IF;

  -- Check calculation status: fail closed if input missing or incomplete
  IF pc.status = 'NEED_INFO' THEN
    RAISE EXCEPTION 'Cannot release to production: missing canonical dimensions or barrier type'
      USING ERRCODE = 'NEED_INFO';
  END IF;
  IF pc.status <> 'CALCULATED' THEN
    RAISE EXCEPTION 'INVALID_TECHNICAL_INPUT';
  END IF;
  IF pc.input_data IS NULL OR pc.input_data = '{}'::jsonb THEN
    RAISE EXCEPTION 'INVALID_TECHNICAL_INPUT';
  END IF;

  -- 9. Fetch and validate authoritative pricing policy
  SELECT * INTO pp FROM public.pricing_policies
  WHERE id = pc.pricing_policy_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'RESOURCE_NOT_FOUND';
  END IF;
  IF pp.company_id <> p_company_id THEN
    RAISE EXCEPTION 'PERMISSION_DENIED';
  END IF;

  -- 10. Validate survey if bound to calculation
  IF pc.survey_id IS NOT NULL THEN
    SELECT * INTO s FROM public.surveys
    WHERE id = pc.survey_id FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'RESOURCE_NOT_FOUND';
    END IF;
    IF s.company_id <> p_company_id THEN
      RAISE EXCEPTION 'PERMISSION_DENIED';
    END IF;
    IF s.customer_id <> o.customer_id THEN
      RAISE EXCEPTION 'MISMATCHED_CUSTOMER_REFERENCE';
    END IF;
    IF s.measurements IS NULL OR s.measurements = '{}'::jsonb THEN
      RAISE EXCEPTION 'INVALID_TECHNICAL_INPUT';
    END IF;
  END IF;

  -- 11. Derive authoritative canonical materials from persisted records
  IF s.id IS NOT NULL AND jsonb_typeof(s.measurements->'materials') = 'object' AND s.measurements->'materials' <> '{}'::jsonb THEN
    v_canonical_materials := s.measurements->'materials';
  ELSIF jsonb_typeof(pc.input_data->'materials') = 'object' AND pc.input_data->'materials' <> '{}'::jsonb THEN
    v_canonical_materials := pc.input_data->'materials';
  ELSIF jsonb_typeof(pp.conditions->'materials') = 'object' AND pp.conditions->'materials' <> '{}'::jsonb THEN
    v_canonical_materials := pp.conditions->'materials';
  ELSIF jsonb_typeof(pp.conditions->'standard_materials') = 'object' AND pp.conditions->'standard_materials' <> '{}'::jsonb THEN
    v_canonical_materials := pp.conditions->'standard_materials';
  ELSIF jsonb_typeof(pp.price_rules->'materials') = 'object' AND pp.price_rules->'materials' <> '{}'::jsonb THEN
    v_canonical_materials := pp.price_rules->'materials';
  ELSIF jsonb_typeof(pp.price_rules->'standard_materials') = 'object' AND pp.price_rules->'standard_materials' <> '{}'::jsonb THEN
    v_canonical_materials := pp.price_rules->'standard_materials';
  ELSE
    v_canonical_materials := NULL;
  END IF;

  -- Fail-closed if authoritative materials are missing
  IF v_canonical_materials IS NULL OR jsonb_typeof(v_canonical_materials) = 'null' OR v_canonical_materials = '{}'::jsonb THEN
    RAISE EXCEPTION 'Cannot release to production: canonical materials specification is missing'
      USING ERRCODE = 'INVALID_TECHNICAL_INPUT';
  END IF;

  -- Detect and reject material tampering / client forgery
  FOR v_key IN SELECT jsonb_object_keys(p_materials) LOOP
    IF v_canonical_materials ? v_key THEN
      IF (p_materials->>v_key) <> (v_canonical_materials->>v_key) THEN
        RAISE EXCEPTION 'Production order material specification cannot contradict canonical policy/survey materials'
          USING ERRCODE = 'INVALID_TECHNICAL_INPUT';
      END IF;
    END IF;
  END LOOP;

  -- Client materials are NOT authoritative; canonical materials are strictly persisted
  v_final_materials := v_canonical_materials;

  -- 12. Derive authoritative canonical specifications (server-authoritative; client cannot override)
  IF s.id IS NOT NULL THEN
    v_cw_mm := NULLIF(s.measurements->>'clear_width_mm', '')::numeric;
    v_bh_mm := NULLIF(s.measurements->>'barrier_height_mm', '')::numeric;
    IF v_cw_mm IS NULL OR v_bh_mm IS NULL OR v_cw_mm <= 0 OR v_bh_mm <= 0 THEN
      RAISE EXCEPTION 'Cannot release to production: missing canonical dimensions or barrier type'
        USING ERRCODE = 'NEED_INFO';
    END IF;
    v_canonical_dim := v_cw_mm::text || 'x' || v_bh_mm::text || 'mm';
    v_canonical_specs := jsonb_build_object(
      'dimensions', v_canonical_dim,
      'canonical_dimensions', v_canonical_dim,
      'canonical_source', 'SURVEY',
      'calculation_id', pc.id,
      'survey_id', s.id,
      'clear_width_mm', v_cw_mm,
      'barrier_height_mm', v_bh_mm
    );
    IF s.measurements ? 'gate_type' AND NULLIF(btrim(s.measurements->>'gate_type'), '') IS NOT NULL THEN
      v_canonical_specs := v_canonical_specs || jsonb_build_object('gate_type', s.measurements->>'gate_type');
    ELSIF pc.input_data ? 'gate_type' AND NULLIF(btrim(pc.input_data->>'gate_type'), '') IS NOT NULL THEN
      v_canonical_specs := v_canonical_specs || jsonb_build_object('gate_type', pc.input_data->>'gate_type');
    END IF;
    IF s.measurements ? 'mounting_method' AND NULLIF(btrim(s.measurements->>'mounting_method'), '') IS NOT NULL THEN
      v_canonical_specs := v_canonical_specs || jsonb_build_object('mounting_method', s.measurements->>'mounting_method');
    ELSIF pc.input_data ? 'mounting_method' AND NULLIF(btrim(pc.input_data->>'mounting_method'), '') IS NOT NULL THEN
      v_canonical_specs := v_canonical_specs || jsonb_build_object('mounting_method', pc.input_data->>'mounting_method');
    END IF;
    -- Canonical thickness from survey -> calculation -> policy
    IF s.measurements ? 'thickness_mm' AND NULLIF(btrim(s.measurements->>'thickness_mm'), '') IS NOT NULL THEN
      v_canonical_specs := v_canonical_specs || jsonb_build_object('thickness_mm', (s.measurements->>'thickness_mm')::numeric);
    ELSIF pc.input_data ? 'thickness_mm' AND NULLIF(btrim(pc.input_data->>'thickness_mm'), '') IS NOT NULL THEN
      v_canonical_specs := v_canonical_specs || jsonb_build_object('thickness_mm', (pc.input_data->>'thickness_mm')::numeric);
    ELSIF pp.conditions ? 'thickness_mm' AND NULLIF(btrim(pp.conditions->>'thickness_mm'), '') IS NOT NULL THEN
      v_canonical_specs := v_canonical_specs || jsonb_build_object('thickness_mm', (pp.conditions->>'thickness_mm')::numeric);
    END IF;
    -- Canonical tolerance from survey -> calculation -> policy
    IF s.measurements ? 'tolerance_mm' AND NULLIF(btrim(s.measurements->>'tolerance_mm'), '') IS NOT NULL THEN
      v_canonical_specs := v_canonical_specs || jsonb_build_object('tolerance_mm', (s.measurements->>'tolerance_mm')::numeric);
    ELSIF pc.input_data ? 'tolerance_mm' AND NULLIF(btrim(pc.input_data->>'tolerance_mm'), '') IS NOT NULL THEN
      v_canonical_specs := v_canonical_specs || jsonb_build_object('tolerance_mm', (pc.input_data->>'tolerance_mm')::numeric);
    ELSIF pp.conditions ? 'tolerance_mm' AND NULLIF(btrim(pp.conditions->>'tolerance_mm'), '') IS NOT NULL THEN
      v_canonical_specs := v_canonical_specs || jsonb_build_object('tolerance_mm', (pp.conditions->>'tolerance_mm')::numeric);
    END IF;
  ELSE
    v_w := NULLIF(pc.input_data->>'width', '')::numeric;
    v_h := NULLIF(pc.input_data->>'height', '')::numeric;
    v_cw_mm := NULLIF(pc.input_data->>'clear_width_mm', '')::numeric;
    v_bh_mm := NULLIF(pc.input_data->>'barrier_height_mm', '')::numeric;

    IF v_w IS NOT NULL AND v_h IS NOT NULL AND v_w > 0 AND v_h > 0 THEN
      v_canonical_dim := (round(v_w * 100)::text || 'x' || round(v_h * 100)::text || 'cm');
      v_canonical_specs := jsonb_build_object(
        'dimensions', v_canonical_dim,
        'canonical_dimensions', v_canonical_dim,
        'canonical_source', 'PRICE_CALCULATION',
        'calculation_id', pc.id,
        'width', v_w,
        'height', v_h
      );
    ELSIF v_cw_mm IS NOT NULL AND v_bh_mm IS NOT NULL AND v_cw_mm > 0 AND v_bh_mm > 0 THEN
      v_canonical_dim := (v_cw_mm::text || 'x' || v_bh_mm::text || 'mm');
      v_canonical_specs := jsonb_build_object(
        'dimensions', v_canonical_dim,
        'canonical_dimensions', v_canonical_dim,
        'canonical_source', 'PRICE_CALCULATION',
        'calculation_id', pc.id,
        'clear_width_mm', v_cw_mm,
        'barrier_height_mm', v_bh_mm
      );
    ELSIF pc.input_data ? 'dimensions' AND NULLIF(btrim(pc.input_data->>'dimensions'), '') IS NOT NULL THEN
      v_canonical_dim := pc.input_data->>'dimensions';
      v_canonical_specs := jsonb_build_object(
        'dimensions', v_canonical_dim,
        'canonical_dimensions', v_canonical_dim,
        'canonical_source', 'PRICE_CALCULATION',
        'calculation_id', pc.id
      );
    ELSE
      -- Incomplete or missing canonical technical input: fail closed
      RAISE EXCEPTION 'Cannot release to production: missing canonical dimensions or barrier type'
        USING ERRCODE = 'NEED_INFO';
    END IF;

    IF pc.input_data ? 'gate_type' AND NULLIF(btrim(pc.input_data->>'gate_type'), '') IS NOT NULL THEN
      v_canonical_specs := v_canonical_specs || jsonb_build_object('gate_type', pc.input_data->>'gate_type');
    END IF;
    IF pc.input_data ? 'mounting_method' AND NULLIF(btrim(pc.input_data->>'mounting_method'), '') IS NOT NULL THEN
      v_canonical_specs := v_canonical_specs || jsonb_build_object('mounting_method', pc.input_data->>'mounting_method');
    END IF;
    -- Canonical thickness from calculation -> policy
    IF pc.input_data ? 'thickness_mm' AND NULLIF(btrim(pc.input_data->>'thickness_mm'), '') IS NOT NULL THEN
      v_canonical_specs := v_canonical_specs || jsonb_build_object('thickness_mm', (pc.input_data->>'thickness_mm')::numeric);
    ELSIF pp.conditions ? 'thickness_mm' AND NULLIF(btrim(pp.conditions->>'thickness_mm'), '') IS NOT NULL THEN
      v_canonical_specs := v_canonical_specs || jsonb_build_object('thickness_mm', (pp.conditions->>'thickness_mm')::numeric);
    END IF;
    -- Canonical tolerance from calculation -> policy
    IF pc.input_data ? 'tolerance_mm' AND NULLIF(btrim(pc.input_data->>'tolerance_mm'), '') IS NOT NULL THEN
      v_canonical_specs := v_canonical_specs || jsonb_build_object('tolerance_mm', (pc.input_data->>'tolerance_mm')::numeric);
    ELSIF pp.conditions ? 'tolerance_mm' AND NULLIF(btrim(pp.conditions->>'tolerance_mm'), '') IS NOT NULL THEN
      v_canonical_specs := v_canonical_specs || jsonb_build_object('tolerance_mm', (pp.conditions->>'tolerance_mm')::numeric);
    END IF;
  END IF;

  -- Technical specifications are strictly server-authoritative.
  -- Every technical field must come from an authoritative persisted source.
  -- Client cannot inject or override technical facts (dimensions, thickness_mm, tolerance_mm, width, height, gate_type, mounting_method).
  -- Only non-technical operational note is accepted from client input (bounded to 1000 characters).
  v_final_specs := v_canonical_specs;
  IF p_specs ? 'notes' AND NULLIF(btrim(p_specs->>'notes'), '') IS NOT NULL THEN
    v_final_specs := v_final_specs || jsonb_build_object('notes', left(btrim(p_specs->>'notes'), 1000));
  END IF;

  -- 12. Insert production order
  INSERT INTO public.production_orders(
    company_id,
    order_id,
    specs,
    materials,
    status,
    deadline,
    qc_status
  ) VALUES (
    p_company_id,
    o.id,
    v_final_specs,
    v_final_materials,
    'RELEASED_TO_FACTORY',
    p_deadline,
    'PENDING'
  ) RETURNING * INTO p;

  -- 13. Advance order status
  UPDATE public.orders SET order_status = 'IN_PRODUCTION', updated_at = now() WHERE id = o.id;

  -- 14. Audit log
  PERFORM public.operations_audit(
    p_company_id,
    p_actor_id,
    'CREATE_PRODUCTION_ORDER',
    'production_orders',
    p.id,
    jsonb_build_object('order_id', o.id)
  );

  RETURN to_jsonb(p);
END;
$$;

CREATE OR REPLACE FUNCTION public.create_warranty_ticket_atomic(
  p_company_id uuid,
  p_actor_id uuid,
  p_customer_id uuid,
  p_order_id uuid,
  p_installation_id uuid DEFAULT NULL,
  p_issue text DEFAULT NULL,
  p_notes text DEFAULT NULL,
  p_idempotency_key text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_role text;
  v_cust public.customers;
  v_order public.orders;
  v_inst public.installations;
  v_derived_inst_id uuid := NULL;
  v_ticket public.warranty_tickets;
  v_existing_id uuid;
BEGIN
  -- 1. Validate actor: BOSS_ADMIN or SALE required, active membership and active user profile
  v_role := public.operations_actor(p_company_id, p_actor_id, ARRAY['BOSS_ADMIN', 'SALE']);

  -- 2. Validate issue description
  IF NULLIF(btrim(p_issue), '') IS NULL THEN
    RAISE EXCEPTION 'INVALID_INPUT';
  END IF;

  -- 3. Check idempotency if key provided
  IF p_idempotency_key IS NOT NULL AND btrim(p_idempotency_key) <> '' THEN
    SELECT resource_id INTO v_existing_id
    FROM public.audit_logs
    WHERE company_id = p_company_id
      AND action = 'CREATE_WARRANTY_TICKET'
      AND metadata->>'idempotency_key' = p_idempotency_key
    LIMIT 1;

    IF v_existing_id IS NOT NULL THEN
      SELECT * INTO v_ticket FROM public.warranty_tickets
      WHERE id = v_existing_id AND company_id = p_company_id;
      IF FOUND THEN
        RETURN to_jsonb(v_ticket);
      END IF;
    END IF;
  END IF;

  -- 4. Validate customer belongs to company
  SELECT * INTO v_cust FROM public.customers
  WHERE company_id = p_company_id AND id = p_customer_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'RESOURCE_NOT_FOUND';
  END IF;

  -- 5. Validate order belongs to company and customer
  SELECT * INTO v_order FROM public.orders
  WHERE company_id = p_company_id AND customer_id = p_customer_id AND id = p_order_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'RESOURCE_NOT_FOUND';
  END IF;

  -- 6. Require order status COMPLETED
  IF v_order.order_status <> 'COMPLETED' THEN
    RAISE EXCEPTION 'INVALID_STATE_TRANSITION';
  END IF;

  -- 7. Validate or derive installation belonging strictly to this company, customer, and order
  IF p_installation_id IS NOT NULL THEN
    SELECT * INTO v_inst FROM public.installations
    WHERE company_id = p_company_id AND customer_id = p_customer_id AND order_id = p_order_id AND id = p_installation_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'RESOURCE_NOT_FOUND';
    END IF;
    v_derived_inst_id := v_inst.id;
  ELSE
    SELECT id INTO v_derived_inst_id FROM public.installations
    WHERE company_id = p_company_id AND customer_id = p_customer_id AND order_id = p_order_id
    ORDER BY created_at DESC LIMIT 1;
  END IF;

  -- 8. Insert warranty ticket
  INSERT INTO public.warranty_tickets (
    company_id,
    customer_id,
    order_id,
    installation_id,
    issue,
    status,
    assigned_to,
    notes,
    opened_at
  ) VALUES (
    p_company_id,
    p_customer_id,
    p_order_id,
    v_derived_inst_id,
    btrim(p_issue),
    'OPEN',
    NULL,
    p_notes,
    now()
  ) RETURNING * INTO v_ticket;

  -- 9. Insert audit log atomically in the same transaction
  INSERT INTO public.audit_logs (
    company_id,
    user_id,
    action,
    resource_type,
    resource_id,
    customer_id,
    result,
    metadata
  ) VALUES (
    p_company_id,
    p_actor_id,
    'CREATE_WARRANTY_TICKET',
    'warranty_tickets',
    v_ticket.id,
    p_customer_id,
    'SUCCESS',
    jsonb_build_object(
      'order_id', p_order_id,
      'installation_id', v_derived_inst_id,
      'idempotency_key', p_idempotency_key
    )
  );

  RETURN to_jsonb(v_ticket);
END;
$$;

DO $$
DECLARE
  f regprocedure;
BEGIN
  FOR f IN SELECT oid::regprocedure FROM pg_proc
    WHERE pronamespace = 'public'::regnamespace
      AND proname IN (
        'create_production_order_atomic',
        'create_warranty_ticket_atomic'
      )
  LOOP
    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC, anon, authenticated', f);
    EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO service_role', f);
  END LOOP;
END $$;

CREATE OR REPLACE FUNCTION public.create_ai_outbound_delivery_pending(
  p_company_id uuid,
  p_conversation_id uuid,
  p_channel text,
  p_client_command_id uuid,
  p_request_fingerprint text DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_delivery_id uuid;
  v_existing_id uuid;
  v_existing_status text;
  v_conversation_company uuid;
BEGIN
  -- Validate mandatory fields
  IF p_company_id IS NULL THEN
    RAISE EXCEPTION 'p_company_id là bắt buộc' USING ERRCODE = '22023';
  END IF;
  IF p_conversation_id IS NULL THEN
    RAISE EXCEPTION 'p_conversation_id là bắt buộc' USING ERRCODE = '22023';
  END IF;
  IF p_channel IS NULL OR p_channel NOT IN ('FACEBOOK', 'ZALO', 'SYSTEM', 'HOTLINE', 'DIRECT') THEN
    RAISE EXCEPTION 'p_channel không hợp lệ' USING ERRCODE = '22023';
  END IF;

  -- Validate conversation exists and belongs to company
  SELECT company_id INTO v_conversation_company
  FROM public.conversations
  WHERE id = p_conversation_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'CONVERSATION_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  IF v_conversation_company <> p_company_id THEN
    RAISE EXCEPTION 'CONVERSATION_COMPANY_MISMATCH' USING ERRCODE = '42501';
  END IF;

  -- Check existing command id for idempotency
  IF p_client_command_id IS NOT NULL THEN
    SELECT id, delivery_status INTO v_existing_id, v_existing_status
    FROM public.outbound_deliveries
    WHERE company_id = p_company_id
      AND client_command_id = p_client_command_id;

    IF FOUND THEN
      RETURN v_existing_id;
    END IF;
  END IF;

  v_delivery_id := gen_random_uuid();

  INSERT INTO public.outbound_deliveries (
    id,
    company_id,
    conversation_id,
    interaction_id,
    channel,
    delivery_status,
    client_command_id,
    request_fingerprint,
    created_at,
    updated_at
  ) VALUES (
    v_delivery_id,
    p_company_id,
    p_conversation_id,
    NULL,
    p_channel,
    'PENDING_DISPATCH',
    p_client_command_id,
    p_request_fingerprint,
    clock_timestamp(),
    clock_timestamp()
  );

  RETURN v_delivery_id;
END;
$$;

CREATE INDEX IF NOT EXISTS idx_outbound_deliveries_window
  ON public.outbound_deliveries (company_id, window_id)
  WHERE window_id IS NOT NULL;

CREATE OR REPLACE FUNCTION public.guard_ai_pre_dispatch(
  p_company_id uuid,
  p_conversation_id uuid,
  p_customer_id uuid,
  p_window_id uuid,
  p_ai_claim_id uuid,
  p_channel text,
  p_lease_seconds integer DEFAULT 120
)
RETURNS TABLE (
  granted boolean,
  reason text,
  delivery_id uuid,
  provider_msg_id text,
  interaction_id uuid,
  window_state text
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
#variable_conflict use_column
DECLARE
  v_window public.response_sla_windows%ROWTYPE;
  v_conv public.conversations%ROWTYPE;
  v_del public.outbound_deliveries%ROWTYPE;
  v_zalo public.zalo_outbound_deliveries%ROWTYPE;
  v_sale_reply_id uuid;
  v_sale_reply_resolved_at timestamptz;
  v_stable_zalo_command text;
  v_new_delivery_id uuid;
  v_now timestamptz := clock_timestamp();
  v_lease interval := make_interval(secs => greatest(coalesce(p_lease_seconds, 120), 10));
BEGIN
  -- A. Mandatory input validation
  IF p_company_id IS NULL OR p_conversation_id IS NULL OR p_customer_id IS NULL OR p_window_id IS NULL THEN
    RETURN QUERY SELECT false, 'INVALID_ARGUMENTS'::text, NULL::uuid, NULL::text, NULL::uuid, NULL::text;
    RETURN;
  END IF;

  -- B. Lock SLA Window
  SELECT * INTO v_window
  FROM public.response_sla_windows
  WHERE id = p_window_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN QUERY SELECT false, 'WINDOW_NOT_FOUND'::text, NULL::uuid, NULL::text, NULL::uuid, NULL::text;
    RETURN;
  END IF;

  IF v_window.company_id <> p_company_id THEN
    RETURN QUERY SELECT false, 'WRONG_COMPANY'::text, NULL::uuid, NULL::text, NULL::uuid, v_window.state;
    RETURN;
  END IF;

  IF v_window.conversation_id <> p_conversation_id THEN
    RETURN QUERY SELECT false, 'CONVERSATION_MISMATCH'::text, NULL::uuid, NULL::text, NULL::uuid, v_window.state;
    RETURN;
  END IF;

  IF v_window.customer_id <> p_customer_id THEN
    RETURN QUERY SELECT false, 'CUSTOMER_MISMATCH'::text, NULL::uuid, NULL::text, NULL::uuid, v_window.state;
    RETURN;
  END IF;

  IF v_window.state <> 'OPEN' THEN
    RETURN QUERY SELECT false, v_window.state, NULL::uuid, NULL::text, NULL::uuid, v_window.state;
    RETURN;
  END IF;

  IF p_ai_claim_id IS NOT NULL AND v_window.ai_claim_id IS DISTINCT FROM p_ai_claim_id THEN
    RETURN QUERY SELECT false, 'CLAIM_MISMATCH'::text, NULL::uuid, NULL::text, NULL::uuid, v_window.state;
    RETURN;
  END IF;

  IF v_window.ai_claim_expires_at IS NOT NULL AND v_window.ai_claim_expires_at <= v_now THEN
    RETURN QUERY SELECT false, 'CLAIM_EXPIRED'::text, NULL::uuid, NULL::text, NULL::uuid, v_window.state;
    RETURN;
  END IF;

  -- C. Lock Conversation
  SELECT * INTO v_conv
  FROM public.conversations
  WHERE id = p_conversation_id AND company_id = p_company_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN QUERY SELECT false, 'CONVERSATION_NOT_FOUND'::text, NULL::uuid, NULL::text, NULL::uuid, v_window.state;
    RETURN;
  END IF;

  IF v_conv.status = 'CLOSED' THEN
    RETURN QUERY SELECT false, 'CONVERSATION_CLOSED'::text, NULL::uuid, NULL::text, NULL::uuid, v_window.state;
    RETURN;
  END IF;

  -- D. Authoritative Check: Did Sale respond after window.started_at?
  SELECT
    i.id,
    coalesce(o.sent_at, i.created_at)
  INTO
    v_sale_reply_id,
    v_sale_reply_resolved_at
  FROM public.interactions i
  LEFT JOIN private.han_outbox o
    ON o.company_id = p_company_id AND o.interaction_id = i.id
  WHERE i.company_id = p_company_id
    AND i.conversation_id = p_conversation_id
    AND i.actor_type = 'SALE'
    AND i.direction = 'OUTBOUND'
    AND i.type = 'MESSAGE'
    AND i.created_at >= v_window.started_at
    AND (
      CASE WHEN o.interaction_id IS NOT NULL THEN o.status = 'SENT' ELSE true END
    )
  ORDER BY i.created_at DESC
  LIMIT 1;

  IF FOUND THEN
    -- Sale won the race! Transition to SALE_RESPONDED atomically
    UPDATE public.response_sla_windows
    SET
      state = 'SALE_RESPONDED',
      sale_response_interaction_id = v_sale_reply_id,
      resolved_at = coalesce(v_sale_reply_resolved_at, v_now),
      updated_at = v_now
    WHERE id = p_window_id;

    IF v_conv.status = 'AI_HANDLING' THEN
      UPDATE public.conversations
      SET status = 'OPEN', updated_at = v_now
      WHERE id = p_conversation_id;
    END IF;

    INSERT INTO public.audit_logs (
      company_id,
      user_id,
      action,
      resource_type,
      resource_id,
      customer_id,
      result,
      metadata
    ) VALUES (
      p_company_id,
      NULL,
      'RESPONSE_SLA_AI_CLAIM',
      'RESPONSE_SLA_WINDOW',
      p_window_id,
      p_customer_id,
      'DENIED',
      jsonb_build_object(
        'decision', 'DENIED',
        'reason', 'SALE_ALREADY_RESPONDED',
        'sale_response_interaction_id', v_sale_reply_id,
        'window_id', p_window_id
      )
    );

    RETURN QUERY SELECT false, 'SALE_ALREADY_RESPONDED'::text, NULL::uuid, NULL::text, NULL::uuid, 'SALE_RESPONDED'::text;
    RETURN;
  END IF;

  -- E. Channel-specific state machine check
  IF p_channel = 'ZALO' THEN
    v_stable_zalo_command := 'ai-sla-win-' || p_window_id::text;

    SELECT * INTO v_zalo
    FROM public.zalo_outbound_deliveries
    WHERE company_id = p_company_id
      AND channel = 'ZALO'
      AND command_id = v_stable_zalo_command
    FOR UPDATE;

    IF FOUND THEN
      IF v_zalo.status = 'SENT' THEN
        RETURN QUERY SELECT false, 'ALREADY_SENT'::text, v_zalo.id, v_zalo.provider_msg_id, v_zalo.interaction_id, v_window.state;
        RETURN;
      ELSIF v_zalo.status = 'PROVIDER_SENT_PENDING_FINALIZE' THEN
        RETURN QUERY SELECT false, 'PENDING_FINALIZE'::text, v_zalo.id, v_zalo.provider_msg_id, NULL::uuid, v_window.state;
        RETURN;
      ELSIF v_zalo.status IN ('PROVIDER_UNCERTAIN', 'UNCERTAIN') THEN
        RETURN QUERY SELECT false, 'UNCERTAIN'::text, v_zalo.id, v_zalo.provider_msg_id, NULL::uuid, v_window.state;
        RETURN;
      ELSIF v_zalo.status = 'SENDING' AND v_zalo.lease_until IS NOT NULL AND v_zalo.lease_until > v_now THEN
        RETURN QUERY SELECT false, 'BUSY'::text, v_zalo.id, NULL::text, NULL::uuid, v_window.state;
        RETURN;
      ELSIF v_zalo.status = 'SENDING' THEN
        -- Lease expired mid-flight: transition to UNCERTAIN, never auto-retry
        UPDATE public.zalo_outbound_deliveries
        SET status = 'PROVIDER_UNCERTAIN', lease_until = NULL, error_code = 'LEASE_EXPIRED_OUTCOME_UNKNOWN', updated_at = v_now
        WHERE id = v_zalo.id;

        RETURN QUERY SELECT false, 'UNCERTAIN'::text, v_zalo.id, NULL::text, NULL::uuid, v_window.state;
        RETURN;
      END IF;
      -- If status is FAILED or PENDING, allow send
      RETURN QUERY SELECT true, 'GRANTED'::text, v_zalo.id, NULL::text, NULL::uuid, v_window.state;
      RETURN;
    END IF;

    -- No prior row: dispatch authority granted for Zalo
    RETURN QUERY SELECT true, 'GRANTED'::text, NULL::uuid, NULL::text, NULL::uuid, v_window.state;
    RETURN;

  ELSE
    -- Generic / Facebook channel backed by public.outbound_deliveries
    SELECT * INTO v_del
    FROM public.outbound_deliveries
    WHERE company_id = p_company_id
      AND client_command_id = p_window_id
    FOR UPDATE;

    IF FOUND THEN
      IF v_del.delivery_status = 'SENT' THEN
        RETURN QUERY SELECT false, 'ALREADY_SENT'::text, v_del.id, v_del.provider_message_id, v_del.interaction_id, v_window.state;
        RETURN;
      ELSIF v_del.delivery_status = 'PROVIDER_SENT_PENDING_FINALIZE' THEN
        RETURN QUERY SELECT false, 'PENDING_FINALIZE'::text, v_del.id, v_del.provider_message_id, NULL::uuid, v_window.state;
        RETURN;
      ELSIF v_del.delivery_status IN ('UNCERTAIN', 'PROVIDER_UNCERTAIN') THEN
        RETURN QUERY SELECT false, 'UNCERTAIN'::text, v_del.id, v_del.provider_message_id, NULL::uuid, v_window.state;
        RETURN;
      ELSIF v_del.delivery_status = 'DISPATCHING' AND v_del.lease_until IS NOT NULL AND v_del.lease_until > v_now THEN
        RETURN QUERY SELECT false, 'BUSY'::text, v_del.id, NULL::text, NULL::uuid, v_window.state;
        RETURN;
      ELSIF v_del.delivery_status = 'DISPATCHING' THEN
        -- Lease expired mid-flight: transition to UNCERTAIN, never auto-retry
        UPDATE public.outbound_deliveries
        SET delivery_status = 'UNCERTAIN', lease_until = NULL, error_message = 'LEASE_EXPIRED_OUTCOME_UNKNOWN', updated_at = v_now
        WHERE id = v_del.id;

        RETURN QUERY SELECT false, 'UNCERTAIN'::text, v_del.id, NULL::text, NULL::uuid, v_window.state;
        RETURN;
      ELSIF v_del.delivery_status IN ('PENDING', 'PENDING_DISPATCH', 'FAILED') THEN
        -- Transition to DISPATCHING under active lease
        UPDATE public.outbound_deliveries
        SET
          delivery_status = 'DISPATCHING',
          lease_until = v_now + v_lease,
          locked_at = v_now,
          locked_by = 'ai_response_runtime',
          updated_at = v_now
        WHERE id = v_del.id;

        RETURN QUERY SELECT true, 'GRANTED'::text, v_del.id, NULL::text, NULL::uuid, v_window.state;
        RETURN;
      END IF;

      RETURN QUERY SELECT false, ('UNEXPECTED_STATUS_' || v_del.delivery_status)::text, v_del.id, NULL::text, NULL::uuid, v_window.state;
      RETURN;
    END IF;

    -- No prior row: insert new row in DISPATCHING state with stable command ID = window_id
    v_new_delivery_id := gen_random_uuid();
    INSERT INTO public.outbound_deliveries (
      id,
      company_id,
      conversation_id,
      interaction_id,
      channel,
      delivery_status,
      client_command_id,
      window_id,
      request_fingerprint,
      lease_until,
      locked_at,
      locked_by,
      created_at,
      updated_at
    ) VALUES (
      v_new_delivery_id,
      p_company_id,
      p_conversation_id,
      NULL,
      p_channel,
      'DISPATCHING',
      p_window_id,
      p_window_id,
      p_company_id::text || ':' || p_conversation_id::text || ':' || p_window_id::text,
      v_now + v_lease,
      v_now,
      'ai_response_runtime',
      v_now,
      v_now
    );

    RETURN QUERY SELECT true, 'GRANTED'::text, v_new_delivery_id, NULL::text, NULL::uuid, v_window.state;
    RETURN;
  END IF;
END;
$$;

CREATE OR REPLACE FUNCTION public.record_ai_outbound_provider_result(
  p_company_id uuid,
  p_delivery_id uuid,
  p_outcome text,
  p_provider_msg_id text DEFAULT NULL,
  p_error_message text DEFAULT NULL
)
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_del public.outbound_deliveries%ROWTYPE;
  v_new_status text;
  v_now timestamptz := clock_timestamp();
BEGIN
  IF p_company_id IS NULL OR p_delivery_id IS NULL OR p_outcome IS NULL THEN
    RAISE EXCEPTION 'MANDATORY_PARAMETERS_MISSING' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_del
  FROM public.outbound_deliveries
  WHERE id = p_delivery_id AND company_id = p_company_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'DELIVERY_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  IF p_outcome = 'SENT' THEN
    IF p_provider_msg_id IS NULL OR length(trim(p_provider_msg_id)) = 0 THEN
      RAISE EXCEPTION 'CANNOT_RECORD_SENT_WITHOUT_PROVIDER_MESSAGE_ID' USING ERRCODE = '22023';
    END IF;
    v_new_status := 'PROVIDER_SENT_PENDING_FINALIZE';

    UPDATE public.outbound_deliveries
    SET
      delivery_status = v_new_status,
      provider_message_id = p_provider_msg_id,
      lease_until = NULL,
      updated_at = v_now
    WHERE id = p_delivery_id;

  ELSIF p_outcome = 'FAILED' THEN
    v_new_status := 'FAILED';

    UPDATE public.outbound_deliveries
    SET
      delivery_status = v_new_status,
      error_message = coalesce(p_error_message, 'Provider rejected message'),
      lease_until = NULL,
      updated_at = v_now
    WHERE id = p_delivery_id;

  ELSIF p_outcome IN ('UNCERTAIN', 'UNKNOWN') THEN
    v_new_status := 'UNCERTAIN';

    UPDATE public.outbound_deliveries
    SET
      delivery_status = v_new_status,
      error_message = coalesce(p_error_message, 'Provider outcome uncertain'),
      lease_until = NULL,
      updated_at = v_now
    WHERE id = p_delivery_id;

  ELSE
    RAISE EXCEPTION 'INVALID_OUTBOUND_OUTCOME: %', p_outcome USING ERRCODE = '22023';
  END IF;

  RETURN v_new_status;
END;
$$;

CREATE OR REPLACE FUNCTION public.finalize_ai_outbound_delivery_atomic(
  p_company_id uuid,
  p_delivery_id uuid,
  p_conversation_id uuid,
  p_customer_id uuid,
  p_window_id uuid,
  p_ai_claim_id uuid,
  p_provider_msg_id text,
  p_sanitized_content text,
  p_raw_content text,
  p_source_metadata jsonb DEFAULT '{}'::jsonb
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_delivery public.outbound_deliveries%ROWTYPE;
  v_conv public.conversations%ROWTYPE;
  v_window public.response_sla_windows%ROWTYPE;
  v_interaction_id uuid;
  v_rows_updated integer;
  v_now timestamptz := clock_timestamp();
BEGIN
  -- 1. Validate mandatory fields
  IF p_company_id IS NULL OR p_delivery_id IS NULL OR p_conversation_id IS NULL
     OR p_customer_id IS NULL OR p_window_id IS NULL THEN
    RAISE EXCEPTION 'MANDATORY_PARAMETERS_MISSING' USING ERRCODE = '22023';
  END IF;

  IF p_provider_msg_id IS NULL OR length(trim(p_provider_msg_id)) = 0 THEN
    RAISE EXCEPTION 'CANNOT_FINALIZE_WITHOUT_PROVIDER_MESSAGE_ID' USING ERRCODE = '22023';
  END IF;

  -- 2. Lock and validate outbound delivery
  SELECT * INTO v_delivery
  FROM public.outbound_deliveries
  WHERE id = p_delivery_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'DELIVERY_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  IF v_delivery.company_id <> p_company_id THEN
    RAISE EXCEPTION 'DELIVERY_COMPANY_MISMATCH' USING ERRCODE = '42501';
  END IF;

  IF v_delivery.conversation_id <> p_conversation_id THEN
    RAISE EXCEPTION 'DELIVERY_CONVERSATION_MISMATCH' USING ERRCODE = '22000';
  END IF;

  -- 3. Lock and validate canonical conversation
  SELECT * INTO v_conv
  FROM public.conversations
  WHERE id = p_conversation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'CONVERSATION_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  IF v_conv.company_id <> p_company_id THEN
    RAISE EXCEPTION 'CONVERSATION_COMPANY_MISMATCH' USING ERRCODE = '42501';
  END IF;

  IF v_conv.customer_id <> p_customer_id THEN
    RAISE EXCEPTION 'CONVERSATION_CUSTOMER_MISMATCH' USING ERRCODE = '42501';
  END IF;

  IF v_delivery.channel <> v_conv.channel THEN
    RAISE EXCEPTION 'DELIVERY_CHANNEL_MISMATCH' USING ERRCODE = '22000';
  END IF;

  -- 4. Lock and validate SLA window
  SELECT * INTO v_window
  FROM public.response_sla_windows
  WHERE id = p_window_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'WINDOW_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  IF v_window.company_id <> p_company_id THEN
    RAISE EXCEPTION 'WINDOW_COMPANY_MISMATCH' USING ERRCODE = '42501';
  END IF;

  IF v_window.conversation_id <> p_conversation_id THEN
    RAISE EXCEPTION 'WINDOW_CONVERSATION_MISMATCH' USING ERRCODE = '22000';
  END IF;

  IF v_window.customer_id <> p_customer_id THEN
    RAISE EXCEPTION 'WINDOW_CUSTOMER_MISMATCH' USING ERRCODE = '42501';
  END IF;

  -- 5. Validate stable logical command identity
  IF v_delivery.client_command_id IS DISTINCT FROM p_window_id THEN
    RAISE EXCEPTION 'COMMAND_IDENTITY_MISMATCH' USING ERRCODE = '22023';
  END IF;

  -- 6. Validate claim authority: window must have active claim or match stable window command
  IF v_window.ai_claim_id IS DISTINCT FROM p_ai_claim_id
     AND v_delivery.client_command_id IS DISTINCT FROM v_window.id THEN
    RAISE EXCEPTION 'CLAIM_NOT_AUTHORIZED' USING ERRCODE = '42501';
  END IF;

  -- 7. Check delivery status and provider message ID
  IF v_delivery.delivery_status = 'SENT' THEN
    -- Idempotent replay: must match same provider_msg_id and client_command_id
    IF v_delivery.provider_message_id = p_provider_msg_id
       AND v_delivery.client_command_id = p_window_id
       AND v_delivery.interaction_id IS NOT NULL THEN
      RETURN v_delivery.interaction_id;
    ELSE
      RAISE EXCEPTION 'IDEMPOTENT_REPLAY_MISMATCH' USING ERRCODE = '23505';
    END IF;
  END IF;

  IF v_delivery.delivery_status <> 'PROVIDER_SENT_PENDING_FINALIZE' THEN
    RAISE EXCEPTION 'DELIVERY_NOT_FINALIZABLE: Status is %', v_delivery.delivery_status USING ERRCODE = '55000';
  END IF;

  IF v_delivery.provider_message_id IS DISTINCT FROM p_provider_msg_id THEN
    RAISE EXCEPTION 'PROVIDER_MSG_ID_MISMATCH' USING ERRCODE = '22023';
  END IF;

  -- 8. Validate SLA window state
  IF v_window.state <> 'OPEN' THEN
    IF v_window.state = 'AI_RESPONDED' AND v_window.ai_response_interaction_id = v_delivery.interaction_id THEN
      RETURN v_delivery.interaction_id;
    END IF;
    RAISE EXCEPTION 'WINDOW_NOT_OPEN: State is %', v_window.state USING ERRCODE = '55000';
  END IF;

  -- 9. Mint public interaction with actor_type = 'AI'
  v_interaction_id := gen_random_uuid();

  INSERT INTO public.interactions (
    id,
    company_id,
    customer_id,
    conversation_id,
    channel,
    type,
    direction,
    sanitized_content,
    sanitization_status,
    sanitized_at,
    sanitizer_version,
    actor_type,
    actor_user_id,
    external_ref,
    created_at
  ) VALUES (
    v_interaction_id,
    p_company_id,
    p_customer_id,
    p_conversation_id,
    v_delivery.channel,
    'MESSAGE',
    'OUTBOUND',
    p_sanitized_content,
    'SUCCEEDED',
    v_now,
    'v1',
    'AI',
    NULL,
    p_provider_msg_id,
    v_now
  );

  -- 10. Mandatory Provenance in private.interaction_raw_contents (Fail-Closed)
  INSERT INTO private.interaction_raw_contents (
    interaction_id,
    company_id,
    raw_content,
    raw_payload,
    source_metadata,
    created_at
  ) VALUES (
    v_interaction_id,
    p_company_id,
    coalesce(p_raw_content, ''),
    '{}'::jsonb,
    coalesce(p_source_metadata, '{}'::jsonb),
    v_now
  );

  -- 11. Update outbound_deliveries to SENT
  UPDATE public.outbound_deliveries
  SET
    delivery_status = 'SENT',
    interaction_id = v_interaction_id,
    lease_until = NULL,
    updated_at = v_now
  WHERE id = p_delivery_id;

  -- 12. Atomically resolve Response SLA window to AI_RESPONDED
  UPDATE public.response_sla_windows
  SET
    state = 'AI_RESPONDED',
    ai_response_interaction_id = v_interaction_id,
    resolved_at = v_now,
    updated_at = v_now
  WHERE id = p_window_id
    AND company_id = p_company_id
    AND state = 'OPEN';

  GET DIAGNOSTICS v_rows_updated = ROW_COUNT;
  IF v_rows_updated = 0 THEN
    RAISE EXCEPTION 'SLA_WINDOW_UPDATE_AFFECTED_ZERO_ROWS' USING ERRCODE = 'P0001';
  END IF;

  -- 13. Reset conversation status to OPEN and update last_message_at
  UPDATE public.conversations
  SET
    status = 'OPEN',
    last_message_at = v_now,
    updated_at = v_now
  WHERE id = p_conversation_id
    AND company_id = p_company_id;

  -- 14. Transactional audit log
  INSERT INTO public.audit_logs (
    company_id,
    user_id,
    action,
    resource_type,
    resource_id,
    customer_id,
    result,
    metadata
  ) VALUES (
    p_company_id,
    NULL,
    'RESPONSE_SLA_AI_RESPONDED',
    'INTERACTION',
    v_interaction_id,
    p_customer_id,
    'SUCCESS',
    jsonb_build_object(
      'delivery_id', p_delivery_id,
      'window_id', p_window_id,
      'ai_claim_id', p_ai_claim_id,
      'provider_msg_id', p_provider_msg_id
    )
  );

  RETURN v_interaction_id;
END;
$$;

CREATE OR REPLACE FUNCTION public.finalize_ai_zalo_sla_atomic(
  p_company_id uuid,
  p_window_id uuid,
  p_ai_claim_id uuid,
  p_zalo_delivery_id uuid,
  p_interaction_id uuid DEFAULT NULL,
  p_provider_msg_id text DEFAULT NULL,
  p_source_metadata jsonb DEFAULT '{}'::jsonb
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_zalo public.zalo_outbound_deliveries%ROWTYPE;
  v_conv public.conversations%ROWTYPE;
  v_window public.response_sla_windows%ROWTYPE;
  v_interaction_id uuid;
  v_ref text;
  v_rows_updated integer;
  v_expected_command text;
  v_now timestamptz := clock_timestamp();
BEGIN
  IF p_company_id IS NULL OR p_window_id IS NULL OR p_zalo_delivery_id IS NULL THEN
    RAISE EXCEPTION 'MANDATORY_PARAMETERS_MISSING' USING ERRCODE = '22023';
  END IF;

  v_expected_command := 'ai-sla-win-' || p_window_id::text;

  -- 1. Lock and validate Zalo outbound delivery
  SELECT * INTO v_zalo
  FROM public.zalo_outbound_deliveries
  WHERE id = p_zalo_delivery_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ZALO_DELIVERY_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  IF v_zalo.company_id <> p_company_id THEN
    RAISE EXCEPTION 'ZALO_DELIVERY_COMPANY_MISMATCH' USING ERRCODE = '42501';
  END IF;

  IF v_zalo.command_id IS DISTINCT FROM v_expected_command THEN
    RAISE EXCEPTION 'ZALO_COMMAND_ID_MISMATCH' USING ERRCODE = '22023';
  END IF;

  IF v_zalo.status NOT IN ('SENT', 'PROVIDER_SENT_PENDING_FINALIZE') THEN
    RAISE EXCEPTION 'ZALO_DELIVERY_NOT_FINALIZABLE: Status is %', v_zalo.status USING ERRCODE = '55000';
  END IF;

  -- 2. Lock and validate Conversation
  SELECT * INTO v_conv
  FROM public.conversations
  WHERE id = v_zalo.conversation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'CONVERSATION_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  IF v_conv.company_id <> p_company_id THEN
    RAISE EXCEPTION 'CONVERSATION_COMPANY_MISMATCH' USING ERRCODE = '42501';
  END IF;

  IF v_conv.channel <> 'ZALO' THEN
    RAISE EXCEPTION 'CONVERSATION_CHANNEL_MISMATCH' USING ERRCODE = '22000';
  END IF;

  -- 3. Lock and validate SLA window
  SELECT * INTO v_window
  FROM public.response_sla_windows
  WHERE id = p_window_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'WINDOW_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  IF v_window.company_id <> p_company_id THEN
    RAISE EXCEPTION 'WINDOW_COMPANY_MISMATCH' USING ERRCODE = '42501';
  END IF;

  IF v_window.conversation_id <> v_zalo.conversation_id THEN
    RAISE EXCEPTION 'WINDOW_CONVERSATION_MISMATCH' USING ERRCODE = '22000';
  END IF;

  IF v_window.customer_id <> v_zalo.customer_id THEN
    RAISE EXCEPTION 'WINDOW_CUSTOMER_MISMATCH' USING ERRCODE = '42501';
  END IF;

  -- 4. Validate claim authority
  IF v_window.ai_claim_id IS DISTINCT FROM p_ai_claim_id
     AND v_zalo.command_id IS DISTINCT FROM v_expected_command THEN
    RAISE EXCEPTION 'CLAIM_NOT_AUTHORIZED' USING ERRCODE = '42501';
  END IF;

  -- 5. Determine or mint interaction
  v_interaction_id := coalesce(p_interaction_id, v_zalo.interaction_id);

  IF v_interaction_id IS NULL THEN
    v_interaction_id := gen_random_uuid();
    v_ref := 'zalo:' || v_zalo.company_id::text || ':' || coalesce(v_zalo.oa_id, 'unknown') || ':'
             || coalesce(v_zalo.provider_msg_id, coalesce(p_provider_msg_id, 'outbound:' || v_zalo.id::text));

    INSERT INTO public.interactions (
      id,
      company_id,
      customer_id,
      conversation_id,
      channel,
      type,
      direction,
      sanitized_content,
      sanitization_status,
      sanitized_at,
      sanitizer_version,
      external_ref,
      actor_type,
      actor_user_id,
      created_at
    ) VALUES (
      v_interaction_id,
      v_zalo.company_id,
      v_zalo.customer_id,
      v_zalo.conversation_id,
      'ZALO',
      'MESSAGE',
      'OUTBOUND',
      v_zalo.content,
      'SUCCEEDED',
      v_now,
      'zalo-sanitizer-v1',
      v_ref,
      'AI',
      NULL,
      v_now
    );

    UPDATE public.zalo_outbound_deliveries
    SET status = 'SENT',
        interaction_id = v_interaction_id,
        provider_msg_id = coalesce(v_zalo.provider_msg_id, p_provider_msg_id),
        finalized_at = v_now,
        lease_until = NULL,
        error_code = NULL,
        error_message = NULL,
        updated_at = v_now
    WHERE id = v_zalo.id;
  END IF;

  -- 6. Idempotent check
  IF v_window.state = 'AI_RESPONDED' AND v_window.ai_response_interaction_id = v_interaction_id THEN
    RETURN v_interaction_id;
  END IF;

  IF v_window.state <> 'OPEN' THEN
    RAISE EXCEPTION 'WINDOW_NOT_OPEN: State is %', v_window.state USING ERRCODE = '55000';
  END IF;

  -- 7. Atomically resolve Response SLA window
  UPDATE public.response_sla_windows
  SET
    state = 'AI_RESPONDED',
    ai_response_interaction_id = v_interaction_id,
    resolved_at = v_now,
    updated_at = v_now
  WHERE id = p_window_id
    AND company_id = p_company_id
    AND state = 'OPEN';

  GET DIAGNOSTICS v_rows_updated = ROW_COUNT;
  IF v_rows_updated = 0 THEN
    RAISE EXCEPTION 'SLA_WINDOW_UPDATE_AFFECTED_ZERO_ROWS' USING ERRCODE = 'P0001';
  END IF;

  -- 8. Enrich private.interaction_raw_contents with full AI Provenance (Blocker H)
  UPDATE private.interaction_raw_contents
  SET
    source_metadata = coalesce(source_metadata, '{}'::jsonb) || p_source_metadata,
    created_at = coalesce(created_at, v_now)
  WHERE interaction_id = v_interaction_id
    AND company_id = p_company_id;

  IF NOT FOUND THEN
    INSERT INTO private.interaction_raw_contents (
      interaction_id,
      company_id,
      raw_content,
      raw_payload,
      source_metadata,
      created_at
    ) VALUES (
      v_interaction_id,
      p_company_id,
      v_zalo.content,
      '{}'::jsonb,
      coalesce(p_source_metadata, '{}'::jsonb),
      v_now
    );
  END IF;

  -- 9. Reset conversation status to OPEN
  UPDATE public.conversations
  SET
    status = 'OPEN',
    last_message_at = v_now,
    updated_at = v_now
  WHERE id = v_zalo.conversation_id
    AND company_id = p_company_id;

  -- 10. Transactional audit log
  INSERT INTO public.audit_logs (
    company_id,
    user_id,
    action,
    resource_type,
    resource_id,
    customer_id,
    result,
    metadata
  ) VALUES (
    p_company_id,
    NULL,
    'RESPONSE_SLA_AI_RESPONDED',
    'INTERACTION',
    v_interaction_id,
    v_zalo.customer_id,
    'SUCCESS',
    jsonb_build_object(
      'zalo_delivery_id', p_zalo_delivery_id,
      'window_id', p_window_id,
      'ai_claim_id', p_ai_claim_id,
      'provider_msg_id', coalesce(v_zalo.provider_msg_id, p_provider_msg_id)
    )
  );

  RETURN v_interaction_id;
END;
$$;

CREATE OR REPLACE FUNCTION public.guard_ai_pre_dispatch(
  p_company_id uuid,
  p_conversation_id uuid,
  p_customer_id uuid,
  p_window_id uuid,
  p_ai_claim_id uuid,
  p_channel text,
  p_lease_seconds integer DEFAULT 120
)
RETURNS TABLE (
  granted boolean,
  reason text,
  delivery_id uuid,
  provider_msg_id text,
  interaction_id uuid,
  window_state text,
  dispatch_token uuid
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
#variable_conflict use_column
DECLARE
  v_window public.response_sla_windows%ROWTYPE;
  v_conv public.conversations%ROWTYPE;
  v_del public.outbound_deliveries%ROWTYPE;
  v_zalo public.zalo_outbound_deliveries%ROWTYPE;
  v_sale_reply_id uuid;
  v_sale_reply_resolved_at timestamptz;
  v_stable_zalo_command text;
  v_new_delivery_id uuid;
  v_dispatch_token uuid;
  v_now timestamptz := clock_timestamp();
  v_lease interval := make_interval(secs => greatest(coalesce(p_lease_seconds, 120), 10));
BEGIN
  -- A. Mandatory input validation
  IF p_company_id IS NULL OR p_conversation_id IS NULL OR p_customer_id IS NULL OR p_window_id IS NULL THEN
    RETURN QUERY SELECT false, 'INVALID_ARGUMENTS'::text, NULL::uuid, NULL::text, NULL::uuid, NULL::text, NULL::uuid;
    RETURN;
  END IF;

  -- Item 5: Mandatory claim ID for new dispatch (no NULL authorization bypass)
  IF p_ai_claim_id IS NULL THEN
    RETURN QUERY SELECT false, 'CLAIM_ID_MANDATORY'::text, NULL::uuid, NULL::text, NULL::uuid, NULL::text, NULL::uuid;
    RETURN;
  END IF;

  -- B. Lock SLA Window
  SELECT * INTO v_window
  FROM public.response_sla_windows
  WHERE id = p_window_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN QUERY SELECT false, 'WINDOW_NOT_FOUND'::text, NULL::uuid, NULL::text, NULL::uuid, NULL::text, NULL::uuid;
    RETURN;
  END IF;

  IF v_window.company_id <> p_company_id THEN
    RETURN QUERY SELECT false, 'WRONG_COMPANY'::text, NULL::uuid, NULL::text, NULL::uuid, v_window.state, NULL::uuid;
    RETURN;
  END IF;

  IF v_window.conversation_id <> p_conversation_id THEN
    RETURN QUERY SELECT false, 'CONVERSATION_MISMATCH'::text, NULL::uuid, NULL::text, NULL::uuid, v_window.state, NULL::uuid;
    RETURN;
  END IF;

  IF v_window.customer_id <> p_customer_id THEN
    RETURN QUERY SELECT false, 'CUSTOMER_MISMATCH'::text, NULL::uuid, NULL::text, NULL::uuid, v_window.state, NULL::uuid;
    RETURN;
  END IF;

  IF v_window.state <> 'OPEN' THEN
    RETURN QUERY SELECT false, v_window.state, NULL::uuid, NULL::text, NULL::uuid, v_window.state, NULL::uuid;
    RETURN;
  END IF;

  IF v_window.ai_claim_id IS DISTINCT FROM p_ai_claim_id THEN
    RETURN QUERY SELECT false, 'CLAIM_MISMATCH'::text, NULL::uuid, NULL::text, NULL::uuid, v_window.state, NULL::uuid;
    RETURN;
  END IF;

  IF v_window.ai_claim_expires_at IS NOT NULL AND v_window.ai_claim_expires_at <= v_now THEN
    RETURN QUERY SELECT false, 'CLAIM_EXPIRED'::text, NULL::uuid, NULL::text, NULL::uuid, v_window.state, NULL::uuid;
    RETURN;
  END IF;

  -- C. Lock Conversation
  SELECT * INTO v_conv
  FROM public.conversations
  WHERE id = p_conversation_id AND company_id = p_company_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN QUERY SELECT false, 'CONVERSATION_NOT_FOUND'::text, NULL::uuid, NULL::text, NULL::uuid, v_window.state, NULL::uuid;
    RETURN;
  END IF;

  IF v_conv.status = 'CLOSED' THEN
    RETURN QUERY SELECT false, 'CONVERSATION_CLOSED'::text, NULL::uuid, NULL::text, NULL::uuid, v_window.state, NULL::uuid;
    RETURN;
  END IF;

  -- D. Authoritative Check: Did Sale respond after window.started_at?
  SELECT
    i.id,
    coalesce(o.sent_at, i.created_at)
  INTO
    v_sale_reply_id,
    v_sale_reply_resolved_at
  FROM public.interactions i
  LEFT JOIN private.han_outbox o
    ON o.company_id = p_company_id AND o.interaction_id = i.id
  WHERE i.company_id = p_company_id
    AND i.conversation_id = p_conversation_id
    AND i.actor_type = 'SALE'
    AND i.direction = 'OUTBOUND'
    AND i.type = 'MESSAGE'
    AND i.created_at >= v_window.started_at
    AND (
      CASE WHEN o.interaction_id IS NOT NULL THEN o.status = 'SENT' ELSE true END
    )
  ORDER BY i.created_at DESC
  LIMIT 1;

  IF FOUND THEN
    -- Sale won the race! Transition to SALE_RESPONDED atomically
    UPDATE public.response_sla_windows
    SET
      state = 'SALE_RESPONDED',
      sale_response_interaction_id = v_sale_reply_id,
      resolved_at = coalesce(v_sale_reply_resolved_at, v_now),
      ai_dispatch_fenced_until = NULL,
      ai_dispatch_token = NULL,
      updated_at = v_now
    WHERE id = p_window_id;

    IF v_conv.status = 'AI_HANDLING' THEN
      UPDATE public.conversations
      SET status = 'OPEN', updated_at = v_now
      WHERE id = p_conversation_id;
    END IF;

    INSERT INTO public.audit_logs (
      company_id,
      user_id,
      action,
      resource_type,
      resource_id,
      customer_id,
      result,
      metadata
    ) VALUES (
      p_company_id,
      NULL,
      'RESPONSE_SLA_AI_CLAIM',
      'RESPONSE_SLA_WINDOW',
      p_window_id,
      p_customer_id,
      'DENIED',
      jsonb_build_object(
        'decision', 'DENIED',
        'reason', 'SALE_ALREADY_RESPONDED',
        'sale_response_interaction_id', v_sale_reply_id,
        'window_id', p_window_id
      )
    );

    RETURN QUERY SELECT false, 'SALE_ALREADY_RESPONDED'::text, NULL::uuid, NULL::text, NULL::uuid, 'SALE_RESPONDED'::text, NULL::uuid;
    RETURN;
  END IF;

  -- Generate durable dispatch token for ownership proof
  v_dispatch_token := gen_random_uuid();

  -- E. Channel-specific state machine check
  IF p_channel = 'ZALO' THEN
    v_stable_zalo_command := 'ai-sla-win-' || p_window_id::text;

    SELECT * INTO v_zalo
    FROM public.zalo_outbound_deliveries
    WHERE company_id = p_company_id
      AND channel = 'ZALO'
      AND command_id = v_stable_zalo_command
    FOR UPDATE;

    IF FOUND THEN
      IF v_zalo.status = 'SENT' THEN
        RETURN QUERY SELECT false, 'ALREADY_SENT'::text, v_zalo.id, v_zalo.provider_msg_id, v_zalo.interaction_id, v_window.state, NULL::uuid;
        RETURN;
      ELSIF v_zalo.status = 'PROVIDER_SENT_PENDING_FINALIZE' THEN
        RETURN QUERY SELECT false, 'PENDING_FINALIZE'::text, v_zalo.id, v_zalo.provider_msg_id, NULL::uuid, v_window.state, NULL::uuid;
        RETURN;
      ELSIF v_zalo.status IN ('PROVIDER_UNCERTAIN', 'UNCERTAIN') THEN
        RETURN QUERY SELECT false, 'UNCERTAIN'::text, v_zalo.id, v_zalo.provider_msg_id, NULL::uuid, v_window.state, NULL::uuid;
        RETURN;
      ELSIF v_zalo.status = 'SENDING' AND v_zalo.lease_until IS NOT NULL AND v_zalo.lease_until > v_now THEN
        RETURN QUERY SELECT false, 'BUSY'::text, v_zalo.id, NULL::text, NULL::uuid, v_window.state, NULL::uuid;
        RETURN;
      ELSIF v_zalo.status = 'SENDING' THEN
        -- Lease expired mid-flight: transition to UNCERTAIN, never auto-retry
        UPDATE public.zalo_outbound_deliveries
        SET status = 'PROVIDER_UNCERTAIN', lease_until = NULL, error_code = 'LEASE_EXPIRED_OUTCOME_UNKNOWN', updated_at = v_now
        WHERE id = v_zalo.id;

        RETURN QUERY SELECT false, 'UNCERTAIN'::text, v_zalo.id, NULL::text, NULL::uuid, v_window.state, NULL::uuid;
        RETURN;
      END IF;

      -- If status is FAILED or PENDING, grant dispatch under fence
      UPDATE public.response_sla_windows
      SET
        ai_dispatch_fenced_until = v_now + v_lease,
        ai_dispatch_delivery_id = v_zalo.id,
        ai_dispatch_token = v_dispatch_token,
        updated_at = v_now
      WHERE id = p_window_id;

      RETURN QUERY SELECT true, 'GRANTED'::text, v_zalo.id, NULL::text, NULL::uuid, v_window.state, v_dispatch_token;
      RETURN;
    END IF;

    -- No prior row: dispatch authority granted for Zalo under fence
    UPDATE public.response_sla_windows
    SET
      ai_dispatch_fenced_until = v_now + v_lease,
      ai_dispatch_delivery_id = NULL,
      ai_dispatch_token = v_dispatch_token,
      updated_at = v_now
    WHERE id = p_window_id;

    RETURN QUERY SELECT true, 'GRANTED'::text, NULL::uuid, NULL::text, NULL::uuid, v_window.state, v_dispatch_token;
    RETURN;

  ELSE
    -- Generic / Facebook channel backed by public.outbound_deliveries
    SELECT * INTO v_del
    FROM public.outbound_deliveries
    WHERE company_id = p_company_id
      AND client_command_id = p_window_id
    FOR UPDATE;

    IF FOUND THEN
      IF v_del.delivery_status = 'SENT' THEN
        RETURN QUERY SELECT false, 'ALREADY_SENT'::text, v_del.id, v_del.provider_message_id, v_del.interaction_id, v_window.state, NULL::uuid;
        RETURN;
      ELSIF v_del.delivery_status = 'PROVIDER_SENT_PENDING_FINALIZE' THEN
        RETURN QUERY SELECT false, 'PENDING_FINALIZE'::text, v_del.id, v_del.provider_message_id, NULL::uuid, v_window.state, NULL::uuid;
        RETURN;
      ELSIF v_del.delivery_status IN ('UNCERTAIN', 'PROVIDER_UNCERTAIN') THEN
        RETURN QUERY SELECT false, 'UNCERTAIN'::text, v_del.id, v_del.provider_message_id, NULL::uuid, v_window.state, NULL::uuid;
        RETURN;
      ELSIF v_del.delivery_status = 'DISPATCHING' AND v_del.lease_until IS NOT NULL AND v_del.lease_until > v_now THEN
        RETURN QUERY SELECT false, 'BUSY'::text, v_del.id, NULL::text, NULL::uuid, v_window.state, NULL::uuid;
        RETURN;
      ELSIF v_del.delivery_status = 'DISPATCHING' THEN
        -- Lease expired mid-flight: transition to UNCERTAIN, never auto-retry
        UPDATE public.outbound_deliveries
        SET delivery_status = 'UNCERTAIN', lease_until = NULL, error_message = 'LEASE_EXPIRED_OUTCOME_UNKNOWN', updated_at = v_now
        WHERE id = v_del.id;

        RETURN QUERY SELECT false, 'UNCERTAIN'::text, v_del.id, NULL::text, NULL::uuid, v_window.state, NULL::uuid;
        RETURN;
      ELSIF v_del.delivery_status IN ('PENDING', 'PENDING_DISPATCH', 'FAILED') THEN
        -- Transition to DISPATCHING under active lease and dispatch_token
        UPDATE public.outbound_deliveries
        SET
          delivery_status = 'DISPATCHING',
          dispatch_token = v_dispatch_token,
          lease_until = v_now + v_lease,
          locked_at = v_now,
          locked_by = 'ai_response_runtime',
          updated_at = v_now
        WHERE id = v_del.id;

        UPDATE public.response_sla_windows
        SET
          ai_dispatch_fenced_until = v_now + v_lease,
          ai_dispatch_delivery_id = v_del.id,
          ai_dispatch_token = v_dispatch_token,
          updated_at = v_now
        WHERE id = p_window_id;

        RETURN QUERY SELECT true, 'GRANTED'::text, v_del.id, NULL::text, NULL::uuid, v_window.state, v_dispatch_token;
        RETURN;
      END IF;

      RETURN QUERY SELECT false, ('UNEXPECTED_STATUS_' || v_del.delivery_status)::text, v_del.id, NULL::text, NULL::uuid, v_window.state, NULL::uuid;
      RETURN;
    END IF;

    -- No prior row: insert new row in DISPATCHING state with stable command ID = window_id
    v_new_delivery_id := gen_random_uuid();
    INSERT INTO public.outbound_deliveries (
      id,
      company_id,
      conversation_id,
      interaction_id,
      channel,
      delivery_status,
      client_command_id,
      window_id,
      request_fingerprint,
      lease_until,
      dispatch_token,
      locked_at,
      locked_by,
      created_at,
      updated_at
    ) VALUES (
      v_new_delivery_id,
      p_company_id,
      p_conversation_id,
      NULL,
      p_channel,
      'DISPATCHING',
      p_window_id,
      p_window_id,
      p_company_id::text || ':' || p_conversation_id::text || ':' || p_window_id::text,
      v_now + v_lease,
      v_dispatch_token,
      v_now,
      'ai_response_runtime',
      v_now,
      v_now
    );

    UPDATE public.response_sla_windows
    SET
      ai_dispatch_fenced_until = v_now + v_lease,
      ai_dispatch_delivery_id = v_new_delivery_id,
      ai_dispatch_token = v_dispatch_token,
      updated_at = v_now
    WHERE id = p_window_id;

    RETURN QUERY SELECT true, 'GRANTED'::text, v_new_delivery_id, NULL::text, NULL::uuid, v_window.state, v_dispatch_token;
    RETURN;
  END IF;
END;
$$;

CREATE OR REPLACE FUNCTION public.record_ai_outbound_provider_result(
  p_company_id uuid,
  p_delivery_id uuid,
  p_outcome text,
  p_dispatch_token uuid,
  p_provider_msg_id text DEFAULT NULL,
  p_error_message text DEFAULT NULL
)
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_del public.outbound_deliveries%ROWTYPE;
  v_new_status text;
  v_now timestamptz := clock_timestamp();
BEGIN
  IF p_company_id IS NULL OR p_delivery_id IS NULL OR p_outcome IS NULL OR p_dispatch_token IS NULL THEN
    RAISE EXCEPTION 'MANDATORY_PARAMETERS_MISSING' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_del
  FROM public.outbound_deliveries
  WHERE id = p_delivery_id AND company_id = p_company_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'DELIVERY_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  -- Validate dispatch token ownership (Item 7)
  IF v_del.dispatch_token IS DISTINCT FROM p_dispatch_token THEN
    RAISE EXCEPTION 'DISPATCH_TOKEN_MISMATCH' USING ERRCODE = '42501';
  END IF;

  -- Validate allowed source delivery states
  IF v_del.delivery_status = 'PROVIDER_SENT_PENDING_FINALIZE' AND p_outcome = 'SENT'
     AND v_del.provider_message_id IS NOT DISTINCT FROM p_provider_msg_id THEN
    RETURN 'PROVIDER_SENT_PENDING_FINALIZE';
  END IF;

  IF v_del.delivery_status NOT IN ('DISPATCHING', 'UNCERTAIN', 'PROVIDER_UNCERTAIN') THEN
    RAISE EXCEPTION 'INVALID_DELIVERY_STATE_TRANSITION: %', v_del.delivery_status USING ERRCODE = '55000';
  END IF;

  IF p_outcome = 'SENT' THEN
    IF p_provider_msg_id IS NULL OR length(trim(p_provider_msg_id)) = 0 THEN
      RAISE EXCEPTION 'CANNOT_RECORD_SENT_WITHOUT_PROVIDER_MESSAGE_ID' USING ERRCODE = '22023';
    END IF;
    v_new_status := 'PROVIDER_SENT_PENDING_FINALIZE';

    UPDATE public.outbound_deliveries
    SET
      delivery_status = v_new_status,
      provider_message_id = p_provider_msg_id,
      lease_until = NULL,
      updated_at = v_now
    WHERE id = p_delivery_id;

  ELSIF p_outcome = 'FAILED' THEN
    v_new_status := 'FAILED';

    UPDATE public.outbound_deliveries
    SET
      delivery_status = v_new_status,
      error_message = coalesce(p_error_message, 'Provider rejected message'),
      lease_until = NULL,
      dispatch_token = NULL,
      updated_at = v_now
    WHERE id = p_delivery_id;

    -- Un-fence SLA window on failure so window can be recovered or answered by Sale
    IF v_del.window_id IS NOT NULL THEN
      UPDATE public.response_sla_windows
      SET ai_dispatch_fenced_until = NULL,
          ai_dispatch_token = NULL,
          updated_at = v_now
      WHERE id = v_del.window_id
        AND ai_dispatch_token = p_dispatch_token;
    END IF;

  ELSIF p_outcome IN ('UNCERTAIN', 'UNKNOWN') THEN
    v_new_status := 'UNCERTAIN';

    UPDATE public.outbound_deliveries
    SET
      delivery_status = v_new_status,
      error_message = coalesce(p_error_message, 'Provider outcome uncertain'),
      lease_until = NULL,
      updated_at = v_now
    WHERE id = p_delivery_id;

  ELSE
    RAISE EXCEPTION 'INVALID_OUTBOUND_OUTCOME: %', p_outcome USING ERRCODE = '22023';
  END IF;

  RETURN v_new_status;
END;
$$;

CREATE OR REPLACE FUNCTION public.resolve_response_sla_on_sale_reply(
  p_company_id uuid,
  p_conversation_id uuid,
  p_sale_interaction_id uuid,
  p_resolved_at timestamptz DEFAULT NULL
)
RETURNS TABLE (
  id uuid,
  company_id uuid,
  conversation_id uuid,
  customer_id uuid,
  trigger_interaction_id uuid,
  started_at timestamptz,
  deadline_at timestamptz,
  state text,
  resolved_at timestamptz,
  sale_response_interaction_id uuid,
  ai_response_interaction_id uuid,
  ai_claimed_at timestamptz,
  ai_claim_id uuid,
  ai_claim_expires_at timestamptz,
  created_at timestamptz,
  updated_at timestamptz
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_customer_id uuid;
  v_interaction_company_id uuid;
  v_interaction_customer_id uuid;
  v_interaction_convo_id uuid;
  v_interaction_type text;
  v_interaction_direction text;
  v_interaction_actor text;
  v_interaction_created_at timestamptz;
  v_resolved_at timestamptz;
  v_window public.response_sla_windows%ROWTYPE;
  v_resolved_window public.response_sla_windows%ROWTYPE;
  v_outbox private.han_outbox%ROWTYPE;
BEGIN
  -- 1. Validate Conversation existence & tenant binding
  SELECT c.customer_id
  INTO v_customer_id
  FROM public.conversations c
  WHERE c.id = p_conversation_id
    AND c.company_id = p_company_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'CONVERSATION_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  -- 2. Validate Sale Interaction (enforce company, customer, conversation alignment)
  SELECT
    i.company_id,
    i.customer_id,
    i.conversation_id,
    i.type,
    i.direction,
    i.actor_type,
    i.created_at
  INTO
    v_interaction_company_id,
    v_interaction_customer_id,
    v_interaction_convo_id,
    v_interaction_type,
    v_interaction_direction,
    v_interaction_actor,
    v_interaction_created_at
  FROM public.interactions i
  WHERE i.id = p_sale_interaction_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'SALE_INTERACTION_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  IF v_interaction_company_id <> p_company_id THEN
    RAISE EXCEPTION 'INTERACTION_COMPANY_MISMATCH' USING ERRCODE = '42501';
  END IF;

  IF v_interaction_convo_id IS NULL OR v_interaction_convo_id <> p_conversation_id THEN
    RAISE EXCEPTION 'INTERACTION_CONVERSATION_MISMATCH' USING ERRCODE = '22000';
  END IF;

  IF v_interaction_customer_id <> v_customer_id THEN
    RAISE EXCEPTION 'INTERACTION_CUSTOMER_MISMATCH' USING ERRCODE = '22000';
  END IF;

  IF v_interaction_type <> 'MESSAGE' THEN
    RAISE EXCEPTION 'INVALID_INTERACTION_TYPE' USING ERRCODE = '22000';
  END IF;

  IF v_interaction_direction <> 'OUTBOUND' THEN
    RAISE EXCEPTION 'INVALID_INTERACTION_DIRECTION' USING ERRCODE = '22000';
  END IF;

  IF v_interaction_actor <> 'SALE' THEN
    RAISE EXCEPTION 'INVALID_INTERACTION_ACTOR' USING ERRCODE = '22000';
  END IF;

  -- Canonical resolved timestamp rules:
  -- Priority 1: If matching Hán outbox row exists, outbox.sent_at is canonical and authoritative.
  SELECT *
  INTO v_outbox
  FROM private.han_outbox o
  WHERE o.company_id = p_company_id
    AND o.interaction_id = p_sale_interaction_id;

  IF FOUND THEN
    IF v_outbox.status <> 'SENT' OR v_outbox.sent_at IS NULL THEN
      RAISE EXCEPTION 'OUTBOX_NOT_CONFIRMED' USING ERRCODE = '22000';
    END IF;

    IF v_outbox.sent_at < v_interaction_created_at THEN
      RAISE EXCEPTION 'CORRUPT_OUTBOX_SENT_AT' USING ERRCODE = '22000';
    END IF;

    v_resolved_at := v_outbox.sent_at;
  ELSE
    -- Priority 2: Non-Hán / generic channel compatibility:
    IF p_resolved_at IS NOT NULL THEN
      IF p_resolved_at < v_interaction_created_at THEN
        RAISE EXCEPTION 'RESOLVED_AT_CANNOT_PRECEDE_INTERACTION' USING ERRCODE = '22000';
      END IF;
      v_resolved_at := p_resolved_at;
    ELSE
      v_resolved_at := v_interaction_created_at;
    END IF;
  END IF;

  -- 3. Lock OPEN SLA window for this conversation
  SELECT *
  INTO v_window
  FROM public.response_sla_windows w
  WHERE w.company_id = p_company_id
    AND w.conversation_id = p_conversation_id
    AND w.state = 'OPEN'
  FOR UPDATE;

  -- 4. If no OPEN window, return empty set (idempotent no-op)
  IF NOT FOUND THEN
    RETURN;
  END IF;

  -- 4b. Linearization Fence Check (Item 1):
  -- If AI has acquired pre-dispatch authority and the fence is still active,
  -- AI is currently dispatching to provider. Sale resolver yields so AI can finalize as winner.
  IF v_window.ai_dispatch_fenced_until IS NOT NULL AND v_window.ai_dispatch_fenced_until > clock_timestamp() THEN
    RETURN;
  END IF;

  -- 5. Resolve window to SALE_RESPONDED
  UPDATE public.response_sla_windows
  SET state = 'SALE_RESPONDED',
      sale_response_interaction_id = p_sale_interaction_id,
      resolved_at = v_resolved_at,
      ai_dispatch_fenced_until = NULL,
      ai_dispatch_token = NULL,
      updated_at = clock_timestamp()
  WHERE public.response_sla_windows.id = v_window.id
  RETURNING * INTO v_resolved_window;

  -- 6. If conversation was in AI_HANDLING, reset to OPEN because Sale has stepped in
  UPDATE public.conversations
  SET status = 'OPEN',
      updated_at = clock_timestamp()
  WHERE public.conversations.id = p_conversation_id
    AND public.conversations.status = 'AI_HANDLING';

  RETURN QUERY
  SELECT
    v_resolved_window.id,
    v_resolved_window.company_id,
    v_resolved_window.conversation_id,
    v_resolved_window.customer_id,
    v_resolved_window.trigger_interaction_id,
    v_resolved_window.started_at,
    v_resolved_window.deadline_at,
    v_resolved_window.state,
    v_resolved_window.resolved_at,
    v_resolved_window.sale_response_interaction_id,
    v_resolved_window.ai_response_interaction_id,
    v_resolved_window.ai_claimed_at,
    v_resolved_window.ai_claim_id,
    v_resolved_window.ai_claim_expires_at,
    v_resolved_window.created_at,
    v_resolved_window.updated_at;
END;
$$;

CREATE OR REPLACE FUNCTION public.finalize_ai_outbound_delivery_atomic(
  p_company_id uuid,
  p_delivery_id uuid,
  p_conversation_id uuid,
  p_customer_id uuid,
  p_window_id uuid,
  p_ai_claim_id uuid,
  p_provider_msg_id text,
  p_sanitized_content text,
  p_raw_content text,
  p_source_metadata jsonb DEFAULT '{}'::jsonb
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_delivery public.outbound_deliveries%ROWTYPE;
  v_conv public.conversations%ROWTYPE;
  v_window public.response_sla_windows%ROWTYPE;
  v_interaction_id uuid;
  v_rows_updated integer;
  v_now timestamptz := clock_timestamp();
BEGIN
  -- 1. Validate mandatory fields
  IF p_company_id IS NULL OR p_delivery_id IS NULL OR p_conversation_id IS NULL
     OR p_customer_id IS NULL OR p_window_id IS NULL THEN
    RAISE EXCEPTION 'MANDATORY_PARAMETERS_MISSING' USING ERRCODE = '22023';
  END IF;

  IF p_provider_msg_id IS NULL OR length(trim(p_provider_msg_id)) = 0 THEN
    RAISE EXCEPTION 'CANNOT_FINALIZE_WITHOUT_PROVIDER_MESSAGE_ID' USING ERRCODE = '22023';
  END IF;

  -- 2. Lock and validate outbound delivery
  SELECT * INTO v_delivery
  FROM public.outbound_deliveries
  WHERE id = p_delivery_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'DELIVERY_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  IF v_delivery.company_id <> p_company_id THEN
    RAISE EXCEPTION 'DELIVERY_COMPANY_MISMATCH' USING ERRCODE = '42501';
  END IF;

  IF v_delivery.conversation_id <> p_conversation_id THEN
    RAISE EXCEPTION 'DELIVERY_CONVERSATION_MISMATCH' USING ERRCODE = '22000';
  END IF;

  -- 3. Lock and validate canonical conversation
  SELECT * INTO v_conv
  FROM public.conversations
  WHERE id = p_conversation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'CONVERSATION_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  IF v_conv.company_id <> p_company_id THEN
    RAISE EXCEPTION 'CONVERSATION_COMPANY_MISMATCH' USING ERRCODE = '42501';
  END IF;

  IF v_conv.customer_id <> p_customer_id THEN
    RAISE EXCEPTION 'CONVERSATION_CUSTOMER_MISMATCH' USING ERRCODE = '42501';
  END IF;

  IF v_delivery.channel <> v_conv.channel THEN
    RAISE EXCEPTION 'DELIVERY_CHANNEL_MISMATCH' USING ERRCODE = '22000';
  END IF;

  -- 4. Validate stable logical command identity & window binding
  IF (v_delivery.window_id IS NOT NULL AND v_delivery.window_id <> p_window_id)
     OR v_delivery.client_command_id IS DISTINCT FROM p_window_id THEN
    RAISE EXCEPTION 'COMMAND_IDENTITY_MISMATCH' USING ERRCODE = '22023';
  END IF;

  -- 5. Lock and validate SLA window
  SELECT * INTO v_window
  FROM public.response_sla_windows
  WHERE id = p_window_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'WINDOW_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  IF v_window.company_id <> p_company_id THEN
    RAISE EXCEPTION 'WINDOW_COMPANY_MISMATCH' USING ERRCODE = '42501';
  END IF;

  IF v_window.conversation_id <> p_conversation_id THEN
    RAISE EXCEPTION 'WINDOW_CONVERSATION_MISMATCH' USING ERRCODE = '22000';
  END IF;

  IF v_window.customer_id <> p_customer_id THEN
    RAISE EXCEPTION 'WINDOW_CUSTOMER_MISMATCH' USING ERRCODE = '42501';
  END IF;

  -- 6. Validate claim authority (Item 2: strict validation, no unconditional bypass)
  IF p_ai_claim_id IS NULL OR v_window.ai_claim_id IS DISTINCT FROM p_ai_claim_id THEN
    RAISE EXCEPTION 'CLAIM_NOT_AUTHORIZED' USING ERRCODE = '42501';
  END IF;

  -- 7. Check delivery status and provider message ID
  IF v_delivery.delivery_status = 'SENT' THEN
    -- Idempotent replay: must match same provider_msg_id and client_command_id
    IF v_delivery.provider_message_id = p_provider_msg_id
       AND v_delivery.client_command_id = p_window_id
       AND v_delivery.interaction_id IS NOT NULL THEN
      RETURN v_delivery.interaction_id;
    ELSE
      RAISE EXCEPTION 'IDEMPOTENT_REPLAY_MISMATCH' USING ERRCODE = '23505';
    END IF;
  END IF;

  IF v_delivery.delivery_status <> 'PROVIDER_SENT_PENDING_FINALIZE' THEN
    RAISE EXCEPTION 'DELIVERY_NOT_FINALIZABLE: Status is %', v_delivery.delivery_status USING ERRCODE = '55000';
  END IF;

  IF v_delivery.provider_message_id IS DISTINCT FROM p_provider_msg_id THEN
    RAISE EXCEPTION 'PROVIDER_MSG_ID_MISMATCH' USING ERRCODE = '22023';
  END IF;

  -- 8. Validate SLA window state
  IF v_window.state <> 'OPEN' THEN
    IF v_window.state = 'AI_RESPONDED' AND v_window.ai_response_interaction_id = v_delivery.interaction_id THEN
      RETURN v_delivery.interaction_id;
    END IF;
    RAISE EXCEPTION 'WINDOW_NOT_OPEN: State is %', v_window.state USING ERRCODE = '55000';
  END IF;

  -- 9. Mint public interaction with actor_type = 'AI'
  v_interaction_id := gen_random_uuid();

  INSERT INTO public.interactions (
    id,
    company_id,
    customer_id,
    conversation_id,
    channel,
    type,
    direction,
    sanitized_content,
    sanitization_status,
    sanitized_at,
    sanitizer_version,
    actor_type,
    actor_user_id,
    external_ref,
    created_at
  ) VALUES (
    v_interaction_id,
    p_company_id,
    p_customer_id,
    p_conversation_id,
    v_delivery.channel,
    'MESSAGE',
    'OUTBOUND',
    p_sanitized_content,
    'SUCCEEDED',
    v_now,
    'v1',
    'AI',
    NULL,
    p_provider_msg_id,
    v_now
  );

  -- 10. Mandatory Provenance in private.interaction_raw_contents (Fail-Closed)
  INSERT INTO private.interaction_raw_contents (
    interaction_id,
    company_id,
    raw_content,
    raw_payload,
    source_metadata,
    created_at
  ) VALUES (
    v_interaction_id,
    p_company_id,
    coalesce(p_raw_content, ''),
    '{}'::jsonb,
    coalesce(p_source_metadata, '{}'::jsonb),
    v_now
  );

  -- 11. Update outbound_deliveries to SENT
  UPDATE public.outbound_deliveries
  SET
    delivery_status = 'SENT',
    interaction_id = v_interaction_id,
    lease_until = NULL,
    updated_at = v_now
  WHERE id = p_delivery_id;

  -- 12. Atomically resolve Response SLA window to AI_RESPONDED & clear linearization fence
  UPDATE public.response_sla_windows
  SET
    state = 'AI_RESPONDED',
    ai_response_interaction_id = v_interaction_id,
    resolved_at = v_now,
    ai_dispatch_fenced_until = NULL,
    ai_dispatch_token = NULL,
    updated_at = v_now
  WHERE id = p_window_id
    AND company_id = p_company_id
    AND state = 'OPEN';

  GET DIAGNOSTICS v_rows_updated = ROW_COUNT;
  IF v_rows_updated = 0 THEN
    RAISE EXCEPTION 'SLA_WINDOW_UPDATE_AFFECTED_ZERO_ROWS' USING ERRCODE = 'P0001';
  END IF;

  -- 13. Reset conversation status to OPEN and update last_message_at
  UPDATE public.conversations
  SET
    status = 'OPEN',
    last_message_at = v_now,
    updated_at = v_now
  WHERE id = p_conversation_id
    AND company_id = p_company_id;

  -- 14. Transactional audit log
  INSERT INTO public.audit_logs (
    company_id,
    user_id,
    action,
    resource_type,
    resource_id,
    customer_id,
    result,
    metadata
  ) VALUES (
    p_company_id,
    NULL,
    'RESPONSE_SLA_AI_RESPONDED',
    'INTERACTION',
    v_interaction_id,
    p_customer_id,
    'SUCCESS',
    jsonb_build_object(
      'delivery_id', p_delivery_id,
      'window_id', p_window_id,
      'ai_claim_id', p_ai_claim_id,
      'provider_msg_id', p_provider_msg_id
    )
  );

  RETURN v_interaction_id;
END;
$$;

CREATE OR REPLACE FUNCTION public.finalize_ai_zalo_sla_atomic(
  p_company_id uuid,
  p_window_id uuid,
  p_ai_claim_id uuid,
  p_zalo_delivery_id uuid,
  p_interaction_id uuid DEFAULT NULL,
  p_provider_msg_id text DEFAULT NULL,
  p_source_metadata jsonb DEFAULT '{}'::jsonb
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_zalo public.zalo_outbound_deliveries%ROWTYPE;
  v_conv public.conversations%ROWTYPE;
  v_window public.response_sla_windows%ROWTYPE;
  v_supplied_interaction public.interactions%ROWTYPE;
  v_interaction_id uuid;
  v_ref text;
  v_rows_updated integer;
  v_expected_command text;
  v_now timestamptz := clock_timestamp();
BEGIN
  IF p_company_id IS NULL OR p_window_id IS NULL OR p_zalo_delivery_id IS NULL THEN
    RAISE EXCEPTION 'MANDATORY_PARAMETERS_MISSING' USING ERRCODE = '22023';
  END IF;

  v_expected_command := 'ai-sla-win-' || p_window_id::text;

  -- 1. Lock and validate Zalo outbound delivery
  SELECT * INTO v_zalo
  FROM public.zalo_outbound_deliveries
  WHERE id = p_zalo_delivery_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ZALO_DELIVERY_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  IF v_zalo.company_id <> p_company_id THEN
    RAISE EXCEPTION 'ZALO_DELIVERY_COMPANY_MISMATCH' USING ERRCODE = '42501';
  END IF;

  IF v_zalo.command_id IS DISTINCT FROM v_expected_command THEN
    RAISE EXCEPTION 'ZALO_COMMAND_ID_MISMATCH' USING ERRCODE = '22023';
  END IF;

  IF v_zalo.status NOT IN ('SENT', 'PROVIDER_SENT_PENDING_FINALIZE') THEN
    RAISE EXCEPTION 'ZALO_DELIVERY_NOT_FINALIZABLE: Status is %', v_zalo.status USING ERRCODE = '55000';
  END IF;

  -- 2. Lock and validate Conversation
  SELECT * INTO v_conv
  FROM public.conversations
  WHERE id = v_zalo.conversation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'CONVERSATION_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  IF v_conv.company_id <> p_company_id THEN
    RAISE EXCEPTION 'CONVERSATION_COMPANY_MISMATCH' USING ERRCODE = '42501';
  END IF;

  IF v_conv.channel <> 'ZALO' THEN
    RAISE EXCEPTION 'CONVERSATION_CHANNEL_MISMATCH' USING ERRCODE = '22000';
  END IF;

  -- 3. Lock and validate SLA window
  SELECT * INTO v_window
  FROM public.response_sla_windows
  WHERE id = p_window_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'WINDOW_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  IF v_window.company_id <> p_company_id THEN
    RAISE EXCEPTION 'WINDOW_COMPANY_MISMATCH' USING ERRCODE = '42501';
  END IF;

  IF v_window.conversation_id <> v_zalo.conversation_id THEN
    RAISE EXCEPTION 'WINDOW_CONVERSATION_MISMATCH' USING ERRCODE = '22000';
  END IF;

  IF v_window.customer_id <> v_zalo.customer_id THEN
    RAISE EXCEPTION 'WINDOW_CUSTOMER_MISMATCH' USING ERRCODE = '42501';
  END IF;

  -- 4. Validate claim authority (Item 2: strict validation, no unconditional bypass)
  IF p_ai_claim_id IS NULL OR v_window.ai_claim_id IS DISTINCT FROM p_ai_claim_id THEN
    RAISE EXCEPTION 'CLAIM_NOT_AUTHORIZED' USING ERRCODE = '42501';
  END IF;

  -- 5. Determine or mint interaction with strict binding validation (Item 6)
  IF p_interaction_id IS NOT NULL THEN
    SELECT * INTO v_supplied_interaction
    FROM public.interactions
    WHERE id = p_interaction_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'INTERACTION_NOT_FOUND' USING ERRCODE = 'P0002';
    END IF;

    IF v_supplied_interaction.company_id <> p_company_id THEN
      RAISE EXCEPTION 'INTERACTION_COMPANY_MISMATCH' USING ERRCODE = '42501';
    END IF;

    IF v_supplied_interaction.conversation_id <> v_zalo.conversation_id THEN
      RAISE EXCEPTION 'INTERACTION_CONVERSATION_MISMATCH' USING ERRCODE = '22000';
    END IF;

    IF v_supplied_interaction.customer_id <> v_zalo.customer_id THEN
      RAISE EXCEPTION 'INTERACTION_CUSTOMER_MISMATCH' USING ERRCODE = '22000';
    END IF;

    IF v_supplied_interaction.channel <> 'ZALO' THEN
      RAISE EXCEPTION 'INTERACTION_CHANNEL_MISMATCH' USING ERRCODE = '22000';
    END IF;

    IF v_supplied_interaction.direction <> 'OUTBOUND' THEN
      RAISE EXCEPTION 'INTERACTION_DIRECTION_MISMATCH' USING ERRCODE = '22000';
    END IF;

    IF v_supplied_interaction.actor_type <> 'AI' THEN
      RAISE EXCEPTION 'INTERACTION_ACTOR_MISMATCH' USING ERRCODE = '22000';
    END IF;

    IF v_zalo.interaction_id IS NOT NULL AND v_zalo.interaction_id <> p_interaction_id THEN
      RAISE EXCEPTION 'INTERACTION_DELIVERY_MISMATCH' USING ERRCODE = '22023';
    END IF;

    v_interaction_id := p_interaction_id;
  ELSE
    v_interaction_id := v_zalo.interaction_id;
  END IF;

  IF v_interaction_id IS NULL THEN
    v_interaction_id := gen_random_uuid();
    v_ref := 'zalo:' || v_zalo.company_id::text || ':' || coalesce(v_zalo.oa_id, 'unknown') || ':'
             || coalesce(v_zalo.provider_msg_id, coalesce(p_provider_msg_id, 'outbound:' || v_zalo.id::text));

    INSERT INTO public.interactions (
      id,
      company_id,
      customer_id,
      conversation_id,
      channel,
      type,
      direction,
      sanitized_content,
      sanitization_status,
      sanitized_at,
      sanitizer_version,
      external_ref,
      actor_type,
      actor_user_id,
      created_at
    ) VALUES (
      v_interaction_id,
      v_zalo.company_id,
      v_zalo.customer_id,
      v_zalo.conversation_id,
      'ZALO',
      'MESSAGE',
      'OUTBOUND',
      v_zalo.content,
      'SUCCEEDED',
      v_now,
      'zalo-sanitizer-v1',
      v_ref,
      'AI',
      NULL,
      v_now
    );

    UPDATE public.zalo_outbound_deliveries
    SET status = 'SENT',
        interaction_id = v_interaction_id,
        provider_msg_id = coalesce(v_zalo.provider_msg_id, p_provider_msg_id),
        finalized_at = v_now,
        lease_until = NULL,
        error_code = NULL,
        error_message = NULL,
        updated_at = v_now
    WHERE id = v_zalo.id;
  END IF;

  -- 6. Idempotent check
  IF v_window.state = 'AI_RESPONDED' AND v_window.ai_response_interaction_id = v_interaction_id THEN
    RETURN v_interaction_id;
  END IF;

  IF v_window.state <> 'OPEN' THEN
    RAISE EXCEPTION 'WINDOW_NOT_OPEN: State is %', v_window.state USING ERRCODE = '55000';
  END IF;

  -- 7. Atomically resolve Response SLA window & clear linearization fence
  UPDATE public.response_sla_windows
  SET
    state = 'AI_RESPONDED',
    ai_response_interaction_id = v_interaction_id,
    resolved_at = v_now,
    ai_dispatch_fenced_until = NULL,
    ai_dispatch_token = NULL,
    updated_at = v_now
  WHERE id = p_window_id
    AND company_id = p_company_id
    AND state = 'OPEN';

  GET DIAGNOSTICS v_rows_updated = ROW_COUNT;
  IF v_rows_updated = 0 THEN
    RAISE EXCEPTION 'SLA_WINDOW_UPDATE_AFFECTED_ZERO_ROWS' USING ERRCODE = 'P0001';
  END IF;

  -- 8. Record AI Provenance in private.interaction_raw_contents (strict append-only)
  IF NOT EXISTS (
    SELECT 1 FROM private.interaction_raw_contents
    WHERE interaction_id = v_interaction_id
  ) THEN
    INSERT INTO private.interaction_raw_contents (
      interaction_id,
      company_id,
      raw_content,
      raw_payload,
      source_metadata,
      created_at
    ) VALUES (
      v_interaction_id,
      p_company_id,
      v_zalo.content,
      '{}'::jsonb,
      coalesce(p_source_metadata, '{}'::jsonb),
      v_now
    );
  END IF;

  -- 9. Reset conversation status to OPEN
  UPDATE public.conversations
  SET
    status = 'OPEN',
    last_message_at = v_now,
    updated_at = v_now
  WHERE id = v_zalo.conversation_id
    AND company_id = p_company_id;

  -- 10. Transactional audit log
  INSERT INTO public.audit_logs (
    company_id,
    user_id,
    action,
    resource_type,
    resource_id,
    customer_id,
    result,
    metadata
  ) VALUES (
    p_company_id,
    NULL,
    'RESPONSE_SLA_AI_RESPONDED',
    'INTERACTION',
    v_interaction_id,
    v_zalo.customer_id,
    'SUCCESS',
    jsonb_build_object(
      'zalo_delivery_id', p_zalo_delivery_id,
      'window_id', p_window_id,
      'ai_claim_id', p_ai_claim_id,
      'provider_msg_id', coalesce(v_zalo.provider_msg_id, p_provider_msg_id)
    )
  );

  RETURN v_interaction_id;
END;
$$;

CREATE INDEX IF NOT EXISTS idx_sla_active_dispatch_fence 
  ON public.response_sla_windows(id) 
  WHERE dispatch_fenced_until IS NOT NULL OR ai_dispatch_fenced_until IS NOT NULL;

CREATE OR REPLACE FUNCTION public.han_prepare_send(
    p_company uuid,
    p_conversation uuid,
    p_actor uuid,
    p_request uuid,
    p_content text,
    p_safe text,
    p_safe_status text,
    p_delivery uuid
)
    RETURNS jsonb
    LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_conversation public.conversations%ROWTYPE;
  v_existing private.han_outbox%ROWTYPE;
  v_interaction uuid;
  v_latest timestamptz;
  v_sla public.response_sla_windows%ROWTYPE;
  v_sale_token uuid;
  v_now timestamptz := clock_timestamp();
  v_lease interval := interval '90 seconds';
BEGIN
  PERFORM pg_advisory_xact_lock(
    hashtextextended(
      'han-send:' || p_company::text || p_request::text,
      0
    )
  );

  SELECT * INTO v_conversation
  FROM public.conversations
  WHERE company_id = p_company
    AND id = p_conversation
    AND channel = 'FACEBOOK'
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'NOT_FOUND';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.company_members m
    JOIN public.user_profiles u ON u.id = m.user_id
    JOIN public.companies c ON c.id = m.company_id
    WHERE m.company_id = p_company
      AND m.user_id = p_actor
      AND m.status = 'ACTIVE'
      AND u.status = 'ACTIVE'
      AND c.status = 'ACTIVE'
      AND m.role IN ('BOSS_ADMIN', 'SALE')
  ) THEN
    RAISE EXCEPTION 'ACCESS_DENIED';
  END IF;

  SELECT * INTO v_existing
  FROM private.han_outbox
  WHERE company_id = p_company
    AND request_id = p_request;

  IF FOUND THEN
    IF v_existing.conversation_id <> p_conversation
      OR v_existing.actor_id <> p_actor
      OR v_existing.content <> p_content
      OR v_existing.care_delivery_id IS DISTINCT FROM p_delivery
    THEN
      RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT';
    END IF;

    RETURN jsonb_build_object(
      'claimed', false,
      'status', v_existing.status
    );
  END IF;

  SELECT max(created_at) INTO v_latest
  FROM public.interactions
  WHERE company_id = p_company
    AND conversation_id = p_conversation
    AND direction = 'INBOUND'
    AND actor_type = 'CUSTOMER';

  IF v_latest IS NULL
    OR v_latest <= v_now - interval '24 hours'
    OR v_latest > v_now + interval '10 seconds'
  THEN
    RAISE EXCEPTION 'WINDOW_CLOSED';
  END IF;

  IF length(p_content) NOT BETWEEN 1 AND 2000
    OR p_content IS NULL
    OR p_safe_status IS NULL OR p_safe_status NOT IN ('FAILED', 'SUCCEEDED')
    OR (p_safe_status = 'FAILED' AND p_safe IS NOT NULL)
    OR (p_safe_status = 'SUCCEEDED' AND p_safe IS NULL)
  THEN
    RAISE EXCEPTION 'INVALID_INPUT';
  END IF;

  IF p_delivery IS NOT NULL THEN
    PERFORM 1
    FROM public.care_deliveries d
    JOIN public.care_campaigns c
      ON c.id = d.campaign_id
      AND c.company_id = d.company_id
    WHERE d.id = p_delivery
      AND d.company_id = p_company
      AND d.customer_id = v_conversation.customer_id
      AND d.channel = 'FACEBOOK'
      AND c.channel = 'FACEBOOK'
      AND d.status = 'PENDING'
    FOR UPDATE OF d;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'INVALID_DELIVERY';
    END IF;

    IF EXISTS (
      SELECT 1 FROM public.care_schedules
      WHERE company_id = p_company
        AND customer_id = v_conversation.customer_id
        AND channel = 'FACEBOOK'
        AND enabled = false
    ) THEN
      RAISE EXCEPTION 'CARE_STOPPED';
    END IF;
  END IF;

  -- ============================================================================
  -- PRE-PROVIDER RESPONSE SLA DISPATCH FENCING (Items 1, 2, 3, 6)
  -- ============================================================================
  SELECT * INTO v_sla
  FROM public.response_sla_windows
  WHERE company_id = p_company
    AND conversation_id = p_conversation
    AND state = 'OPEN'
  FOR UPDATE;

  IF FOUND THEN
    -- Check existing dispatch ownership and state
    IF v_sla.dispatch_state = 'UNCERTAIN' AND (v_sla.dispatch_owner = 'AI' OR v_sla.ai_dispatch_fenced_until IS NOT NULL) THEN
      RETURN jsonb_build_object(
        'claimed', false,
        'status', 'DISPATCH_UNCERTAIN'
      );
    END IF;

    IF v_sla.dispatch_owner = 'AI' OR v_sla.ai_dispatch_fenced_until IS NOT NULL THEN
      IF (v_sla.dispatch_state = 'DISPATCHING' OR v_sla.ai_dispatch_token IS NOT NULL) THEN
        IF coalesce(v_sla.dispatch_fenced_until, v_sla.ai_dispatch_fenced_until) > v_now THEN
          -- AI currently holds the external provider dispatch authority!
          RETURN jsonb_build_object(
            'claimed', false,
            'status', 'AI_DISPATCH_FENCED'
          );
        ELSE
          -- AI dispatch lease expired mid-flight: transition logical operation to UNCERTAIN! Fail safe!
          UPDATE public.response_sla_windows
          SET dispatch_state = 'UNCERTAIN',
              dispatch_fenced_until = NULL,
              ai_dispatch_fenced_until = NULL,
              updated_at = v_now
          WHERE id = v_sla.id;

          RETURN jsonb_build_object(
            'claimed', false,
            'status', 'DISPATCH_UNCERTAIN'
          );
        END IF;
      ELSIF v_sla.dispatch_state = 'PROVIDER_ACCEPTED' THEN
        RETURN jsonb_build_object(
          'claimed', false,
          'status', 'AI_ALREADY_RESPONDED'
        );
      END IF;
    END IF;

    IF v_sla.dispatch_owner = 'SALE' AND v_sla.dispatch_state = 'DISPATCHING' THEN
      IF v_sla.dispatch_fenced_until <= v_now THEN
        -- Sale's own previous dispatch lease expired without resolution: transition to UNCERTAIN
        UPDATE public.response_sla_windows
        SET dispatch_state = 'UNCERTAIN',
            dispatch_fenced_until = NULL,
            updated_at = v_now
        WHERE id = v_sla.id;

        RETURN jsonb_build_object(
          'claimed', false,
          'status', 'DISPATCH_UNCERTAIN'
        );
      END IF;
    END IF;

    -- Atomically acquire SALE response dispatch ownership before returning claimed = true
    v_sale_token := gen_random_uuid();
    UPDATE public.response_sla_windows
    SET
      dispatch_owner = 'SALE',
      dispatch_state = 'DISPATCHING',
      dispatch_token = v_sale_token,
      dispatch_fenced_until = v_now + v_lease,
      dispatch_delivery_id = p_request,
      updated_at = v_now
    WHERE id = v_sla.id;
  END IF;

  INSERT INTO public.interactions (
    company_id, customer_id, conversation_id,
    channel, type, direction,
    sanitized_content, sanitization_status,
    sanitized_at, sanitizer_version,
    actor_type, actor_user_id
  )
  VALUES (
    p_company, v_conversation.customer_id,
    p_conversation, 'FACEBOOK', 'MESSAGE', 'OUTBOUND',
    p_safe, p_safe_status,
    CASE WHEN p_safe_status = 'SUCCEEDED' THEN v_now END,
    'han-bounded-v2', 'SALE', p_actor
  )
  RETURNING id INTO v_interaction;

  INSERT INTO private.interaction_raw_contents (
    interaction_id, company_id, raw_content
  )
  VALUES (v_interaction, p_company, p_content);

  INSERT INTO private.han_outbox (
    company_id, request_id, conversation_id,
    interaction_id, actor_id, content,
    status, care_delivery_id
  )
  VALUES (
    p_company, p_request, p_conversation,
    v_interaction, p_actor, p_content,
    'SENDING', p_delivery
  );

  INSERT INTO public.audit_logs (
    company_id, user_id, action, resource_type,
    resource_id, customer_id, result
  )
  VALUES (
    p_company, p_actor, 'MESSENGER_SEND_REQUESTED',
    'Interaction', v_interaction,
    v_conversation.customer_id, 'SUCCESS'
  );

  RETURN jsonb_build_object(
    'claimed', true,
    'status', 'SENDING'
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.guard_ai_pre_dispatch(
  p_company_id uuid,
  p_conversation_id uuid,
  p_customer_id uuid,
  p_window_id uuid,
  p_ai_claim_id uuid,
  p_channel text,
  p_lease_seconds integer DEFAULT 120
)
RETURNS TABLE (
  granted boolean,
  reason text,
  delivery_id uuid,
  provider_msg_id text,
  interaction_id uuid,
  window_state text,
  dispatch_token uuid
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
#variable_conflict use_column
DECLARE
  v_window public.response_sla_windows%ROWTYPE;
  v_conv public.conversations%ROWTYPE;
  v_del public.outbound_deliveries%ROWTYPE;
  v_zalo public.zalo_outbound_deliveries%ROWTYPE;
  v_sale_reply_id uuid;
  v_sale_reply_resolved_at timestamptz;
  v_stable_zalo_command text;
  v_new_delivery_id uuid;
  v_dispatch_token uuid;
  v_now timestamptz := clock_timestamp();
  v_lease interval := make_interval(secs => greatest(coalesce(p_lease_seconds, 120), 10));
BEGIN
  -- A. Mandatory input validation
  IF p_company_id IS NULL OR p_conversation_id IS NULL OR p_customer_id IS NULL OR p_window_id IS NULL THEN
    RETURN QUERY SELECT false, 'INVALID_ARGUMENTS'::text, NULL::uuid, NULL::text, NULL::uuid, NULL::text, NULL::uuid;
    RETURN;
  END IF;

  -- Mandatory claim ID for new dispatch (no NULL authorization bypass)
  IF p_ai_claim_id IS NULL THEN
    RETURN QUERY SELECT false, 'CLAIM_ID_MANDATORY'::text, NULL::uuid, NULL::text, NULL::uuid, NULL::text, NULL::uuid;
    RETURN;
  END IF;

  -- B. Lock SLA Window
  SELECT * INTO v_window
  FROM public.response_sla_windows
  WHERE id = p_window_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN QUERY SELECT false, 'WINDOW_NOT_FOUND'::text, NULL::uuid, NULL::text, NULL::uuid, NULL::text, NULL::uuid;
    RETURN;
  END IF;

  IF v_window.company_id <> p_company_id THEN
    RETURN QUERY SELECT false, 'WRONG_COMPANY'::text, NULL::uuid, NULL::text, NULL::uuid, v_window.state, NULL::uuid;
    RETURN;
  END IF;

  IF v_window.conversation_id <> p_conversation_id THEN
    RETURN QUERY SELECT false, 'CONVERSATION_MISMATCH'::text, NULL::uuid, NULL::text, NULL::uuid, v_window.state, NULL::uuid;
    RETURN;
  END IF;

  IF v_window.customer_id <> p_customer_id THEN
    RETURN QUERY SELECT false, 'CUSTOMER_MISMATCH'::text, NULL::uuid, NULL::text, NULL::uuid, v_window.state, NULL::uuid;
    RETURN;
  END IF;

  IF v_window.state <> 'OPEN' THEN
    RETURN QUERY SELECT false, v_window.state, NULL::uuid, NULL::text, NULL::uuid, v_window.state, NULL::uuid;
    RETURN;
  END IF;

  IF v_window.ai_claim_id IS DISTINCT FROM p_ai_claim_id THEN
    RETURN QUERY SELECT false, 'CLAIM_MISMATCH'::text, NULL::uuid, NULL::text, NULL::uuid, v_window.state, NULL::uuid;
    RETURN;
  END IF;

  IF v_window.ai_claim_expires_at IS NOT NULL AND v_window.ai_claim_expires_at <= v_now THEN
    RETURN QUERY SELECT false, 'CLAIM_EXPIRED'::text, NULL::uuid, NULL::text, NULL::uuid, v_window.state, NULL::uuid;
    RETURN;
  END IF;

  -- ============================================================================
  -- CROSS-ACTOR DISPATCH OWNERSHIP INSPECTION (Items 2, 4, 5, 6)
  -- ============================================================================
  IF v_window.dispatch_state = 'UNCERTAIN' THEN
    RETURN QUERY SELECT false, 'UNCERTAIN'::text, v_window.dispatch_delivery_id, NULL::text, NULL::uuid, v_window.state, NULL::uuid;
    RETURN;
  END IF;

  IF v_window.dispatch_owner = 'SALE' THEN
    IF v_window.dispatch_state = 'DISPATCHING' THEN
      IF v_window.dispatch_fenced_until > v_now THEN
        RETURN QUERY SELECT false, 'SALE_DISPATCHING'::text, v_window.dispatch_delivery_id, NULL::text, NULL::uuid, v_window.state, NULL::uuid;
        RETURN;
      ELSE
        -- Sale dispatch lease expired mid-flight: transition to UNCERTAIN! Never let AI compete automatically
        UPDATE public.response_sla_windows
        SET dispatch_state = 'UNCERTAIN',
            dispatch_fenced_until = NULL,
            updated_at = v_now
        WHERE id = p_window_id;

        RETURN QUERY SELECT false, 'UNCERTAIN'::text, v_window.dispatch_delivery_id, NULL::text, NULL::uuid, v_window.state, NULL::uuid;
        RETURN;
      END IF;
    ELSIF v_window.dispatch_state = 'PROVIDER_ACCEPTED' THEN
      RETURN QUERY SELECT false, 'SALE_ALREADY_RESPONDED'::text, NULL::uuid, NULL::text, NULL::uuid, 'SALE_RESPONDED'::text, NULL::uuid;
      RETURN;
    END IF;
  END IF;

  -- C. Lock Conversation
  SELECT * INTO v_conv
  FROM public.conversations
  WHERE id = p_conversation_id AND company_id = p_company_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN QUERY SELECT false, 'CONVERSATION_NOT_FOUND'::text, NULL::uuid, NULL::text, NULL::uuid, v_window.state, NULL::uuid;
    RETURN;
  END IF;

  IF v_conv.status = 'CLOSED' THEN
    RETURN QUERY SELECT false, 'CONVERSATION_CLOSED'::text, NULL::uuid, NULL::text, NULL::uuid, v_window.state, NULL::uuid;
    RETURN;
  END IF;

  -- D. Authoritative Check: Did Sale respond after window.started_at?
  SELECT
    i.id,
    coalesce(o.sent_at, i.created_at)
  INTO
    v_sale_reply_id,
    v_sale_reply_resolved_at
  FROM public.interactions i
  LEFT JOIN private.han_outbox o
    ON o.company_id = p_company_id AND o.interaction_id = i.id
  WHERE i.company_id = p_company_id
    AND i.conversation_id = p_conversation_id
    AND i.actor_type = 'SALE'
    AND i.direction = 'OUTBOUND'
    AND i.type = 'MESSAGE'
    AND i.created_at >= v_window.started_at
    AND (
      CASE WHEN o.interaction_id IS NOT NULL THEN o.status = 'SENT' ELSE true END
    )
  ORDER BY i.created_at DESC
  LIMIT 1;

  IF FOUND THEN
    -- Sale won the race! Transition to SALE_RESPONDED atomically
    UPDATE public.response_sla_windows
    SET
      state = 'SALE_RESPONDED',
      sale_response_interaction_id = v_sale_reply_id,
      resolved_at = coalesce(v_sale_reply_resolved_at, v_now),
      dispatch_owner = 'SALE',
      dispatch_state = 'PROVIDER_ACCEPTED',
      dispatch_fenced_until = NULL,
      ai_dispatch_fenced_until = NULL,
      ai_dispatch_token = NULL,
      updated_at = v_now
    WHERE id = p_window_id;

    IF v_conv.status = 'AI_HANDLING' THEN
      UPDATE public.conversations
      SET status = 'OPEN', updated_at = v_now
      WHERE id = p_conversation_id;
    END IF;

    RETURN QUERY SELECT false, 'SALE_ALREADY_RESPONDED'::text, NULL::uuid, NULL::text, NULL::uuid, 'SALE_RESPONDED'::text, NULL::uuid;
    RETURN;
  END IF;

  -- Generate durable dispatch token for ownership proof
  v_dispatch_token := gen_random_uuid();

  -- E. Channel-specific state machine check
  IF p_channel = 'ZALO' THEN
    v_stable_zalo_command := 'ai-sla-win-' || p_window_id::text;

    SELECT * INTO v_zalo
    FROM public.zalo_outbound_deliveries
    WHERE company_id = p_company_id
      AND channel = 'ZALO'
      AND command_id = v_stable_zalo_command
    FOR UPDATE;

    IF FOUND THEN
      IF v_zalo.status = 'SENT' THEN
        RETURN QUERY SELECT false, 'ALREADY_SENT'::text, v_zalo.id, v_zalo.provider_msg_id, v_zalo.interaction_id, v_window.state, NULL::uuid;
        RETURN;
      ELSIF v_zalo.status = 'PROVIDER_SENT_PENDING_FINALIZE' THEN
        RETURN QUERY SELECT false, 'PENDING_FINALIZE'::text, v_zalo.id, v_zalo.provider_msg_id, NULL::uuid, v_window.state, NULL::uuid;
        RETURN;
      ELSIF v_zalo.status IN ('PROVIDER_UNCERTAIN', 'UNCERTAIN') THEN
        UPDATE public.response_sla_windows
        SET dispatch_state = 'UNCERTAIN', dispatch_fenced_until = NULL, updated_at = v_now
        WHERE id = p_window_id;

        RETURN QUERY SELECT false, 'UNCERTAIN'::text, v_zalo.id, v_zalo.provider_msg_id, NULL::uuid, v_window.state, NULL::uuid;
        RETURN;
      ELSIF v_zalo.status = 'SENDING' AND v_zalo.lease_until IS NOT NULL AND v_zalo.lease_until > v_now THEN
        RETURN QUERY SELECT false, 'BUSY'::text, v_zalo.id, NULL::text, NULL::uuid, v_window.state, NULL::uuid;
        RETURN;
      ELSIF v_zalo.status = 'SENDING' THEN
        -- Lease expired mid-flight: transition to UNCERTAIN, never auto-retry
        UPDATE public.zalo_outbound_deliveries
        SET status = 'PROVIDER_UNCERTAIN', lease_until = NULL, error_code = 'LEASE_EXPIRED_OUTCOME_UNKNOWN', updated_at = v_now
        WHERE id = v_zalo.id;

        UPDATE public.response_sla_windows
        SET dispatch_state = 'UNCERTAIN', dispatch_fenced_until = NULL, updated_at = v_now
        WHERE id = p_window_id;

        RETURN QUERY SELECT false, 'UNCERTAIN'::text, v_zalo.id, NULL::text, NULL::uuid, v_window.state, NULL::uuid;
        RETURN;
      END IF;

      -- If status is FAILED or PENDING, grant dispatch under fence
      UPDATE public.response_sla_windows
      SET
        dispatch_owner = 'AI',
        dispatch_state = 'DISPATCHING',
        dispatch_token = v_dispatch_token,
        dispatch_fenced_until = v_now + v_lease,
        dispatch_delivery_id = v_zalo.id,
        ai_dispatch_fenced_until = v_now + v_lease,
        ai_dispatch_delivery_id = v_zalo.id,
        ai_dispatch_token = v_dispatch_token,
        updated_at = v_now
      WHERE id = p_window_id;

      RETURN QUERY SELECT true, 'GRANTED'::text, v_zalo.id, NULL::text, NULL::uuid, v_window.state, v_dispatch_token;
      RETURN;
    END IF;

    -- No prior row: dispatch authority granted for Zalo under fence
    UPDATE public.response_sla_windows
    SET
      dispatch_owner = 'AI',
      dispatch_state = 'DISPATCHING',
      dispatch_token = v_dispatch_token,
      dispatch_fenced_until = v_now + v_lease,
      dispatch_delivery_id = NULL,
      ai_dispatch_fenced_until = v_now + v_lease,
      ai_dispatch_delivery_id = NULL,
      ai_dispatch_token = v_dispatch_token,
      updated_at = v_now
    WHERE id = p_window_id;

    RETURN QUERY SELECT true, 'GRANTED'::text, NULL::uuid, NULL::text, NULL::uuid, v_window.state, v_dispatch_token;
    RETURN;

  ELSE
    -- Generic / Facebook channel backed by public.outbound_deliveries
    SELECT * INTO v_del
    FROM public.outbound_deliveries
    WHERE company_id = p_company_id
      AND client_command_id = p_window_id
    FOR UPDATE;

    IF FOUND THEN
      IF v_del.delivery_status = 'SENT' THEN
        RETURN QUERY SELECT false, 'ALREADY_SENT'::text, v_del.id, v_del.provider_message_id, v_del.interaction_id, v_window.state, NULL::uuid;
        RETURN;
      ELSIF v_del.delivery_status = 'PROVIDER_SENT_PENDING_FINALIZE' THEN
        RETURN QUERY SELECT false, 'PENDING_FINALIZE'::text, v_del.id, v_del.provider_message_id, NULL::uuid, v_window.state, NULL::uuid;
        RETURN;
      ELSIF v_del.delivery_status IN ('UNCERTAIN', 'PROVIDER_UNCERTAIN') THEN
        UPDATE public.response_sla_windows
        SET dispatch_state = 'UNCERTAIN', dispatch_fenced_until = NULL, updated_at = v_now
        WHERE id = p_window_id;

        RETURN QUERY SELECT false, 'UNCERTAIN'::text, v_del.id, v_del.provider_message_id, NULL::uuid, v_window.state, NULL::uuid;
        RETURN;
      ELSIF v_del.delivery_status = 'DISPATCHING' AND v_del.lease_until IS NOT NULL AND v_del.lease_until > v_now THEN
        RETURN QUERY SELECT false, 'BUSY'::text, v_del.id, NULL::text, NULL::uuid, v_window.state, NULL::uuid;
        RETURN;
      ELSIF v_del.delivery_status = 'DISPATCHING' THEN
        -- Lease expired mid-flight: transition to UNCERTAIN, never auto-retry
        UPDATE public.outbound_deliveries
        SET delivery_status = 'UNCERTAIN', lease_until = NULL, error_message = 'LEASE_EXPIRED_OUTCOME_UNKNOWN', updated_at = v_now
        WHERE id = v_del.id;

        UPDATE public.response_sla_windows
        SET dispatch_state = 'UNCERTAIN', dispatch_fenced_until = NULL, updated_at = v_now
        WHERE id = p_window_id;

        RETURN QUERY SELECT false, 'UNCERTAIN'::text, v_del.id, NULL::text, NULL::uuid, v_window.state, NULL::uuid;
        RETURN;
      ELSIF v_del.delivery_status IN ('PENDING', 'PENDING_DISPATCH', 'FAILED') THEN
        UPDATE public.outbound_deliveries
        SET
          delivery_status = 'DISPATCHING',
          dispatch_token = v_dispatch_token,
          lease_until = v_now + v_lease,
          locked_at = v_now,
          locked_by = 'ai_response_runtime',
          updated_at = v_now
        WHERE id = v_del.id;

        UPDATE public.response_sla_windows
        SET
          dispatch_owner = 'AI',
          dispatch_state = 'DISPATCHING',
          dispatch_token = v_dispatch_token,
          dispatch_fenced_until = v_now + v_lease,
          dispatch_delivery_id = v_del.id,
          ai_dispatch_fenced_until = v_now + v_lease,
          ai_dispatch_delivery_id = v_del.id,
          ai_dispatch_token = v_dispatch_token,
          updated_at = v_now
        WHERE id = p_window_id;

        RETURN QUERY SELECT true, 'GRANTED'::text, v_del.id, NULL::text, NULL::uuid, v_window.state, v_dispatch_token;
        RETURN;
      END IF;

      RETURN QUERY SELECT false, ('UNEXPECTED_STATUS_' || v_del.delivery_status)::text, v_del.id, NULL::text, NULL::uuid, v_window.state, NULL::uuid;
      RETURN;
    END IF;

    v_new_delivery_id := gen_random_uuid();
    INSERT INTO public.outbound_deliveries (
      id,
      company_id,
      conversation_id,
      interaction_id,
      channel,
      delivery_status,
      client_command_id,
      window_id,
      request_fingerprint,
      lease_until,
      dispatch_token,
      locked_at,
      locked_by,
      created_at,
      updated_at
    ) VALUES (
      v_new_delivery_id,
      p_company_id,
      p_conversation_id,
      NULL,
      p_channel,
      'DISPATCHING',
      p_window_id,
      p_window_id,
      p_company_id::text || ':' || p_conversation_id::text || ':' || p_window_id::text,
      v_now + v_lease,
      v_dispatch_token,
      v_now,
      'ai_response_runtime',
      v_now,
      v_now
    );

    UPDATE public.response_sla_windows
    SET
      dispatch_owner = 'AI',
      dispatch_state = 'DISPATCHING',
      dispatch_token = v_dispatch_token,
      dispatch_fenced_until = v_now + v_lease,
      dispatch_delivery_id = v_new_delivery_id,
      ai_dispatch_fenced_until = v_now + v_lease,
      ai_dispatch_delivery_id = v_new_delivery_id,
      ai_dispatch_token = v_dispatch_token,
      updated_at = v_now
    WHERE id = p_window_id;

    RETURN QUERY SELECT true, 'GRANTED'::text, v_new_delivery_id, NULL::text, NULL::uuid, v_window.state, v_dispatch_token;
    RETURN;
  END IF;
END;
$$;

CREATE OR REPLACE FUNCTION public.record_ai_outbound_provider_result(
  p_company_id uuid,
  p_delivery_id uuid,
  p_outcome text,
  p_dispatch_token uuid,
  p_provider_msg_id text DEFAULT NULL,
  p_error_message text DEFAULT NULL
)
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_del public.outbound_deliveries%ROWTYPE;
  v_win public.response_sla_windows%ROWTYPE;
  v_new_status text;
  v_now timestamptz := clock_timestamp();
BEGIN
  IF p_company_id IS NULL OR p_delivery_id IS NULL OR p_outcome IS NULL OR p_dispatch_token IS NULL THEN
    RAISE EXCEPTION 'MANDATORY_PARAMETERS_MISSING' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_del
  FROM public.outbound_deliveries
  WHERE id = p_delivery_id AND company_id = p_company_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'DELIVERY_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  -- Validate delivery dispatch token
  IF v_del.dispatch_token IS DISTINCT FROM p_dispatch_token THEN
    RAISE EXCEPTION 'DISPATCH_TOKEN_MISMATCH' USING ERRCODE = '42501';
  END IF;

  -- Validate SLA-window dispatch token if delivery is bound to a window
  IF v_del.window_id IS NOT NULL THEN
    SELECT * INTO v_win
    FROM public.response_sla_windows
    WHERE id = v_del.window_id
    FOR UPDATE;

    IF FOUND THEN
      IF coalesce(v_win.dispatch_token, v_win.ai_dispatch_token) IS DISTINCT FROM p_dispatch_token THEN
        RAISE EXCEPTION 'DISPATCH_TOKEN_MISMATCH' USING ERRCODE = '42501';
      END IF;
    END IF;
  END IF;

  IF v_del.delivery_status = 'PROVIDER_SENT_PENDING_FINALIZE' AND p_outcome = 'SENT'
     AND v_del.provider_message_id IS NOT DISTINCT FROM p_provider_msg_id THEN
    RETURN 'PROVIDER_SENT_PENDING_FINALIZE';
  END IF;

  IF v_del.delivery_status NOT IN ('DISPATCHING', 'UNCERTAIN', 'PROVIDER_UNCERTAIN') THEN
    RAISE EXCEPTION 'INVALID_DELIVERY_STATE_TRANSITION: %', v_del.delivery_status USING ERRCODE = '55000';
  END IF;

  IF p_outcome = 'SENT' THEN
    IF p_provider_msg_id IS NULL OR length(trim(p_provider_msg_id)) = 0 THEN
      RAISE EXCEPTION 'CANNOT_RECORD_SENT_WITHOUT_PROVIDER_MESSAGE_ID' USING ERRCODE = '22023';
    END IF;
    v_new_status := 'PROVIDER_SENT_PENDING_FINALIZE';

    UPDATE public.outbound_deliveries
    SET
      delivery_status = v_new_status,
      provider_message_id = p_provider_msg_id,
      lease_until = NULL,
      updated_at = v_now
    WHERE id = p_delivery_id;

    IF v_del.window_id IS NOT NULL THEN
      UPDATE public.response_sla_windows
      SET dispatch_state = 'PROVIDER_ACCEPTED',
          updated_at = v_now
      WHERE id = v_del.window_id;
    END IF;

  ELSIF p_outcome = 'FAILED' THEN
    v_new_status := 'FAILED';

    UPDATE public.outbound_deliveries
    SET
      delivery_status = v_new_status,
      error_message = coalesce(p_error_message, 'Provider rejected message'),
      lease_until = NULL,
      dispatch_token = NULL,
      updated_at = v_now
    WHERE id = p_delivery_id;

    IF v_del.window_id IS NOT NULL THEN
      UPDATE public.response_sla_windows
      SET dispatch_owner = NULL,
          dispatch_state = 'FAILED',
          dispatch_token = NULL,
          dispatch_fenced_until = NULL,
          dispatch_delivery_id = NULL,
          ai_dispatch_fenced_until = NULL,
          ai_dispatch_token = NULL,
          updated_at = v_now
      WHERE id = v_del.window_id
        AND (dispatch_token = p_dispatch_token OR ai_dispatch_token = p_dispatch_token);
    END IF;

  ELSIF p_outcome IN ('UNCERTAIN', 'UNKNOWN') THEN
    v_new_status := 'UNCERTAIN';

    UPDATE public.outbound_deliveries
    SET
      delivery_status = v_new_status,
      error_message = coalesce(p_error_message, 'Provider outcome uncertain'),
      lease_until = NULL,
      updated_at = v_now
    WHERE id = p_delivery_id;

    IF v_del.window_id IS NOT NULL THEN
      UPDATE public.response_sla_windows
      SET dispatch_state = 'UNCERTAIN',
          dispatch_fenced_until = NULL,
          ai_dispatch_fenced_until = NULL,
          updated_at = v_now
      WHERE id = v_del.window_id;
    END IF;

  ELSE
    RAISE EXCEPTION 'INVALID_OUTBOUND_OUTCOME: %', p_outcome USING ERRCODE = '22023';
  END IF;

  RETURN v_new_status;
END;
$$;

CREATE OR REPLACE FUNCTION public.zalo_claim_outbound_delivery(
  p_company_id uuid,
  p_conversation_id uuid,
  p_command_id text,
  p_actor_type text,
  p_actor_user_id uuid,
  p_raw_content text,
  p_sanitized_content text,
  p_content_sha256 text,
  p_oa_id text DEFAULT NULL,
  p_lease_seconds integer DEFAULT 120
)
RETURNS TABLE (
  claim_status text,
  delivery_id uuid,
  claim_token uuid,
  oa_id text,
  recipient_zalo_uid text,
  customer_id uuid,
  provider_msg_id text,
  interaction_id uuid
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
#variable_conflict use_column
DECLARE
  v_conv record;
  v_oa text;
  v_row public.zalo_outbound_deliveries%ROWTYPE;
  v_token uuid := gen_random_uuid();
  v_lease interval := make_interval(secs => greatest(coalesce(p_lease_seconds, 120), 10));
  v_sla public.response_sla_windows%ROWTYPE;
  v_now timestamptz := clock_timestamp();
BEGIN
  IF coalesce(btrim(p_command_id), '') = '' OR length(p_command_id) > 200 THEN
    RAISE EXCEPTION 'ZALO_OUTBOUND_COMMAND_ID_INVALID' USING ERRCODE = '22023';
  END IF;
  IF coalesce(btrim(p_raw_content), '') = '' OR coalesce(p_content_sha256, '') = '' THEN
    RAISE EXCEPTION 'ZALO_OUTBOUND_CONTENT_INVALID' USING ERRCODE = '22023';
  END IF;
  IF p_actor_type NOT IN ('SALE', 'AI', 'SYSTEM') THEN
    RAISE EXCEPTION 'ZALO_OUTBOUND_ACTOR_INVALID' USING ERRCODE = '22023';
  END IF;

  IF p_actor_type = 'SALE' THEN
    IF p_actor_user_id IS NULL OR NOT EXISTS (
      SELECT 1
      FROM public.company_members m
      JOIN public.user_profiles up ON up.id = m.user_id AND up.status = 'ACTIVE'
      WHERE m.company_id = p_company_id
        AND m.user_id = p_actor_user_id
        AND m.status = 'ACTIVE'
        AND m.role IN ('SALE', 'BOSS_ADMIN')
    ) THEN
      RAISE EXCEPTION 'ZALO_OUTBOUND_ACTOR_FORBIDDEN' USING ERRCODE = '42501';
    END IF;
  ELSIF p_actor_user_id IS NOT NULL THEN
    RAISE EXCEPTION 'ZALO_OUTBOUND_ACTOR_INVALID' USING ERRCODE = '22023';
  END IF;

  SELECT c.id, c.customer_id, c.external_conversation_id INTO v_conv
  FROM public.conversations c
  WHERE c.id = p_conversation_id AND c.company_id = p_company_id AND c.channel = 'ZALO';
  IF v_conv.id IS NULL THEN
    RAISE EXCEPTION 'ZALO_CONVERSATION_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  IF p_oa_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.zalo_oa_configs c
      WHERE c.company_id = p_company_id AND c.oa_id = p_oa_id AND c.status = 'ACTIVE'
    ) THEN
      RAISE EXCEPTION 'ZALO_OA_NOT_CONFIGURED' USING ERRCODE = 'P0002';
    END IF;
    v_oa := p_oa_id;
  ELSE
    v_oa := private.zalo_resolve_customer_oa(p_company_id, v_conv.customer_id);
  END IF;
  IF v_oa IS NULL THEN
    RAISE EXCEPTION 'ZALO_OA_NOT_CONFIGURED' USING ERRCODE = 'P0002';
  END IF;

  -- ============================================================================
  -- HUMAN SALE RESPONSE SLA CROSS-ACTOR DISPATCH FENCING (Item 7)
  -- ============================================================================
  IF p_actor_type = 'SALE' THEN
    SELECT * INTO v_sla
    FROM public.response_sla_windows
    WHERE company_id = p_company_id
      AND conversation_id = p_conversation_id
      AND state = 'OPEN'
    FOR UPDATE;

    IF FOUND THEN
      IF v_sla.dispatch_state = 'UNCERTAIN' THEN
        RAISE EXCEPTION 'DISPATCH_UNCERTAIN' USING ERRCODE = '55000';
      END IF;

      IF v_sla.dispatch_owner = 'AI' OR v_sla.ai_dispatch_fenced_until IS NOT NULL THEN
        IF (v_sla.dispatch_state = 'DISPATCHING' OR v_sla.ai_dispatch_token IS NOT NULL) THEN
          IF coalesce(v_sla.dispatch_fenced_until, v_sla.ai_dispatch_fenced_until) > v_now THEN
            RAISE EXCEPTION 'AI_DISPATCH_FENCED' USING ERRCODE = '55000';
          ELSE
            UPDATE public.response_sla_windows
            SET dispatch_state = 'UNCERTAIN',
                dispatch_fenced_until = NULL,
                ai_dispatch_fenced_until = NULL,
                updated_at = v_now
            WHERE id = v_sla.id;

            RAISE EXCEPTION 'DISPATCH_UNCERTAIN' USING ERRCODE = '55000';
          END IF;
        ELSIF v_sla.dispatch_state = 'PROVIDER_ACCEPTED' THEN
          RAISE EXCEPTION 'AI_ALREADY_RESPONDED' USING ERRCODE = '55000';
        END IF;
      END IF;

      -- Acquire SALE response dispatch ownership
      UPDATE public.response_sla_windows
      SET
        dispatch_owner = 'SALE',
        dispatch_state = 'DISPATCHING',
        dispatch_token = v_token,
        dispatch_fenced_until = v_now + v_lease,
        updated_at = v_now
      WHERE id = v_sla.id;
    END IF;
  END IF;

  INSERT INTO public.zalo_outbound_deliveries AS d (
    company_id, conversation_id, customer_id, recipient_zalo_uid, idempotency_key, content,
    status, attempts, command_id, channel, lease_until, oa_id, actor_type, actor_user_id,
    claim_token, content_sha256
  ) VALUES (
    p_company_id, v_conv.id, v_conv.customer_id, v_conv.external_conversation_id,
    'zalo_out:' || p_company_id::text || ':' || p_command_id, p_sanitized_content,
    'SENDING', 1, p_command_id, 'ZALO', v_now + v_lease, v_oa, p_actor_type, p_actor_user_id,
    v_token, p_content_sha256
  )
  ON CONFLICT DO NOTHING
  RETURNING d.* INTO v_row;

  IF v_row.id IS NOT NULL THEN
    INSERT INTO private.zalo_outbound_payloads (delivery_id, company_id, raw_content)
    VALUES (v_row.id, p_company_id, p_raw_content);

    IF p_actor_type = 'SALE' AND v_sla.id IS NOT NULL THEN
      UPDATE public.response_sla_windows
      SET dispatch_delivery_id = v_row.id
      WHERE id = v_sla.id;
    END IF;

    RETURN QUERY SELECT 'CLAIMED'::text, v_row.id, v_token, v_oa, v_row.recipient_zalo_uid,
                        v_row.customer_id, NULL::text, NULL::uuid;
    RETURN;
  END IF;

  SELECT d.* INTO v_row
  FROM public.zalo_outbound_deliveries d
  WHERE d.company_id = p_company_id AND d.channel = 'ZALO' AND d.command_id = p_command_id
  FOR UPDATE;

  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'ZALO_OUTBOUND_COMMAND_CONFLICT' USING ERRCODE = '23505';
  END IF;

  IF v_row.conversation_id <> v_conv.id OR v_row.content_sha256 IS DISTINCT FROM p_content_sha256 THEN
    RETURN QUERY SELECT 'CONFLICT'::text, v_row.id, NULL::uuid, v_row.oa_id, v_row.recipient_zalo_uid,
                        v_row.customer_id, v_row.provider_msg_id, v_row.interaction_id;
    RETURN;
  END IF;

  IF v_row.status = 'SENT' THEN
    RETURN QUERY SELECT 'ALREADY_SENT'::text, v_row.id, NULL::uuid, v_row.oa_id, v_row.recipient_zalo_uid,
                        v_row.customer_id, v_row.provider_msg_id, v_row.interaction_id;
    RETURN;
  END IF;

  IF v_row.status = 'PROVIDER_SENT_PENDING_FINALIZE' THEN
    RETURN QUERY SELECT 'PENDING_FINALIZE'::text, v_row.id, NULL::uuid, v_row.oa_id, v_row.recipient_zalo_uid,
                        v_row.customer_id, v_row.provider_msg_id, NULL::uuid;
    RETURN;
  END IF;

  IF v_row.status IN ('FAILED', 'PENDING') THEN
    UPDATE public.zalo_outbound_deliveries d
    SET status = 'SENDING', attempts = d.attempts + 1, lease_until = v_now + v_lease,
        claim_token = v_token, error_code = NULL, error_message = NULL, updated_at = v_now
    WHERE d.id = v_row.id;

    IF p_actor_type = 'SALE' AND v_sla.id IS NOT NULL THEN
      UPDATE public.response_sla_windows
      SET dispatch_delivery_id = v_row.id
      WHERE id = v_sla.id;
    END IF;

    RETURN QUERY SELECT 'CLAIMED'::text, v_row.id, v_token, v_row.oa_id, v_row.recipient_zalo_uid,
                        v_row.customer_id, NULL::text, NULL::uuid;
    RETURN;
  END IF;

  IF v_row.status = 'SENDING' AND v_row.lease_until IS NOT NULL AND v_row.lease_until > v_now THEN
    RETURN QUERY SELECT 'BUSY'::text, v_row.id, NULL::uuid, v_row.oa_id, v_row.recipient_zalo_uid,
                        v_row.customer_id, NULL::text, NULL::uuid;
    RETURN;
  END IF;

  IF v_row.status = 'SENDING' THEN
    UPDATE public.zalo_outbound_deliveries d
    SET status = 'PROVIDER_UNCERTAIN', lease_until = NULL,
        error_code = 'LEASE_EXPIRED_OUTCOME_UNKNOWN', updated_at = v_now
    WHERE d.id = v_row.id;

    IF p_actor_type = 'SALE' AND v_sla.id IS NOT NULL THEN
      UPDATE public.response_sla_windows
      SET dispatch_state = 'UNCERTAIN', dispatch_fenced_until = NULL, updated_at = v_now
      WHERE id = v_sla.id;
    END IF;
  END IF;

  RETURN QUERY SELECT 'UNCERTAIN'::text, v_row.id, NULL::uuid, v_row.oa_id, v_row.recipient_zalo_uid,
                      v_row.customer_id, v_row.provider_msg_id, v_row.interaction_id;
END;
$$;

CREATE OR REPLACE FUNCTION public.zalo_finalize_outbound_delivery(p_delivery_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_row public.zalo_outbound_deliveries%ROWTYPE;
  v_raw text;
  v_ref text;
  v_interaction_id uuid;
  v_existing record;
  v_now timestamptz := clock_timestamp();
BEGIN
  SELECT d.* INTO v_row FROM public.zalo_outbound_deliveries d WHERE d.id = p_delivery_id FOR UPDATE;
  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'ZALO_OUTBOUND_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  IF v_row.status = 'SENT' THEN
    RETURN jsonb_build_object('interaction_id', v_row.interaction_id, 'already_finalized', true,
                              'provider_msg_id', v_row.provider_msg_id);
  END IF;

  IF v_row.status <> 'PROVIDER_SENT_PENDING_FINALIZE' THEN
    RAISE EXCEPTION 'ZALO_OUTBOUND_NOT_FINALIZABLE' USING ERRCODE = '55000';
  END IF;

  SELECT p.raw_content INTO v_raw FROM private.zalo_outbound_payloads p WHERE p.delivery_id = v_row.id;
  IF v_raw IS NULL THEN
    RAISE EXCEPTION 'ZALO_OUTBOUND_PAYLOAD_MISSING' USING ERRCODE = 'P0002';
  END IF;

  PERFORM private.zalo_lock_user(v_row.company_id, v_row.recipient_zalo_uid);

  v_ref := 'zalo:' || v_row.company_id::text || ':' || coalesce(v_row.oa_id, 'unknown') || ':'
           || coalesce(v_row.provider_msg_id, 'outbound:' || v_row.id::text);

  SELECT i.id, i.actor_user_id INTO v_existing
  FROM public.interactions i
  WHERE i.company_id = v_row.company_id AND i.channel = 'ZALO' AND i.external_ref = v_ref;

  IF v_existing.id IS NOT NULL THEN
    v_interaction_id := v_existing.id;
    UPDATE public.interactions i
    SET actor_type = coalesce(v_row.actor_type, i.actor_type),
        actor_user_id = coalesce(i.actor_user_id, v_row.actor_user_id)
    WHERE i.id = v_existing.id AND i.actor_user_id IS NULL;
  ELSE
    INSERT INTO public.interactions (
      company_id, customer_id, conversation_id, channel, type, direction,
      sanitized_content, sanitization_status, sanitized_at, sanitizer_version,
      external_ref, actor_type, actor_user_id, created_at
    ) VALUES (
      v_row.company_id, v_row.customer_id, v_row.conversation_id, 'ZALO', 'MESSAGE', 'OUTBOUND',
      v_row.content, 'SUCCEEDED', v_now, 'zalo-sanitizer-v1',
      v_ref, coalesce(v_row.actor_type, 'SYSTEM'), v_row.actor_user_id,
      coalesce(v_row.provider_accepted_at, v_now)
    )
    RETURNING id INTO v_interaction_id;

    INSERT INTO private.interaction_raw_contents (interaction_id, company_id, raw_content, raw_payload, source_metadata)
    VALUES (
      v_interaction_id, v_row.company_id, v_raw,
      jsonb_build_object('recipient', jsonb_build_object('user_id', v_row.recipient_zalo_uid)),
      jsonb_build_object(
        'oa_id', v_row.oa_id,
        'recipient_id', v_row.recipient_zalo_uid,
        'provider_msg_id', v_row.provider_msg_id,
        'delivery_id', v_row.id,
        'command_id', v_row.command_id,
        'origin', 'CRM_OUTBOX'
      )
    );

    UPDATE public.conversations c
    SET last_message_at = greatest(c.last_message_at, coalesce(v_row.provider_accepted_at, v_now)),
        status = CASE WHEN c.status = 'AI_HANDLING' THEN 'OPEN' ELSE c.status END
    WHERE c.id = v_row.conversation_id;
  END IF;

  UPDATE public.zalo_outbound_deliveries d
  SET status = 'SENT', interaction_id = v_interaction_id, finalized_at = v_now,
      claim_token = NULL, lease_until = NULL, error_code = NULL, error_message = NULL, updated_at = v_now
  WHERE d.id = v_row.id;

  -- If this was a SALE send, resolve the Response SLA window to SALE_RESPONDED
  IF v_row.actor_type = 'SALE' THEN
    UPDATE public.response_sla_windows
    SET state = 'SALE_RESPONDED',
        sale_response_interaction_id = v_interaction_id,
        resolved_at = coalesce(v_row.provider_accepted_at, v_now),
        dispatch_owner = 'SALE',
        dispatch_state = 'PROVIDER_ACCEPTED',
        dispatch_fenced_until = NULL,
        ai_dispatch_fenced_until = NULL,
        ai_dispatch_token = NULL,
        updated_at = v_now
    WHERE conversation_id = v_row.conversation_id
      AND state = 'OPEN';
  END IF;

  RETURN jsonb_build_object('interaction_id', v_interaction_id, 'already_finalized', false,
                            'provider_msg_id', v_row.provider_msg_id);
END;
$$;

CREATE OR REPLACE FUNCTION public.finalize_ai_outbound_delivery_atomic(
  p_company_id uuid,
  p_delivery_id uuid,
  p_conversation_id uuid,
  p_customer_id uuid,
  p_window_id uuid,
  p_ai_claim_id uuid,
  p_provider_msg_id text,
  p_sanitized_content text,
  p_raw_content text,
  p_source_metadata jsonb DEFAULT '{}'::jsonb
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_delivery public.outbound_deliveries%ROWTYPE;
  v_conv public.conversations%ROWTYPE;
  v_window public.response_sla_windows%ROWTYPE;
  v_interaction_id uuid;
  v_rows_updated integer;
  v_now timestamptz := clock_timestamp();
BEGIN
  -- 1. Validate mandatory fields
  IF p_company_id IS NULL OR p_delivery_id IS NULL OR p_conversation_id IS NULL
     OR p_customer_id IS NULL OR p_window_id IS NULL THEN
    RAISE EXCEPTION 'MANDATORY_PARAMETERS_MISSING' USING ERRCODE = '22023';
  END IF;

  IF p_provider_msg_id IS NULL OR length(trim(p_provider_msg_id)) = 0 THEN
    RAISE EXCEPTION 'CANNOT_FINALIZE_WITHOUT_PROVIDER_MESSAGE_ID' USING ERRCODE = '22023';
  END IF;

  -- 2. Lock and validate outbound delivery
  SELECT * INTO v_delivery
  FROM public.outbound_deliveries
  WHERE id = p_delivery_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'DELIVERY_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  IF v_delivery.company_id <> p_company_id THEN
    RAISE EXCEPTION 'DELIVERY_COMPANY_MISMATCH' USING ERRCODE = '42501';
  END IF;

  IF v_delivery.conversation_id <> p_conversation_id THEN
    RAISE EXCEPTION 'DELIVERY_CONVERSATION_MISMATCH' USING ERRCODE = '22000';
  END IF;

  -- 3. Lock and validate canonical conversation
  SELECT * INTO v_conv
  FROM public.conversations
  WHERE id = p_conversation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'CONVERSATION_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  IF v_conv.company_id <> p_company_id THEN
    RAISE EXCEPTION 'CONVERSATION_COMPANY_MISMATCH' USING ERRCODE = '42501';
  END IF;

  IF v_conv.customer_id <> p_customer_id THEN
    RAISE EXCEPTION 'CONVERSATION_CUSTOMER_MISMATCH' USING ERRCODE = '42501';
  END IF;

  IF v_delivery.channel <> v_conv.channel THEN
    RAISE EXCEPTION 'DELIVERY_CHANNEL_MISMATCH' USING ERRCODE = '22000';
  END IF;

  -- 4. Validate stable logical command identity & window binding
  IF (v_delivery.window_id IS NOT NULL AND v_delivery.window_id <> p_window_id)
     OR v_delivery.client_command_id IS DISTINCT FROM p_window_id THEN
    RAISE EXCEPTION 'COMMAND_IDENTITY_MISMATCH' USING ERRCODE = '22023';
  END IF;

  -- 5. Lock and validate SLA window
  SELECT * INTO v_window
  FROM public.response_sla_windows
  WHERE id = p_window_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'WINDOW_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  IF v_window.company_id <> p_company_id THEN
    RAISE EXCEPTION 'WINDOW_COMPANY_MISMATCH' USING ERRCODE = '42501';
  END IF;

  IF v_window.conversation_id <> p_conversation_id THEN
    RAISE EXCEPTION 'WINDOW_CONVERSATION_MISMATCH' USING ERRCODE = '22000';
  END IF;

  IF v_window.customer_id <> p_customer_id THEN
    RAISE EXCEPTION 'WINDOW_CUSTOMER_MISMATCH' USING ERRCODE = '42501';
  END IF;

  -- 6. Validate claim authority (Item 2: strict validation, no unconditional bypass)
  IF p_ai_claim_id IS NULL OR v_window.ai_claim_id IS DISTINCT FROM p_ai_claim_id THEN
    RAISE EXCEPTION 'CLAIM_NOT_AUTHORIZED' USING ERRCODE = '42501';
  END IF;

  -- 7. Check delivery status and provider message ID
  IF v_delivery.delivery_status = 'SENT' THEN
    -- Idempotent replay: must match same provider_msg_id and client_command_id
    IF v_delivery.provider_message_id = p_provider_msg_id
       AND v_delivery.client_command_id = p_window_id
       AND v_delivery.interaction_id IS NOT NULL THEN
      RETURN v_delivery.interaction_id;
    ELSE
      RAISE EXCEPTION 'IDEMPOTENT_REPLAY_MISMATCH' USING ERRCODE = '23505';
    END IF;
  END IF;

  IF v_delivery.delivery_status <> 'PROVIDER_SENT_PENDING_FINALIZE' THEN
    RAISE EXCEPTION 'DELIVERY_NOT_FINALIZABLE: Status is %', v_delivery.delivery_status USING ERRCODE = '55000';
  END IF;

  IF v_delivery.provider_message_id IS DISTINCT FROM p_provider_msg_id THEN
    RAISE EXCEPTION 'PROVIDER_MSG_ID_MISMATCH' USING ERRCODE = '22023';
  END IF;

  -- 8. Validate SLA window state
  IF v_window.state <> 'OPEN' THEN
    IF v_window.state = 'AI_RESPONDED' AND v_window.ai_response_interaction_id = v_delivery.interaction_id THEN
      RETURN v_delivery.interaction_id;
    END IF;
    RAISE EXCEPTION 'WINDOW_NOT_OPEN: State is %', v_window.state USING ERRCODE = '55000';
  END IF;

  -- 9. Mint public interaction with actor_type = 'AI'
  v_interaction_id := gen_random_uuid();

  INSERT INTO public.interactions (
    id,
    company_id,
    customer_id,
    conversation_id,
    channel,
    type,
    direction,
    sanitized_content,
    sanitization_status,
    sanitized_at,
    sanitizer_version,
    actor_type,
    actor_user_id,
    external_ref,
    created_at
  ) VALUES (
    v_interaction_id,
    p_company_id,
    p_customer_id,
    p_conversation_id,
    v_delivery.channel,
    'MESSAGE',
    'OUTBOUND',
    p_sanitized_content,
    'SUCCEEDED',
    v_now,
    'v1',
    'AI',
    NULL,
    p_provider_msg_id,
    v_now
  );

  -- 10. Mandatory Provenance in private.interaction_raw_contents (Fail-Closed)
  INSERT INTO private.interaction_raw_contents (
    interaction_id,
    company_id,
    raw_content,
    raw_payload,
    source_metadata,
    created_at
  ) VALUES (
    v_interaction_id,
    p_company_id,
    coalesce(p_raw_content, ''),
    '{}'::jsonb,
    coalesce(p_source_metadata, '{}'::jsonb),
    v_now
  );

  -- 11. Update outbound_deliveries to SENT
  UPDATE public.outbound_deliveries
  SET
    delivery_status = 'SENT',
    interaction_id = v_interaction_id,
    lease_until = NULL,
    updated_at = v_now
  WHERE id = p_delivery_id;

  -- 12. Atomically resolve Response SLA window to AI_RESPONDED & set dispatch ownership
  UPDATE public.response_sla_windows
  SET
    state = 'AI_RESPONDED',
    ai_response_interaction_id = v_interaction_id,
    resolved_at = v_now,
    dispatch_owner = 'AI',
    dispatch_state = 'PROVIDER_ACCEPTED',
    dispatch_fenced_until = NULL,
    ai_dispatch_fenced_until = NULL,
    ai_dispatch_token = NULL,
    updated_at = v_now
  WHERE id = p_window_id
    AND company_id = p_company_id
    AND state = 'OPEN';

  GET DIAGNOSTICS v_rows_updated = ROW_COUNT;
  IF v_rows_updated = 0 THEN
    RAISE EXCEPTION 'SLA_WINDOW_UPDATE_AFFECTED_ZERO_ROWS' USING ERRCODE = 'P0001';
  END IF;

  -- 13. Reset conversation status to OPEN and update last_message_at
  UPDATE public.conversations
  SET
    status = 'OPEN',
    last_message_at = v_now,
    updated_at = v_now
  WHERE id = p_conversation_id
    AND company_id = p_company_id;

  -- 14. Transactional audit log
  INSERT INTO public.audit_logs (
    company_id,
    user_id,
    action,
    resource_type,
    resource_id,
    customer_id,
    result,
    metadata
  ) VALUES (
    p_company_id,
    NULL,
    'RESPONSE_SLA_AI_RESPONDED',
    'INTERACTION',
    v_interaction_id,
    p_customer_id,
    'SUCCESS',
    jsonb_build_object(
      'delivery_id', p_delivery_id,
      'window_id', p_window_id,
      'ai_claim_id', p_ai_claim_id,
      'provider_msg_id', p_provider_msg_id
    )
  );

  RETURN v_interaction_id;
END;
$$;

CREATE OR REPLACE FUNCTION public.finalize_ai_zalo_sla_atomic(
  p_company_id uuid,
  p_window_id uuid,
  p_ai_claim_id uuid,
  p_zalo_delivery_id uuid,
  p_interaction_id uuid DEFAULT NULL,
  p_provider_msg_id text DEFAULT NULL,
  p_source_metadata jsonb DEFAULT '{}'::jsonb
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_zalo public.zalo_outbound_deliveries%ROWTYPE;
  v_conv public.conversations%ROWTYPE;
  v_window public.response_sla_windows%ROWTYPE;
  v_supplied_interaction public.interactions%ROWTYPE;
  v_interaction_id uuid;
  v_ref text;
  v_rows_updated integer;
  v_expected_command text;
  v_now timestamptz := clock_timestamp();
BEGIN
  IF p_company_id IS NULL OR p_window_id IS NULL OR p_zalo_delivery_id IS NULL THEN
    RAISE EXCEPTION 'MANDATORY_PARAMETERS_MISSING' USING ERRCODE = '22023';
  END IF;

  v_expected_command := 'ai-sla-win-' || p_window_id::text;

  -- 1. Lock and validate Zalo outbound delivery
  SELECT * INTO v_zalo
  FROM public.zalo_outbound_deliveries
  WHERE id = p_zalo_delivery_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ZALO_DELIVERY_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  IF v_zalo.company_id <> p_company_id THEN
    RAISE EXCEPTION 'ZALO_DELIVERY_COMPANY_MISMATCH' USING ERRCODE = '42501';
  END IF;

  IF v_zalo.command_id IS DISTINCT FROM v_expected_command THEN
    RAISE EXCEPTION 'ZALO_COMMAND_ID_MISMATCH' USING ERRCODE = '22023';
  END IF;

  IF v_zalo.status NOT IN ('SENT', 'PROVIDER_SENT_PENDING_FINALIZE') THEN
    RAISE EXCEPTION 'ZALO_DELIVERY_NOT_FINALIZABLE: Status is %', v_zalo.status USING ERRCODE = '55000';
  END IF;

  -- 2. Lock and validate Conversation
  SELECT * INTO v_conv
  FROM public.conversations
  WHERE id = v_zalo.conversation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'CONVERSATION_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  IF v_conv.company_id <> p_company_id THEN
    RAISE EXCEPTION 'CONVERSATION_COMPANY_MISMATCH' USING ERRCODE = '42501';
  END IF;

  IF v_conv.channel <> 'ZALO' THEN
    RAISE EXCEPTION 'CONVERSATION_CHANNEL_MISMATCH' USING ERRCODE = '22000';
  END IF;

  -- 3. Lock and validate SLA window
  SELECT * INTO v_window
  FROM public.response_sla_windows
  WHERE id = p_window_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'WINDOW_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  IF v_window.company_id <> p_company_id THEN
    RAISE EXCEPTION 'WINDOW_COMPANY_MISMATCH' USING ERRCODE = '42501';
  END IF;

  IF v_window.conversation_id <> v_zalo.conversation_id THEN
    RAISE EXCEPTION 'WINDOW_CONVERSATION_MISMATCH' USING ERRCODE = '22000';
  END IF;

  IF v_window.customer_id <> v_zalo.customer_id THEN
    RAISE EXCEPTION 'WINDOW_CUSTOMER_MISMATCH' USING ERRCODE = '42501';
  END IF;

  -- 4. Validate claim authority (Item 2: strict validation, no unconditional bypass)
  IF p_ai_claim_id IS NULL OR v_window.ai_claim_id IS DISTINCT FROM p_ai_claim_id THEN
    RAISE EXCEPTION 'CLAIM_NOT_AUTHORIZED' USING ERRCODE = '42501';
  END IF;

  -- 5. Determine or mint interaction with strict binding validation (Item 6)
  IF p_interaction_id IS NOT NULL THEN
    SELECT * INTO v_supplied_interaction
    FROM public.interactions
    WHERE id = p_interaction_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'INTERACTION_NOT_FOUND' USING ERRCODE = 'P0002';
    END IF;

    IF v_supplied_interaction.company_id <> p_company_id THEN
      RAISE EXCEPTION 'INTERACTION_COMPANY_MISMATCH' USING ERRCODE = '42501';
    END IF;

    IF v_supplied_interaction.conversation_id <> v_zalo.conversation_id THEN
      RAISE EXCEPTION 'INTERACTION_CONVERSATION_MISMATCH' USING ERRCODE = '22000';
    END IF;

    IF v_supplied_interaction.customer_id <> v_zalo.customer_id THEN
      RAISE EXCEPTION 'INTERACTION_CUSTOMER_MISMATCH' USING ERRCODE = '22000';
    END IF;

    IF v_supplied_interaction.channel <> 'ZALO' THEN
      RAISE EXCEPTION 'INTERACTION_CHANNEL_MISMATCH' USING ERRCODE = '22000';
    END IF;

    IF v_supplied_interaction.direction <> 'OUTBOUND' THEN
      RAISE EXCEPTION 'INTERACTION_DIRECTION_MISMATCH' USING ERRCODE = '22000';
    END IF;

    IF v_supplied_interaction.actor_type <> 'AI' THEN
      RAISE EXCEPTION 'INTERACTION_ACTOR_MISMATCH' USING ERRCODE = '22000';
    END IF;

    IF v_zalo.interaction_id IS NOT NULL AND v_zalo.interaction_id <> p_interaction_id THEN
      RAISE EXCEPTION 'INTERACTION_DELIVERY_MISMATCH' USING ERRCODE = '22023';
    END IF;

    v_interaction_id := p_interaction_id;
  ELSE
    v_interaction_id := v_zalo.interaction_id;
  END IF;

  IF v_interaction_id IS NULL THEN
    v_interaction_id := gen_random_uuid();
    v_ref := 'zalo:' || v_zalo.company_id::text || ':' || coalesce(v_zalo.oa_id, 'unknown') || ':'
             || coalesce(v_zalo.provider_msg_id, coalesce(p_provider_msg_id, 'outbound:' || v_zalo.id::text));

    INSERT INTO public.interactions (
      id,
      company_id,
      customer_id,
      conversation_id,
      channel,
      type,
      direction,
      sanitized_content,
      sanitization_status,
      sanitized_at,
      sanitizer_version,
      external_ref,
      actor_type,
      actor_user_id,
      created_at
    ) VALUES (
      v_interaction_id,
      v_zalo.company_id,
      v_zalo.customer_id,
      v_zalo.conversation_id,
      'ZALO',
      'MESSAGE',
      'OUTBOUND',
      v_zalo.content,
      'SUCCEEDED',
      v_now,
      'zalo-sanitizer-v1',
      v_ref,
      'AI',
      NULL,
      v_now
    );

    UPDATE public.zalo_outbound_deliveries
    SET status = 'SENT',
        interaction_id = v_interaction_id,
        provider_msg_id = coalesce(v_zalo.provider_msg_id, p_provider_msg_id),
        finalized_at = v_now,
        lease_until = NULL,
        error_code = NULL,
        error_message = NULL,
        updated_at = v_now
    WHERE id = v_zalo.id;
  END IF;

  -- 6. Idempotent check
  IF v_window.state = 'AI_RESPONDED' AND v_window.ai_response_interaction_id = v_interaction_id THEN
    RETURN v_interaction_id;
  END IF;

  IF v_window.state <> 'OPEN' THEN
    RAISE EXCEPTION 'WINDOW_NOT_OPEN: State is %', v_window.state USING ERRCODE = '55000';
  END IF;

  -- 7. Atomically resolve Response SLA window & set dispatch ownership
  UPDATE public.response_sla_windows
  SET
    state = 'AI_RESPONDED',
    ai_response_interaction_id = v_interaction_id,
    resolved_at = v_now,
    dispatch_owner = 'AI',
    dispatch_state = 'PROVIDER_ACCEPTED',
    dispatch_fenced_until = NULL,
    ai_dispatch_fenced_until = NULL,
    ai_dispatch_token = NULL,
    updated_at = v_now
  WHERE id = p_window_id
    AND company_id = p_company_id
    AND state = 'OPEN';

  GET DIAGNOSTICS v_rows_updated = ROW_COUNT;
  IF v_rows_updated = 0 THEN
    RAISE EXCEPTION 'SLA_WINDOW_UPDATE_AFFECTED_ZERO_ROWS' USING ERRCODE = 'P0001';
  END IF;

  -- 8. Record AI Provenance in private.interaction_raw_contents (strict append-only)
  IF NOT EXISTS (
    SELECT 1 FROM private.interaction_raw_contents
    WHERE interaction_id = v_interaction_id
  ) THEN
    INSERT INTO private.interaction_raw_contents (
      interaction_id,
      company_id,
      raw_content,
      raw_payload,
      source_metadata,
      created_at
    ) VALUES (
      v_interaction_id,
      p_company_id,
      v_zalo.content,
      '{}'::jsonb,
      coalesce(p_source_metadata, '{}'::jsonb),
      v_now
    );
  END IF;

  -- 9. Reset conversation status to OPEN
  UPDATE public.conversations
  SET
    status = 'OPEN',
    last_message_at = v_now,
    updated_at = v_now
  WHERE id = v_zalo.conversation_id
    AND company_id = p_company_id;

  -- 10. Transactional audit log
  INSERT INTO public.audit_logs (
    company_id,
    user_id,
    action,
    resource_type,
    resource_id,
    customer_id,
    result,
    metadata
  ) VALUES (
    p_company_id,
    NULL,
    'RESPONSE_SLA_AI_RESPONDED',
    'INTERACTION',
    v_interaction_id,
    v_zalo.customer_id,
    'SUCCESS',
    jsonb_build_object(
      'zalo_delivery_id', p_zalo_delivery_id,
      'window_id', p_window_id,
      'ai_claim_id', p_ai_claim_id,
      'provider_msg_id', coalesce(v_zalo.provider_msg_id, p_provider_msg_id)
    )
  );

  RETURN v_interaction_id;
END;
$$;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint WHERE conname = 'chk_response_sla_dispatch_owner'
  ) THEN
    ALTER TABLE public.response_sla_windows
      ADD CONSTRAINT chk_response_sla_dispatch_owner
      CHECK (dispatch_owner IS NULL OR dispatch_owner IN ('AI', 'SALE', 'NONE'));
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint WHERE conname = 'chk_response_sla_dispatch_state'
  ) THEN
    ALTER TABLE public.response_sla_windows
      ADD CONSTRAINT chk_response_sla_dispatch_state
      CHECK (dispatch_state IS NULL OR dispatch_state IN ('IDLE', 'DISPATCHING', 'PROVIDER_ACCEPTED', 'FAILED', 'UNCERTAIN'));
  END IF;
END $$;

CREATE INDEX IF NOT EXISTS idx_sla_active_dispatch_fence_composite
  ON public.response_sla_windows (company_id, conversation_id, dispatch_owner, dispatch_fenced_until)
  WHERE state = 'OPEN' AND dispatch_owner IN ('AI', 'SALE');

CREATE OR REPLACE FUNCTION public.han_prepare_send(
    p_company uuid,
    p_conversation uuid,
    p_actor uuid,
    p_request uuid,
    p_content text,
    p_safe text,
    p_safe_status text,
    p_delivery uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
#variable_conflict use_column
DECLARE
  v_existing private.han_outbox%ROWTYPE;
  v_conversation public.conversations%ROWTYPE;
  v_interaction uuid;
  v_now timestamptz := clock_timestamp();
  v_last_inbound timestamptz;
  v_sla public.response_sla_windows%ROWTYPE;
  v_sale_token uuid;
  v_lease interval := interval '120 seconds';
BEGIN
  -- Validate actor role and active status
  IF NOT EXISTS (
    SELECT 1
    FROM public.company_members m
    JOIN public.user_profiles up ON up.id = m.user_id AND up.status = 'ACTIVE'
    WHERE m.company_id = p_company
      AND m.user_id = p_actor
      AND m.status = 'ACTIVE'
      AND m.role IN ('SALE', 'BOSS_ADMIN')
  ) THEN
    RAISE EXCEPTION 'ACCESS_DENIED';
  END IF;

  -- Validate conversation exists in the company
  SELECT * INTO v_conversation
  FROM public.conversations
  WHERE id = p_conversation AND company_id = p_company
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'NOT_FOUND';
  END IF;

  -- 24-hour Messenger window check
  SELECT max(created_at) INTO v_last_inbound
  FROM public.interactions
  WHERE conversation_id = p_conversation
    AND company_id = p_company
    AND direction = 'INBOUND';

  IF v_last_inbound IS NULL OR v_last_inbound < (v_now - interval '24 hours') THEN
    RAISE EXCEPTION 'WINDOW_CLOSED';
  END IF;

  -- Check existing outbox row for this request_id (idempotency)
  SELECT * INTO v_existing
  FROM private.han_outbox
  WHERE company_id = p_company AND request_id = p_request
  FOR UPDATE;

  IF FOUND THEN
    IF v_existing.conversation_id <> p_conversation
       OR v_existing.content <> p_content
       OR v_existing.care_delivery_id IS DISTINCT FROM p_delivery THEN
      RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT';
    END IF;

    RETURN jsonb_build_object(
      'claimed', false,
      'status', v_existing.status
    );
  END IF;

  -- Validation
  IF coalesce(btrim(p_content), '') = '' OR coalesce(btrim(p_safe), '') = '' THEN
    RAISE EXCEPTION 'INVALID_INPUT';
  END IF;

  IF p_delivery IS NOT NULL THEN
    PERFORM 1
    FROM public.care_deliveries d
    JOIN public.care_campaigns c
      ON c.id = d.campaign_id
      AND c.company_id = d.company_id
    WHERE d.id = p_delivery
      AND d.company_id = p_company
      AND d.customer_id = v_conversation.customer_id
      AND d.channel = 'FACEBOOK'
      AND c.channel = 'FACEBOOK'
      AND d.status = 'PENDING'
    FOR UPDATE OF d;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'INVALID_DELIVERY';
    END IF;

    IF EXISTS (
      SELECT 1 FROM public.care_schedules
      WHERE company_id = p_company
        AND customer_id = v_conversation.customer_id
        AND channel = 'FACEBOOK'
        AND enabled = false
    ) THEN
      RAISE EXCEPTION 'CARE_STOPPED';
    END IF;
  END IF;

  -- ============================================================================
  -- PRE-PROVIDER RESPONSE SLA DISPATCH FENCING (Requirements 1, 3, 5)
  -- ============================================================================
  SELECT * INTO v_sla
  FROM public.response_sla_windows
  WHERE company_id = p_company
    AND conversation_id = p_conversation
    AND state = 'OPEN'
  FOR UPDATE;

  IF FOUND THEN
    -- A. If AI currently owns dispatch
    IF v_sla.dispatch_owner = 'AI' OR v_sla.ai_dispatch_fenced_until IS NOT NULL THEN
      IF (v_sla.dispatch_state = 'DISPATCHING' OR v_sla.ai_dispatch_token IS NOT NULL) THEN
        IF coalesce(v_sla.dispatch_fenced_until, v_sla.ai_dispatch_fenced_until) > v_now THEN
          -- AI currently holds external provider dispatch authority!
          RETURN jsonb_build_object(
            'claimed', false,
            'status', 'AI_DISPATCH_FENCED'
          );
        ELSE
          -- AI dispatch lease expired mid-flight: transition logical operation to UNCERTAIN! Fail safe!
          UPDATE public.response_sla_windows
          SET
            dispatch_state = 'UNCERTAIN',
            dispatch_fenced_until = NULL,
            ai_dispatch_fenced_until = NULL,
            updated_at = v_now
          WHERE id = v_sla.id;

          RETURN jsonb_build_object(
            'claimed', false,
            'status', 'DISPATCH_UNCERTAIN'
          );
        END IF;
      ELSIF v_sla.dispatch_state = 'PROVIDER_ACCEPTED' THEN
        RETURN jsonb_build_object(
          'claimed', false,
          'status', 'AI_ALREADY_RESPONDED'
        );
      END IF;
    END IF;

    -- B. If SALE currently owns dispatch (Sale-vs-Sale concurrency protection)
    IF v_sla.dispatch_owner = 'SALE' THEN
      IF v_sla.dispatch_state = 'DISPATCHING' THEN
        IF v_sla.dispatch_fenced_until > v_now THEN
          -- Sale dispatch is currently in-flight!
          -- If this is a DIFFERENT request, deny before external provider call:
          IF v_sla.dispatch_delivery_id IS DISTINCT FROM p_request THEN
            RETURN jsonb_build_object(
              'claimed', false,
              'status', 'SALE_ALREADY_DISPATCHING'
            );
          END IF;
        ELSE
          -- Existing Sale lease expired unresolved: transition to UNCERTAIN! Fail safe!
          UPDATE public.response_sla_windows
          SET
            dispatch_state = 'UNCERTAIN',
            dispatch_fenced_until = NULL,
            updated_at = v_now
          WHERE id = v_sla.id;

          RETURN jsonb_build_object(
            'claimed', false,
            'status', 'DISPATCH_UNCERTAIN'
          );
        END IF;
      ELSIF v_sla.dispatch_state = 'PROVIDER_ACCEPTED' THEN
        RETURN jsonb_build_object(
          'claimed', false,
          'status', 'SALE_ALREADY_RESPONDED'
        );
      END IF;
    END IF;

    -- C. If dispatch_state is UNCERTAIN (regardless of owner)
    IF v_sla.dispatch_state = 'UNCERTAIN' THEN
      -- Neither Sale nor AI may automatically dispatch a new message while outcome is ambiguous!
      RETURN jsonb_build_object(
        'claimed', false,
        'status', 'DISPATCH_UNCERTAIN'
      );
    END IF;

    -- D. Atomically acquire SALE dispatch ownership for this new send
    v_sale_token := gen_random_uuid();
    UPDATE public.response_sla_windows
    SET
      dispatch_owner = 'SALE',
      dispatch_state = 'DISPATCHING',
      dispatch_token = v_sale_token,
      dispatch_fenced_until = v_now + v_lease,
      dispatch_delivery_id = p_request,
      updated_at = v_now
    WHERE id = v_sla.id;
  END IF;

  INSERT INTO public.interactions (
    company_id, customer_id, conversation_id,
    channel, type, direction,
    sanitized_content, sanitization_status,
    sanitized_at, sanitizer_version,
    actor_type, actor_user_id
  )
  VALUES (
    p_company, v_conversation.customer_id,
    p_conversation, 'FACEBOOK', 'MESSAGE', 'OUTBOUND',
    p_safe, p_safe_status,
    CASE WHEN p_safe_status = 'SUCCEEDED' THEN v_now END,
    'han-bounded-v2', 'SALE', p_actor
  )
  RETURNING id INTO v_interaction;

  INSERT INTO private.interaction_raw_contents (
    interaction_id, company_id, raw_content
  )
  VALUES (v_interaction, p_company, p_content);

  INSERT INTO private.han_outbox (
    company_id, request_id, conversation_id,
    interaction_id, actor_id, content,
    status, care_delivery_id
  )
  VALUES (
    p_company, p_request, p_conversation,
    v_interaction, p_actor, p_content,
    'SENDING', p_delivery
  );

  INSERT INTO public.audit_logs (
    company_id, user_id, action, resource_type,
    resource_id, customer_id, result
  )
  VALUES (
    p_company, p_actor, 'MESSENGER_SEND_REQUESTED',
    'Interaction', v_interaction,
    v_conversation.customer_id, 'SUCCESS'
  );

  RETURN jsonb_build_object(
    'claimed', true,
    'status', 'SENDING'
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.zalo_claim_outbound_delivery(
  p_company_id uuid,
  p_conversation_id uuid,
  p_command_id text,
  p_actor_type text,
  p_actor_user_id uuid,
  p_raw_content text,
  p_sanitized_content text,
  p_content_sha256 text,
  p_oa_id text DEFAULT NULL,
  p_lease_seconds integer DEFAULT 120
)
RETURNS TABLE (
  claim_status text,
  delivery_id uuid,
  claim_token uuid,
  oa_id text,
  recipient_zalo_uid text,
  customer_id uuid,
  provider_msg_id text,
  interaction_id uuid
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
#variable_conflict use_column
DECLARE
  v_conv record;
  v_oa text;
  v_row public.zalo_outbound_deliveries%ROWTYPE;
  v_token uuid := gen_random_uuid();
  v_lease interval := make_interval(secs => greatest(coalesce(p_lease_seconds, 120), 10));
  v_sla public.response_sla_windows%ROWTYPE;
  v_now timestamptz := clock_timestamp();
  v_existing_cmd text;
BEGIN
  IF coalesce(btrim(p_command_id), '') = '' OR length(p_command_id) > 200 THEN
    RAISE EXCEPTION 'ZALO_OUTBOUND_COMMAND_ID_INVALID' USING ERRCODE = '22023';
  END IF;
  IF coalesce(btrim(p_raw_content), '') = '' OR coalesce(p_content_sha256, '') = '' THEN
    RAISE EXCEPTION 'ZALO_OUTBOUND_CONTENT_INVALID' USING ERRCODE = '22023';
  END IF;
  IF p_actor_type NOT IN ('SALE', 'AI', 'SYSTEM') THEN
    RAISE EXCEPTION 'ZALO_OUTBOUND_ACTOR_INVALID' USING ERRCODE = '22023';
  END IF;

  IF p_actor_type = 'SALE' THEN
    IF p_actor_user_id IS NULL OR NOT EXISTS (
      SELECT 1
      FROM public.company_members m
      JOIN public.user_profiles up ON up.id = m.user_id AND up.status = 'ACTIVE'
      WHERE m.company_id = p_company_id
        AND m.user_id = p_actor_user_id
        AND m.status = 'ACTIVE'
        AND m.role IN ('SALE', 'BOSS_ADMIN')
    ) THEN
      RAISE EXCEPTION 'ZALO_OUTBOUND_ACTOR_FORBIDDEN' USING ERRCODE = '42501';
    END IF;
  ELSIF p_actor_user_id IS NOT NULL THEN
    RAISE EXCEPTION 'ZALO_OUTBOUND_ACTOR_INVALID' USING ERRCODE = '22023';
  END IF;

  SELECT c.id, c.customer_id, c.external_conversation_id INTO v_conv
  FROM public.conversations c
  WHERE c.id = p_conversation_id AND c.company_id = p_company_id AND c.channel = 'ZALO';
  IF v_conv.id IS NULL THEN
    RAISE EXCEPTION 'ZALO_CONVERSATION_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  IF p_oa_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.zalo_oa_configs c
      WHERE c.company_id = p_company_id AND c.oa_id = p_oa_id AND c.status = 'ACTIVE'
    ) THEN
      RAISE EXCEPTION 'ZALO_OA_NOT_CONFIGURED' USING ERRCODE = 'P0002';
    END IF;
    v_oa := p_oa_id;
  ELSE
    v_oa := private.zalo_resolve_customer_oa(p_company_id, v_conv.customer_id);
  END IF;
  IF v_oa IS NULL THEN
    RAISE EXCEPTION 'ZALO_OA_NOT_CONFIGURED' USING ERRCODE = 'P0002';
  END IF;

  -- ============================================================================
  -- HUMAN SALE RESPONSE SLA CROSS-ACTOR & SAME-ACTOR DISPATCH FENCING (Requirements 2, 3)
  -- ============================================================================
  IF p_actor_type = 'SALE' THEN
    SELECT * INTO v_sla
    FROM public.response_sla_windows
    WHERE company_id = p_company_id
      AND conversation_id = p_conversation_id
      AND state = 'OPEN'
    FOR UPDATE;

    IF FOUND THEN
      -- A. If dispatch_state is already UNCERTAIN
      IF v_sla.dispatch_state = 'UNCERTAIN' THEN
        RAISE EXCEPTION 'DISPATCH_UNCERTAIN' USING ERRCODE = '55000';
      END IF;

      -- B. If AI currently owns dispatch
      IF v_sla.dispatch_owner = 'AI' OR v_sla.ai_dispatch_fenced_until IS NOT NULL THEN
        IF (v_sla.dispatch_state = 'DISPATCHING' OR v_sla.ai_dispatch_token IS NOT NULL) THEN
          IF coalesce(v_sla.dispatch_fenced_until, v_sla.ai_dispatch_fenced_until) > v_now THEN
            RAISE EXCEPTION 'AI_DISPATCH_FENCED' USING ERRCODE = '55000';
          ELSE
            UPDATE public.response_sla_windows
            SET dispatch_state = 'UNCERTAIN',
                dispatch_fenced_until = NULL,
                ai_dispatch_fenced_until = NULL,
                updated_at = v_now
            WHERE id = v_sla.id;

            RAISE EXCEPTION 'DISPATCH_UNCERTAIN' USING ERRCODE = '55000';
          END IF;
        ELSIF v_sla.dispatch_state = 'PROVIDER_ACCEPTED' THEN
          RAISE EXCEPTION 'AI_ALREADY_RESPONDED' USING ERRCODE = '55000';
        END IF;
      END IF;

      -- C. If SALE currently owns dispatch (Sale-vs-Sale concurrent dispatch prevention)
      IF v_sla.dispatch_owner = 'SALE' THEN
        IF v_sla.dispatch_state = 'DISPATCHING' THEN
          IF v_sla.dispatch_fenced_until > v_now THEN
            -- An active Sale dispatch lease exists!
            -- Check if this command belongs to the currently in-flight delivery
            IF v_sla.dispatch_delivery_id IS NOT NULL THEN
              SELECT command_id INTO v_existing_cmd
              FROM public.zalo_outbound_deliveries
              WHERE id = v_sla.dispatch_delivery_id;

              IF v_existing_cmd IS DISTINCT FROM p_command_id THEN
                -- Different Sale command while C1 is in-flight! Deny before provider call:
                RAISE EXCEPTION 'SALE_ALREADY_DISPATCHING' USING ERRCODE = '55000';
              END IF;
            ELSE
              RAISE EXCEPTION 'SALE_ALREADY_DISPATCHING' USING ERRCODE = '55000';
            END IF;
          ELSE
            -- Existing Sale lease expired unresolved: transition to UNCERTAIN! Fail safe!
            UPDATE public.response_sla_windows
            SET dispatch_state = 'UNCERTAIN',
                dispatch_fenced_until = NULL,
                updated_at = v_now
            WHERE id = v_sla.id;

            RAISE EXCEPTION 'DISPATCH_UNCERTAIN' USING ERRCODE = '55000';
          END IF;
        ELSIF v_sla.dispatch_state = 'PROVIDER_ACCEPTED' THEN
          RAISE EXCEPTION 'SALE_ALREADY_RESPONDED' USING ERRCODE = '55000';
        END IF;
      END IF;

      -- Acquire SALE response dispatch ownership
      UPDATE public.response_sla_windows
      SET
        dispatch_owner = 'SALE',
        dispatch_state = 'DISPATCHING',
        dispatch_token = v_token,
        dispatch_fenced_until = v_now + v_lease,
        updated_at = v_now
      WHERE id = v_sla.id;
    END IF;
  END IF;

  INSERT INTO public.zalo_outbound_deliveries AS d (
    company_id, conversation_id, customer_id, recipient_zalo_uid, idempotency_key, content,
    status, attempts, command_id, channel, lease_until, oa_id, actor_type, actor_user_id,
    claim_token, content_sha256
  ) VALUES (
    p_company_id, v_conv.id, v_conv.customer_id, v_conv.external_conversation_id,
    'zalo_out:' || p_company_id::text || ':' || p_command_id, p_sanitized_content,
    'SENDING', 1, p_command_id, 'ZALO', v_now + v_lease, v_oa, p_actor_type, p_actor_user_id,
    v_token, p_content_sha256
  )
  ON CONFLICT DO NOTHING
  RETURNING d.* INTO v_row;

  IF v_row.id IS NOT NULL THEN
    INSERT INTO private.zalo_outbound_payloads (delivery_id, company_id, raw_content)
    VALUES (v_row.id, p_company_id, p_raw_content);

    IF p_actor_type = 'SALE' AND v_sla.id IS NOT NULL THEN
      UPDATE public.response_sla_windows
      SET dispatch_delivery_id = v_row.id
      WHERE id = v_sla.id;
    END IF;

    RETURN QUERY SELECT 'CLAIMED'::text, v_row.id, v_token, v_oa, v_row.recipient_zalo_uid,
                        v_row.customer_id, NULL::text, NULL::uuid;
    RETURN;
  END IF;

  SELECT d.* INTO v_row
  FROM public.zalo_outbound_deliveries d
  WHERE d.company_id = p_company_id AND d.channel = 'ZALO' AND d.command_id = p_command_id
  FOR UPDATE;

  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'ZALO_OUTBOUND_COMMAND_CONFLICT' USING ERRCODE = '23505';
  END IF;

  IF v_row.conversation_id <> v_conv.id OR v_row.content_sha256 IS DISTINCT FROM p_content_sha256 THEN
    RETURN QUERY SELECT 'CONFLICT'::text, v_row.id, NULL::uuid, v_row.oa_id, v_row.recipient_zalo_uid,
                        v_row.customer_id, v_row.provider_msg_id, v_row.interaction_id;
    RETURN;
  END IF;

  IF v_row.status = 'SENT' THEN
    RETURN QUERY SELECT 'ALREADY_SENT'::text, v_row.id, NULL::uuid, v_row.oa_id, v_row.recipient_zalo_uid,
                        v_row.customer_id, v_row.provider_msg_id, v_row.interaction_id;
    RETURN;
  END IF;

  IF v_row.status = 'PROVIDER_SENT_PENDING_FINALIZE' THEN
    RETURN QUERY SELECT 'PENDING_FINALIZE'::text, v_row.id, NULL::uuid, v_row.oa_id, v_row.recipient_zalo_uid,
                        v_row.customer_id, v_row.provider_msg_id, v_row.interaction_id;
    RETURN;
  END IF;

  IF v_row.status IN ('PROVIDER_UNCERTAIN', 'UNCERTAIN') THEN
    RETURN QUERY SELECT 'UNCERTAIN'::text, v_row.id, NULL::uuid, v_row.oa_id, v_row.recipient_zalo_uid,
                        v_row.customer_id, v_row.provider_msg_id, v_row.interaction_id;
    RETURN;
  END IF;

  IF v_row.status = 'SENDING' AND v_row.lease_until > v_now THEN
    RETURN QUERY SELECT 'BUSY'::text, v_row.id, NULL::uuid, v_row.oa_id, v_row.recipient_zalo_uid,
                        v_row.customer_id, NULL::text, NULL::uuid;
    RETURN;
  END IF;

  UPDATE public.zalo_outbound_deliveries
  SET claim_token = v_token, lease_until = v_now + v_lease, attempts = attempts + 1, updated_at = v_now
  WHERE id = v_row.id;

  IF p_actor_type = 'SALE' AND v_sla.id IS NOT NULL THEN
    UPDATE public.response_sla_windows
    SET dispatch_delivery_id = v_row.id
    WHERE id = v_sla.id;
  END IF;

  RETURN QUERY SELECT 'CLAIMED'::text, v_row.id, v_token, v_row.oa_id, v_row.recipient_zalo_uid,
                      v_row.customer_id, NULL::text, NULL::uuid;
END;
$$;

CREATE OR REPLACE FUNCTION public.zalo_finalize_outbound_delivery(p_delivery_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
#variable_conflict use_column
DECLARE
  v_row public.zalo_outbound_deliveries%ROWTYPE;
  v_sla public.response_sla_windows%ROWTYPE;
  v_raw text;
  v_ref text;
  v_interaction_id uuid;
  v_existing record;
  v_now timestamptz := clock_timestamp();
BEGIN
  SELECT d.* INTO v_row FROM public.zalo_outbound_deliveries d WHERE d.id = p_delivery_id FOR UPDATE;
  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'ZALO_OUTBOUND_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  IF v_row.status = 'SENT' THEN
    RETURN jsonb_build_object('interaction_id', v_row.interaction_id, 'already_finalized', true,
                              'provider_msg_id', v_row.provider_msg_id);
  END IF;

  IF v_row.status <> 'PROVIDER_SENT_PENDING_FINALIZE' THEN
    RAISE EXCEPTION 'ZALO_OUTBOUND_NOT_FINALIZABLE' USING ERRCODE = '55000';
  END IF;

  SELECT p.raw_content INTO v_raw FROM private.zalo_outbound_payloads p WHERE p.delivery_id = v_row.id;
  IF v_raw IS NULL THEN
    RAISE EXCEPTION 'ZALO_OUTBOUND_PAYLOAD_MISSING' USING ERRCODE = 'P0002';
  END IF;

  PERFORM private.zalo_lock_user(v_row.company_id, v_row.recipient_zalo_uid);

  v_ref := 'zalo:' || v_row.company_id::text || ':' || coalesce(v_row.oa_id, 'unknown') || ':'
           || coalesce(v_row.provider_msg_id, 'outbound:' || v_row.id::text);

  SELECT i.id, i.actor_user_id INTO v_existing
  FROM public.interactions i
  WHERE i.company_id = v_row.company_id AND i.channel = 'ZALO' AND i.external_ref = v_ref;

  IF v_existing.id IS NOT NULL THEN
    v_interaction_id := v_existing.id;
    UPDATE public.interactions i
    SET actor_type = coalesce(v_row.actor_type, i.actor_type),
        actor_user_id = coalesce(i.actor_user_id, v_row.actor_user_id)
    WHERE i.id = v_existing.id AND i.actor_user_id IS NULL;
  ELSE
    INSERT INTO public.interactions (
      company_id, customer_id, conversation_id, channel, type, direction,
      sanitized_content, sanitization_status, sanitized_at, sanitizer_version,
      external_ref, actor_type, actor_user_id, created_at
    ) VALUES (
      v_row.company_id, v_row.customer_id, v_row.conversation_id, 'ZALO', 'MESSAGE', 'OUTBOUND',
      v_row.content, 'SUCCEEDED', v_now, 'zalo-sanitizer-v1',
      v_ref, coalesce(v_row.actor_type, 'SYSTEM'), v_row.actor_user_id,
      coalesce(v_row.provider_accepted_at, v_now)
    )
    RETURNING id INTO v_interaction_id;

    INSERT INTO private.interaction_raw_contents (interaction_id, company_id, raw_content, raw_payload, source_metadata)
    VALUES (
      v_interaction_id, v_row.company_id, v_raw,
      jsonb_build_object('recipient', jsonb_build_object('user_id', v_row.recipient_zalo_uid)),
      jsonb_build_object(
        'oa_id', v_row.oa_id,
        'recipient_id', v_row.recipient_zalo_uid,
        'provider_msg_id', v_row.provider_msg_id,
        'delivery_id', v_row.id,
        'command_id', v_row.command_id,
        'origin', 'CRM_OUTBOX'
      )
    );

    UPDATE public.conversations c
    SET last_message_at = greatest(c.last_message_at, coalesce(v_row.provider_accepted_at, v_now)),
        status = CASE WHEN c.status = 'AI_HANDLING' THEN 'OPEN' ELSE c.status END
    WHERE c.id = v_row.conversation_id;
  END IF;

  UPDATE public.zalo_outbound_deliveries d
  SET status = 'SENT', interaction_id = v_interaction_id, finalized_at = v_now,
      claim_token = NULL, lease_until = NULL, error_code = NULL, error_message = NULL, updated_at = v_now
  WHERE d.id = v_row.id;

  -- Bind outcome mutation to dispatch_delivery_id == p_delivery_id and Sale ownership (Requirements 3 & 5)
  IF v_row.actor_type = 'SALE' THEN
    SELECT * INTO v_sla
    FROM public.response_sla_windows
    WHERE conversation_id = v_row.conversation_id
      AND company_id = v_row.company_id
      AND state = 'OPEN'
    FOR UPDATE;

    IF FOUND THEN
      -- Validate exact delivery binding
      IF v_sla.dispatch_delivery_id = p_delivery_id AND v_sla.dispatch_owner = 'SALE' THEN
        UPDATE public.response_sla_windows
        SET state = 'SALE_RESPONDED',
            sale_response_interaction_id = v_interaction_id,
            resolved_at = coalesce(v_row.provider_accepted_at, v_now),
            dispatch_owner = 'SALE',
            dispatch_state = 'PROVIDER_ACCEPTED',
            dispatch_fenced_until = NULL,
            ai_dispatch_fenced_until = NULL,
            ai_dispatch_token = NULL,
            updated_at = v_now
        WHERE id = v_sla.id;
      END IF;
    END IF;
  END IF;

  RETURN jsonb_build_object('interaction_id', v_interaction_id, 'already_finalized', false,
                            'provider_msg_id', v_row.provider_msg_id);
END;
$$;

CREATE OR REPLACE FUNCTION public.han_prepare_send(
  p_company uuid,
  p_conversation uuid,
  p_actor uuid,
  p_request uuid,
  p_content text,
  p_safe text,
  p_safe_status text,
  p_delivery uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_conversation public.conversations%ROWTYPE;
  v_existing private.han_outbox%ROWTYPE;
  v_interaction uuid;
  v_latest timestamptz;
  v_sla public.response_sla_windows%ROWTYPE;
  v_sale_token uuid;
  v_now timestamptz := clock_timestamp();
  v_lease interval := interval '120 seconds';
BEGIN
  -- 1. Advisory transaction lock for (company, request) idempotent serialization
  PERFORM pg_advisory_xact_lock(
    hashtextextended(
      'han-send:' || p_company::text || p_request::text,
      0
    )
  );

  -- 2. Validate Conversation belongs to company and channel is FACEBOOK
  SELECT * INTO v_conversation
  FROM public.conversations
  WHERE company_id = p_company
    AND id = p_conversation
    AND channel = 'FACEBOOK'
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'NOT_FOUND';
  END IF;

  -- 3. Validate company, user profile, and membership are ACTIVE with allowed role
  IF NOT EXISTS (
    SELECT 1
    FROM public.company_members m
    JOIN public.user_profiles u ON u.id = m.user_id
    JOIN public.companies c ON c.id = m.company_id
    WHERE m.company_id = p_company
      AND m.user_id = p_actor
      AND m.status = 'ACTIVE'
      AND u.status = 'ACTIVE'
      AND c.status = 'ACTIVE'
      AND m.role IN ('BOSS_ADMIN', 'SALE')
  ) THEN
    RAISE EXCEPTION 'ACCESS_DENIED';
  END IF;

  -- 4. Existing outbox idempotency with actor_id binding
  SELECT * INTO v_existing
  FROM private.han_outbox
  WHERE company_id = p_company
    AND request_id = p_request;

  IF FOUND THEN
    IF v_existing.conversation_id <> p_conversation
      OR v_existing.actor_id <> p_actor
      OR v_existing.content <> p_content
      OR v_existing.care_delivery_id IS DISTINCT FROM p_delivery
    THEN
      RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT';
    END IF;

    RETURN jsonb_build_object(
      'claimed', false,
      'status', v_existing.status
    );
  END IF;

  -- 5. Messenger window based strictly on CUSTOMER inbound messages with future-timestamp tolerance
  SELECT max(created_at) INTO v_latest
  FROM public.interactions
  WHERE company_id = p_company
    AND conversation_id = p_conversation
    AND direction = 'INBOUND'
    AND actor_type = 'CUSTOMER';

  IF v_latest IS NULL
    OR v_latest <= v_now - interval '24 hours'
    OR v_latest > v_now + interval '10 seconds'
  THEN
    RAISE EXCEPTION 'WINDOW_CLOSED';
  END IF;

  -- 6. Content length bounds and strict p_safe_status rules
  IF length(p_content) NOT BETWEEN 1 AND 2000
    OR p_content IS NULL
    OR p_safe_status IS NULL OR p_safe_status NOT IN ('FAILED', 'SUCCEEDED')
    OR (p_safe_status = 'FAILED' AND p_safe IS NOT NULL)
    OR (p_safe_status = 'SUCCEEDED' AND p_safe IS NULL)
    OR (p_safe IS NOT NULL AND length(p_safe) NOT BETWEEN 1 AND 2000)
  THEN
    RAISE EXCEPTION 'INVALID_INPUT';
  END IF;

  -- 7. Care delivery validation
  IF p_delivery IS NOT NULL THEN
    PERFORM 1
    FROM public.care_deliveries d
    JOIN public.care_campaigns c
      ON c.id = d.campaign_id
      AND c.company_id = d.company_id
    WHERE d.id = p_delivery
      AND d.company_id = p_company
      AND d.customer_id = v_conversation.customer_id
      AND d.channel = 'FACEBOOK'
      AND c.channel = 'FACEBOOK'
      AND d.status = 'PENDING'
    FOR UPDATE OF d;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'INVALID_DELIVERY';
    END IF;

    IF EXISTS (
      SELECT 1 FROM public.care_schedules
      WHERE company_id = p_company
        AND customer_id = v_conversation.customer_id
        AND channel = 'FACEBOOK'
        AND enabled = false
    ) THEN
      RAISE EXCEPTION 'CARE_STOPPED';
    END IF;
  END IF;

  -- ============================================================================
  -- 8. PRE-PROVIDER RESPONSE SLA DISPATCH FENCING (Cross-Actor & Same-Actor)
  -- ============================================================================
  SELECT * INTO v_sla
  FROM public.response_sla_windows
  WHERE company_id = p_company
    AND conversation_id = p_conversation
    AND state = 'OPEN'
  FOR UPDATE;

  IF FOUND THEN
    -- A. If AI currently owns dispatch
    IF v_sla.dispatch_owner = 'AI' OR v_sla.ai_dispatch_fenced_until IS NOT NULL THEN
      IF (v_sla.dispatch_state = 'DISPATCHING' OR v_sla.ai_dispatch_token IS NOT NULL) THEN
        IF coalesce(v_sla.dispatch_fenced_until, v_sla.ai_dispatch_fenced_until) > v_now THEN
          RETURN jsonb_build_object(
            'claimed', false,
            'status', 'AI_DISPATCH_FENCED'
          );
        ELSE
          UPDATE public.response_sla_windows
          SET
            dispatch_state = 'UNCERTAIN',
            dispatch_fenced_until = NULL,
            ai_dispatch_fenced_until = NULL,
            updated_at = v_now
          WHERE id = v_sla.id;

          RETURN jsonb_build_object(
            'claimed', false,
            'status', 'DISPATCH_UNCERTAIN'
          );
        END IF;
      ELSIF v_sla.dispatch_state = 'PROVIDER_ACCEPTED' THEN
        RETURN jsonb_build_object(
          'claimed', false,
          'status', 'AI_ALREADY_RESPONDED'
        );
      END IF;
    END IF;

    -- B. If SALE currently owns dispatch (Same-actor concurrent dispatch prevention)
    IF v_sla.dispatch_owner = 'SALE' THEN
      IF v_sla.dispatch_state = 'DISPATCHING' THEN
        IF v_sla.dispatch_fenced_until > v_now THEN
          IF v_sla.dispatch_delivery_id IS DISTINCT FROM p_request THEN
            RETURN jsonb_build_object(
              'claimed', false,
              'status', 'SALE_ALREADY_DISPATCHING'
            );
          END IF;
        ELSE
          UPDATE public.response_sla_windows
          SET
            dispatch_state = 'UNCERTAIN',
            dispatch_fenced_until = NULL,
            updated_at = v_now
          WHERE id = v_sla.id;

          RETURN jsonb_build_object(
            'claimed', false,
            'status', 'DISPATCH_UNCERTAIN'
          );
        END IF;
      ELSIF v_sla.dispatch_state = 'PROVIDER_ACCEPTED' THEN
        RETURN jsonb_build_object(
          'claimed', false,
          'status', 'SALE_ALREADY_RESPONDED'
        );
      END IF;
    END IF;

    -- C. If dispatch_state is UNCERTAIN
    IF v_sla.dispatch_state = 'UNCERTAIN' THEN
      RETURN jsonb_build_object(
        'claimed', false,
        'status', 'DISPATCH_UNCERTAIN'
      );
    END IF;

    -- D. Atomically acquire SALE dispatch ownership for this send
    v_sale_token := gen_random_uuid();
    UPDATE public.response_sla_windows
    SET
      dispatch_owner = 'SALE',
      dispatch_state = 'DISPATCHING',
      dispatch_token = v_sale_token,
      dispatch_fenced_until = v_now + v_lease,
      dispatch_delivery_id = p_request,
      updated_at = v_now
    WHERE id = v_sla.id;
  END IF;

  INSERT INTO public.interactions (
    company_id, customer_id, conversation_id,
    channel, type, direction,
    sanitized_content, sanitization_status,
    sanitized_at, sanitizer_version,
    actor_type, actor_user_id
  )
  VALUES (
    p_company, v_conversation.customer_id,
    p_conversation, 'FACEBOOK', 'MESSAGE', 'OUTBOUND',
    p_safe, p_safe_status,
    CASE WHEN p_safe_status = 'SUCCEEDED' THEN v_now END,
    'han-bounded-v2', 'SALE', p_actor
  )
  RETURNING id INTO v_interaction;

  INSERT INTO private.interaction_raw_contents (
    interaction_id, company_id, raw_content
  )
  VALUES (v_interaction, p_company, p_content);

  INSERT INTO private.han_outbox (
    company_id, request_id, conversation_id,
    interaction_id, actor_id, content,
    status, care_delivery_id
  )
  VALUES (
    p_company, p_request, p_conversation,
    v_interaction, p_actor, p_content,
    'SENDING', p_delivery
  );

  INSERT INTO public.audit_logs (
    company_id, user_id, action, resource_type,
    resource_id, customer_id, result
  )
  VALUES (
    p_company, p_actor, 'MESSENGER_SEND_REQUESTED',
    'Interaction', v_interaction,
    v_conversation.customer_id, 'SUCCESS'
  );

  RETURN jsonb_build_object(
    'claimed', true,
    'status', 'SENDING'
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.zalo_claim_outbound_delivery(
  p_company_id uuid,
  p_conversation_id uuid,
  p_command_id text,
  p_actor_type text,
  p_actor_user_id uuid,
  p_raw_content text,
  p_sanitized_content text,
  p_content_sha256 text,
  p_oa_id text DEFAULT NULL,
  p_lease_seconds integer DEFAULT 120
)
RETURNS TABLE (
  claim_status text,
  delivery_id uuid,
  claim_token uuid,
  oa_id text,
  recipient_zalo_uid text,
  customer_id uuid,
  provider_msg_id text,
  interaction_id uuid
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
#variable_conflict use_column
DECLARE
  v_conv record;
  v_oa text;
  v_row public.zalo_outbound_deliveries%ROWTYPE;
  v_token uuid;
  v_lease interval := make_interval(secs => greatest(coalesce(p_lease_seconds, 120), 10));
  v_sla public.response_sla_windows%ROWTYPE;
  v_now timestamptz := clock_timestamp();
BEGIN
  IF coalesce(btrim(p_command_id), '') = '' OR length(p_command_id) > 200 THEN
    RAISE EXCEPTION 'ZALO_OUTBOUND_COMMAND_ID_INVALID' USING ERRCODE = '22023';
  END IF;
  IF coalesce(btrim(p_raw_content), '') = '' OR coalesce(p_content_sha256, '') = '' THEN
    RAISE EXCEPTION 'ZALO_OUTBOUND_CONTENT_INVALID' USING ERRCODE = '22023';
  END IF;
  IF p_actor_type NOT IN ('SALE', 'AI', 'SYSTEM') THEN
    RAISE EXCEPTION 'ZALO_OUTBOUND_ACTOR_INVALID' USING ERRCODE = '22023';
  END IF;

  IF p_actor_type = 'SALE' THEN
    IF p_actor_user_id IS NULL OR NOT EXISTS (
      SELECT 1
      FROM public.company_members m
      JOIN public.user_profiles up ON up.id = m.user_id AND up.status = 'ACTIVE'
      WHERE m.company_id = p_company_id
        AND m.user_id = p_actor_user_id
        AND m.status = 'ACTIVE'
        AND m.role IN ('SALE', 'BOSS_ADMIN')
    ) THEN
      RAISE EXCEPTION 'ZALO_OUTBOUND_ACTOR_FORBIDDEN' USING ERRCODE = '42501';
    END IF;
  ELSIF p_actor_user_id IS NOT NULL THEN
    RAISE EXCEPTION 'ZALO_OUTBOUND_ACTOR_INVALID' USING ERRCODE = '22023';
  END IF;

  SELECT c.id, c.customer_id, c.external_conversation_id INTO v_conv
  FROM public.conversations c
  WHERE c.id = p_conversation_id AND c.company_id = p_company_id AND c.channel = 'ZALO';
  IF v_conv.id IS NULL THEN
    RAISE EXCEPTION 'ZALO_CONVERSATION_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  IF p_oa_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.zalo_oa_configs c
      WHERE c.company_id = p_company_id AND c.oa_id = p_oa_id AND c.status = 'ACTIVE'
    ) THEN
      RAISE EXCEPTION 'ZALO_OA_NOT_CONFIGURED' USING ERRCODE = 'P0002';
    END IF;
    v_oa := p_oa_id;
  ELSE
    v_oa := private.zalo_resolve_customer_oa(p_company_id, v_conv.customer_id);
  END IF;
  IF v_oa IS NULL THEN
    RAISE EXCEPTION 'ZALO_OA_NOT_CONFIGURED' USING ERRCODE = 'P0002';
  END IF;

  -- ============================================================================
  -- STEP 1: INSPECT SAME-COMMAND DELIVERY FIRST BEFORE MUTATING ANY TOKENS
  -- (Requirement 2 & 3: Token Stability & PENDING_FINALIZE Crash Recovery)
  -- ============================================================================
  SELECT d.* INTO v_row
  FROM public.zalo_outbound_deliveries d
  WHERE d.company_id = p_company_id AND d.channel = 'ZALO' AND d.command_id = p_command_id
  FOR UPDATE;

  IF v_row.id IS NOT NULL THEN
    -- Mismatch check
    IF v_row.conversation_id <> v_conv.id OR v_row.content_sha256 IS DISTINCT FROM p_content_sha256 THEN
      RETURN QUERY SELECT 'CONFLICT'::text, v_row.id, NULL::uuid, v_row.oa_id, v_row.recipient_zalo_uid,
                          v_row.customer_id, v_row.provider_msg_id, v_row.interaction_id;
      RETURN;
    END IF;

    -- Already finalized
    IF v_row.status = 'SENT' THEN
      RETURN QUERY SELECT 'ALREADY_SENT'::text, v_row.id, NULL::uuid, v_row.oa_id, v_row.recipient_zalo_uid,
                          v_row.customer_id, v_row.provider_msg_id, v_row.interaction_id;
      RETURN;
    END IF;

    -- PENDING_FINALIZE crash recovery (zero network, zero token rotation, allows Sale recovery)
    IF v_row.status = 'PROVIDER_SENT_PENDING_FINALIZE' THEN
      RETURN QUERY SELECT 'PENDING_FINALIZE'::text, v_row.id, v_row.claim_token, v_row.oa_id, v_row.recipient_zalo_uid,
                          v_row.customer_id, v_row.provider_msg_id, v_row.interaction_id;
      RETURN;
    END IF;

    -- Ambiguous / Uncertain
    IF v_row.status IN ('PROVIDER_UNCERTAIN', 'UNCERTAIN') THEN
      RETURN QUERY SELECT 'UNCERTAIN'::text, v_row.id, NULL::uuid, v_row.oa_id, v_row.recipient_zalo_uid,
                          v_row.customer_id, v_row.provider_msg_id, v_row.interaction_id;
      RETURN;
    END IF;

    -- In-flight SENDING
    IF v_row.status = 'SENDING' THEN
      IF v_row.lease_until > v_now THEN
        -- Live lease: return BUSY with ZERO mutation of tokens or window
        RETURN QUERY SELECT 'BUSY'::text, v_row.id, NULL::uuid, v_row.oa_id, v_row.recipient_zalo_uid,
                            v_row.customer_id, NULL::text, NULL::uuid;
        RETURN;
      ELSE
        -- Lease expired mid-flight: persist PROVIDER_UNCERTAIN on delivery and UNCERTAIN on window
        UPDATE public.zalo_outbound_deliveries
        SET status = 'PROVIDER_UNCERTAIN',
            error_code = 'LEASE_EXPIRED',
            error_message = 'Outbound delivery lease expired while in-flight',
            claim_token = NULL,
            lease_until = NULL,
            updated_at = v_now
        WHERE id = v_row.id;

        IF p_actor_type = 'SALE' THEN
          UPDATE public.response_sla_windows
          SET dispatch_state = 'UNCERTAIN',
              dispatch_fenced_until = NULL,
              updated_at = v_now
          WHERE company_id = p_company_id
            AND conversation_id = p_conversation_id
            AND state = 'OPEN'
            AND (dispatch_delivery_id = v_row.id OR dispatch_owner = 'SALE');
        END IF;

        RETURN QUERY SELECT 'UNCERTAIN'::text, v_row.id, NULL::uuid, v_row.oa_id, v_row.recipient_zalo_uid,
                            v_row.customer_id, NULL::text, NULL::uuid;
        RETURN;
      END IF;
    END IF;

    -- If status is FAILED: genuine retryable terminal state! We will mint a new token below.
    IF v_row.status <> 'FAILED' THEN
      RAISE EXCEPTION 'ZALO_OUTBOUND_COMMAND_CONFLICT' USING ERRCODE = '23505';
    END IF;
  END IF;

  -- ============================================================================
  -- STEP 2: RESPONSE SLA DISPATCH FENCING (NEW CLAIM OR RETRY OF FAILED)
  -- ============================================================================
  IF p_actor_type = 'SALE' THEN
    SELECT * INTO v_sla
    FROM public.response_sla_windows
    WHERE company_id = p_company_id
      AND conversation_id = p_conversation_id
      AND state = 'OPEN'
    FOR UPDATE;

    IF FOUND THEN
      -- A. If dispatch_state is already UNCERTAIN
      IF v_sla.dispatch_state = 'UNCERTAIN' THEN
        RETURN QUERY SELECT 'UNCERTAIN'::text, NULL::uuid, NULL::uuid, v_oa, v_conv.external_conversation_id,
                            v_conv.customer_id, NULL::text, NULL::uuid;
        RETURN;
      END IF;

      -- B. If AI currently owns dispatch
      IF v_sla.dispatch_owner = 'AI' OR v_sla.ai_dispatch_fenced_until IS NOT NULL THEN
        IF (v_sla.dispatch_state = 'DISPATCHING' OR v_sla.ai_dispatch_token IS NOT NULL) THEN
          IF coalesce(v_sla.dispatch_fenced_until, v_sla.ai_dispatch_fenced_until) > v_now THEN
            RAISE EXCEPTION 'AI_DISPATCH_FENCED' USING ERRCODE = '55000';
          ELSE
            -- AI lease expired: persist UNCERTAIN (Requirement 4: no raise after mutation)
            UPDATE public.response_sla_windows
            SET dispatch_state = 'UNCERTAIN',
                dispatch_fenced_until = NULL,
                ai_dispatch_fenced_until = NULL,
                updated_at = v_now
            WHERE id = v_sla.id;

            RETURN QUERY SELECT 'UNCERTAIN'::text, NULL::uuid, NULL::uuid, v_oa, v_conv.external_conversation_id,
                                v_conv.customer_id, NULL::text, NULL::uuid;
            RETURN;
          END IF;
        ELSIF v_sla.dispatch_state = 'PROVIDER_ACCEPTED' THEN
          RAISE EXCEPTION 'AI_ALREADY_RESPONDED' USING ERRCODE = '55000';
        END IF;
      END IF;

      -- C. If SALE currently owns dispatch (Sale-vs-Sale concurrency protection)
      IF v_sla.dispatch_owner = 'SALE' THEN
        IF v_sla.dispatch_state = 'DISPATCHING' THEN
          IF v_sla.dispatch_fenced_until > v_now THEN
            -- Active Sale dispatch lease exists on a DIFFERENT command (since same-command was checked in Step 1)
            RAISE EXCEPTION 'SALE_ALREADY_DISPATCHING' USING ERRCODE = '55000';
          ELSE
            -- Sale lease expired: persist UNCERTAIN (Requirement 4: no raise after mutation)
            UPDATE public.response_sla_windows
            SET dispatch_state = 'UNCERTAIN',
                dispatch_fenced_until = NULL,
                updated_at = v_now
            WHERE id = v_sla.id;

            RETURN QUERY SELECT 'UNCERTAIN'::text, NULL::uuid, NULL::uuid, v_oa, v_conv.external_conversation_id,
                                v_conv.customer_id, NULL::text, NULL::uuid;
            RETURN;
          END IF;
        ELSIF v_sla.dispatch_state = 'PROVIDER_ACCEPTED' THEN
          RAISE EXCEPTION 'SALE_ALREADY_RESPONDED' USING ERRCODE = '55000';
        END IF;
      END IF;

      -- Acquire SALE response dispatch ownership
      v_token := gen_random_uuid();
      UPDATE public.response_sla_windows
      SET
        dispatch_owner = 'SALE',
        dispatch_state = 'DISPATCHING',
        dispatch_token = v_token,
        dispatch_fenced_until = v_now + v_lease,
        updated_at = v_now
      WHERE id = v_sla.id;
    END IF;
  END IF;

  IF v_token IS NULL THEN
    v_token := gen_random_uuid();
  END IF;

  -- ============================================================================
  -- STEP 3: MINT/UPDATE DELIVERY AND BIND SLA DISPATCH_DELIVERY_ID
  -- ============================================================================
  IF v_row.id IS NOT NULL AND v_row.status = 'FAILED' THEN
    -- Retry FAILED: update delivery and shared window to the SAME new token atomically
    UPDATE public.zalo_outbound_deliveries
    SET claim_token = v_token,
        lease_until = v_now + v_lease,
        status = 'SENDING',
        attempts = attempts + 1,
        error_code = NULL,
        error_message = NULL,
        updated_at = v_now
    WHERE id = v_row.id;

    IF p_actor_type = 'SALE' AND v_sla.id IS NOT NULL THEN
      UPDATE public.response_sla_windows
      SET dispatch_delivery_id = v_row.id
      WHERE id = v_sla.id;
    END IF;

    RETURN QUERY SELECT 'CLAIMED'::text, v_row.id, v_token, v_row.oa_id, v_row.recipient_zalo_uid,
                        v_row.customer_id, NULL::text, NULL::uuid;
    RETURN;
  END IF;

  -- New delivery insertion
  INSERT INTO public.zalo_outbound_deliveries AS d (
    company_id, conversation_id, customer_id, recipient_zalo_uid, idempotency_key, content,
    status, attempts, command_id, channel, lease_until, oa_id, actor_type, actor_user_id,
    claim_token, content_sha256
  ) VALUES (
    p_company_id, v_conv.id, v_conv.customer_id, v_conv.external_conversation_id,
    'zalo_out:' || p_company_id::text || ':' || p_command_id, p_sanitized_content,
    'SENDING', 1, p_command_id, 'ZALO', v_now + v_lease, v_oa, p_actor_type, p_actor_user_id,
    v_token, p_content_sha256
  )
  RETURNING d.* INTO v_row;

  INSERT INTO private.zalo_outbound_payloads (delivery_id, company_id, raw_content)
  VALUES (v_row.id, p_company_id, p_raw_content);

  IF p_actor_type = 'SALE' AND v_sla.id IS NOT NULL THEN
    UPDATE public.response_sla_windows
    SET dispatch_delivery_id = v_row.id
    WHERE id = v_sla.id;
  END IF;

  RETURN QUERY SELECT 'CLAIMED'::text, v_row.id, v_token, v_oa, v_row.recipient_zalo_uid,
                      v_row.customer_id, NULL::text, NULL::uuid;
END;
$$;

CREATE OR REPLACE FUNCTION public.zalo_claim_outbound_delivery(
  p_company_id uuid,
  p_conversation_id uuid,
  p_command_id text,
  p_actor_type text,
  p_actor_user_id uuid,
  p_raw_content text,
  p_sanitized_content text,
  p_content_sha256 text,
  p_oa_id text DEFAULT NULL,
  p_lease_seconds integer DEFAULT 120
)
RETURNS TABLE (
  claim_status text,
  delivery_id uuid,
  claim_token uuid,
  oa_id text,
  recipient_zalo_uid text,
  customer_id uuid,
  provider_msg_id text,
  interaction_id uuid
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
#variable_conflict use_column
DECLARE
  v_conv public.conversations%ROWTYPE;
  v_row public.zalo_outbound_deliveries%ROWTYPE;
  v_sla public.response_sla_windows%ROWTYPE;
  v_oa text;
  v_now timestamptz := clock_timestamp();
  v_lease interval := make_interval(secs => greatest(coalesce(p_lease_seconds, 120), 10));
  v_token uuid;
BEGIN
  IF p_company_id IS NULL OR p_conversation_id IS NULL OR p_command_id IS NULL
     OR p_actor_type IS NULL OR p_raw_content IS NULL OR p_sanitized_content IS NULL
     OR p_content_sha256 IS NULL THEN
    RAISE EXCEPTION 'ZALO_OUTBOUND_INVALID_ARGUMENTS' USING ERRCODE = '22023';
  END IF;

  IF coalesce(btrim(p_command_id), '') = '' OR length(p_command_id) > 200 THEN
    RAISE EXCEPTION 'ZALO_OUTBOUND_COMMAND_ID_INVALID' USING ERRCODE = '22023';
  END IF;
  IF coalesce(btrim(p_raw_content), '') = '' OR coalesce(p_content_sha256, '') = '' THEN
    RAISE EXCEPTION 'ZALO_OUTBOUND_CONTENT_INVALID' USING ERRCODE = '22023';
  END IF;
  IF p_actor_type NOT IN ('SALE', 'AI', 'SYSTEM') THEN
    RAISE EXCEPTION 'ZALO_OUTBOUND_ACTOR_INVALID' USING ERRCODE = '22023';
  END IF;

  IF p_actor_type = 'SALE' THEN
    IF p_actor_user_id IS NULL OR NOT EXISTS (
      SELECT 1
      FROM public.company_members m
      JOIN public.user_profiles up ON up.id = m.user_id AND up.status = 'ACTIVE'
      WHERE m.company_id = p_company_id
        AND m.user_id = p_actor_user_id
        AND m.status = 'ACTIVE'
        AND m.role IN ('SALE', 'BOSS_ADMIN')
    ) THEN
      RAISE EXCEPTION 'ZALO_OUTBOUND_ACTOR_FORBIDDEN' USING ERRCODE = '42501';
    END IF;
  ELSIF p_actor_user_id IS NOT NULL THEN
    RAISE EXCEPTION 'ZALO_OUTBOUND_ACTOR_INVALID' USING ERRCODE = '22023';
  END IF;

  SELECT c.* INTO v_conv
  FROM public.conversations c
  WHERE c.id = p_conversation_id AND c.company_id = p_company_id AND c.channel = 'ZALO'
  FOR UPDATE;

  IF v_conv.id IS NULL THEN
    RAISE EXCEPTION 'ZALO_CONVERSATION_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  IF p_oa_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.zalo_oa_configs c
      WHERE c.company_id = p_company_id AND c.oa_id = p_oa_id AND c.status = 'ACTIVE'
    ) THEN
      RAISE EXCEPTION 'ZALO_OA_NOT_CONFIGURED' USING ERRCODE = 'P0002';
    END IF;
    v_oa := p_oa_id;
  ELSE
    v_oa := private.zalo_resolve_customer_oa(p_company_id, v_conv.customer_id);
  END IF;
  IF v_oa IS NULL THEN
    RAISE EXCEPTION 'ZALO_OA_NOT_CONFIGURED' USING ERRCODE = 'P0002';
  END IF;

  -- ============================================================================
  -- STEP 1: INSPECT SAME-COMMAND DELIVERY FIRST BEFORE MUTATING ANY TOKENS
  -- (Requirement 1, 2 & 3: Token Stability, Crash Recovery & UNCERTAIN Reconciliation)
  -- ============================================================================
  SELECT d.* INTO v_row
  FROM public.zalo_outbound_deliveries d
  WHERE d.company_id = p_company_id AND d.channel = 'ZALO' AND d.command_id = p_command_id
  FOR UPDATE;

  IF v_row.id IS NOT NULL THEN
    -- Mismatch check
    IF v_row.conversation_id <> v_conv.id OR v_row.content_sha256 IS DISTINCT FROM p_content_sha256 THEN
      RETURN QUERY SELECT 'CONFLICT'::text, v_row.id, NULL::uuid, v_row.oa_id, v_row.recipient_zalo_uid,
                          v_row.customer_id, v_row.provider_msg_id, v_row.interaction_id;
      RETURN;
    END IF;

    -- Already finalized
    IF v_row.status = 'SENT' THEN
      RETURN QUERY SELECT 'ALREADY_SENT'::text, v_row.id, NULL::uuid, v_row.oa_id, v_row.recipient_zalo_uid,
                          v_row.customer_id, v_row.provider_msg_id, v_row.interaction_id;
      RETURN;
    END IF;

    -- PENDING_FINALIZE crash recovery (zero network, zero token rotation, allows Sale recovery)
    IF v_row.status = 'PROVIDER_SENT_PENDING_FINALIZE' THEN
      RETURN QUERY SELECT 'PENDING_FINALIZE'::text, v_row.id, v_row.claim_token, v_row.oa_id, v_row.recipient_zalo_uid,
                          v_row.customer_id, v_row.provider_msg_id, v_row.interaction_id;
      RETURN;
    END IF;

    -- Ambiguous / Uncertain: preserve claim_token for late authoritative reconciliation (Requirement 1)
    IF v_row.status IN ('PROVIDER_UNCERTAIN', 'UNCERTAIN') THEN
      RETURN QUERY SELECT 'UNCERTAIN'::text, v_row.id, v_row.claim_token, v_row.oa_id, v_row.recipient_zalo_uid,
                          v_row.customer_id, v_row.provider_msg_id, v_row.interaction_id;
      RETURN;
    END IF;

    -- In-flight SENDING
    IF v_row.status = 'SENDING' THEN
      IF v_row.lease_until > v_now THEN
        -- Live lease: return BUSY with ZERO mutation of tokens or window
        RETURN QUERY SELECT 'BUSY'::text, v_row.id, NULL::uuid, v_row.oa_id, v_row.recipient_zalo_uid,
                            v_row.customer_id, NULL::text, NULL::uuid;
        RETURN;
      ELSE
        -- Lease expired mid-flight: persist PROVIDER_UNCERTAIN on delivery and UNCERTAIN on window
        -- PRESERVE claim_token for late authoritative reconciliation (Requirement 1)
        UPDATE public.zalo_outbound_deliveries
        SET status = 'PROVIDER_UNCERTAIN',
            error_code = 'LEASE_EXPIRED',
            error_message = 'Outbound delivery lease expired while in-flight',
            lease_until = NULL,
            updated_at = v_now
        WHERE id = v_row.id;

        IF p_actor_type = 'SALE' THEN
          -- EXACT OWNERSHIP PREDICATE: D1 must NEVER mutate window if window belongs to D2! (Requirement 2)
          UPDATE public.response_sla_windows
          SET dispatch_state = 'UNCERTAIN',
              dispatch_fenced_until = NULL,
              updated_at = v_now
          WHERE company_id = p_company_id
            AND conversation_id = p_conversation_id
            AND state = 'OPEN'
            AND dispatch_owner = 'SALE'
            AND dispatch_delivery_id = v_row.id
            AND dispatch_token = v_row.claim_token;
        END IF;

        RETURN QUERY SELECT 'UNCERTAIN'::text, v_row.id, v_row.claim_token, v_row.oa_id, v_row.recipient_zalo_uid,
                            v_row.customer_id, NULL::text, NULL::uuid;
        RETURN;
      END IF;
    END IF;

    -- If status is FAILED: genuine retryable terminal state! We will mint a new token below.
    IF v_row.status <> 'FAILED' THEN
      RAISE EXCEPTION 'ZALO_OUTBOUND_COMMAND_CONFLICT' USING ERRCODE = '23505';
    END IF;
  END IF;

  -- ============================================================================
  -- STEP 2: RESPONSE SLA DISPATCH FENCING (NEW CLAIM OR RETRY OF FAILED)
  -- ============================================================================
  IF p_actor_type = 'SALE' THEN
    SELECT * INTO v_sla
    FROM public.response_sla_windows
    WHERE company_id = p_company_id
      AND conversation_id = p_conversation_id
      AND state = 'OPEN'
    FOR UPDATE;

    IF FOUND THEN
      -- A. If dispatch_state is already UNCERTAIN
      IF v_sla.dispatch_state = 'UNCERTAIN' THEN
        RETURN QUERY SELECT 'UNCERTAIN'::text, NULL::uuid, NULL::uuid, v_oa, v_conv.external_conversation_id,
                            v_conv.customer_id, NULL::text, NULL::uuid;
        RETURN;
      END IF;

      -- B. If AI currently owns dispatch
      IF v_sla.dispatch_owner = 'AI' OR v_sla.ai_dispatch_fenced_until IS NOT NULL THEN
        IF (v_sla.dispatch_state = 'DISPATCHING' OR v_sla.ai_dispatch_token IS NOT NULL) THEN
          IF coalesce(v_sla.dispatch_fenced_until, v_sla.ai_dispatch_fenced_until) > v_now THEN
            RAISE EXCEPTION 'AI_DISPATCH_FENCED' USING ERRCODE = '55000';
          ELSE
            -- AI lease expired: persist UNCERTAIN without transaction rollback
            UPDATE public.response_sla_windows
            SET dispatch_state = 'UNCERTAIN',
                dispatch_fenced_until = NULL,
                ai_dispatch_fenced_until = NULL,
                updated_at = v_now
            WHERE id = v_sla.id;

            RETURN QUERY SELECT 'UNCERTAIN'::text, NULL::uuid, NULL::uuid, v_oa, v_conv.external_conversation_id,
                                v_conv.customer_id, NULL::text, NULL::uuid;
            RETURN;
          END IF;
        ELSIF v_sla.dispatch_state = 'PROVIDER_ACCEPTED' THEN
          RAISE EXCEPTION 'AI_ALREADY_RESPONDED' USING ERRCODE = '55000';
        END IF;
      END IF;

      -- C. If SALE currently owns dispatch (Sale-vs-Sale concurrency protection)
      IF v_sla.dispatch_owner = 'SALE' THEN
        IF v_sla.dispatch_state = 'DISPATCHING' THEN
          IF v_sla.dispatch_fenced_until > v_now THEN
            -- Active Sale dispatch lease exists on a DIFFERENT command (since same-command was checked in Step 1)
            RAISE EXCEPTION 'SALE_ALREADY_DISPATCHING' USING ERRCODE = '55000';
          ELSE
            -- Sale lease expired: persist UNCERTAIN without transaction rollback
            UPDATE public.response_sla_windows
            SET dispatch_state = 'UNCERTAIN',
                dispatch_fenced_until = NULL,
                updated_at = v_now
            WHERE id = v_sla.id;

            RETURN QUERY SELECT 'UNCERTAIN'::text, NULL::uuid, NULL::uuid, v_oa, v_conv.external_conversation_id,
                                v_conv.customer_id, NULL::text, NULL::uuid;
            RETURN;
          END IF;
        ELSIF v_sla.dispatch_state = 'PROVIDER_ACCEPTED' THEN
          RAISE EXCEPTION 'SALE_ALREADY_RESPONDED' USING ERRCODE = '55000';
        END IF;
      END IF;

      -- Acquire SALE response dispatch ownership
      v_token := gen_random_uuid();
      UPDATE public.response_sla_windows
      SET
        dispatch_owner = 'SALE',
        dispatch_state = 'DISPATCHING',
        dispatch_token = v_token,
        dispatch_fenced_until = v_now + v_lease,
        updated_at = v_now
      WHERE id = v_sla.id;
    END IF;
  END IF;

  IF v_token IS NULL THEN
    v_token := gen_random_uuid();
  END IF;

  -- ============================================================================
  -- STEP 3: MINT/UPDATE DELIVERY AND BIND SLA DISPATCH_DELIVERY_ID
  -- ============================================================================
  IF v_row.id IS NOT NULL AND v_row.status = 'FAILED' THEN
    -- Retry FAILED: update delivery and shared window to the SAME new token atomically
    UPDATE public.zalo_outbound_deliveries
    SET claim_token = v_token,
        lease_until = v_now + v_lease,
        status = 'SENDING',
        attempts = attempts + 1,
        error_code = NULL,
        error_message = NULL,
        updated_at = v_now
    WHERE id = v_row.id;

    IF p_actor_type = 'SALE' AND v_sla.id IS NOT NULL THEN
      UPDATE public.response_sla_windows
      SET dispatch_delivery_id = v_row.id
      WHERE id = v_sla.id;
    END IF;

    RETURN QUERY SELECT 'CLAIMED'::text, v_row.id, v_token, v_row.oa_id, v_row.recipient_zalo_uid,
                        v_row.customer_id, NULL::text, NULL::uuid;
    RETURN;
  END IF;

  -- New delivery insertion
  INSERT INTO public.zalo_outbound_deliveries AS d (
    company_id, conversation_id, customer_id, recipient_zalo_uid, idempotency_key, content,
    status, attempts, command_id, channel, lease_until, oa_id, actor_type, actor_user_id,
    claim_token, content_sha256
  ) VALUES (
    p_company_id, v_conv.id, v_conv.customer_id, v_conv.external_conversation_id,
    'zalo_out:' || p_company_id::text || ':' || p_command_id, p_sanitized_content,
    'SENDING', 1, p_command_id, 'ZALO', v_now + v_lease, v_oa, p_actor_type, p_actor_user_id,
    v_token, p_content_sha256
  )
  RETURNING d.* INTO v_row;

  INSERT INTO private.zalo_outbound_payloads (delivery_id, company_id, raw_content)
  VALUES (v_row.id, p_company_id, p_raw_content);

  IF p_actor_type = 'SALE' AND v_sla.id IS NOT NULL THEN
    UPDATE public.response_sla_windows
    SET dispatch_delivery_id = v_row.id
    WHERE id = v_sla.id;
  END IF;

  RETURN QUERY SELECT 'CLAIMED'::text, v_row.id, v_token, v_oa, v_row.recipient_zalo_uid,
                      v_row.customer_id, NULL::text, NULL::uuid;
END;
$$;

CREATE OR REPLACE FUNCTION public.update_order_deposit_rpc(
    p_company_id uuid,
    p_order_id uuid,
    p_actor_user_id uuid,
    p_deposit_amount numeric,
    p_idempotency_key text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
    v_order public.orders%ROWTYPE;
    v_existing_tx public.payment_transactions%ROWTYPE;
    v_tx_id uuid;
    v_collected_amount numeric;
    v_required_deposit numeric;
    v_deposit_threshold_reached boolean := false;
    v_payload_hash text;
    v_customer_previous_stage text;
BEGIN
    IF p_deposit_amount <= 0 THEN
        RAISE EXCEPTION 'Deposit amount must be greater than 0';
    END IF;

    -- Validate actor is BOSS_ADMIN in company
    IF NOT EXISTS (
        SELECT 1 FROM public.company_members cm
        JOIN public.user_profiles up ON cm.user_id = up.id
        WHERE cm.company_id = p_company_id
          AND cm.user_id = p_actor_user_id
          AND cm.status = 'ACTIVE'
          AND up.status = 'ACTIVE'
          AND cm.role = 'BOSS_ADMIN'
    ) THEN
        RAISE EXCEPTION 'UNAUTHORIZED_BOSS_REQUIRED';
    END IF;

    -- Concurrency: Advisory lock per (company_id, idempotency_key)
    PERFORM pg_advisory_xact_lock(hashtext(p_company_id::text || ':MANUAL:' || p_idempotency_key));

    -- Lock Order strictly scoped to company
    SELECT * INTO v_order
    FROM public.orders
    WHERE id = p_order_id AND company_id = p_company_id
    FOR UPDATE;

    IF v_order.id IS NULL THEN
        RAISE EXCEPTION 'RESOURCE_NOT_FOUND: Order not found';
    END IF;

    -- Check if idempotency key was already used
    SELECT * INTO v_existing_tx
    FROM public.payment_transactions
    WHERE company_id = p_company_id AND provider = 'MANUAL' AND provider_ref = p_idempotency_key;

    IF v_existing_tx.id IS NOT NULL THEN
        -- Section 2: Idempotency must strictly bind to matched_order_id and amount
        IF v_existing_tx.matched_order_id IS DISTINCT FROM p_order_id OR v_existing_tx.amount <> p_deposit_amount THEN
            RAISE EXCEPTION 'PAYMENT_IDEMPOTENCY_KEY_REUSED_WITH_DIFFERENT_PAYLOAD';
        END IF;

        SELECT collected_amount INTO v_collected_amount 
        FROM public.finance_summaries WHERE order_id = p_order_id;

        SELECT (pp.conditions->>'deposit_percentage')::numeric / 100 * v_order.final_amount
        INTO v_required_deposit
        FROM public.price_calculations pc
        JOIN public.pricing_policies pp ON pc.pricing_policy_id = pp.id
        WHERE pc.id = v_order.price_calculation_id;

        RETURN jsonb_build_object(
            'success', true,
            'status', 'ALREADY_PROCESSED',
            'orderId', v_existing_tx.matched_order_id,
            'transactionId', v_existing_tx.id,
            'depositConfirmed', (v_order.deposit_status IN ('CONFIRMED', 'DEPOSIT_CONFIRMED')),
            'collectedAmount', COALESCE(v_collected_amount, 0),
            'requiredDeposit', v_required_deposit
        );
    END IF;

    -- Compute deterministic payload hash for manual transaction
    v_payload_hash := encode(sha256(
        (p_company_id::text || ':MANUAL:' || p_idempotency_key || ':' || p_order_id::text || ':' || p_deposit_amount::text)::bytea
    ), 'hex');

    -- Insert manual transaction
    INSERT INTO public.payment_transactions (
        company_id, provider, provider_account, provider_ref, amount, occurred_at, transfer_content,
        matched_order_id, match_confidence, status, payload_hash, payment_reference
    ) VALUES (
        p_company_id, 'MANUAL', 'MANUAL_CASH', p_idempotency_key, p_deposit_amount, now(), 'MANUAL DEPOSIT CONFIRMATION',
        v_order.id, 1.0, 'MATCHED', v_payload_hash, v_order.payment_reference
    ) RETURNING id INTO v_tx_id;

    -- Update finance_summaries
    INSERT INTO public.finance_summaries (order_id, company_id, contract_value, collected_amount, receivable_amount)
    VALUES (v_order.id, p_company_id, v_order.final_amount, p_deposit_amount, GREATEST(v_order.final_amount - p_deposit_amount, 0))
    ON CONFLICT (order_id) DO UPDATE 
    SET 
        collected_amount = public.finance_summaries.collected_amount + EXCLUDED.collected_amount,
        receivable_amount = GREATEST(public.finance_summaries.contract_value - (public.finance_summaries.collected_amount + EXCLUDED.collected_amount), 0),
        updated_at = now();

    SELECT collected_amount INTO v_collected_amount 
    FROM public.finance_summaries WHERE order_id = p_order_id;

    SELECT (pp.conditions->>'deposit_percentage')::numeric / 100 * v_order.final_amount
    INTO v_required_deposit
    FROM public.price_calculations pc
    JOIN public.pricing_policies pp ON pc.pricing_policy_id = pp.id
    WHERE pc.id = v_order.price_calculation_id;

    IF v_required_deposit IS NULL THEN
        RAISE EXCEPTION 'POLICY_CONFIGURATION_ERROR';
    END IF;

    IF v_collected_amount >= v_required_deposit THEN
        v_deposit_threshold_reached := true;
        UPDATE public.orders
        SET 
            deposit_status = 'DEPOSIT_CONFIRMED',
            order_status = 'DEPOSIT_CONFIRMED',
            updated_at = now()
        WHERE id = p_order_id;

        -- Capture customer previous stage with row lock before updating
        SELECT stage INTO v_customer_previous_stage
        FROM public.customers
        WHERE id = v_order.customer_id AND company_id = p_company_id
        FOR UPDATE;

        -- Update customer stage to DEPOSIT_CONFIRMED only if in earlier stage
        IF v_customer_previous_stage IN ('LEAD_NEW', 'LEAD', 'SURVEY_SCHEDULED', 'SURVEY_COMPLETED', 'PRICE_CALCULATED', 'PRICE_OFFERED', 'NEGOTIATING', 'ORDER_CREATED') THEN
            UPDATE public.customers
            SET stage = 'DEPOSIT_CONFIRMED', updated_at = now()
            WHERE id = v_order.customer_id;

            INSERT INTO public.customer_stage_histories (
                company_id, customer_id, from_stage, to_stage, actor_type, changed_by_user_id, reason
            ) VALUES (
                p_company_id, v_order.customer_id, v_customer_previous_stage, 'DEPOSIT_CONFIRMED', 'USER', p_actor_user_id, 'Manual deposit confirmed by Boss Admin'
            );
        END IF;
    ELSE
        UPDATE public.orders
        SET deposit_status = 'DEPOSIT_PENDING', updated_at = now()
        WHERE id = p_order_id;
    END IF;

    -- Mandatory audit log
    INSERT INTO public.audit_logs (company_id, user_id, action, resource_type, resource_id, customer_id, result, metadata)
    VALUES (
        p_company_id, p_actor_user_id, 'MANUAL_DEPOSIT_CONFIRMED', 'orders', p_order_id, v_order.customer_id, 'SUCCESS',
        jsonb_build_object('amount', p_deposit_amount, 'collected_amount', v_collected_amount, 'required_deposit', v_required_deposit)
    );

    RETURN jsonb_build_object(
        'success', true,
        'status', 'MATCHED',
        'orderId', p_order_id,
        'transactionId', v_tx_id,
        'depositConfirmed', v_deposit_threshold_reached,
        'collectedAmount', v_collected_amount,
        'requiredDeposit', v_required_deposit
    );
END;
$$;

