CREATE FUNCTION public.zalo_assert_actor(p_company uuid,p_actor uuid,p_boss_only boolean DEFAULT false) RETURNS text
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE v_role text;
BEGIN
  SELECT m.role INTO v_role FROM public.company_members m
  JOIN public.user_profiles u ON u.id=m.user_id JOIN public.companies c ON c.id=m.company_id
  WHERE m.company_id=p_company AND m.user_id=p_actor AND m.status='ACTIVE' AND u.status='ACTIVE' AND c.status='ACTIVE';
  IF v_role IS NULL OR v_role NOT IN ('BOSS_ADMIN','SALE') OR (p_boss_only AND v_role<>'BOSS_ADMIN') THEN
    RAISE EXCEPTION 'ZALO_FORBIDDEN' USING ERRCODE='42501';
  END IF;
  RETURN v_role;
END $$;

CREATE FUNCTION public.zalo_manage_device(p_company uuid,p_actor uuid,p_device uuid,p_name text,p_hash text,p_staff uuid DEFAULT NULL,p_revoke boolean DEFAULT false)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
  PERFORM public.zalo_assert_actor(p_company,p_actor,true);
  IF p_revoke THEN
    UPDATE public.zalo_recording_devices SET active=false WHERE company_id=p_company AND id=p_device;
    IF NOT FOUND THEN RAISE EXCEPTION 'ZALO_NOT_FOUND'; END IF;
  ELSE
    IF p_staff IS NOT NULL THEN PERFORM public.zalo_assert_actor(p_company,p_staff); END IF;
    -- Re-registration never mutates an account context or silently reactivates a revoked credential.
    INSERT INTO public.zalo_recording_devices(id,company_id,staff_user_id,device_name,device_key_hash)
    VALUES(p_device,p_company,p_staff,p_name,p_hash);
  END IF;
  INSERT INTO public.audit_logs(company_id,user_id,action,resource_type,resource_id,result,metadata)
  VALUES(p_company,p_actor,CASE WHEN p_revoke THEN 'ZALO_DEVICE_REVOKED' ELSE 'ZALO_DEVICE_REGISTERED' END,'ZALO_DEVICE',p_device,'SUCCESS','{}');
  RETURN p_device;
END $$;

CREATE FUNCTION public.zalo_reserve_recording(p_device uuid,p_key_hash text,p_metadata jsonb,p_checksum text,p_bytes bigint,p_fingerprint text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE d public.zalo_recording_devices; c public.zalo_personal_calls; v_id uuid; v_lease uuid; v_name text;
BEGIN
  SELECT * INTO d FROM public.zalo_recording_devices WHERE id=p_device AND active AND device_key_hash=p_key_hash FOR SHARE;
  IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.companies WHERE id=d.company_id AND status='ACTIVE') THEN
    RAISE EXCEPTION 'ZALO_DEVICE_UNAUTHORIZED' USING ERRCODE='42501';
  END IF;
  IF d.staff_user_id IS NOT NULL THEN PERFORM public.zalo_assert_actor(d.company_id,d.staff_user_id); END IF;
  IF p_metadata->>'device_id' IS DISTINCT FROM p_device::text OR p_metadata->>'source' IS DISTINCT FROM 'ZALO_PERSONAL'
    OR (p_metadata->>'schema_version')::int IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'ZALO_INVALID_METADATA'; END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_device::text||':'||(p_metadata->>'local_call_id'),0));
  SELECT * INTO c FROM public.zalo_personal_calls WHERE company_id=d.company_id AND device_id=d.id AND local_call_id=(p_metadata->>'local_call_id')::uuid FOR UPDATE;
  IF FOUND THEN
    IF c.payload_fingerprint<>p_fingerprint OR c.recording_sha256<>p_checksum OR c.recording_bytes<>p_bytes THEN RAISE EXCEPTION 'ZALO_IDEMPOTENCY_CONFLICT'; END IF;
    IF c.recording_status='READY' THEN RETURN jsonb_build_object('duplicate',true,'call_id',c.id,'recording_id',c.id); END IF;
    IF c.upload_lease_until>now() THEN RETURN jsonb_build_object('in_progress',true); END IF;
    v_lease:=gen_random_uuid();
    UPDATE public.zalo_personal_calls SET upload_lease=v_lease,upload_lease_until=now()+interval '5 minutes' WHERE id=c.id;
    RETURN jsonb_build_object('duplicate',false,'call_id',c.id,'recording_id',c.id,'lease',v_lease,'path',c.recording_path);
  END IF;
  v_id:=gen_random_uuid(); v_lease:=gen_random_uuid(); v_name:=nullif(btrim(p_metadata->>'remote_display_name'),'');
  INSERT INTO public.zalo_personal_calls(id,company_id,device_id,local_call_id,staff_user_id,zalo_account_key,
    direction,remote_display_name,remote_display_name_normalized,identity_confidence,started_at,answered_at,ended_at,
    duration_seconds,agent_version,audio_validation,recording_path,recording_bytes,recording_sha256,payload_fingerprint,upload_lease,upload_lease_until)
  VALUES(v_id,d.company_id,d.id,(p_metadata->>'local_call_id')::uuid,d.staff_user_id,d.zalo_account_key,
    p_metadata->>'direction',v_name,public.zalo_normalize_display_name(v_name),CASE WHEN v_name IS NULL THEN 'UNKNOWN' ELSE 'MEDIUM' END,
    (p_metadata->>'started_at')::timestamptz,(p_metadata->>'answered_at')::timestamptz,(p_metadata->>'ended_at')::timestamptz,
    (p_metadata->>'duration_seconds')::double precision,p_metadata->>'agent_version',p_metadata->'audio_validation',
    'company/'||d.company_id||'/zalo/'||to_char((p_metadata->>'started_at')::timestamptz AT TIME ZONE 'UTC','YYYY/MM')||'/'||v_id||'.m4a',
    p_bytes,p_checksum,p_fingerprint,v_lease,now()+interval '5 minutes') RETURNING * INTO c;
  UPDATE public.zalo_recording_devices SET last_seen_at=now() WHERE id=d.id;
  RETURN jsonb_build_object('duplicate',false,'call_id',c.id,'recording_id',c.id,'lease',v_lease,'path',c.recording_path);
END $$;

CREATE FUNCTION public.zalo_finish_recording(p_device uuid,p_key_hash text,p_call uuid,p_lease uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE d public.zalo_recording_devices; c public.zalo_personal_calls; v_count int; v_customers int; v_customer uuid; v_ambiguous boolean;
BEGIN
  SELECT * INTO d FROM public.zalo_recording_devices WHERE id=p_device AND active AND device_key_hash=p_key_hash FOR SHARE;
  IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.companies WHERE id=d.company_id AND status='ACTIVE') THEN RAISE EXCEPTION 'ZALO_DEVICE_UNAUTHORIZED' USING ERRCODE='42501'; END IF;
  IF d.staff_user_id IS NOT NULL THEN PERFORM public.zalo_assert_actor(d.company_id,d.staff_user_id); END IF;
  SELECT * INTO c FROM public.zalo_personal_calls WHERE id=p_call AND company_id=d.company_id AND device_id=d.id FOR UPDATE;
  IF NOT FOUND OR c.upload_lease<>p_lease THEN RAISE EXCEPTION 'ZALO_LEASE_LOST'; END IF;
  IF c.recording_status='READY' THEN RETURN jsonb_build_object('call_id',c.id,'recording_id',c.id,'duplicate',true); END IF;
  IF NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='zalo-call-recordings' AND name=c.recording_path
    AND (metadata->>'size')::bigint=c.recording_bytes) THEN RAISE EXCEPTION 'ZALO_OBJECT_MISSING'; END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(c.company_id::text||c.zalo_account_key::text||c.remote_display_name_normalized,0));
  SELECT count(*),coalesce(bool_or(needs_confirmation),false) INTO v_count,v_ambiguous FROM public.zalo_customer_identity_mappings
    WHERE company_id=c.company_id AND zalo_account_key=c.zalo_account_key AND remote_display_name_normalized=c.remote_display_name_normalized AND active;
  SELECT count(*) INTO v_customers FROM public.customers WHERE company_id=c.company_id AND public.zalo_search_name(name)=public.zalo_search_name(c.remote_display_name_normalized);
  v_ambiguous:=v_ambiguous OR v_count>1 OR v_customers>1;
  IF v_count=1 AND NOT v_ambiguous AND c.remote_display_name_normalized<>'' THEN
    SELECT customer_id INTO v_customer FROM public.zalo_customer_identity_mappings WHERE company_id=c.company_id AND zalo_account_key=c.zalo_account_key AND remote_display_name_normalized=c.remote_display_name_normalized AND active;
  END IF;
  UPDATE public.zalo_personal_calls SET recording_status='READY',customer_id=v_customer,identity_ambiguous=v_ambiguous,
    matching_status=CASE WHEN v_customer IS NOT NULL THEN 'EXACT' WHEN v_count>0 OR v_customers>0 THEN 'SUGGESTED' ELSE 'UNMATCHED' END WHERE id=c.id;
  INSERT INTO public.audit_logs(company_id,user_id,action,resource_type,resource_id,result,metadata)
    VALUES(c.company_id,d.staff_user_id,'ZALO_RECORDING_READY','ZALO_CALL',c.id,'SUCCESS',jsonb_build_object('device_id',d.id));
  RETURN jsonb_build_object('call_id',c.id,'recording_id',c.id,'duplicate',false);
END $$;

CREATE FUNCTION public.zalo_link_customer(p_company uuid,p_actor uuid,p_call uuid,p_customer uuid DEFAULT NULL,p_new_name text DEFAULT NULL,p_remember boolean DEFAULT false)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE c public.zalo_personal_calls; v_role text; v_customer uuid:=p_customer; v_conflict boolean:=false;
BEGIN
  v_role:=public.zalo_assert_actor(p_company,p_actor);
  SELECT * INTO c FROM public.zalo_personal_calls WHERE id=p_call AND company_id=p_company FOR UPDATE;
  IF NOT FOUND OR c.recording_status<>'READY' OR (v_role='SALE' AND c.staff_user_id IS DISTINCT FROM p_actor) THEN RAISE EXCEPTION 'ZALO_FORBIDDEN' USING ERRCODE='42501'; END IF;
  -- A repeated create/link action returns the existing attachment, never creates a second customer.
  IF c.customer_id IS NOT NULL AND p_new_name IS NOT NULL THEN RETURN jsonb_build_object('customer_id',c.customer_id); END IF;
  IF v_customer IS NULL THEN
    IF p_new_name IS NULL OR length(btrim(p_new_name)) NOT BETWEEN 1 AND 200 THEN RAISE EXCEPTION 'ZALO_INVALID_CUSTOMER'; END IF;
    INSERT INTO public.customers(company_id,name,source,stage) VALUES(p_company,btrim(p_new_name),'ZALO','LEAD_NEW') RETURNING id INTO v_customer;
    INSERT INTO public.customer_stage_histories(company_id,customer_id,to_stage,actor_type,changed_by_user_id,reason)
      VALUES(p_company,v_customer,'LEAD_NEW','USER',p_actor,'Created from Zalo call confirmation');
  END IF;
  IF NOT EXISTS(SELECT 1 FROM public.customers WHERE company_id=p_company AND id=v_customer) THEN RAISE EXCEPTION 'ZALO_INVALID_CUSTOMER'; END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(c.company_id::text||c.zalo_account_key::text||c.remote_display_name_normalized,0));
  IF c.remote_display_name_normalized<>'' THEN
    SELECT EXISTS(SELECT 1 FROM public.zalo_customer_identity_mappings WHERE company_id=p_company AND zalo_account_key=c.zalo_account_key
      AND remote_display_name_normalized=c.remote_display_name_normalized AND active AND customer_id<>v_customer) INTO v_conflict;
    -- Any contradictory manual link poisons automatic reuse, even without "remember".
    IF v_conflict THEN UPDATE public.zalo_customer_identity_mappings SET needs_confirmation=true,updated_at=now()
      WHERE company_id=p_company AND zalo_account_key=c.zalo_account_key AND remote_display_name_normalized=c.remote_display_name_normalized; END IF;
    IF p_remember THEN
      INSERT INTO public.zalo_customer_identity_mappings(company_id,zalo_account_key,remote_display_name_original,remote_display_name_normalized,customer_id,confirmed_by,needs_confirmation)
      VALUES(p_company,c.zalo_account_key,c.remote_display_name,c.remote_display_name_normalized,v_customer,p_actor,v_conflict)
      ON CONFLICT(company_id,zalo_account_key,remote_display_name_normalized,customer_id) DO UPDATE
        SET active=true,confirmed_by=p_actor,confirmed_at=now(),updated_at=now(),needs_confirmation=public.zalo_customer_identity_mappings.needs_confirmation OR v_conflict;
    END IF;
  ELSIF p_remember THEN RAISE EXCEPTION 'ZALO_NAME_REQUIRED_FOR_MAPPING'; END IF;
  UPDATE public.zalo_personal_calls SET customer_id=v_customer,linked_by=p_actor,linked_at=now(),matching_status='EXACT',identity_ambiguous=identity_ambiguous OR v_conflict WHERE id=c.id;
  INSERT INTO public.audit_logs(company_id,user_id,action,resource_type,resource_id,customer_id,result,metadata)
    VALUES(p_company,p_actor,'ZALO_CUSTOMER_CONFIRMED','ZALO_CALL',c.id,v_customer,'SUCCESS',jsonb_build_object('remember',p_remember,'ambiguous',v_conflict));
  RETURN jsonb_build_object('customer_id',v_customer,'ambiguous',v_conflict);
END $$;

REVOKE ALL ON FUNCTION public.zalo_assert_actor(uuid,uuid,boolean),public.zalo_manage_device(uuid,uuid,uuid,text,text,uuid,boolean),
  public.zalo_reserve_recording(uuid,text,jsonb,text,bigint,text),public.zalo_finish_recording(uuid,text,uuid,uuid),
  public.zalo_link_customer(uuid,uuid,uuid,uuid,text,boolean) FROM PUBLIC,anon,authenticated;

GRANT EXECUTE ON FUNCTION public.zalo_assert_actor(uuid,uuid,boolean),public.zalo_manage_device(uuid,uuid,uuid,text,text,uuid,boolean),
  public.zalo_reserve_recording(uuid,text,jsonb,text,bigint,text),public.zalo_finish_recording(uuid,text,uuid,uuid),
  public.zalo_link_customer(uuid,uuid,uuid,uuid,text,boolean) TO service_role;

CREATE FUNCTION public.zalo_search_customers(p_company uuid,p_actor uuid,p_call uuid,p_search text DEFAULT NULL)
RETURNS TABLE(id uuid,name text,customer_code text) LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE c public.zalo_personal_calls; v_role text; v_search text;
BEGIN
  v_role:=public.zalo_assert_actor(p_company,p_actor);
  SELECT * INTO c FROM public.zalo_personal_calls WHERE company_id=p_company AND public.zalo_personal_calls.id=p_call;
  IF NOT FOUND OR (v_role='SALE' AND c.staff_user_id IS DISTINCT FROM p_actor) THEN RAISE EXCEPTION 'ZALO_FORBIDDEN' USING ERRCODE='42501'; END IF;
  v_search:=public.zalo_search_name(coalesce(p_search,c.remote_display_name));
  IF length(v_search)<2 OR length(v_search)>200 THEN RETURN; END IF;
  RETURN QUERY SELECT u.id,u.name,u.customer_code FROM public.customers u WHERE u.company_id=p_company AND
    (position(v_search IN public.zalo_search_name(u.name))>0 OR position(v_search IN lower(u.customer_code))>0 OR
     (p_search IS NULL AND EXISTS(SELECT 1 FROM public.zalo_customer_identity_mappings m WHERE m.company_id=p_company AND m.customer_id=u.id AND m.zalo_account_key=c.zalo_account_key AND m.remote_display_name_normalized=c.remote_display_name_normalized AND m.active)))
    ORDER BY u.name,u.id LIMIT 20;
END $$;

CREATE POLICY zalo_outbound_call_requests_read ON public.zalo_outbound_call_requests FOR SELECT TO authenticated USING (
  public.has_company_role(company_id, 'BOSS_ADMIN') OR
  (public.has_company_role(company_id, 'SALE') AND staff_user_id = auth.uid())
);

CREATE OR REPLACE FUNCTION public.zalo_create_outbound_call_request(
  p_company uuid,
  p_actor uuid,
  p_customer uuid,
  p_device uuid DEFAULT NULL
)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE
  v_role text;
  v_cust_name text;
  v_cust_phone text;
  v_mapping text;
  v_expected_name text;
  v_req_id uuid;
BEGIN
  v_role := public.zalo_assert_actor(p_company, p_actor);
  SELECT name INTO v_cust_name FROM public.customers WHERE company_id = p_company AND id = p_customer;
  IF v_cust_name IS NULL THEN RAISE EXCEPTION 'CUSTOMER_NOT_FOUND' USING ERRCODE='42501'; END IF;

  -- Look up customer phone from private contacts
  SELECT normalized_phone INTO v_cust_phone
  FROM private.customer_private_contacts
  WHERE company_id = p_company AND customer_id = p_customer
  ORDER BY is_verified DESC, created_at DESC LIMIT 1;

  -- Prefer confirmed Zalo mapping if available, otherwise CRM customer name
  SELECT remote_display_name_original INTO v_mapping
  FROM public.zalo_customer_identity_mappings
  WHERE company_id = p_company AND customer_id = p_customer AND active AND NOT needs_confirmation
  ORDER BY confirmed_at DESC LIMIT 1;

  v_expected_name := coalesce(v_mapping, v_cust_name);
  v_req_id := gen_random_uuid();

  INSERT INTO public.zalo_outbound_call_requests(
    id, company_id, customer_id, staff_user_id, device_id, phone_normalized, expected_display_name, status, expires_at
  )
  VALUES (
    v_req_id, p_company, p_customer, p_actor, p_device, nullif(btrim(v_cust_phone), ''), v_expected_name, 'PENDING', now() + interval '5 minutes'
  );

  INSERT INTO public.audit_logs(company_id, user_id, action, resource_type, resource_id, customer_id, result, metadata)
  VALUES(p_company, p_actor, 'ZALO_OUTBOUND_REQUEST_CREATED', 'ZALO_OUTBOUND_REQUEST', v_req_id, p_customer, 'SUCCESS',
    jsonb_build_object('expected_display_name', v_expected_name, 'device_id', p_device));

  RETURN jsonb_build_object(
    'request_id', v_req_id,
    'customer_id', p_customer,
    'customer_name', v_cust_name,
    'phone', nullif(btrim(v_cust_phone), ''),
    'expected_display_name', v_expected_name,
    'expires_at', (now() + interval '5 minutes')
  );
END $$;

CREATE OR REPLACE FUNCTION public.zalo_claim_outbound_call_request(
  p_device uuid,
  p_key_hash text,
  p_request_id uuid
)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE
  d public.zalo_recording_devices;
  req public.zalo_outbound_call_requests;
  v_cust_name text;
BEGIN
  SELECT * INTO d FROM public.zalo_recording_devices WHERE id = p_device AND active AND device_key_hash = p_key_hash FOR SHARE;
  IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.companies WHERE id = d.company_id AND status = 'ACTIVE') THEN
    RAISE EXCEPTION 'ZALO_DEVICE_UNAUTHORIZED' USING ERRCODE='42501';
  END IF;
  IF d.staff_user_id IS NOT NULL THEN PERFORM public.zalo_assert_actor(d.company_id, d.staff_user_id); END IF;

  SELECT * INTO req FROM public.zalo_outbound_call_requests WHERE id = p_request_id AND company_id = d.company_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ZALO_REQUEST_NOT_FOUND'; END IF;

  IF req.expires_at < now() THEN
    UPDATE public.zalo_outbound_call_requests SET status = 'EXPIRED' WHERE id = req.id;
    RAISE EXCEPTION 'ZALO_REQUEST_EXPIRED';
  END IF;

  IF req.status NOT IN ('PENDING', 'CLAIMED') OR (req.claimed_by_device_id IS NOT NULL AND req.claimed_by_device_id <> d.id) THEN
    RAISE EXCEPTION 'ZALO_REQUEST_ALREADY_CLAIMED';
  END IF;

  IF req.device_id IS NOT NULL AND req.device_id <> d.id THEN
    RAISE EXCEPTION 'ZALO_REQUEST_DEVICE_MISMATCH';
  END IF;

  UPDATE public.zalo_outbound_call_requests
  SET status = 'CLAIMED', claimed_at = coalesce(claimed_at, now()), claimed_by_device_id = d.id
  WHERE id = req.id;

  SELECT name INTO v_cust_name FROM public.customers WHERE company_id = d.company_id AND id = req.customer_id;

  RETURN jsonb_build_object(
    'id', req.id,
    'customer_id', req.customer_id,
    'customer_name', coalesce(v_cust_name, ''),
    'phone_normalized', req.phone_normalized,
    'expected_display_name', req.expected_display_name,
    'company_id', d.company_id,
    'staff_user_id', req.staff_user_id
  );
END $$;

CREATE OR REPLACE FUNCTION public.zalo_update_outbound_call_status(
  p_device uuid,
  p_key_hash text,
  p_request_id uuid,
  p_status text,
  p_failure_reason text DEFAULT NULL
)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE
  d public.zalo_recording_devices;
  req public.zalo_outbound_call_requests;
BEGIN
  SELECT * INTO d FROM public.zalo_recording_devices WHERE id = p_device AND active AND device_key_hash = p_key_hash FOR SHARE;
  IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.companies WHERE id = d.company_id AND status = 'ACTIVE') THEN
    RAISE EXCEPTION 'ZALO_DEVICE_UNAUTHORIZED' USING ERRCODE='42501';
  END IF;

  SELECT * INTO req FROM public.zalo_outbound_call_requests WHERE id = p_request_id AND company_id = d.company_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ZALO_REQUEST_NOT_FOUND'; END IF;

  IF req.claimed_by_device_id IS DISTINCT FROM d.id THEN
    RAISE EXCEPTION 'ZALO_REQUEST_DEVICE_MISMATCH';
  END IF;

  UPDATE public.zalo_outbound_call_requests
  SET status = p_status,
      failure_reason = p_failure_reason,
      completed_at = CASE WHEN p_status IN ('COMPLETED', 'FAILED', 'EXPIRED') THEN now() ELSE completed_at END
  WHERE id = req.id;

  RETURN jsonb_build_object('ok', true, 'status', p_status);
END $$;

CREATE OR REPLACE FUNCTION public.zalo_reserve_recording(
  p_device uuid,
  p_key_hash text,
  p_metadata jsonb,
  p_checksum text,
  p_bytes bigint,
  p_fingerprint text
)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE
  d public.zalo_recording_devices;
  c public.zalo_personal_calls;
  v_id uuid;
  v_lease uuid;
  v_name text;
  v_outbound_req uuid := null;
BEGIN
  SELECT * INTO d FROM public.zalo_recording_devices WHERE id=p_device AND active AND device_key_hash=p_key_hash FOR SHARE;
  IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.companies WHERE id=d.company_id AND status='ACTIVE') THEN
    RAISE EXCEPTION 'ZALO_DEVICE_UNAUTHORIZED' USING ERRCODE='42501';
  END IF;
  IF d.staff_user_id IS NOT NULL THEN PERFORM public.zalo_assert_actor(d.company_id,d.staff_user_id); END IF;
  IF p_metadata->>'device_id' IS DISTINCT FROM p_device::text OR p_metadata->>'source' IS DISTINCT FROM 'ZALO_PERSONAL'
    OR (p_metadata->>'schema_version')::int IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'ZALO_INVALID_METADATA'; END IF;

  -- Validate optional outbound request association
  IF p_metadata->>'crm_call_request_id' IS NOT NULL THEN
    BEGIN
      v_outbound_req := (p_metadata->>'crm_call_request_id')::uuid;
      IF NOT EXISTS(SELECT 1 FROM public.zalo_outbound_call_requests WHERE id = v_outbound_req AND company_id = d.company_id) THEN
        v_outbound_req := null;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_outbound_req := null;
    END;
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_device::text||':'||(p_metadata->>'local_call_id'),0));
  SELECT * INTO c FROM public.zalo_personal_calls WHERE company_id=d.company_id AND device_id=d.id AND local_call_id=(p_metadata->>'local_call_id')::uuid FOR UPDATE;
  IF FOUND THEN
    IF c.payload_fingerprint<>p_fingerprint OR c.recording_sha256<>p_checksum OR c.recording_bytes<>p_bytes THEN RAISE EXCEPTION 'ZALO_IDEMPOTENCY_CONFLICT'; END IF;
    IF c.recording_status='READY' THEN RETURN jsonb_build_object('duplicate',true,'call_id',c.id,'recording_id',c.id); END IF;
    IF c.upload_lease_until>now() THEN RETURN jsonb_build_object('in_progress',true); END IF;
    v_lease:=gen_random_uuid();
    UPDATE public.zalo_personal_calls SET upload_lease=v_lease,upload_lease_until=now()+interval '5 minutes' WHERE id=c.id;
    RETURN jsonb_build_object('duplicate',false,'call_id',c.id,'recording_id',c.id,'lease',v_lease,'path',c.recording_path);
  END IF;
  v_id:=gen_random_uuid(); v_lease:=gen_random_uuid(); v_name:=nullif(btrim(p_metadata->>'remote_display_name'),'');
  INSERT INTO public.zalo_personal_calls(id,company_id,device_id,local_call_id,staff_user_id,zalo_account_key,
    direction,remote_display_name,remote_display_name_normalized,identity_confidence,started_at,answered_at,ended_at,
    duration_seconds,agent_version,audio_validation,recording_path,recording_bytes,recording_sha256,payload_fingerprint,upload_lease,upload_lease_until,outbound_request_id)
  VALUES(v_id,d.company_id,d.id,(p_metadata->>'local_call_id')::uuid,d.staff_user_id,d.zalo_account_key,
    p_metadata->>'direction',v_name,public.zalo_normalize_display_name(v_name),CASE WHEN v_name IS NULL THEN 'UNKNOWN' ELSE 'MEDIUM' END,
    (p_metadata->>'started_at')::timestamptz,(p_metadata->>'answered_at')::timestamptz,(p_metadata->>'ended_at')::timestamptz,
    (p_metadata->>'duration_seconds')::double precision,p_metadata->>'agent_version',p_metadata->'audio_validation',
    'company/'||d.company_id||'/zalo/'||to_char((p_metadata->>'started_at')::timestamptz AT TIME ZONE 'UTC','YYYY/MM')||'/'||v_id||'.m4a',
    p_bytes,p_checksum,p_fingerprint,v_lease,now()+interval '5 minutes',v_outbound_req) RETURNING * INTO c;
  UPDATE public.zalo_recording_devices SET last_seen_at=now() WHERE id=d.id;
  RETURN jsonb_build_object('duplicate',false,'call_id',c.id,'recording_id',c.id,'lease',v_lease,'path',c.recording_path);
END $$;

CREATE OR REPLACE FUNCTION public.zalo_finish_recording(
  p_device uuid,
  p_key_hash text,
  p_call uuid,
  p_lease uuid
)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE
  d public.zalo_recording_devices;
  c public.zalo_personal_calls;
  v_count int := 0;
  v_customers int := 0;
  v_customer uuid := null;
  v_ambiguous boolean := false;
BEGIN
  SELECT * INTO d FROM public.zalo_recording_devices WHERE id=p_device AND active AND device_key_hash=p_key_hash FOR SHARE;
  IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.companies WHERE id=d.company_id AND status='ACTIVE') THEN RAISE EXCEPTION 'ZALO_DEVICE_UNAUTHORIZED' USING ERRCODE='42501'; END IF;
  IF d.staff_user_id IS NOT NULL THEN PERFORM public.zalo_assert_actor(d.company_id,d.staff_user_id); END IF;
  SELECT * INTO c FROM public.zalo_personal_calls WHERE id=p_call AND company_id=d.company_id AND device_id=d.id FOR UPDATE;
  IF NOT FOUND OR c.upload_lease<>p_lease THEN RAISE EXCEPTION 'ZALO_LEASE_LOST'; END IF;
  IF c.recording_status='READY' THEN RETURN jsonb_build_object('call_id',c.id,'recording_id',c.id,'duplicate',true); END IF;
  IF NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='zalo-call-recordings' AND name=c.recording_path
    AND (metadata->>'size')::bigint=c.recording_bytes) THEN RAISE EXCEPTION 'ZALO_OBJECT_MISSING'; END IF;

  -- 1. Direct attachment from verified outbound request (zero heuristic / zero ambiguity needed)
  IF c.outbound_request_id IS NOT NULL THEN
    SELECT customer_id INTO v_customer FROM public.zalo_outbound_call_requests
    WHERE id = c.outbound_request_id AND company_id = c.company_id;
    IF v_customer IS NOT NULL THEN
      UPDATE public.zalo_outbound_call_requests
      SET status = 'COMPLETED', completed_at = now()
      WHERE id = c.outbound_request_id;
      v_ambiguous := false;
      v_count := 1;
    END IF;
  END IF;

  -- 2. Fallback to confirmed mappings / name suggestions for inbound or standalone calls
  IF v_customer IS NULL THEN
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(c.company_id::text||c.zalo_account_key::text||c.remote_display_name_normalized,0));
    SELECT count(*),coalesce(bool_or(needs_confirmation),false) INTO v_count,v_ambiguous FROM public.zalo_customer_identity_mappings
      WHERE company_id=c.company_id AND zalo_account_key=c.zalo_account_key AND remote_display_name_normalized=c.remote_display_name_normalized AND active;
    SELECT count(*) INTO v_customers FROM public.customers WHERE company_id=c.company_id AND public.zalo_search_name(name)=public.zalo_search_name(c.remote_display_name_normalized);
    v_ambiguous:=v_ambiguous OR v_count>1 OR v_customers>1;
    IF v_count=1 AND NOT v_ambiguous AND c.remote_display_name_normalized<>'' THEN
      SELECT customer_id INTO v_customer FROM public.zalo_customer_identity_mappings WHERE company_id=c.company_id AND zalo_account_key=c.zalo_account_key AND remote_display_name_normalized=c.remote_display_name_normalized AND active;
    END IF;
  END IF;

  UPDATE public.zalo_personal_calls SET recording_status='READY',customer_id=v_customer,identity_ambiguous=v_ambiguous,
    matching_status=CASE WHEN v_customer IS NOT NULL THEN 'EXACT' WHEN v_count>0 OR v_customers>0 THEN 'SUGGESTED' ELSE 'UNMATCHED' END WHERE id=c.id;
  INSERT INTO public.audit_logs(company_id,user_id,action,resource_type,resource_id,customer_id,result,metadata)
    VALUES(c.company_id,d.staff_user_id,'ZALO_RECORDING_READY','ZALO_CALL',c.id,v_customer,'SUCCESS',
      jsonb_build_object('device_id',d.id,'outbound_request_id',c.outbound_request_id));
  RETURN jsonb_build_object('call_id',c.id,'recording_id',c.id,'duplicate',false);
END $$;

REVOKE ALL ON FUNCTION public.zalo_create_outbound_call_request(uuid,uuid,uuid,uuid),
  public.zalo_claim_outbound_call_request(uuid,text,uuid),
  public.zalo_update_outbound_call_status(uuid,text,uuid,text,text) FROM PUBLIC,anon,authenticated;

GRANT EXECUTE ON FUNCTION public.zalo_create_outbound_call_request(uuid,uuid,uuid,uuid),
  public.zalo_claim_outbound_call_request(uuid,text,uuid),
  public.zalo_update_outbound_call_status(uuid,text,uuid,text,text) TO service_role;

CREATE OR REPLACE FUNCTION public.zalo_claim_outbound_call_request(
  p_device uuid,
  p_key_hash text,
  p_request_id uuid
)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE
  d public.zalo_recording_devices;
  req public.zalo_outbound_call_requests;
  v_cust_name text;
  v_req_role text;
BEGIN
  SELECT * INTO d FROM public.zalo_recording_devices WHERE id = p_device AND active AND device_key_hash = p_key_hash FOR SHARE;
  IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.companies WHERE id = d.company_id AND status = 'ACTIVE') THEN
    RAISE EXCEPTION 'ZALO_DEVICE_UNAUTHORIZED' USING ERRCODE='42501';
  END IF;

  SELECT * INTO req FROM public.zalo_outbound_call_requests WHERE id = p_request_id AND company_id = d.company_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ZALO_REQUEST_NOT_FOUND';
  END IF;

  -- Requesting actor must have active role in company
  v_req_role := public.zalo_assert_actor(d.company_id, req.staff_user_id);

  -- Validate device staff if assigned; Boss may target any staff device if explicitly assigned to this device
  IF d.staff_user_id IS NOT NULL THEN
    PERFORM public.zalo_assert_actor(d.company_id, d.staff_user_id);
    IF d.staff_user_id <> req.staff_user_id THEN
      IF v_req_role <> 'BOSS_ADMIN' OR req.device_id IS DISTINCT FROM d.id THEN
        RAISE EXCEPTION 'ZALO_REQUEST_STAFF_MISMATCH';
      END IF;
    END IF;
  END IF;

  -- Device assignment check
  IF req.device_id IS NOT NULL AND req.device_id <> d.id THEN
    RAISE EXCEPTION 'ZALO_REQUEST_DEVICE_MISMATCH';
  END IF;

  -- Expiry check at claim time
  IF req.expires_at < now() THEN
    RAISE EXCEPTION 'ZALO_REQUEST_EXPIRED';
  END IF;

  -- Claim atomic once: request must be in PENDING status. Same-device replay rejected.
  IF req.status <> 'PENDING' THEN
    RAISE EXCEPTION 'ZALO_REQUEST_ALREADY_CLAIMED';
  END IF;

  UPDATE public.zalo_outbound_call_requests
  SET status = 'CLAIMED', claimed_at = now(), claimed_by_device_id = d.id
  WHERE id = req.id;

  SELECT name INTO v_cust_name FROM public.customers WHERE company_id = d.company_id AND id = req.customer_id;

  -- Return payload to authenticated claiming device including phone_normalized for dialing
  RETURN jsonb_build_object(
    'id', req.id,
    'customer_id', req.customer_id,
    'customer_name', coalesce(v_cust_name, ''),
    'phone_normalized', req.phone_normalized,
    'expected_display_name', req.expected_display_name,
    'company_id', d.company_id,
    'staff_user_id', req.staff_user_id
  );
END $$;

CREATE OR REPLACE FUNCTION public.zalo_update_outbound_call_status(
  p_device uuid,
  p_key_hash text,
  p_request_id uuid,
  p_status text,
  p_failure_reason text DEFAULT NULL
)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE
  d public.zalo_recording_devices;
  req public.zalo_outbound_call_requests;
  v_req_role text;
BEGIN
  SELECT * INTO d FROM public.zalo_recording_devices WHERE id = p_device AND active AND device_key_hash = p_key_hash FOR SHARE;
  IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.companies WHERE id = d.company_id AND status = 'ACTIVE') THEN
    RAISE EXCEPTION 'ZALO_DEVICE_UNAUTHORIZED' USING ERRCODE='42501';
  END IF;

  SELECT * INTO req FROM public.zalo_outbound_call_requests WHERE id = p_request_id AND company_id = d.company_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ZALO_REQUEST_NOT_FOUND';
  END IF;

  -- Must be claimed by this exact device
  IF req.claimed_by_device_id IS DISTINCT FROM d.id THEN
    RAISE EXCEPTION 'ZALO_REQUEST_DEVICE_MISMATCH';
  END IF;

  v_req_role := public.zalo_assert_actor(d.company_id, req.staff_user_id);
  IF d.staff_user_id IS NOT NULL THEN
    PERFORM public.zalo_assert_actor(d.company_id, d.staff_user_id);
    IF d.staff_user_id <> req.staff_user_id THEN
      IF v_req_role <> 'BOSS_ADMIN' OR req.device_id IS DISTINCT FROM d.id THEN
        RAISE EXCEPTION 'ZALO_REQUEST_STAFF_MISMATCH';
      END IF;
    END IF;
  END IF;

  -- Client COMPLETED forbidden always; trusted recording finalization owns it
  IF p_status = 'COMPLETED' THEN
    RAISE EXCEPTION 'ZALO_STATUS_INVALID';
  END IF;

  -- Allowed statuses for agent update
  IF p_status NOT IN ('OPENING_ZALO', 'CONTACT_VERIFIED', 'CALL_TRIGGERED', 'CALL_DETECTED', 'FAILED') THEN
    RAISE EXCEPTION 'ZALO_STATUS_INVALID';
  END IF;

  -- Terminal states are immutable
  IF req.status IN ('COMPLETED', 'FAILED', 'EXPIRED') THEN
    IF req.status = p_status THEN
      RETURN jsonb_build_object('ok', true, 'status', req.status);
    END IF;
    RAISE EXCEPTION 'ZALO_STATUS_TERMINAL';
  END IF;

  -- Idempotency check for same status
  IF req.status = p_status THEN
    RETURN jsonb_build_object('ok', true, 'status', req.status);
  END IF;

  -- FAILED allowed from any non-terminal state
  IF p_status = 'FAILED' THEN
    UPDATE public.zalo_outbound_call_requests
    SET status = 'FAILED',
        failure_reason = p_failure_reason,
        completed_at = now()
    WHERE id = req.id;
    RETURN jsonb_build_object('ok', true, 'status', 'FAILED');
  END IF;

  -- Harmless async reordering: late CALL_TRIGGERED arriving when CALL_DETECTED already stored
  IF req.status = 'CALL_DETECTED' AND p_status = 'CALL_TRIGGERED' THEN
    RETURN jsonb_build_object('ok', true, 'status', req.status);
  END IF;

  -- Activation phase expiry check: non-established phases cannot advance past expires_at
  IF req.status IN ('CLAIMED', 'OPENING_ZALO', 'CONTACT_VERIFIED') THEN
    IF req.expires_at < now() THEN
      RAISE EXCEPTION 'ZALO_REQUEST_EXPIRED';
    END IF;
  END IF;

  -- Legal transitions:
  -- CLAIMED -> OPENING_ZALO
  -- OPENING_ZALO -> CONTACT_VERIFIED
  -- CONTACT_VERIFIED -> CALL_TRIGGERED
  -- CONTACT_VERIFIED -> CALL_DETECTED (observed call arrives before trigger ACK)
  -- CALL_TRIGGERED -> CALL_DETECTED
  IF NOT (
    (req.status = 'CLAIMED' AND p_status = 'OPENING_ZALO') OR
    (req.status = 'OPENING_ZALO' AND p_status = 'CONTACT_VERIFIED') OR
    (req.status = 'CONTACT_VERIFIED' AND p_status IN ('CALL_TRIGGERED', 'CALL_DETECTED')) OR
    (req.status = 'CALL_TRIGGERED' AND p_status = 'CALL_DETECTED')
  ) THEN
    RAISE EXCEPTION 'ZALO_STATUS_TRANSITION_INVALID';
  END IF;

  UPDATE public.zalo_outbound_call_requests
  SET status = p_status,
      failure_reason = NULL
  WHERE id = req.id;

  RETURN jsonb_build_object('ok', true, 'status', p_status);
END $$;

CREATE OR REPLACE FUNCTION public.zalo_reserve_recording(
  p_device uuid,
  p_key_hash text,
  p_metadata jsonb,
  p_checksum text,
  p_bytes bigint,
  p_fingerprint text
)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE
  d public.zalo_recording_devices;
  c public.zalo_personal_calls;
  req public.zalo_outbound_call_requests;
  v_id uuid;
  v_lease uuid;
  v_name text;
  v_outbound_req uuid := null;
  v_started_at timestamptz;
  v_req_role text;
  v_recording_staff uuid;
  v_call_found boolean := false;
BEGIN
  -- 1. Take device FOR UPDATE as FIRST row lock
  SELECT * INTO d FROM public.zalo_recording_devices
  WHERE id = p_device AND active AND device_key_hash = p_key_hash
  FOR UPDATE;

  IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.companies WHERE id = d.company_id AND status = 'ACTIVE') THEN
    RAISE EXCEPTION 'ZALO_DEVICE_UNAUTHORIZED' USING ERRCODE='42501';
  END IF;

  IF d.staff_user_id IS NOT NULL THEN
    PERFORM public.zalo_assert_actor(d.company_id, d.staff_user_id);
  END IF;

  IF p_metadata->>'device_id' IS DISTINCT FROM p_device::text
    OR p_metadata->>'source' IS DISTINCT FROM 'ZALO_PERSONAL'
    OR (p_metadata->>'schema_version')::int IS DISTINCT FROM 1 THEN
    RAISE EXCEPTION 'ZALO_INVALID_METADATA';
  END IF;

  -- 2. Parse explicit request UUID and direction
  IF p_metadata->>'crm_call_request_id' IS NOT NULL THEN
    BEGIN
      v_outbound_req := (p_metadata->>'crm_call_request_id')::uuid;
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'ZALO_REQUEST_INVALID';
    END;

    IF p_metadata->>'direction' IS DISTINCT FROM 'OUTBOUND' THEN
      RAISE EXCEPTION 'ZALO_REQUEST_DIRECTION_MISMATCH';
    END IF;
  END IF;

  -- 3. Lock call row following consistent order: Device -> Call -> Request
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_device::text||':'||(p_metadata->>'local_call_id'), 0));

  SELECT * INTO c FROM public.zalo_personal_calls
  WHERE company_id = d.company_id AND device_id = d.id AND local_call_id = (p_metadata->>'local_call_id')::uuid
  FOR UPDATE;

  IF FOUND THEN
    v_call_found := true;
    IF c.outbound_request_id IS DISTINCT FROM v_outbound_req THEN
      RAISE EXCEPTION 'ZALO_IDEMPOTENCY_CONFLICT';
    END IF;
    IF c.payload_fingerprint <> p_fingerprint OR c.recording_sha256 <> p_checksum OR c.recording_bytes <> p_bytes THEN
      RAISE EXCEPTION 'ZALO_IDEMPOTENCY_CONFLICT';
    END IF;

    -- Exact READY replay returns duplicate even if request is COMPLETED
    IF c.recording_status = 'READY' THEN
      RETURN jsonb_build_object('duplicate', true, 'call_id', c.id, 'recording_id', c.id);
    END IF;
  END IF;

  -- 4. Validate request BEFORE in_progress or new lease return
  IF v_outbound_req IS NOT NULL THEN
    SELECT * INTO req FROM public.zalo_outbound_call_requests
    WHERE id = v_outbound_req AND company_id = d.company_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'ZALO_REQUEST_NOT_FOUND';
    END IF;

    v_req_role := public.zalo_assert_actor(d.company_id, req.staff_user_id);

    IF req.claimed_at IS NULL OR req.claimed_by_device_id IS NULL THEN
      RAISE EXCEPTION 'ZALO_REQUEST_UNCLAIMED';
    END IF;

    IF req.claimed_by_device_id <> d.id THEN
      RAISE EXCEPTION 'ZALO_REQUEST_DEVICE_MISMATCH';
    END IF;

    IF req.device_id IS NOT NULL AND req.device_id <> d.id THEN
      RAISE EXCEPTION 'ZALO_REQUEST_DEVICE_MISMATCH';
    END IF;

    IF d.staff_user_id IS NOT NULL AND d.staff_user_id <> req.staff_user_id THEN
      IF v_req_role <> 'BOSS_ADMIN' OR req.device_id IS DISTINCT FROM d.id THEN
        RAISE EXCEPTION 'ZALO_REQUEST_STAFF_MISMATCH';
      END IF;
    END IF;

    IF req.status = 'FAILED' THEN
      RAISE EXCEPTION 'ZALO_REQUEST_FAILED';
    END IF;
    IF req.status = 'EXPIRED' THEN
      RAISE EXCEPTION 'ZALO_REQUEST_EXPIRED';
    END IF;
    IF req.status = 'COMPLETED' THEN
      RAISE EXCEPTION 'ZALO_REQUEST_REUSED';
    END IF;
    IF req.status NOT IN ('CALL_TRIGGERED', 'CALL_DETECTED') THEN
      RAISE EXCEPTION 'ZALO_REQUEST_INVALID_STATE';
    END IF;

    IF EXISTS(
      SELECT 1 FROM public.zalo_personal_calls
      WHERE outbound_request_id = v_outbound_req
        AND (device_id <> d.id OR local_call_id <> (p_metadata->>'local_call_id')::uuid)
    ) THEN
      RAISE EXCEPTION 'ZALO_REQUEST_REUSED';
    END IF;

    v_started_at := (p_metadata->>'started_at')::timestamptz;
    IF v_started_at < (req.created_at - interval '30 seconds') OR v_started_at < (req.claimed_at - interval '30 seconds') THEN
      RAISE EXCEPTION 'ZALO_REQUEST_TIMING_INVALID';
    END IF;
    IF v_started_at > req.expires_at THEN
      RAISE EXCEPTION 'ZALO_REQUEST_EXPIRED';
    END IF;
  END IF;

  -- 5. Existing non-READY call: verify stored fields before in_progress / lease grant
  IF v_call_found THEN
    IF v_outbound_req IS NOT NULL THEN
      IF c.direction IS DISTINCT FROM 'OUTBOUND' THEN
        RAISE EXCEPTION 'ZALO_REQUEST_DIRECTION_MISMATCH';
      END IF;
      IF c.started_at < (req.created_at - interval '30 seconds') OR c.started_at < (req.claimed_at - interval '30 seconds') THEN
        RAISE EXCEPTION 'ZALO_REQUEST_TIMING_INVALID';
      END IF;
      IF c.started_at > req.expires_at THEN
        RAISE EXCEPTION 'ZALO_REQUEST_EXPIRED';
      END IF;
    END IF;

    IF c.upload_lease_until > now() THEN
      RETURN jsonb_build_object('in_progress', true);
    END IF;

    v_lease := gen_random_uuid();
    UPDATE public.zalo_personal_calls
    SET upload_lease = v_lease, upload_lease_until = now() + interval '5 minutes'
    WHERE id = c.id;

    UPDATE public.zalo_recording_devices SET last_seen_at = now() WHERE id = d.id;

    RETURN jsonb_build_object('duplicate', false, 'call_id', c.id, 'recording_id', c.id, 'lease', v_lease, 'path', c.recording_path);
  END IF;

  -- 6. New call creation
  v_recording_staff := coalesce(d.staff_user_id, CASE WHEN v_outbound_req IS NOT NULL THEN req.staff_user_id ELSE NULL END);
  v_id := gen_random_uuid();
  v_lease := gen_random_uuid();
  v_name := nullif(btrim(p_metadata->>'remote_display_name'), '');

  INSERT INTO public.zalo_personal_calls(
    id, company_id, device_id, local_call_id, staff_user_id, zalo_account_key,
    direction, remote_display_name, remote_display_name_normalized, identity_confidence,
    started_at, answered_at, ended_at, duration_seconds, agent_version, audio_validation,
    recording_path, recording_bytes, recording_sha256, payload_fingerprint,
    upload_lease, upload_lease_until, outbound_request_id
  )
  VALUES (
    v_id, d.company_id, d.id, (p_metadata->>'local_call_id')::uuid, v_recording_staff, d.zalo_account_key,
    p_metadata->>'direction', v_name, public.zalo_normalize_display_name(v_name),
    CASE WHEN v_name IS NULL THEN 'UNKNOWN' ELSE 'MEDIUM' END,
    (p_metadata->>'started_at')::timestamptz, (p_metadata->>'answered_at')::timestamptz, (p_metadata->>'ended_at')::timestamptz,
    (p_metadata->>'duration_seconds')::double precision, p_metadata->>'agent_version', p_metadata->'audio_validation',
    'company/'||d.company_id||'/zalo/'||to_char((p_metadata->>'started_at')::timestamptz AT TIME ZONE 'UTC', 'YYYY/MM')||'/'||v_id||'.m4a',
    p_bytes, p_checksum, p_fingerprint,
    v_lease, now() + interval '5 minutes', v_outbound_req
  ) RETURNING * INTO c;

  UPDATE public.zalo_recording_devices SET last_seen_at = now() WHERE id = d.id;

  RETURN jsonb_build_object('duplicate', false, 'call_id', c.id, 'recording_id', c.id, 'lease', v_lease, 'path', c.recording_path);
END $$;

CREATE OR REPLACE FUNCTION public.zalo_finish_recording(
  p_device uuid,
  p_key_hash text,
  p_call uuid,
  p_lease uuid
)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE
  d public.zalo_recording_devices;
  c public.zalo_personal_calls;
  req public.zalo_outbound_call_requests;
  v_count int := 0;
  v_customers int := 0;
  v_customer uuid := null;
  v_ambiguous boolean := false;
  v_req_role text;
  v_final_staff uuid;
BEGIN
  -- 1. Take device FOR UPDATE as FIRST row lock
  SELECT * INTO d FROM public.zalo_recording_devices
  WHERE id = p_device AND active AND device_key_hash = p_key_hash
  FOR UPDATE;

  IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.companies WHERE id = d.company_id AND status = 'ACTIVE') THEN
    RAISE EXCEPTION 'ZALO_DEVICE_UNAUTHORIZED' USING ERRCODE='42501';
  END IF;

  IF d.staff_user_id IS NOT NULL THEN
    PERFORM public.zalo_assert_actor(d.company_id, d.staff_user_id);
  END IF;

  -- 2. Lock call row FOR UPDATE
  SELECT * INTO c FROM public.zalo_personal_calls
  WHERE id = p_call AND company_id = d.company_id AND device_id = d.id
  FOR UPDATE;

  IF NOT FOUND OR c.upload_lease <> p_lease THEN
    RAISE EXCEPTION 'ZALO_LEASE_LOST';
  END IF;

  IF c.recording_status = 'READY' THEN
    RETURN jsonb_build_object('call_id', c.id, 'recording_id', c.id, 'duplicate', true);
  END IF;

  IF NOT EXISTS(
    SELECT 1 FROM storage.objects
    WHERE bucket_id = 'zalo-call-recordings'
      AND name = c.recording_path
      AND (metadata->>'size')::bigint = c.recording_bytes
  ) THEN
    RAISE EXCEPTION 'ZALO_OBJECT_MISSING';
  END IF;

  v_final_staff := c.staff_user_id;

  -- 3. Direct attachment from verified outbound request
  IF c.outbound_request_id IS NOT NULL THEN
    SELECT * INTO req FROM public.zalo_outbound_call_requests
    WHERE id = c.outbound_request_id AND company_id = c.company_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'ZALO_REQUEST_NOT_FOUND';
    END IF;

    IF c.direction IS DISTINCT FROM 'OUTBOUND' THEN
      RAISE EXCEPTION 'ZALO_REQUEST_DIRECTION_MISMATCH';
    END IF;

    IF req.claimed_at IS NULL OR req.claimed_by_device_id IS NULL THEN
      RAISE EXCEPTION 'ZALO_REQUEST_UNCLAIMED';
    END IF;

    IF req.claimed_by_device_id <> d.id THEN
      RAISE EXCEPTION 'ZALO_REQUEST_DEVICE_MISMATCH';
    END IF;

    IF req.device_id IS NOT NULL AND req.device_id <> d.id THEN
      RAISE EXCEPTION 'ZALO_REQUEST_DEVICE_MISMATCH';
    END IF;

    v_req_role := public.zalo_assert_actor(c.company_id, req.staff_user_id);
    IF d.staff_user_id IS NOT NULL THEN
      PERFORM public.zalo_assert_actor(d.company_id, d.staff_user_id);
      IF d.staff_user_id <> req.staff_user_id THEN
        IF v_req_role <> 'BOSS_ADMIN' OR req.device_id IS DISTINCT FROM d.id THEN
          RAISE EXCEPTION 'ZALO_REQUEST_STAFF_MISMATCH';
        END IF;
      END IF;
    END IF;

    IF req.status = 'FAILED' THEN
      RAISE EXCEPTION 'ZALO_REQUEST_FAILED';
    END IF;
    IF req.status = 'EXPIRED' THEN
      RAISE EXCEPTION 'ZALO_REQUEST_EXPIRED';
    END IF;
    IF req.status = 'COMPLETED' THEN
      RAISE EXCEPTION 'ZALO_REQUEST_REUSED';
    END IF;
    IF req.status NOT IN ('CALL_TRIGGERED', 'CALL_DETECTED') THEN
      RAISE EXCEPTION 'ZALO_REQUEST_INVALID_STATE';
    END IF;

    IF c.started_at < (req.created_at - interval '30 seconds') OR c.started_at < (req.claimed_at - interval '30 seconds') THEN
      RAISE EXCEPTION 'ZALO_REQUEST_TIMING_INVALID';
    END IF;
    IF c.started_at > req.expires_at THEN
      RAISE EXCEPTION 'ZALO_REQUEST_EXPIRED';
    END IF;

    IF EXISTS(
      SELECT 1 FROM public.zalo_personal_calls
      WHERE outbound_request_id = req.id
        AND id <> c.id
    ) THEN
      RAISE EXCEPTION 'ZALO_REQUEST_REUSED';
    END IF;

    IF NOT EXISTS(SELECT 1 FROM public.customers WHERE id = req.customer_id AND company_id = c.company_id) THEN
      RAISE EXCEPTION 'CUSTOMER_NOT_FOUND';
    END IF;

    v_customer := req.customer_id;

    -- Fill legacy shared outbound staff ONLY when device staff is null and call staff is null
    IF v_final_staff IS NULL AND d.staff_user_id IS NULL THEN
      v_final_staff := req.staff_user_id;
    END IF;

    UPDATE public.zalo_outbound_call_requests
    SET status = 'COMPLETED', completed_at = now()
    WHERE id = req.id;

    v_ambiguous := false;
    v_count := 1;
  END IF;

  -- 4. Fallback to confirmed mappings / name suggestions for inbound or standalone calls
  IF v_customer IS NULL THEN
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(c.company_id::text||c.zalo_account_key::text||c.remote_display_name_normalized, 0));
    SELECT count(*), coalesce(bool_or(needs_confirmation), false) INTO v_count, v_ambiguous
    FROM public.zalo_customer_identity_mappings
    WHERE company_id = c.company_id
      AND zalo_account_key = c.zalo_account_key
      AND remote_display_name_normalized = c.remote_display_name_normalized
      AND active;

    SELECT count(*) INTO v_customers
    FROM public.customers
    WHERE company_id = c.company_id
      AND public.zalo_search_name(name) = public.zalo_search_name(c.remote_display_name_normalized);

    v_ambiguous := v_ambiguous OR v_count > 1 OR v_customers > 1;

    IF v_count = 1 AND NOT v_ambiguous AND c.remote_display_name_normalized <> '' THEN
      SELECT customer_id INTO v_customer
      FROM public.zalo_customer_identity_mappings
      WHERE company_id = c.company_id
        AND zalo_account_key = c.zalo_account_key
        AND remote_display_name_normalized = c.remote_display_name_normalized
        AND active;
    END IF;
  END IF;

  -- 5. Atomic state transition and audit logging
  UPDATE public.zalo_personal_calls
  SET recording_status = 'READY',
      customer_id = v_customer,
      staff_user_id = v_final_staff,
      identity_ambiguous = v_ambiguous,
      matching_status = CASE
        WHEN v_customer IS NOT NULL THEN 'EXACT'
        WHEN v_count > 0 OR v_customers > 0 THEN 'SUGGESTED'
        ELSE 'UNMATCHED'
      END
  WHERE id = c.id;

  INSERT INTO public.audit_logs(company_id, user_id, action, resource_type, resource_id, customer_id, result, metadata)
  VALUES (
    c.company_id,
    coalesce(d.staff_user_id, req.staff_user_id),
    'ZALO_RECORDING_READY',
    'ZALO_CALL',
    c.id,
    v_customer,
    'SUCCESS',
    jsonb_build_object(
      'device_id', d.id,
      'outbound_request_id', c.outbound_request_id,
      'initiating_staff_user_id', req.staff_user_id,
      'actual_staff_user_id', d.staff_user_id
    )
  );

  RETURN jsonb_build_object('call_id', c.id, 'recording_id', c.id, 'duplicate', false);
END $$;

CREATE OR REPLACE FUNCTION public.zalo_create_outbound_call_request(
  p_company uuid,
  p_actor uuid,
  p_customer uuid,
  p_device uuid DEFAULT NULL
)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE
  v_role text;
  v_cust_name text;
  v_cust_phone text;
  v_mapping text;
  v_expected_name text;
  v_req_id uuid;
  v_target_dev public.zalo_recording_devices;
BEGIN
  v_role := public.zalo_assert_actor(p_company, p_actor);
  SELECT name INTO v_cust_name FROM public.customers WHERE company_id = p_company AND id = p_customer;
  IF v_cust_name IS NULL THEN RAISE EXCEPTION 'CUSTOMER_NOT_FOUND' USING ERRCODE='42501'; END IF;

  -- Validate target device if explicitly specified
  IF p_device IS NOT NULL THEN
    SELECT * INTO v_target_dev
    FROM public.zalo_recording_devices
    WHERE id = p_device AND company_id = p_company AND active;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'ZALO_DEVICE_UNAUTHORIZED' USING ERRCODE='42501';
    END IF;

    IF v_target_dev.staff_user_id IS NOT NULL THEN
      PERFORM public.zalo_assert_actor(p_company, v_target_dev.staff_user_id);
    END IF;

    IF v_role = 'SALE' THEN
      IF v_target_dev.staff_user_id IS NOT NULL AND v_target_dev.staff_user_id <> p_actor THEN
        RAISE EXCEPTION 'ZALO_DEVICE_UNAUTHORIZED' USING ERRCODE='42501';
      END IF;
    END IF;
  END IF;

  -- Look up customer phone from private contacts
  SELECT normalized_phone INTO v_cust_phone
  FROM private.customer_private_contacts
  WHERE company_id = p_company AND customer_id = p_customer
  ORDER BY is_verified DESC, created_at DESC LIMIT 1;

  -- Scope confirmed mapping to selected device account key; fallback to CRM customer name
  IF p_device IS NOT NULL AND v_target_dev.zalo_account_key IS NOT NULL THEN
    SELECT remote_display_name_original INTO v_mapping
    FROM public.zalo_customer_identity_mappings
    WHERE company_id = p_company
      AND customer_id = p_customer
      AND zalo_account_key = v_target_dev.zalo_account_key
      AND active
      AND NOT needs_confirmation
    ORDER BY confirmed_at DESC LIMIT 1;

    v_expected_name := coalesce(v_mapping, v_cust_name);
  ELSE
    v_expected_name := v_cust_name;
  END IF;

  v_req_id := gen_random_uuid();

  INSERT INTO public.zalo_outbound_call_requests(
    id, company_id, customer_id, staff_user_id, device_id, phone_normalized, expected_display_name, status, expires_at
  )
  VALUES (
    v_req_id, p_company, p_customer, p_actor, p_device, nullif(btrim(v_cust_phone), ''), v_expected_name, 'PENDING', now() + interval '5 minutes'
  );

  INSERT INTO public.audit_logs(company_id, user_id, action, resource_type, resource_id, customer_id, result, metadata)
  VALUES(p_company, p_actor, 'ZALO_OUTBOUND_REQUEST_CREATED', 'ZALO_OUTBOUND_REQUEST', v_req_id, p_customer, 'SUCCESS',
    jsonb_build_object('expected_display_name', v_expected_name, 'device_id', p_device));

  RETURN jsonb_build_object(
    'request_id', v_req_id,
    'customer_id', p_customer,
    'customer_name', v_cust_name,
    'phone', nullif(btrim(v_cust_phone), ''),
    'expected_display_name', v_expected_name,
    'expires_at', (now() + interval '5 minutes')
  );
END $$;

ALTER TABLE public.zalo_personal_calls
  ADD COLUMN IF NOT EXISTS transcript_status text NOT NULL DEFAULT 'NOT_STARTED'
  CHECK (transcript_status IN ('NOT_STARTED', 'PENDING', 'PROCESSING', 'COMPLETED', 'FAILED'));

CREATE INDEX idx_zalo_call_transcriptions_due
  ON public.zalo_call_transcriptions (status, next_run_at)
  WHERE status IN ('PENDING', 'PROCESSING');

CREATE POLICY zalo_call_transcriptions_read ON public.zalo_call_transcriptions
  FOR SELECT TO authenticated USING (
    public.has_company_role(company_id, 'BOSS_ADMIN') OR (
      public.has_company_role(company_id, 'SALE') AND EXISTS (
        SELECT 1 FROM public.zalo_personal_calls zpc
        WHERE zpc.id = call_id AND zpc.company_id = company_id AND zpc.staff_user_id = auth.uid()
      )
    )
  );

CREATE POLICY zalo_call_transcript_utterances_read ON public.zalo_call_transcript_utterances
  FOR SELECT TO authenticated USING (
    public.has_company_role(company_id, 'BOSS_ADMIN') OR (
      public.has_company_role(company_id, 'SALE') AND EXISTS (
        SELECT 1 FROM public.zalo_personal_calls zpc
        WHERE zpc.id = call_id AND zpc.company_id = company_id AND zpc.staff_user_id = auth.uid()
      )
    )
  );

