CREATE OR REPLACE FUNCTION public.sync_zalo_personal_contacts(
  p_company uuid,
  p_contacts jsonb
) RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path=''
AS $$
DECLARE
  item jsonb;
  ext text;
  display text;
  linked uuid;
  identity_customer uuid;
  conversation_customer uuid;
  candidate public.zalo_personal_contact_candidates;
  seen_count int := 0;
  auto_linked int := 0;
  auto_created int := 0;
  route_conflicts int := 0;
  legacy_upgraded int := 0;
  route_identity_count bigint;
  blank_identity_count bigint;
  legacy_identity_customer uuid;
  route_conversation_count bigint;
  blank_provider_conversation_count bigint;
  route_conversation_customer_count bigint;
  legacy_conversation_customer uuid;
BEGIN
  IF p_company IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.companies WHERE id=p_company
  ) THEN RAISE EXCEPTION 'INVALID_COMPANY'; END IF;

  IF jsonb_typeof(p_contacts) <> 'array' OR jsonb_array_length(p_contacts) > 5000 THEN
    RAISE EXCEPTION 'INVALID_CONTACT_BATCH';
  END IF;

  FOR item IN SELECT value FROM jsonb_array_elements(p_contacts) LOOP
    ext := btrim(coalesce(item->>'externalUserId',''));
    display := nullif(left(regexp_replace(coalesce(item->>'displayName',''), '\\s+', ' ', 'g'),160),'');
    IF ext !~ '^[0-9]{5,40}$' THEN CONTINUE; END IF;
    seen_count := seen_count + 1;

    PERFORM pg_advisory_xact_lock(hashtextextended(p_company::text || ':ZALO_PERSONAL:' || ext, 0));

    INSERT INTO public.zalo_personal_contact_candidates(
      company_id,external_id,display_name,status,linked_customer_id,last_seen_at,linked_at,metadata
    ) VALUES (
      p_company,ext,display,'UNLINKED',NULL,clock_timestamp(),NULL,
      jsonb_build_object('source','ZCAJS','directory','personal_directory')
    )
    ON CONFLICT(company_id,external_id) DO UPDATE SET
      display_name=coalesce(EXCLUDED.display_name,public.zalo_personal_contact_candidates.display_name),
      last_seen_at=clock_timestamp(),
      metadata=coalesce(public.zalo_personal_contact_candidates.metadata,'{}'::jsonb) || EXCLUDED.metadata;

    SELECT * INTO candidate
      FROM public.zalo_personal_contact_candidates
     WHERE company_id=p_company AND external_id=ext
     FOR UPDATE;

    -- Legacy compatibility: older personal-Zalo rows were created before provider metadata existed.
    -- Promote only when there is exactly one blank-metadata identity, exactly one blank-provider
    -- conversation, both point to the same customer, and this UID is now observed by the ZCAJS
    -- personal directory. Names are never used as a join key.
    SELECT count(*),
           count(*) FILTER (
             WHERE nullif(btrim(coalesce(i.metadata->>'source','')),'') IS NULL
               AND nullif(btrim(coalesce(i.metadata->>'provider','')),'') IS NULL
           ),
           max(i.customer_id::text)::uuid
      INTO route_identity_count,blank_identity_count,legacy_identity_customer
      FROM public.identities i
     WHERE i.company_id=p_company
       AND i.channel='ZALO'
       AND i.external_id=ext;

    SELECT count(*),
           count(*) FILTER (
             WHERE nullif(btrim(coalesce(c.metadata->>'provider','')),'') IS NULL
           ),
           count(DISTINCT c.customer_id),
           max(c.customer_id::text)::uuid
      INTO route_conversation_count,blank_provider_conversation_count,
           route_conversation_customer_count,legacy_conversation_customer
      FROM public.conversations c
     WHERE c.company_id=p_company
       AND c.channel='ZALO'
       AND c.external_conversation_id=ext;

    IF upper(coalesce(candidate.metadata->>'source',''))='ZCAJS'
       AND coalesce(candidate.metadata->>'directory','')='personal_directory'
       AND route_identity_count=1
       AND blank_identity_count=1
       AND route_conversation_count=1
       AND blank_provider_conversation_count=1
       AND route_conversation_customer_count=1
       AND legacy_identity_customer IS NOT NULL
       AND legacy_identity_customer=legacy_conversation_customer
       AND EXISTS (
         SELECT 1 FROM public.customers cu
          WHERE cu.company_id=p_company
            AND cu.id=legacy_identity_customer
            AND cu.source='ZALO'
       )
    THEN
      UPDATE public.identities i
         SET metadata=coalesce(i.metadata,'{}'::jsonb) || jsonb_build_object(
               'source','ZCAJS',
               'provider','zcajs',
               'directory_seen',true,
               'zero_touch',true,
               'legacy_upgraded',true,
               'link_source','legacy_exact_uid'
             ),
             display_name=coalesce(display,i.display_name),
             updated_at=clock_timestamp()
       WHERE i.company_id=p_company
         AND i.channel='ZALO'
         AND i.external_id=ext
         AND i.customer_id=legacy_identity_customer
         AND nullif(btrim(coalesce(i.metadata->>'source','')),'') IS NULL
         AND nullif(btrim(coalesce(i.metadata->>'provider','')),'') IS NULL;

      UPDATE public.conversations c
         SET metadata=coalesce(c.metadata,'{}'::jsonb) || jsonb_build_object(
               'source','ZCAJS',
               'provider','zcajs',
               'legacy_upgraded',true
             ),
             updated_at=clock_timestamp()
       WHERE c.company_id=p_company
         AND c.channel='ZALO'
         AND c.external_conversation_id=ext
         AND c.customer_id=legacy_identity_customer
         AND nullif(btrim(coalesce(c.metadata->>'provider','')),'') IS NULL;

      legacy_upgraded := legacy_upgraded + 1;
    END IF;

    -- Explicit OA/other-provider routes remain fail-closed. A safely promoted legacy route now
    -- carries ZCAJS metadata and therefore passes this guard.
    IF EXISTS (
      SELECT 1 FROM public.identities i
       WHERE i.company_id=p_company AND i.channel='ZALO' AND i.external_id=ext
         AND NOT (
           upper(coalesce(i.metadata->>'source',''))='ZCAJS'
           OR lower(coalesce(i.metadata->>'provider',''))='zcajs'
         )
    ) OR EXISTS (
      SELECT 1 FROM public.conversations c
       WHERE c.company_id=p_company AND c.channel='ZALO'
         AND c.external_conversation_id=ext
         AND lower(coalesce(c.metadata->>'provider','')) <> 'zcajs'
    ) THEN
      route_conflicts := route_conflicts + 1;
      UPDATE public.zalo_personal_contact_candidates
         SET status='UNLINKED', linked_customer_id=NULL, linked_at=NULL,
             metadata=coalesce(metadata,'{}'::jsonb) || jsonb_build_object(
               'route_conflict',true,
               'zero_touch_blocked',true
             )
       WHERE id=candidate.id;
      CONTINUE;
    END IF;

    identity_customer := NULL;
    conversation_customer := NULL;

    SELECT i.customer_id INTO identity_customer
      FROM public.identities i
     WHERE i.company_id=p_company
       AND i.channel='ZALO'
       AND i.external_id=ext
       AND (
         upper(coalesce(i.metadata->>'source',''))='ZCAJS'
         OR lower(coalesce(i.metadata->>'provider',''))='zcajs'
       )
     LIMIT 1;

    SELECT c.customer_id INTO conversation_customer
      FROM public.conversations c
     WHERE c.company_id=p_company
       AND c.channel='ZALO'
       AND c.external_conversation_id=ext
       AND lower(coalesce(c.metadata->>'provider',''))='zcajs'
     LIMIT 1;

    IF identity_customer IS NOT NULL
       AND conversation_customer IS NOT NULL
       AND identity_customer <> conversation_customer THEN
      route_conflicts := route_conflicts + 1;
      UPDATE public.zalo_personal_contact_candidates
         SET status='UNLINKED', linked_customer_id=NULL, linked_at=NULL,
             metadata=coalesce(metadata,'{}'::jsonb) || jsonb_build_object(
               'route_conflict',true,
               'zero_touch_blocked',true
             )
       WHERE id=candidate.id;
      CONTINUE;
    END IF;

    linked := NULL;
    IF candidate.linked_customer_id IS NOT NULL AND EXISTS (
      SELECT 1 FROM public.customers
       WHERE company_id=p_company AND id=candidate.linked_customer_id
    ) THEN
      linked := candidate.linked_customer_id;
      IF (identity_customer IS NOT NULL AND identity_customer <> linked)
         OR (conversation_customer IS NOT NULL AND conversation_customer <> linked) THEN
        route_conflicts := route_conflicts + 1;
        UPDATE public.zalo_personal_contact_candidates
           SET status='UNLINKED', linked_customer_id=NULL, linked_at=NULL,
               metadata=coalesce(metadata,'{}'::jsonb) || jsonb_build_object(
                 'route_conflict',true,
                 'zero_touch_blocked',true
               )
         WHERE id=candidate.id;
        CONTINUE;
      END IF;
    ELSE
      linked := coalesce(identity_customer,conversation_customer);
    END IF;

    IF linked IS NULL THEN
      INSERT INTO public.customers(company_id,name,source,stage)
      VALUES (
        p_company,
        coalesce(display,'Khách Zalo ' || right(ext,6)),
        'ZALO',
        'LEAD_NEW'
      ) RETURNING id INTO linked;
      auto_created := auto_created + 1;
    ELSE
      auto_linked := auto_linked + 1;
    END IF;

    INSERT INTO public.identities(
      company_id,customer_id,channel,external_id,verified,metadata,display_name,created_at,updated_at
    ) VALUES (
      p_company,linked,'ZALO',ext,false,
      jsonb_build_object(
        'source','ZCAJS',
        'provider','zcajs',
        'link_source',CASE WHEN candidate.linked_customer_id IS NULL THEN 'directory_zero_touch' ELSE 'existing_link' END,
        'directory_seen',true,
        'zero_touch',true
      ),
      display,clock_timestamp(),clock_timestamp()
    )
    ON CONFLICT(company_id,channel,external_id) DO UPDATE SET
      display_name=coalesce(EXCLUDED.display_name,public.identities.display_name),
      updated_at=clock_timestamp(),
      metadata=coalesce(public.identities.metadata,'{}'::jsonb) || EXCLUDED.metadata
    WHERE public.identities.customer_id=EXCLUDED.customer_id
      AND (
        upper(coalesce(public.identities.metadata->>'source',''))='ZCAJS'
        OR lower(coalesce(public.identities.metadata->>'provider',''))='zcajs'
      );

    UPDATE public.zalo_personal_contact_candidates
       SET status='LINKED',
           linked_customer_id=linked,
           linked_at=coalesce(linked_at,clock_timestamp()),
           metadata=(coalesce(metadata,'{}'::jsonb) - 'route_conflict' - 'zero_touch_blocked') ||
             jsonb_build_object(
               'zero_touch',true,
               'link_source',CASE WHEN legacy_identity_customer=linked AND legacy_upgraded>0
                                  THEN 'legacy_exact_uid' ELSE 'uid' END
             ),
           last_seen_at=greatest(last_seen_at,clock_timestamp())
     WHERE id=candidate.id;
  END LOOP;

  RETURN jsonb_build_object(
    'seen',seen_count,
    'auto_linked',auto_linked,
    'auto_created',auto_created,
    'legacy_upgraded',legacy_upgraded,
    'route_conflicts',route_conflicts
  );
END $$;

DO $$
DECLARE
  row record;
BEGIN
  FOR row IN
    SELECT company_id,
           jsonb_agg(jsonb_build_object(
             'externalUserId',external_id,
             'displayName',display_name
           ) ORDER BY external_id) AS contacts
      FROM public.zalo_personal_contact_candidates
     GROUP BY company_id
  LOOP
    PERFORM public.sync_zalo_personal_contacts(row.company_id,row.contacts);
  END LOOP;
END $$;

DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public'
    AND table_name='ai_brain_live_deliveries' AND column_name='retryable') THEN
    ALTER TABLE public.ai_brain_live_deliveries ADD COLUMN retryable boolean NOT NULL DEFAULT true;
    -- One-time fence: existing failures require deliberate owner selection.
    UPDATE public.ai_brain_live_deliveries SET retryable = false WHERE channel = 'ZALO' AND send_status = 'FAILED';
  END IF;
END $$;

CREATE OR REPLACE FUNCTION public.ai_brain_live_retry_and_sla_guard()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE v_source_at timestamptz;
BEGIN
  IF TG_OP = 'INSERT' AND NEW.channel = 'ZALO' THEN
    SELECT i.created_at INTO v_source_at FROM public.interactions i
    WHERE i.id = NEW.source_interaction_id AND i.company_id = NEW.company_id
      AND i.customer_id = NEW.customer_id AND i.conversation_id = NEW.conversation_id;
    IF v_source_at IS NULL THEN RAISE EXCEPTION 'LIVE_SOURCE_INVALID'; END IF;
    NEW.available_at := GREATEST(NEW.available_at, v_source_at + interval '5 minutes');
  END IF;
  IF NEW.send_status = 'FAILED' AND (NEW.attempts >= 5 OR NEW.error_code IN (
    'BRAIN_CONFIG_MISSING', 'BRAIN_UNAVAILABLE', 'BRAIN_AUTH_FAILED', 'RUNTIME_AUTH_FAILED',
    'MODEL_CONFIG_INVALID', 'BRAIN_REQUEST_INVALID', 'RUNTIME_REQUEST_INVALID'
  )) THEN NEW.retryable := false; END IF;
  RETURN NEW;
END; $$;

CREATE OR REPLACE FUNCTION public.ai_brain_live_retry_and_sla_guard()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE v_source_at timestamptz;
BEGIN
  IF TG_OP = 'INSERT' AND NEW.channel = 'ZALO' THEN
    SELECT i.created_at INTO v_source_at FROM public.interactions i
    WHERE i.id = NEW.source_interaction_id AND i.company_id = NEW.company_id
      AND i.customer_id = NEW.customer_id AND i.conversation_id = NEW.conversation_id;
    IF v_source_at IS NULL THEN RAISE EXCEPTION 'LIVE_SOURCE_INVALID'; END IF;
    NEW.available_at := GREATEST(NEW.available_at, v_source_at + interval '1 minute');
  END IF;
  IF NEW.send_status = 'FAILED' AND (NEW.attempts >= 5 OR NEW.error_code IN (
    'BRAIN_CONFIG_MISSING', 'BRAIN_UNAVAILABLE', 'BRAIN_AUTH_FAILED', 'RUNTIME_AUTH_FAILED',
    'MODEL_CONFIG_INVALID', 'BRAIN_REQUEST_INVALID', 'RUNTIME_REQUEST_INVALID'
  )) THEN NEW.retryable := false; END IF;
  RETURN NEW;
END; $$;

CREATE OR REPLACE FUNCTION public.zalo_finish_recording(
  p_device uuid,
  p_key_hash text,
  p_call uuid,
  p_lease uuid
)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE
  d public.zalo_recording_devices;
  c public.zalo_personal_calls;
  req public.zalo_outbound_call_requests;
  v_count int := 0;
  v_customers int := 0;
  v_customer uuid := null;
  v_ambiguous boolean := false;
  v_req_role text;
  v_final_staff uuid;
BEGIN
  SELECT * INTO d
  FROM public.zalo_recording_devices
  WHERE id = p_device AND active AND device_key_hash = p_key_hash
  FOR UPDATE;

  IF NOT FOUND OR NOT EXISTS (
    SELECT 1 FROM public.companies WHERE id = d.company_id AND status = 'ACTIVE'
  ) THEN
    RAISE EXCEPTION 'ZALO_DEVICE_UNAUTHORIZED' USING ERRCODE='42501';
  END IF;

  IF d.staff_user_id IS NOT NULL THEN
    PERFORM public.zalo_assert_actor(d.company_id, d.staff_user_id);
  END IF;

  SELECT * INTO c
  FROM public.zalo_personal_calls
  WHERE id = p_call AND company_id = d.company_id AND device_id = d.id
  FOR UPDATE;

  IF NOT FOUND OR c.upload_lease <> p_lease THEN
    RAISE EXCEPTION 'ZALO_LEASE_LOST';
  END IF;

  IF c.recording_status = 'READY' THEN
    RETURN jsonb_build_object('call_id', c.id, 'recording_id', c.id, 'duplicate', true);
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM storage.objects
    WHERE bucket_id = 'zalo-call-recordings'
      AND name = c.recording_path
      AND (metadata->>'size')::bigint = c.recording_bytes
  ) THEN
    RAISE EXCEPTION 'ZALO_OBJECT_MISSING';
  END IF;

  v_final_staff := c.staff_user_id;

  -- Verified outbound requests always carry the authoritative customer.
  IF c.outbound_request_id IS NOT NULL THEN
    SELECT * INTO req
    FROM public.zalo_outbound_call_requests
    WHERE id = c.outbound_request_id AND company_id = c.company_id
    FOR UPDATE;

    IF NOT FOUND THEN RAISE EXCEPTION 'ZALO_REQUEST_NOT_FOUND'; END IF;
    IF c.direction IS DISTINCT FROM 'OUTBOUND' THEN RAISE EXCEPTION 'ZALO_REQUEST_DIRECTION_MISMATCH'; END IF;
    IF req.claimed_at IS NULL OR req.claimed_by_device_id IS NULL THEN RAISE EXCEPTION 'ZALO_REQUEST_UNCLAIMED'; END IF;
    IF req.claimed_by_device_id <> d.id THEN RAISE EXCEPTION 'ZALO_REQUEST_DEVICE_MISMATCH'; END IF;
    IF req.device_id IS NOT NULL AND req.device_id <> d.id THEN RAISE EXCEPTION 'ZALO_REQUEST_DEVICE_MISMATCH'; END IF;

    v_req_role := public.zalo_assert_actor(c.company_id, req.staff_user_id);
    IF d.staff_user_id IS NOT NULL THEN
      PERFORM public.zalo_assert_actor(d.company_id, d.staff_user_id);
      IF d.staff_user_id <> req.staff_user_id
         AND (v_req_role <> 'BOSS_ADMIN' OR req.device_id IS DISTINCT FROM d.id) THEN
        RAISE EXCEPTION 'ZALO_REQUEST_STAFF_MISMATCH';
      END IF;
    END IF;

    IF req.status = 'FAILED' THEN RAISE EXCEPTION 'ZALO_REQUEST_FAILED'; END IF;
    IF req.status = 'EXPIRED' THEN RAISE EXCEPTION 'ZALO_REQUEST_EXPIRED'; END IF;
    IF req.status = 'COMPLETED' THEN RAISE EXCEPTION 'ZALO_REQUEST_REUSED'; END IF;
    IF req.status NOT IN ('CALL_TRIGGERED', 'CALL_DETECTED') THEN RAISE EXCEPTION 'ZALO_REQUEST_INVALID_STATE'; END IF;
    IF c.started_at < (req.created_at - interval '30 seconds')
       OR c.started_at < (req.claimed_at - interval '30 seconds') THEN
      RAISE EXCEPTION 'ZALO_REQUEST_TIMING_INVALID';
    END IF;
    IF c.started_at > req.expires_at THEN RAISE EXCEPTION 'ZALO_REQUEST_EXPIRED'; END IF;
    IF EXISTS (
      SELECT 1 FROM public.zalo_personal_calls
      WHERE outbound_request_id = req.id AND id <> c.id
    ) THEN
      RAISE EXCEPTION 'ZALO_REQUEST_REUSED';
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM public.customers WHERE id = req.customer_id AND company_id = c.company_id
    ) THEN
      RAISE EXCEPTION 'CUSTOMER_NOT_FOUND';
    END IF;

    v_customer := req.customer_id;
    IF v_final_staff IS NULL AND d.staff_user_id IS NULL THEN v_final_staff := req.staff_user_id; END IF;
    UPDATE public.zalo_outbound_call_requests
    SET status = 'COMPLETED', completed_at = now()
    WHERE id = req.id;
    v_count := 1;
  END IF;

  -- Inbound/standalone calls auto-link only when the identity is unique.
  IF v_customer IS NULL THEN
    PERFORM pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(c.company_id::text || c.zalo_account_key::text || c.remote_display_name_normalized, 0)
    );

    SELECT count(*), coalesce(bool_or(needs_confirmation), false)
    INTO v_count, v_ambiguous
    FROM public.zalo_customer_identity_mappings
    WHERE company_id = c.company_id
      AND zalo_account_key = c.zalo_account_key
      AND remote_display_name_normalized = c.remote_display_name_normalized
      AND active;

    SELECT count(*) INTO v_customers
    FROM public.customers
    WHERE company_id = c.company_id
      AND public.zalo_search_name(name) = public.zalo_search_name(c.remote_display_name_normalized);

    v_ambiguous := v_ambiguous OR v_count > 1 OR v_customers > 1;

    IF v_count = 1 AND NOT v_ambiguous AND c.remote_display_name_normalized <> '' THEN
      SELECT customer_id INTO v_customer
      FROM public.zalo_customer_identity_mappings
      WHERE company_id = c.company_id
        AND zalo_account_key = c.zalo_account_key
        AND remote_display_name_normalized = c.remote_display_name_normalized
        AND active;
    ELSIF v_count = 0 AND v_customers = 1 AND NOT v_ambiguous
          AND c.remote_display_name_normalized <> '' THEN
      SELECT id INTO v_customer
      FROM public.customers
      WHERE company_id = c.company_id
        AND public.zalo_search_name(name) = public.zalo_search_name(c.remote_display_name_normalized);
    END IF;
  END IF;

  UPDATE public.zalo_personal_calls
  SET recording_status = 'READY',
      transcript_status = 'PENDING',
      customer_id = v_customer,
      staff_user_id = v_final_staff,
      identity_ambiguous = v_ambiguous,
      matching_status = CASE
        WHEN v_customer IS NOT NULL THEN 'EXACT'
        WHEN v_count > 0 OR v_customers > 0 THEN 'SUGGESTED'
        ELSE 'UNMATCHED'
      END
  WHERE id = c.id;

  INSERT INTO public.zalo_call_transcriptions (company_id, call_id, customer_id, status, next_run_at)
  VALUES (c.company_id, c.id, v_customer, 'PENDING', now())
  ON CONFLICT (company_id, call_id) DO UPDATE
    SET customer_id = EXCLUDED.customer_id, updated_at = now()
    WHERE public.zalo_call_transcriptions.status IN ('PENDING', 'PROCESSING');

  INSERT INTO public.audit_logs(company_id, user_id, action, resource_type, resource_id, customer_id, result, metadata)
  VALUES (
    c.company_id,
    coalesce(d.staff_user_id, req.staff_user_id),
    'ZALO_RECORDING_READY',
    'ZALO_CALL',
    c.id,
    v_customer,
    'SUCCESS',
    jsonb_build_object(
      'device_id', d.id,
      'outbound_request_id', c.outbound_request_id,
      'initiating_staff_user_id', req.staff_user_id,
      'actual_staff_user_id', d.staff_user_id,
      'auto_linked', v_customer IS NOT NULL
    )
  );

  RETURN jsonb_build_object('call_id', c.id, 'recording_id', c.id, 'duplicate', false);
END $$;

CREATE INDEX zalo_live_voice_sessions_expiry_idx
  ON public.zalo_personal_live_voice_sessions(expires_at)
  WHERE status IN ('REQUESTED', 'ACTIVE');

CREATE OR REPLACE FUNCTION public.zalo_begin_live_voice_session(
  p_device uuid,
  p_key_hash text,
  p_request_id uuid,
  p_local_call_id uuid
)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE
  d public.zalo_recording_devices;
  req public.zalo_outbound_call_requests;
  s public.zalo_personal_live_voice_sessions;
  v_role text;
BEGIN
  SELECT * INTO d
  FROM public.zalo_recording_devices
  WHERE id = p_device AND active AND device_key_hash = p_key_hash
  FOR SHARE;
  IF NOT FOUND OR NOT EXISTS (
    SELECT 1 FROM public.companies WHERE id = d.company_id AND status = 'ACTIVE'
  ) THEN
    RAISE EXCEPTION 'ZALO_DEVICE_UNAUTHORIZED' USING ERRCODE='42501';
  END IF;

  SELECT * INTO req
  FROM public.zalo_outbound_call_requests
  WHERE id = p_request_id AND company_id = d.company_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ZALO_REQUEST_NOT_FOUND'; END IF;
  IF req.claimed_by_device_id IS DISTINCT FROM d.id THEN
    RAISE EXCEPTION 'ZALO_REQUEST_DEVICE_MISMATCH';
  END IF;
  IF req.status NOT IN ('CALL_TRIGGERED', 'CALL_DETECTED') THEN
    RAISE EXCEPTION 'ZALO_LIVE_CALL_NOT_CONFIRMED';
  END IF;
  v_role := public.zalo_assert_actor(d.company_id, req.staff_user_id);
  IF d.staff_user_id IS NOT NULL AND d.staff_user_id <> req.staff_user_id
     AND (v_role <> 'BOSS_ADMIN' OR req.device_id IS DISTINCT FROM d.id) THEN
    RAISE EXCEPTION 'ZALO_REQUEST_STAFF_MISMATCH';
  END IF;

  SELECT * INTO s
  FROM public.zalo_personal_live_voice_sessions
  WHERE company_id = d.company_id AND local_call_id = p_local_call_id
  FOR UPDATE;
  IF FOUND THEN
    IF s.device_id IS DISTINCT FROM d.id OR s.outbound_request_id IS DISTINCT FROM req.id THEN
      RAISE EXCEPTION 'ZALO_LIVE_SESSION_CONFLICT';
    END IF;
    IF s.expires_at < now() AND s.status IN ('REQUESTED', 'ACTIVE') THEN
      UPDATE public.zalo_personal_live_voice_sessions
      SET status = 'EXPIRED', ended_at = now(), failure_code = 'SESSION_EXPIRED'
      WHERE id = s.id;
      RAISE EXCEPTION 'ZALO_LIVE_SESSION_EXPIRED';
    END IF;
    RETURN jsonb_build_object(
      'session_id', s.id, 'company_id', s.company_id, 'customer_id', s.customer_id,
      'request_id', s.outbound_request_id, 'local_call_id', s.local_call_id,
      'status', s.status, 'expires_at', s.expires_at
    );
  END IF;

  INSERT INTO public.zalo_personal_live_voice_sessions(
    company_id, customer_id, outbound_request_id, device_id, local_call_id
  ) VALUES (d.company_id, req.customer_id, req.id, d.id, p_local_call_id)
  RETURNING * INTO s;

  RETURN jsonb_build_object(
    'session_id', s.id, 'company_id', s.company_id, 'customer_id', s.customer_id,
    'request_id', s.outbound_request_id, 'local_call_id', s.local_call_id,
    'status', s.status, 'expires_at', s.expires_at
  );
END $$;

CREATE OR REPLACE FUNCTION public.zalo_finish_live_voice_session(
  p_device uuid,
  p_key_hash text,
  p_session_id uuid,
  p_status text,
  p_provider_session_id text DEFAULT NULL,
  p_failure_code text DEFAULT NULL
)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE
  d public.zalo_recording_devices;
  s public.zalo_personal_live_voice_sessions;
BEGIN
  SELECT * INTO d FROM public.zalo_recording_devices
  WHERE id = p_device AND active AND device_key_hash = p_key_hash FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ZALO_DEVICE_UNAUTHORIZED' USING ERRCODE='42501'; END IF;
  IF p_status NOT IN ('ACTIVE', 'ENDED', 'FAILED', 'EXPIRED') THEN
    RAISE EXCEPTION 'ZALO_LIVE_STATUS_INVALID';
  END IF;
  SELECT * INTO s FROM public.zalo_personal_live_voice_sessions
  WHERE id = p_session_id AND company_id = d.company_id AND device_id = d.id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ZALO_LIVE_SESSION_NOT_FOUND'; END IF;
  IF s.status IN ('ENDED', 'FAILED', 'EXPIRED') AND s.status <> p_status THEN
    RAISE EXCEPTION 'ZALO_LIVE_STATUS_TERMINAL';
  END IF;
  UPDATE public.zalo_personal_live_voice_sessions
  SET status = p_status,
      provider_session_id = coalesce(p_provider_session_id, provider_session_id),
      failure_code = p_failure_code,
      started_at = CASE WHEN p_status = 'ACTIVE' THEN coalesce(started_at, now()) ELSE started_at END,
      ended_at = CASE WHEN p_status IN ('ENDED', 'FAILED', 'EXPIRED') THEN coalesce(ended_at, now()) ELSE ended_at END
  WHERE id = s.id;
  RETURN true;
END $$;

CREATE OR REPLACE FUNCTION public.zalo_begin_inbound_live_voice_session(
  p_device uuid,
  p_key_hash text,
  p_local_call_id uuid,
  p_remote_display_name text DEFAULT NULL
)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE
  d public.zalo_recording_devices;
  s public.zalo_personal_live_voice_sessions;
  v_name text := nullif(btrim(p_remote_display_name), '');
BEGIN
  SELECT * INTO d
  FROM public.zalo_recording_devices
  WHERE id = p_device AND active AND device_key_hash = p_key_hash
  FOR SHARE;
  IF NOT FOUND OR NOT EXISTS (
    SELECT 1 FROM public.companies WHERE id = d.company_id AND status = 'ACTIVE'
  ) THEN
    RAISE EXCEPTION 'ZALO_DEVICE_UNAUTHORIZED' USING ERRCODE='42501';
  END IF;
  IF d.staff_user_id IS NOT NULL THEN
    PERFORM public.zalo_assert_actor(d.company_id, d.staff_user_id);
  END IF;

  SELECT * INTO s
  FROM public.zalo_personal_live_voice_sessions
  WHERE company_id = d.company_id AND local_call_id = p_local_call_id
  FOR UPDATE;
  IF FOUND THEN
    IF s.device_id IS DISTINCT FROM d.id OR s.direction IS DISTINCT FROM 'INBOUND' THEN
      RAISE EXCEPTION 'ZALO_LIVE_SESSION_CONFLICT';
    END IF;
    RETURN jsonb_build_object(
      'session_id', s.id, 'company_id', s.company_id, 'customer_id', s.customer_id,
      'request_id', s.outbound_request_id, 'local_call_id', s.local_call_id,
      'direction', s.direction, 'remote_display_name', s.remote_display_name,
      'status', s.status, 'expires_at', s.expires_at
    );
  END IF;

  INSERT INTO public.zalo_personal_live_voice_sessions(
    company_id, customer_id, outbound_request_id, device_id, local_call_id,
    direction, remote_display_name
  ) VALUES (d.company_id, NULL, NULL, d.id, p_local_call_id, 'INBOUND', v_name)
  RETURNING * INTO s;

  RETURN jsonb_build_object(
    'session_id', s.id, 'company_id', s.company_id, 'customer_id', s.customer_id,
    'request_id', s.outbound_request_id, 'local_call_id', s.local_call_id,
    'direction', s.direction, 'remote_display_name', s.remote_display_name,
    'status', s.status, 'expires_at', s.expires_at
  );
END $$;

CREATE OR REPLACE FUNCTION public.zalo_begin_inbound_live_voice_session(
  p_device uuid,
  p_key_hash text,
  p_local_call_id uuid,
  p_remote_display_name text DEFAULT NULL
)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE
  d public.zalo_recording_devices;
  s public.zalo_personal_live_voice_sessions;
  v_name text := nullif(btrim(p_remote_display_name), '');
BEGIN
  SELECT * INTO d
  FROM public.zalo_recording_devices
  WHERE id = p_device AND active AND device_key_hash = p_key_hash
  FOR SHARE;
  IF NOT FOUND OR NOT EXISTS (
    SELECT 1 FROM public.companies WHERE id = d.company_id AND status = 'ACTIVE'
  ) THEN
    RAISE EXCEPTION 'ZALO_DEVICE_UNAUTHORIZED' USING ERRCODE='42501';
  END IF;
  IF d.staff_user_id IS NOT NULL THEN
    PERFORM public.zalo_assert_actor(d.company_id, d.staff_user_id);
  END IF;

  SELECT * INTO s
  FROM public.zalo_personal_live_voice_sessions
  WHERE company_id = d.company_id AND local_call_id = p_local_call_id
  FOR UPDATE;
  IF FOUND THEN
    IF s.device_id IS DISTINCT FROM d.id OR s.direction IS DISTINCT FROM 'INBOUND' THEN
      RAISE EXCEPTION 'ZALO_LIVE_SESSION_CONFLICT';
    END IF;
    IF s.expires_at < now() AND s.status IN ('REQUESTED', 'ACTIVE') THEN
      UPDATE public.zalo_personal_live_voice_sessions
      SET status = 'EXPIRED', ended_at = now(), failure_code = 'SESSION_EXPIRED'
      WHERE id = s.id;
      RAISE EXCEPTION 'ZALO_LIVE_SESSION_EXPIRED';
    END IF;
    IF s.status IN ('ENDED', 'FAILED', 'EXPIRED') THEN
      RAISE EXCEPTION 'ZALO_LIVE_SESSION_TERMINAL';
    END IF;
    RETURN jsonb_build_object(
      'session_id', s.id, 'company_id', s.company_id, 'customer_id', s.customer_id,
      'request_id', s.outbound_request_id, 'local_call_id', s.local_call_id,
      'direction', s.direction, 'remote_display_name', s.remote_display_name,
      'status', s.status, 'expires_at', s.expires_at
    );
  END IF;

  INSERT INTO public.zalo_personal_live_voice_sessions(
    company_id, customer_id, outbound_request_id, device_id, local_call_id,
    direction, remote_display_name
  ) VALUES (d.company_id, NULL, NULL, d.id, p_local_call_id, 'INBOUND', v_name)
  RETURNING * INTO s;

  RETURN jsonb_build_object(
    'session_id', s.id, 'company_id', s.company_id, 'customer_id', s.customer_id,
    'request_id', s.outbound_request_id, 'local_call_id', s.local_call_id,
    'direction', s.direction, 'remote_display_name', s.remote_display_name,
    'status', s.status, 'expires_at', s.expires_at
  );
END $$;

CREATE OR REPLACE FUNCTION public.ingest_provider_message_atomic(
  p_company_id uuid,
  p_channel text,
  p_external_user_id text DEFAULT NULL,
  p_sender_name text DEFAULT NULL,
  p_sender_phone text DEFAULT NULL,
  p_external_conversation_id text DEFAULT NULL,
  p_external_ref text DEFAULT NULL,
  p_sanitized_content text DEFAULT '',
  p_raw_content text DEFAULT '',
  p_source_metadata jsonb DEFAULT '{}'::jsonb,
  p_sanitization_status text DEFAULT 'SUCCEEDED',
  p_customer_id uuid DEFAULT NULL
)
RETURNS TABLE (
  interaction_id uuid,
  conversation_id uuid,
  customer_id uuid,
  is_duplicate boolean
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
#variable_conflict use_column
DECLARE
  v_channel text;
  v_sanitization_status text;
  v_customer_id uuid := NULL;
  v_cust_name text;
  v_normalized_phone text := NULL;
  v_conversation public.conversations%ROWTYPE;
  v_existing_interaction public.interactions%ROWTYPE;
  v_conversation_id uuid;
  v_interaction_id uuid;
  v_ext_conv_id text;
  v_now timestamptz := clock_timestamp();
  v_metadata jsonb := coalesce(p_source_metadata, '{}'::jsonb);
  v_legacy_ref text;
  v_legacy_confidence text;
BEGIN
  -- 1. Validate mandatory fields (Fail-Closed)
  IF p_company_id IS NULL THEN
    RAISE EXCEPTION 'p_company_id là bắt buộc'
      USING ERRCODE = '22023', HINT = 'MISSING_COMPANY_ID';
  END IF;
  IF p_channel IS NULL OR trim(p_channel) = '' THEN
    RAISE EXCEPTION 'p_channel là bắt buộc'
      USING ERRCODE = '22023', HINT = 'MISSING_CHANNEL';
  END IF;

  v_channel := upper(trim(p_channel));
  IF v_channel = 'FB' THEN
    v_channel := 'FACEBOOK';
  ELSIF v_channel = 'ZL' THEN
    v_channel := 'ZALO';
  END IF;

  -- Missing provider user ID / message ID must be rejected before persistence
  IF v_channel IN ('FACEBOOK', 'ZALO') THEN
    IF p_external_user_id IS NULL OR trim(p_external_user_id) = '' THEN
      RAISE EXCEPTION 'MISSING_PROVIDER_USER_ID: Missing required provider user ID for %', v_channel
        USING ERRCODE = '22023', HINT = 'MISSING_PROVIDER_USER_ID';
    END IF;
    IF p_external_ref IS NULL OR trim(p_external_ref) = '' THEN
      RAISE EXCEPTION 'MISSING_PROVIDER_MESSAGE_ID: Missing required provider message ID for %', v_channel
        USING ERRCODE = '22023', HINT = 'MISSING_PROVIDER_MESSAGE_ID';
    END IF;
  END IF;

  -- Canonical sanitization status mapping
  v_sanitization_status := CASE
    WHEN upper(trim(coalesce(p_sanitization_status, 'SUCCEEDED'))) IN ('CLEAN', 'SANITIZED', 'SUCCEEDED') THEN 'SUCCEEDED'
    WHEN upper(trim(coalesce(p_sanitization_status, 'SUCCEEDED'))) = 'PENDING' THEN 'PENDING'
    WHEN upper(trim(coalesce(p_sanitization_status, 'SUCCEEDED'))) = 'FAILED' THEN 'FAILED'
    WHEN upper(trim(coalesce(p_sanitization_status, 'SUCCEEDED'))) = 'NOT_REQUIRED' THEN 'NOT_REQUIRED'
    ELSE 'SUCCEEDED'
  END;

  -- Chuẩn hóa số điện thoại nếu có
  IF p_sender_phone IS NOT NULL AND trim(p_sender_phone) <> '' THEN
    v_normalized_phone := CASE
      WHEN trim(p_sender_phone) ~ '^0[1-9][0-9]{8}$' THEN '+84' || substring(trim(p_sender_phone) from 2)
      WHEN trim(p_sender_phone) ~ '^\+[1-9][0-9]{7,14}$' THEN trim(p_sender_phone)
      WHEN trim(p_sender_phone) ~ '^84[1-9][0-9]{8}$' THEN '+' || trim(p_sender_phone)
      ELSE '+84' || regexp_replace(trim(p_sender_phone), '[^0-9]', '', 'g')
    END;
  END IF;

  -- Concurrency serialization mutex before Customer creation
  IF p_external_user_id IS NOT NULL AND trim(p_external_user_id) <> '' THEN
    PERFORM pg_advisory_xact_lock(
      hashtextextended(p_company_id::text || ':' || v_channel || ':' || trim(p_external_user_id), 0)
    );
  END IF;

  IF v_normalized_phone IS NOT NULL AND trim(v_normalized_phone) <> '' THEN
    PERFORM pg_advisory_xact_lock(
      hashtextextended(p_company_id::text || ':phone:' || v_normalized_phone, 0)
    );
  END IF;

  -- 2. Durable Idempotency Check (under lock with confirmed-alias semantics)
  --
  -- Confirmed-alias rule:
  -- When BOTH p_external_ref (canonical meta_mid_v2) AND v_legacy_ref are present
  -- AND they differ, the caller is a v2 worker. The legacy_ref is an UNCONFIRMED
  -- alias guessed from current viewport ordinal which may have shifted due to
  -- Meta DOM virtualization. We MUST NOT suppress a new canonical MID based on
  -- an unconfirmed guessed legacy collision.
  --
  -- The legacy branch only fires safely for:
  -- (a) Pure v1 callers (no v2 canonical ref, only legacy ref)
  -- (b) Edge case where p_external_ref == v_legacy_ref (same identity, no shift risk)
  --
  -- Priority: NO MESSAGE LOSS > one-time duplicate avoidance.

  v_legacy_ref := nullif(trim(coalesce(v_metadata->>'legacy_external_ref', '')), '');
  v_legacy_confidence := nullif(trim(coalesce(v_metadata->>'legacy_alias_confidence', '')), '');

  IF p_external_ref IS NOT NULL AND trim(p_external_ref) <> '' THEN
    -- 1. Always check canonical ref first (100% authoritative identity)
    SELECT *
    INTO v_existing_interaction
    FROM public.interactions
    WHERE company_id = p_company_id
      AND channel = v_channel
      AND external_ref = trim(p_external_ref)
    LIMIT 1;

    IF FOUND THEN
      RETURN QUERY SELECT
        v_existing_interaction.id,
        v_existing_interaction.conversation_id,
        v_existing_interaction.customer_id,
        true;
      RETURN;
    END IF;

    -- 2. If not found by canonical ref, check legacy ref ONLY IF confirmed
    -- (a) Pure legacy match where canonical equals legacy (no shift risk)
    -- (b) OR explicitly confirmed by worker with historical proof (v_legacy_confidence = 'confirmed')
    -- Guessed legacy refs without proof MUST NOT suppress a new canonical MID.
    IF v_legacy_ref IS NOT NULL THEN
      IF v_legacy_ref = trim(p_external_ref) OR v_legacy_confidence = 'confirmed' THEN
        SELECT *
        INTO v_existing_interaction
        FROM public.interactions
        WHERE company_id = p_company_id
          AND channel = v_channel
          AND external_ref = v_legacy_ref
        LIMIT 1;

        IF FOUND THEN
          RETURN QUERY SELECT
            v_existing_interaction.id,
            v_existing_interaction.conversation_id,
            v_existing_interaction.customer_id,
            true;
          RETURN;
        END IF;
      END IF;
    END IF;
  ELSIF v_legacy_ref IS NOT NULL THEN
    -- Pure v1 caller: only legacy ref available, safe to check
    SELECT *
    INTO v_existing_interaction
    FROM public.interactions
    WHERE company_id = p_company_id
      AND channel = v_channel
      AND external_ref = v_legacy_ref
    LIMIT 1;

    IF FOUND THEN
      RETURN QUERY SELECT
        v_existing_interaction.id,
        v_existing_interaction.conversation_id,
        v_existing_interaction.customer_id,
        true;
      RETURN;
    END IF;
  END IF;

  -- 3. 4-Tier Customer Resolution
  IF p_customer_id IS NOT NULL THEN
    SELECT c.id INTO v_customer_id
    FROM public.customers c
    WHERE c.id = p_customer_id AND c.company_id = p_company_id
    LIMIT 1;
  END IF;

  IF v_customer_id IS NULL AND p_external_user_id IS NOT NULL AND trim(p_external_user_id) <> '' THEN
    SELECT idt.customer_id INTO v_customer_id
    FROM public.identities idt
    WHERE idt.company_id = p_company_id
      AND idt.channel = v_channel
      AND idt.external_id = trim(p_external_user_id)
    LIMIT 1;
  END IF;

  IF v_customer_id IS NULL AND v_normalized_phone IS NOT NULL THEN
    SELECT cpc.customer_id INTO v_customer_id
    FROM private.customer_private_contacts cpc
    WHERE cpc.company_id = p_company_id
      AND (cpc.normalized_phone = v_normalized_phone OR cpc.raw_phone = trim(p_sender_phone))
    LIMIT 1;

    IF v_customer_id IS NULL THEN
      v_cust_name := coalesce(nullif(trim(p_sender_name), ''), 'Khách hàng ' || v_channel);
      INSERT INTO public.customers (
        company_id, name, source, stage, created_at, updated_at
      ) VALUES (
        p_company_id, v_cust_name, v_channel, 'LEAD_NEW', v_now, v_now
      ) RETURNING id INTO v_customer_id;

      IF v_normalized_phone ~ '^\+[1-9][0-9]{7,14}$' THEN
        INSERT INTO private.customer_private_contacts (
          company_id, customer_id, raw_phone, normalized_phone, phone_country_code, is_verified, created_at, updated_at
        ) VALUES (
          p_company_id, v_customer_id, trim(p_sender_phone), v_normalized_phone, 'VN', false, v_now, v_now
        ) ON CONFLICT (company_id, normalized_phone) DO NOTHING;
      END IF;

      INSERT INTO public.customer_stage_histories (
        company_id, customer_id, from_stage, to_stage, actor_type, reason, changed_at
      ) VALUES (
        p_company_id, v_customer_id, NULL, 'LEAD_NEW', 'SYSTEM', 'Tự động tạo từ tương tác ' || v_channel, v_now
      );

      IF p_external_user_id IS NOT NULL AND trim(p_external_user_id) <> '' THEN
        INSERT INTO public.identities (
          company_id, customer_id, channel, external_id, verified, metadata, created_at, updated_at
        ) VALUES (
          p_company_id, v_customer_id, v_channel, trim(p_external_user_id), false, '{}'::jsonb, v_now, v_now
        ) ON CONFLICT (company_id, channel, external_id) DO NOTHING;
      END IF;
    END IF;
  END IF;

  IF v_customer_id IS NULL AND p_external_user_id IS NOT NULL AND trim(p_external_user_id) <> '' THEN
    v_cust_name := coalesce(nullif(trim(p_sender_name), ''), 'Khách hàng ' || v_channel);
    INSERT INTO public.customers (
      company_id, name, source, stage, created_at, updated_at
    ) VALUES (
      p_company_id, v_cust_name, v_channel, 'LEAD_NEW', v_now, v_now
    ) RETURNING id INTO v_customer_id;

    INSERT INTO public.identities (
      company_id, customer_id, channel, external_id, verified, metadata, created_at, updated_at
    ) VALUES (
      p_company_id, v_customer_id, v_channel, trim(p_external_user_id), false, '{}'::jsonb, v_now, v_now
    )
    ON CONFLICT (company_id, channel, external_id) DO UPDATE
      SET updated_at = v_now
    RETURNING customer_id INTO v_customer_id;

    INSERT INTO public.customer_stage_histories (
      company_id, customer_id, from_stage, to_stage, actor_type, reason, changed_at
    ) VALUES (
      p_company_id, v_customer_id, NULL, 'LEAD_NEW', 'SYSTEM', 'Tự động tạo từ tương tác ' || v_channel, v_now
    );
  END IF;

  IF v_customer_id IS NULL THEN
    RAISE EXCEPTION 'Inbound customer resolution failed: Fail-Closed'
      USING ERRCODE = 'P0002', HINT = 'CUSTOMER_RESOLUTION_FAILED';
  END IF;

  -- =========================================================================
  -- CRM Display Name Update Semantics:
  -- existing generic customer name + incoming real Facebook display name => update real display name
  -- existing manual/custom name + incoming Facebook name => keep existing manual name
  -- customer_code is strictly preserved and never changed.
  -- =========================================================================
  IF p_sender_name IS NOT NULL AND trim(p_sender_name) <> '' THEN
    SELECT c.name INTO v_cust_name
    FROM public.customers c
    WHERE c.id = v_customer_id;

    IF public.is_generic_customer_name(v_cust_name)
       AND NOT public.is_generic_customer_name(trim(p_sender_name)) THEN
      UPDATE public.customers
      SET name = trim(p_sender_name),
          updated_at = v_now
      WHERE id = v_customer_id;
    END IF;
  END IF;

  -- 4. Khóa hoặc tạo mới public.conversations (Lưu trữ và cập nhật metadata)
  IF p_external_conversation_id IS NOT NULL AND trim(p_external_conversation_id) <> '' THEN
    SELECT * INTO v_conversation
    FROM public.conversations
    WHERE company_id = p_company_id
      AND channel = v_channel
      AND external_conversation_id = trim(p_external_conversation_id)
    FOR UPDATE;
  END IF;

  IF v_conversation.id IS NULL AND v_customer_id IS NOT NULL THEN
    SELECT * INTO v_conversation
    FROM public.conversations
    WHERE company_id = p_company_id
      AND channel = v_channel
      AND customer_id = v_customer_id
    FOR UPDATE;
  END IF;

  IF v_conversation.id IS NOT NULL THEN
    UPDATE public.conversations
    SET unread_count = public.conversations.unread_count + 1,
        last_message_at = v_now,
        status = 'OPEN',
        metadata = coalesce(public.conversations.metadata, '{}'::jsonb) || v_metadata,
        updated_at = v_now
    WHERE id = v_conversation.id
      AND company_id = p_company_id
    RETURNING * INTO v_conversation;

    v_conversation_id := v_conversation.id;
  ELSE
    v_ext_conv_id := coalesce(nullif(trim(p_external_conversation_id), ''), v_customer_id::text);

    INSERT INTO public.conversations (
      company_id,
      customer_id,
      channel,
      external_conversation_id,
      last_message_at,
      unread_count,
      status,
      metadata,
      created_at,
      updated_at
    ) VALUES (
      p_company_id,
      v_customer_id,
      v_channel,
      v_ext_conv_id,
      v_now,
      1,
      'OPEN',
      v_metadata,
      v_now,
      v_now
    )
    ON CONFLICT (company_id, channel, external_conversation_id) DO UPDATE
      SET unread_count = public.conversations.unread_count + 1,
          last_message_at = v_now,
          status = 'OPEN',
          metadata = coalesce(public.conversations.metadata, '{}'::jsonb) || v_metadata,
          updated_at = v_now
    RETURNING id INTO v_conversation_id;
  END IF;

  -- 5. INSERT public.interactions
  v_interaction_id := gen_random_uuid();

  INSERT INTO public.interactions (
    id,
    company_id,
    customer_id,
    conversation_id,
    channel,
    type,
    direction,
    sanitized_content,
    sanitization_status,
    sanitized_at,
    sanitizer_version,
    external_ref,
    actor_type,
    created_at
  ) VALUES (
    v_interaction_id,
    p_company_id,
    v_customer_id,
    v_conversation_id,
    v_channel,
    'MESSAGE',
    'INBOUND',
    coalesce(p_sanitized_content, ''),
    v_sanitization_status,
    v_now,
    'v1',
    nullif(trim(p_external_ref), ''),
    'CUSTOMER',
    v_now
  );

  -- 6. INSERT private.interaction_raw_contents
  INSERT INTO private.interaction_raw_contents (
    interaction_id,
    company_id,
    raw_content,
    raw_payload,
    source_metadata,
    created_at
  ) VALUES (
    v_interaction_id,
    p_company_id,
    coalesce(p_raw_content, ''),
    v_metadata,
    v_metadata,
    v_now
  );

  RETURN QUERY SELECT
    v_interaction_id,
    v_conversation_id,
    v_customer_id,
    false;
END;
$$;

CREATE OR REPLACE FUNCTION public.apply_zalo_display_name(
  p_company uuid,
  p_external_id text,
  p_display_name text,
  p_source text DEFAULT 'message_dname'
) RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_external_id text := btrim(coalesce(p_external_id, ''));
  v_display_name text := nullif(left(regexp_replace(coalesce(p_display_name, ''), '\s+', ' ', 'g'), 160), '');
  v_source text := coalesce(nullif(btrim(p_source), ''), 'message_dname');
  v_customer_ids uuid[];
  v_customers integer := 0;
  v_identities integer := 0;
  v_conversations integer := 0;
BEGIN
  IF p_company IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.companies WHERE id = p_company
  ) THEN
    RAISE EXCEPTION 'INVALID_COMPANY';
  END IF;
  IF v_external_id !~ '^[0-9]{5,40}$' THEN
    RAISE EXCEPTION 'INVALID_ZALO_EXTERNAL_ID';
  END IF;

  IF v_display_name IS NULL OR public.is_generic_customer_name(v_display_name) THEN
    RETURN jsonb_build_object(
      'customers', 0,
      'identities', 0,
      'conversations', 0,
      'ignored', true
    );
  END IF;

  -- Identities created by ingest may not carry ZCAJS metadata yet, so collect
  -- customers from every projection of the same personal Zalo UID.
  SELECT coalesce(array_agg(DISTINCT projected.customer_id), '{}'::uuid[])
    INTO v_customer_ids
    FROM (
      SELECT i.customer_id
        FROM public.identities i
       WHERE i.company_id = p_company
         AND i.channel = 'ZALO'
         AND i.external_id = v_external_id
      UNION
      SELECT c.customer_id
        FROM public.conversations c
       WHERE c.company_id = p_company
         AND c.channel = 'ZALO'
         AND c.external_conversation_id = v_external_id
         AND c.customer_id IS NOT NULL
    ) projected;

  IF cardinality(v_customer_ids) > 0 THEN
    UPDATE public.customers c
       SET name = v_display_name,
           updated_at = clock_timestamp()
     WHERE c.company_id = p_company
       AND c.id = ANY(v_customer_ids)
       AND public.is_generic_customer_name(c.name);
    GET DIAGNOSTICS v_customers = ROW_COUNT;
  END IF;

  UPDATE public.identities i
     SET display_name = v_display_name,
         updated_at = clock_timestamp()
   WHERE i.company_id = p_company
     AND i.channel = 'ZALO'
     AND i.external_id = v_external_id
     AND i.display_name IS DISTINCT FROM v_display_name;
  GET DIAGNOSTICS v_identities = ROW_COUNT;

  UPDATE public.conversations c
     SET metadata = coalesce(c.metadata, '{}'::jsonb) || jsonb_build_object(
           'zalo_display_name', v_display_name,
           'zalo_display_name_source', v_source,
           'zalo_display_name_updated_at', clock_timestamp()
         ),
         updated_at = clock_timestamp()
   WHERE c.company_id = p_company
     AND c.channel = 'ZALO'
     AND c.external_conversation_id = v_external_id
     AND lower(coalesce(c.metadata->>'provider', 'zcajs')) = 'zcajs'
     AND (
       coalesce(c.metadata->>'zalo_display_name', '') IS DISTINCT FROM v_display_name
       OR coalesce(c.metadata->>'zalo_display_name_source', '') IS DISTINCT FROM v_source
     );
  GET DIAGNOSTICS v_conversations = ROW_COUNT;

  RETURN jsonb_build_object(
    'customers', v_customers,
    'identities', v_identities,
    'conversations', v_conversations,
    'ignored', false
  );
END $$;

CREATE OR REPLACE FUNCTION public.repair_zalo_personal_display_names(p_company uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  row record;
  result jsonb;
  v_customers integer := 0;
  v_identities integer := 0;
  v_conversations integer := 0;
BEGIN
  IF p_company IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.companies WHERE id = p_company
  ) THEN
    RAISE EXCEPTION 'INVALID_COMPANY';
  END IF;

  FOR row IN
    SELECT external_id, display_name
      FROM public.zalo_personal_contact_candidates
     WHERE company_id = p_company
       AND display_name IS NOT NULL
       AND btrim(display_name) <> ''
  LOOP
    result := public.apply_zalo_display_name(
      p_company,
      row.external_id,
      row.display_name,
      'directory'
    );
    v_customers := v_customers + coalesce((result->>'customers')::integer, 0);
    v_identities := v_identities + coalesce((result->>'identities')::integer, 0);
    v_conversations := v_conversations + coalesce((result->>'conversations')::integer, 0);
  END LOOP;

  RETURN jsonb_build_object(
    'customers', v_customers,
    'identities', v_identities,
    'conversations', v_conversations
  );
END $$;

DO $$
DECLARE
  company record;
BEGIN
  FOR company IN
    SELECT DISTINCT company_id
      FROM public.zalo_personal_contact_candidates
     WHERE display_name IS NOT NULL
       AND btrim(display_name) <> ''
  LOOP
    PERFORM public.repair_zalo_personal_display_names(company.company_id);
  END LOOP;
END $$;

CREATE OR REPLACE FUNCTION public.repair_messenger_external_conversation_id()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_page_id text;
  v_recipient_id text;
  v_canonical text;
BEGIN
  IF NEW.channel <> 'FACEBOOK' THEN
    RETURN NEW;
  END IF;

  IF NEW.external_conversation_id ~ '^[0-9]+:[0-9]+$' THEN
    RETURN NEW;
  END IF;

  v_page_id := public.ai_messenger_page_id(NEW.external_conversation_id, NEW.metadata);
  v_recipient_id := public.ai_messenger_recipient_id(NEW.external_conversation_id, NEW.metadata);
  IF v_page_id IS NULL OR v_recipient_id IS NULL THEN
    RETURN NEW;
  END IF;

  v_canonical := v_page_id || ':' || v_recipient_id;

  -- Never steal a canonical key from another conversation. If this happens the
  -- ingestion path should have matched that conversation instead.
  IF EXISTS (
    SELECT 1
    FROM public.conversations c
    WHERE c.company_id = NEW.company_id
      AND c.channel = NEW.channel
      AND c.external_conversation_id = v_canonical
      AND c.id <> NEW.id
  ) THEN
    RETURN NEW;
  END IF;

  NEW.external_conversation_id := v_canonical;
  RETURN NEW;
END;
$$;

CREATE TRIGGER trg_repair_messenger_external_conversation_id
  BEFORE INSERT OR UPDATE OF external_conversation_id, metadata ON public.conversations
  FOR EACH ROW EXECUTE FUNCTION public.repair_messenger_external_conversation_id();

CREATE OR REPLACE FUNCTION public.seed_du_hoc_messenger_canary()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_page_id text;
BEGIN
  IF NEW.channel <> 'FACEBOOK' THEN
    RETURN NEW;
  END IF;

  v_page_id := public.ai_messenger_page_id(NEW.external_conversation_id, NEW.metadata);
  IF v_page_id IS DISTINCT FROM '1343097708890171' THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.ai_brain_live_canary_allowlist (
    company_id, channel, conversation_id, page_id, enabled
  ) VALUES (
    NEW.company_id, 'MESSENGER', NEW.id, v_page_id, true
  )
  ON CONFLICT (company_id, channel, conversation_id, page_id) DO NOTHING;

  -- Create the tenant kill switch only when it has never been configured. An
  -- operator-disabled setting must remain disabled.
  INSERT INTO public.ai_brain_live_settings (
    company_id, channel, enabled, min_confidence
  ) VALUES (
    NEW.company_id, 'MESSENGER', true, 0.850
  )
  ON CONFLICT (company_id, channel) DO NOTHING;

  RETURN NEW;
END;
$$;

CREATE TRIGGER trg_seed_du_hoc_messenger_canary
  AFTER INSERT OR UPDATE OF external_conversation_id, metadata ON public.conversations
  FOR EACH ROW EXECUTE FUNCTION public.seed_du_hoc_messenger_canary();

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint WHERE conname = 'fk_ai_brain_live_canary_conversation'
  ) THEN
    ALTER TABLE public.ai_brain_live_canary_allowlist
      ADD CONSTRAINT fk_ai_brain_live_canary_conversation
      FOREIGN KEY (company_id, conversation_id)
      REFERENCES public.conversations(company_id, id)
      ON DELETE CASCADE;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint WHERE conname = 'chk_ai_brain_live_canary_page_id_numeric'
  ) THEN
    ALTER TABLE public.ai_brain_live_canary_allowlist
      DROP CONSTRAINT IF EXISTS ai_brain_live_canary_allowlist_page_id_check;
    ALTER TABLE public.ai_brain_live_canary_allowlist
      ADD CONSTRAINT chk_ai_brain_live_canary_page_id_numeric
      CHECK (page_id ~ '^[0-9]+$');
  END IF;
END $$;

CREATE INDEX IF NOT EXISTS idx_ai_brain_live_canary_lookup
  ON public.ai_brain_live_canary_allowlist (company_id, channel, conversation_id, page_id)
  WHERE enabled = true;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_trigger
    WHERE tgname = 'trg_ai_brain_live_canary_allowlist_updated_at'
  ) THEN
    CREATE TRIGGER trg_ai_brain_live_canary_allowlist_updated_at
      BEFORE UPDATE ON public.ai_brain_live_canary_allowlist
      FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
  END IF;
END $$;

CREATE UNIQUE INDEX IF NOT EXISTS uq_ai_analyses_dedupe
  ON public.ai_analyses (company_id, customer_id, dedupe_key)
  WHERE dedupe_key IS NOT NULL;

CREATE OR REPLACE FUNCTION public.update_customer_stage_atomic(
  p_company_id uuid,
  p_customer_id uuid,
  p_new_stage text,
  p_note text DEFAULT NULL,
  p_changed_by uuid DEFAULT NULL,
  p_actor_type text DEFAULT 'USER',
  p_source_ref text DEFAULT NULL,
  p_expected_stage text DEFAULT NULL,
  p_evidence text DEFAULT NULL,
  p_confidence numeric DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_customer public.customers%ROWTYPE;
  v_history public.customer_stage_histories%ROWTYPE;
  v_reason text;
  v_now timestamptz := now();
  v_old_stage text;
  v_old_canonical text;
  v_new_canonical text;
  v_expected_canonical text;
  v_actor_type text;
  v_verification_status text;
BEGIN
  IF p_company_id IS NULL THEN
    RAISE EXCEPTION 'p_company_id là bắt buộc' USING ERRCODE = '22000';
  END IF;
  IF p_customer_id IS NULL THEN
    RAISE EXCEPTION 'p_customer_id là bắt buộc' USING ERRCODE = '22000';
  END IF;
  IF p_new_stage IS NULL OR pg_catalog.btrim(p_new_stage) = '' THEN
    RAISE EXCEPTION 'p_new_stage là bắt buộc' USING ERRCODE = '22000';
  END IF;
  IF p_confidence IS NOT NULL AND (p_confidence < 0 OR p_confidence > 1) THEN
    RAISE EXCEPTION 'INVALID_CONFIDENCE' USING ERRCODE = '22000';
  END IF;

  v_new_canonical := public.canonical_customer_stage(p_new_stage);
  IF v_new_canonical IS NULL THEN
    RAISE EXCEPTION 'INVALID_STAGE' USING ERRCODE = '22000';
  END IF;

  SELECT * INTO v_customer
  FROM public.customers
  WHERE id = p_customer_id
    AND company_id = p_company_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'CUSTOMER_NOT_FOUND: Khách hàng không tồn tại hoặc không thuộc quyền quản lý của tổ chức.'
      USING ERRCODE = 'P0002', HINT = 'CUSTOMER_NOT_FOUND';
  END IF;

  v_old_stage := v_customer.stage;
  v_old_canonical := public.canonical_customer_stage(v_customer.stage);

  IF p_expected_stage IS NOT NULL AND pg_catalog.btrim(p_expected_stage) <> '' THEN
    v_expected_canonical := public.canonical_customer_stage(p_expected_stage);
    IF v_expected_canonical IS NULL OR v_expected_canonical <> v_old_canonical THEN
      RAISE EXCEPTION 'STAGE_CONFLICT'
        USING ERRCODE = '40001',
              DETAIL = v_customer.stage,
              HINT = 'STAGE_CONFLICT';
    END IF;
  END IF;

  -- Không tạo history nhiễu khi giai đoạn canonical không đổi.
  IF v_new_canonical = v_old_canonical THEN
    RETURN jsonb_build_object(
      'customer', to_jsonb(v_customer),
      'history', NULL,
      'changed', false
    );
  END IF;

  UPDATE public.customers
  SET stage = v_new_canonical,
      updated_at = v_now
  WHERE id = p_customer_id
    AND company_id = p_company_id
  RETURNING * INTO v_customer;

  v_actor_type := pg_catalog.upper(coalesce(p_actor_type, 'USER'));
  IF v_actor_type NOT IN ('USER', 'AI', 'SYSTEM') THEN
    v_actor_type := 'USER';
  END IF;

  v_verification_status := CASE
    WHEN v_actor_type = 'AI' THEN 'AI_SUGGESTED'
    ELSE 'VERIFIED'
  END;

  v_reason := coalesce(
    NULLIF(pg_catalog.btrim(p_note), ''),
    'Chuyển giai đoạn sang [' || v_new_canonical || ']'
  );

  INSERT INTO public.customer_stage_histories (
    company_id,
    customer_id,
    from_stage,
    to_stage,
    actor_type,
    changed_by_user_id,
    reason,
    source_ref,
    evidence,
    confidence,
    verification_status,
    changed_at
  ) VALUES (
    p_company_id,
    p_customer_id,
    v_old_stage,
    v_new_canonical,
    v_actor_type,
    p_changed_by,
    v_reason,
    p_source_ref,
    p_evidence,
    p_confidence,
    v_verification_status,
    v_now
  )
  RETURNING * INTO v_history;

  RETURN jsonb_build_object(
    'customer', to_jsonb(v_customer),
    'history', to_jsonb(v_history),
    'changed', true
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.record_ai_analysis(
  p_company_id uuid,
  p_customer_id uuid,
  p_source_refs jsonb,
  p_summary text,
  p_stage_suggestion text DEFAULT NULL,
  p_stop_reason text DEFAULT NULL,
  p_objections jsonb DEFAULT '[]'::jsonb,
  p_next_action text DEFAULT NULL,
  p_confidence numeric DEFAULT NULL,
  p_evidence text DEFAULT NULL,
  p_model_version text DEFAULT NULL,
  p_current_stage text DEFAULT NULL,
  p_reason text DEFAULT NULL,
  p_requires_verification boolean DEFAULT true,
  p_evidence_items jsonb DEFAULT '[]'::jsonb,
  p_dedupe_key text DEFAULT NULL,
  p_classifier_version text DEFAULT NULL,
  p_previous_analysis_id uuid DEFAULT NULL
)
RETURNS TABLE (
  id uuid,
  company_id uuid,
  customer_id uuid,
  source_refs jsonb,
  summary text,
  stage_suggestion text,
  current_stage text,
  stop_reason text,
  objections jsonb,
  next_action text,
  confidence numeric,
  evidence text,
  evidence_items jsonb,
  reason text,
  requires_verification boolean,
  verification_status text,
  verified_by uuid,
  verified_at timestamptz,
  verification_note text,
  classifier_version text,
  dedupe_key text,
  model_version text,
  created_at timestamptz
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_customer_company_id uuid;
  v_elem jsonb;
  v_ref_id uuid;
  v_ref_type text;
  v_int_company_id uuid;
  v_int_customer_id uuid;
  v_int_type text;
  v_int_sanitization_status text;
  v_int_sanitized_content text;
  v_utt_company_id uuid;
  v_utt_customer_id uuid;
  v_utt_status text;
  v_obj_text text;
  v_stage_suggestion text;
  v_current_stage text;
  v_new_row public.ai_analyses%ROWTYPE;
  v_existing public.ai_analyses%ROWTYPE;
  v_previous public.ai_analyses%ROWTYPE;
BEGIN
  -- 1. Tenant binding
  SELECT c.company_id INTO v_customer_company_id
  FROM public.customers c
  WHERE c.id = p_customer_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'CUSTOMER_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;
  IF v_customer_company_id <> p_company_id THEN
    RAISE EXCEPTION 'TENANT_MISMATCH' USING ERRCODE = '42501';
  END IF;

  -- 2. Confidence
  IF p_confidence IS NULL OR p_confidence < 0 OR p_confidence > 1 THEN
    RAISE EXCEPTION 'INVALID_CONFIDENCE' USING ERRCODE = '22000';
  END IF;

  -- 3. Summary
  IF p_summary IS NULL OR pg_catalog.btrim(p_summary) = '' THEN
    RAISE EXCEPTION 'EMPTY_SUMMARY' USING ERRCODE = '22000';
  END IF;
  IF pg_catalog.length(p_summary) > 2000 THEN
    RAISE EXCEPTION 'SUMMARY_TOO_LONG' USING ERRCODE = '22000';
  END IF;

  -- 4. Evidence
  IF p_evidence IS NULL OR pg_catalog.btrim(p_evidence) = '' THEN
    RAISE EXCEPTION 'EMPTY_EVIDENCE' USING ERRCODE = '22000';
  END IF;
  IF pg_catalog.length(p_evidence) > 5000 THEN
    RAISE EXCEPTION 'EVIDENCE_TOO_LONG' USING ERRCODE = '22000';
  END IF;

  -- 5. Model version
  IF p_model_version IS NULL OR pg_catalog.btrim(p_model_version) = '' THEN
    RAISE EXCEPTION 'EMPTY_MODEL_VERSION' USING ERRCODE = '22000';
  END IF;
  IF pg_catalog.length(p_model_version) > 100 THEN
    RAISE EXCEPTION 'MODEL_VERSION_TOO_LONG' USING ERRCODE = '22000';
  END IF;

  -- 6. Stage suggestion + current stage (normalize legacy -> canonical)
  IF p_stage_suggestion IS NOT NULL THEN
    v_stage_suggestion := public.canonical_customer_stage(p_stage_suggestion);
    IF v_stage_suggestion IS NULL THEN
      RAISE EXCEPTION 'INVALID_STAGE_SUGGESTION' USING ERRCODE = '22000';
    END IF;
  END IF;

  IF p_current_stage IS NOT NULL THEN
    v_current_stage := public.canonical_customer_stage(p_current_stage);
    IF v_current_stage IS NULL THEN
      RAISE EXCEPTION 'INVALID_CURRENT_STAGE' USING ERRCODE = '22000';
    END IF;
  END IF;

  -- 7. Stop reason / next action / reason / classifier version
  IF p_stop_reason IS NOT NULL AND pg_catalog.length(p_stop_reason) > 1000 THEN
    RAISE EXCEPTION 'STOP_REASON_TOO_LONG' USING ERRCODE = '22000';
  END IF;
  IF p_next_action IS NOT NULL AND pg_catalog.length(p_next_action) > 1000 THEN
    RAISE EXCEPTION 'NEXT_ACTION_TOO_LONG' USING ERRCODE = '22000';
  END IF;
  IF p_reason IS NOT NULL AND pg_catalog.length(p_reason) > 1000 THEN
    RAISE EXCEPTION 'REASON_TOO_LONG' USING ERRCODE = '22000';
  END IF;
  IF p_classifier_version IS NOT NULL AND pg_catalog.length(p_classifier_version) > 100 THEN
    RAISE EXCEPTION 'CLASSIFIER_VERSION_TOO_LONG' USING ERRCODE = '22000';
  END IF;
  IF p_dedupe_key IS NOT NULL AND p_dedupe_key !~ '^[a-f0-9]{64}$' THEN
    RAISE EXCEPTION 'INVALID_DEDUPE_KEY' USING ERRCODE = '22000';
  END IF;

  -- 8. Objections
  IF p_objections IS NULL OR jsonb_typeof(p_objections) <> 'array' THEN
    RAISE EXCEPTION 'INVALID_OBJECTIONS_STRUCTURE' USING ERRCODE = '22000';
  END IF;
  IF jsonb_array_length(p_objections) > 20 THEN
    RAISE EXCEPTION 'OBJECTIONS_LIMIT_EXCEEDED' USING ERRCODE = '22000';
  END IF;
  FOR v_elem IN SELECT * FROM jsonb_array_elements(p_objections) LOOP
    IF jsonb_typeof(v_elem) <> 'string' THEN
      RAISE EXCEPTION 'INVALID_OBJECTION_ITEM' USING ERRCODE = '22000';
    END IF;
    v_obj_text := v_elem #>> '{}';
    IF pg_catalog.btrim(v_obj_text) = '' THEN
      RAISE EXCEPTION 'EMPTY_OBJECTION_ITEM' USING ERRCODE = '22000';
    END IF;
    IF pg_catalog.length(v_obj_text) > 500 THEN
      RAISE EXCEPTION 'OBJECTION_TOO_LONG' USING ERRCODE = '22000';
    END IF;
  END LOOP;

  -- 9. Evidence items (structured, quote-only, no sensitive payloads)
  IF p_evidence_items IS NULL OR jsonb_typeof(p_evidence_items) <> 'array' THEN
    RAISE EXCEPTION 'INVALID_EVIDENCE_ITEMS_STRUCTURE' USING ERRCODE = '22000';
  END IF;
  IF jsonb_array_length(p_evidence_items) > 20 THEN
    RAISE EXCEPTION 'EVIDENCE_ITEMS_LIMIT_EXCEEDED' USING ERRCODE = '22000';
  END IF;
  FOR v_elem IN SELECT * FROM jsonb_array_elements(p_evidence_items) LOOP
    IF jsonb_typeof(v_elem) <> 'object' THEN
      RAISE EXCEPTION 'INVALID_EVIDENCE_ITEM' USING ERRCODE = '22000';
    END IF;
    IF v_elem ? 'phone' OR v_elem ? 'recording' OR v_elem ? 'raw_payload'
       OR v_elem ? 'token' OR v_elem ? 'content' THEN
      RAISE EXCEPTION 'SENSITIVE_DATA_IN_EVIDENCE_ITEM' USING ERRCODE = '22000';
    END IF;
    v_obj_text := v_elem->>'quote';
    IF v_obj_text IS NULL OR pg_catalog.btrim(v_obj_text) = '' THEN
      RAISE EXCEPTION 'EMPTY_EVIDENCE_QUOTE' USING ERRCODE = '22000';
    END IF;
    IF pg_catalog.length(v_obj_text) > 500 THEN
      RAISE EXCEPTION 'EVIDENCE_QUOTE_TOO_LONG' USING ERRCODE = '22000';
    END IF;
    v_obj_text := v_elem->>'source';
    IF v_obj_text IS NULL OR pg_catalog.length(v_obj_text) > 50 THEN
      RAISE EXCEPTION 'INVALID_EVIDENCE_SOURCE' USING ERRCODE = '22000';
    END IF;
    v_obj_text := v_elem->>'speaker';
    IF v_obj_text IS NOT NULL AND v_obj_text NOT IN ('CUSTOMER', 'STAFF', 'UNKNOWN') THEN
      RAISE EXCEPTION 'INVALID_EVIDENCE_SPEAKER' USING ERRCODE = '22000';
    END IF;
    IF v_elem ? 'stage' AND v_elem->>'stage' IS NOT NULL
       AND public.canonical_customer_stage(v_elem->>'stage') IS NULL THEN
      RAISE EXCEPTION 'INVALID_EVIDENCE_STAGE' USING ERRCODE = '22000';
    END IF;
  END LOOP;

  -- 10. Source refs: INTERACTION hoặc CALL_TRANSCRIPT_UTTERANCE
  IF p_source_refs IS NULL OR jsonb_typeof(p_source_refs) <> 'array' THEN
    RAISE EXCEPTION 'INVALID_SOURCE_REFS_STRUCTURE' USING ERRCODE = '22000';
  END IF;
  IF jsonb_array_length(p_source_refs) = 0 THEN
    RAISE EXCEPTION 'EMPTY_SOURCE_REFS' USING ERRCODE = '22000';
  END IF;
  IF jsonb_array_length(p_source_refs) > 100 THEN
    RAISE EXCEPTION 'SOURCE_REFS_LIMIT_EXCEEDED' USING ERRCODE = '22000';
  END IF;

  FOR v_elem IN SELECT * FROM jsonb_array_elements(p_source_refs) LOOP
    IF jsonb_typeof(v_elem) <> 'object' THEN
      RAISE EXCEPTION 'INVALID_SOURCE_REF_ITEM' USING ERRCODE = '22000';
    END IF;

    v_ref_type := v_elem->>'type';
    IF v_ref_type IS NULL OR v_ref_type NOT IN ('INTERACTION', 'CALL_TRANSCRIPT_UTTERANCE') THEN
      RAISE EXCEPTION 'FORBIDDEN_SOURCE_REF_TYPE' USING ERRCODE = '22000';
    END IF;

    IF v_elem ? 'content' OR v_elem ? 'phone' OR v_elem ? 'transcript'
       OR v_elem ? 'recording' OR v_elem ? 'raw_payload' OR v_elem ? 'token' THEN
      RAISE EXCEPTION 'SENSITIVE_DATA_IN_SOURCE_REF' USING ERRCODE = '22000';
    END IF;

    BEGIN
      v_ref_id := (v_elem->>'id')::uuid;
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'INVALID_SOURCE_REF_UUID' USING ERRCODE = '22000';
    END;

    IF v_ref_type = 'INTERACTION' THEN
      SELECT i.company_id, i.customer_id, i.type, i.sanitization_status, i.sanitized_content
      INTO v_int_company_id, v_int_customer_id, v_int_type, v_int_sanitization_status, v_int_sanitized_content
      FROM public.interactions i
      WHERE i.id = v_ref_id;

      IF NOT FOUND THEN
        RAISE EXCEPTION 'SOURCE_INTERACTION_NOT_FOUND' USING ERRCODE = 'P0002';
      END IF;
      IF v_int_company_id <> p_company_id THEN
        RAISE EXCEPTION 'SOURCE_INTERACTION_TENANT_MISMATCH' USING ERRCODE = '42501';
      END IF;
      IF v_int_customer_id <> p_customer_id THEN
        RAISE EXCEPTION 'SOURCE_INTERACTION_CUSTOMER_MISMATCH' USING ERRCODE = '22000';
      END IF;
      IF v_int_type <> 'MESSAGE' THEN
        RAISE EXCEPTION 'SOURCE_INTERACTION_NOT_MESSAGE' USING ERRCODE = '22000';
      END IF;
      IF v_int_sanitization_status <> 'SUCCEEDED' THEN
        RAISE EXCEPTION 'SOURCE_INTERACTION_NOT_SANITIZED' USING ERRCODE = '22000';
      END IF;
      IF v_int_sanitized_content IS NULL OR pg_catalog.btrim(v_int_sanitized_content) = '' THEN
        RAISE EXCEPTION 'SOURCE_INTERACTION_NO_CONTENT' USING ERRCODE = '22000';
      END IF;
    ELSE
      SELECT u.company_id, t.customer_id, t.status
      INTO v_utt_company_id, v_utt_customer_id, v_utt_status
      FROM public.zalo_call_transcript_utterances u
      JOIN public.zalo_call_transcriptions t
        ON t.id = u.transcription_id
       AND t.company_id = u.company_id
      WHERE u.id = v_ref_id;

      IF NOT FOUND THEN
        RAISE EXCEPTION 'SOURCE_TRANSCRIPT_NOT_FOUND' USING ERRCODE = 'P0002';
      END IF;
      IF v_utt_company_id <> p_company_id THEN
        RAISE EXCEPTION 'SOURCE_TRANSCRIPT_TENANT_MISMATCH' USING ERRCODE = '42501';
      END IF;
      IF v_utt_customer_id <> p_customer_id THEN
        RAISE EXCEPTION 'SOURCE_TRANSCRIPT_CUSTOMER_MISMATCH' USING ERRCODE = '22000';
      END IF;
      IF v_utt_status <> 'COMPLETED' THEN
        RAISE EXCEPTION 'SOURCE_TRANSCRIPT_NOT_COMPLETED' USING ERRCODE = '22000';
      END IF;
    END IF;
  END LOOP;

  -- 11. Previous analysis reference
  IF p_previous_analysis_id IS NOT NULL THEN
    SELECT * INTO v_previous
    FROM public.ai_analyses a
    WHERE a.id = p_previous_analysis_id
      AND a.company_id = p_company_id
      AND a.customer_id = p_customer_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'PREVIOUS_ANALYSIS_NOT_FOUND' USING ERRCODE = 'P0002';
    END IF;
  END IF;

  -- 12. Idempotency: cùng dedupe_key trả về bản ghi cũ, không tạo ghi chú trùng
  IF p_dedupe_key IS NOT NULL THEN
    SELECT * INTO v_existing
    FROM public.ai_analyses a
    WHERE a.company_id = p_company_id
      AND a.customer_id = p_customer_id
      AND a.dedupe_key = p_dedupe_key
    LIMIT 1;

    IF FOUND THEN
      RETURN QUERY SELECT
        v_existing.id, v_existing.company_id, v_existing.customer_id, v_existing.source_refs,
        v_existing.summary, v_existing.stage_suggestion, v_existing.current_stage,
        v_existing.stop_reason, v_existing.objections, v_existing.next_action,
        v_existing.confidence, v_existing.evidence, v_existing.evidence_items,
        v_existing.reason, v_existing.requires_verification, v_existing.verification_status,
        v_existing.verified_by, v_existing.verified_at, v_existing.verification_note,
        v_existing.classifier_version, v_existing.dedupe_key, v_existing.model_version,
        v_existing.created_at;
      RETURN;
    END IF;
  END IF;

  BEGIN
    INSERT INTO public.ai_analyses (
      company_id,
      customer_id,
      source_refs,
      summary,
      stage_suggestion,
      current_stage,
      stop_reason,
      objections,
      next_action,
      confidence,
      evidence,
      evidence_items,
      reason,
      requires_verification,
      classifier_version,
      dedupe_key,
      previous_analysis_id,
      model_version
    ) VALUES (
      p_company_id,
      p_customer_id,
      p_source_refs,
      p_summary,
      v_stage_suggestion,
      v_current_stage,
      p_stop_reason,
      p_objections,
      p_next_action,
      p_confidence,
      p_evidence,
      p_evidence_items,
      p_reason,
      coalesce(p_requires_verification, true),
      p_classifier_version,
      p_dedupe_key,
      p_previous_analysis_id,
      p_model_version
    )
    RETURNING * INTO v_new_row;
  EXCEPTION WHEN unique_violation THEN
    -- Concurrent reprocessing of the same conversation: return the winner row.
    IF p_dedupe_key IS NULL THEN
      RAISE;
    END IF;
    SELECT * INTO v_new_row
    FROM public.ai_analyses a
    WHERE a.company_id = p_company_id
      AND a.customer_id = p_customer_id
      AND a.dedupe_key = p_dedupe_key
    LIMIT 1;
  END;

  IF v_new_row.id IS NULL AND p_dedupe_key IS NOT NULL THEN
    SELECT * INTO v_new_row
    FROM public.ai_analyses a
    WHERE a.company_id = p_company_id
      AND a.customer_id = p_customer_id
      AND a.dedupe_key = p_dedupe_key
    LIMIT 1;
  END IF;

  IF v_new_row.id IS NULL THEN
    RAISE EXCEPTION 'AI_ANALYSIS_PERSIST_FAILED' USING ERRCODE = 'P0001';
  END IF;

  RETURN QUERY SELECT
    v_new_row.id, v_new_row.company_id, v_new_row.customer_id, v_new_row.source_refs,
    v_new_row.summary, v_new_row.stage_suggestion, v_new_row.current_stage,
    v_new_row.stop_reason, v_new_row.objections, v_new_row.next_action,
    v_new_row.confidence, v_new_row.evidence, v_new_row.evidence_items,
    v_new_row.reason, v_new_row.requires_verification, v_new_row.verification_status,
    v_new_row.verified_by, v_new_row.verified_at, v_new_row.verification_note,
    v_new_row.classifier_version, v_new_row.dedupe_key, v_new_row.model_version,
    v_new_row.created_at;
END;
$$;

CREATE OR REPLACE FUNCTION public.verify_ai_stage_suggestion(
  p_company_id uuid,
  p_analysis_id uuid,
  p_decision text,
  p_verified_by uuid,
  p_verifier_role text,
  p_note text DEFAULT NULL,
  p_customer_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_analysis public.ai_analyses%ROWTYPE;
  v_customer public.customers%ROWTYPE;
  v_result jsonb;
  v_current_canonical text;
  v_new_canonical text;
  v_decision text;
  v_role text;
  v_note text;
BEGIN
  v_decision := pg_catalog.upper(pg_catalog.btrim(coalesce(p_decision, '')));
  v_role := pg_catalog.upper(pg_catalog.btrim(coalesce(p_verifier_role, '')));

  IF v_decision NOT IN ('ACCEPTED', 'REJECTED') THEN
    RAISE EXCEPTION 'INVALID_DECISION' USING ERRCODE = '22000';
  END IF;
  IF v_role NOT IN ('SALE', 'BOSS_ADMIN') THEN
    RAISE EXCEPTION 'ROLE_FORBIDDEN' USING ERRCODE = '42501';
  END IF;
  IF p_verified_by IS NULL THEN
    RAISE EXCEPTION 'VERIFIER_REQUIRED' USING ERRCODE = '22000';
  END IF;
  IF p_note IS NOT NULL AND pg_catalog.length(p_note) > 1000 THEN
    RAISE EXCEPTION 'NOTE_TOO_LONG' USING ERRCODE = '22000';
  END IF;
  v_note := NULLIF(pg_catalog.btrim(p_note), '');

  SELECT * INTO v_analysis
  FROM public.ai_analyses a
  WHERE a.id = p_analysis_id
    AND a.company_id = p_company_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ANALYSIS_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;
  IF p_customer_id IS NOT NULL AND v_analysis.customer_id <> p_customer_id THEN
    -- Không cho phép áp dụng đề xuất của khách hàng khác qua URL.
    RAISE EXCEPTION 'ANALYSIS_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;
  IF v_analysis.verification_status <> 'PENDING' THEN
    RAISE EXCEPTION 'ANALYSIS_ALREADY_VERIFIED' USING ERRCODE = '22000';
  END IF;

  SELECT * INTO v_customer
  FROM public.customers c
  WHERE c.id = v_analysis.customer_id
    AND c.company_id = p_company_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'CUSTOMER_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  IF v_decision = 'REJECTED' THEN
    UPDATE public.ai_analyses
    SET verification_status = 'REJECTED',
        verified_by = p_verified_by,
        verified_at = now(),
        verification_note = v_note
    WHERE id = p_analysis_id
      AND company_id = p_company_id;

    RETURN jsonb_build_object(
      'analysis', to_jsonb(v_analysis) || jsonb_build_object(
        'verification_status', 'REJECTED',
        'verified_by', p_verified_by,
        'verified_at', now(),
        'verification_note', v_note
      ),
      'customer', NULL,
      'history', NULL
    );
  END IF;

  IF v_analysis.stage_suggestion IS NULL THEN
    RAISE EXCEPTION 'NOTHING_TO_ACCEPT' USING ERRCODE = '22000';
  END IF;

  v_new_canonical := public.canonical_customer_stage(v_analysis.stage_suggestion);
  v_current_canonical := public.canonical_customer_stage(v_customer.stage);

  IF v_new_canonical IS NULL THEN
    RAISE EXCEPTION 'INVALID_STAGE_SUGGESTION' USING ERRCODE = '22000';
  END IF;

  IF v_analysis.current_stage IS NOT NULL
     AND public.canonical_customer_stage(v_analysis.current_stage) <> v_current_canonical THEN
    RAISE EXCEPTION 'STAGE_CHANGED_SINCE_ANALYSIS'
      USING ERRCODE = '40001',
            DETAIL = v_customer.stage,
            HINT = 'STAGE_CHANGED_SINCE_ANALYSIS';
  END IF;

  IF v_new_canonical = 'contract_signed' THEN
    IF v_role <> 'BOSS_ADMIN' THEN
      RAISE EXCEPTION 'CONTRACT_SIGNED_REQUIRES_BOSS_ADMIN' USING ERRCODE = '42501';
    END IF;
    -- High-risk change: require a written verification note with real evidence.
    IF v_note IS NULL OR pg_catalog.length(v_note) < 10 THEN
      RAISE EXCEPTION 'CONTRACT_SIGNED_NOTE_REQUIRED' USING ERRCODE = '22000';
    END IF;
  END IF;

  v_result := public.update_customer_stage_atomic(
    p_company_id => p_company_id,
    p_customer_id => v_analysis.customer_id,
    p_new_stage => v_new_canonical,
    p_note => coalesce(
      v_note,
      'Nhân viên xác nhận đề xuất AI: ' || coalesce(v_analysis.reason, v_analysis.summary)
    ),
    p_changed_by => p_verified_by,
    p_actor_type => 'USER',
    p_source_ref => 'AI_ANALYSIS:' || p_analysis_id::text,
    p_expected_stage => v_customer.stage,
    p_evidence => v_analysis.evidence,
    p_confidence => v_analysis.confidence
  );

  UPDATE public.ai_analyses
  SET verification_status = 'ACCEPTED',
      verified_by = p_verified_by,
      verified_at = now(),
      verification_note = v_note
  WHERE id = p_analysis_id
    AND company_id = p_company_id;

  RETURN jsonb_build_object(
    'analysis', to_jsonb(v_analysis) || jsonb_build_object(
      'verification_status', 'ACCEPTED',
      'verified_by', p_verified_by,
      'verified_at', now(),
      'verification_note', v_note
    ),
    'customer', v_result->'customer',
    'history', v_result->'history'
  );
END;
$$;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns
